import { Feather } from '@expo/vector-icons';
import { useMemo, useState } from 'react';
import {
  ActivityIndicator,
  Modal,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { Alerte, BoutonDiscret, PaireBoutons } from '@/components/formulaire';
import { langue, type Langue } from '@/i18n';
import {
  mesInvitations,
  repondreInvitation,
  type Invitation,
} from '@/lib/co-enseignement';
import { useRequete } from '@/lib/requete';
import { espace, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Le panneau des invitations au co-enseignement qui ME sont adressées.
 *
 * 🔑 Symétrique de l'invitation : là où le·la propriétaire invite, l'invité·e
 * accepte ou refuse ici. Accepter, c'est devenir co-prof et partager le
 * semainier et sa moitié du programme (immersion).
 *
 * 🎨 Charte : feuille qui monte du bas (mobile) ou volet à droite (web), croix
 * FIXE hors du défilement, tutoiement, écriture inclusive, pas de tiret cadratin.
 */

type Lib = {
  titre: string;
  fermer: string;
  intro: string;
  aucune: string;
  classeSansNom: string;
  parQui: (nom: string) => string;
  parInconnu: string;
  lecture: string;
  ecriture: string;
  accepter: string;
  refuser: string;
  erreur: string;
};

const LIB: Record<Langue, Lib> = {
  fr: {
    titre: 'Invitations',
    fermer: 'Fermer',
    intro:
      "Un·e collègue t'invite à co-enseigner sa classe. En acceptant, vous partagez le semainier et sa moitié du programme.",
    aucune: "Aucune invitation en attente. Quand un·e collègue t'invitera, ça apparaîtra ici.",
    classeSansNom: 'Une classe',
    parQui: (nom: string) => `Invitation de ${nom}`,
    parInconnu: 'Invitation reçue',
    lecture: 'Accès en lecture',
    ecriture: 'Accès en écriture',
    accepter: 'Accepter',
    refuser: 'Refuser',
    erreur: "Ça n'a pas marché. Réessaie.",
  },
  nl: {
    titre: 'Uitnodigingen',
    fermer: 'Sluiten',
    intro:
      'Een collega nodigt je uit om zijn/haar klas samen te geven. Als je aanvaardt, deel je de weekplanning en de helft van het programma.',
    aucune: 'Geen uitnodigingen in afwachting. Zodra een collega je uitnodigt, verschijnt het hier.',
    classeSansNom: 'Een klas',
    parQui: (nom: string) => `Uitnodiging van ${nom}`,
    parInconnu: 'Uitnodiging ontvangen',
    lecture: 'Leestoegang',
    ecriture: 'Schrijftoegang',
    accepter: 'Aanvaarden',
    refuser: 'Weigeren',
    erreur: 'Het is niet gelukt. Probeer opnieuw.',
  },
};

function lib(): Lib {
  return LIB[langue] ?? LIB.fr;
}

export function PanneauInvitations({
  visible,
  onFermer,
  onRepondu,
}: {
  visible: boolean;
  onFermer: () => void;
  /** Appelé après une réponse (accept/refus) : sert à rafraîchir l'appelant. */
  onRepondu?: () => void;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const web = Platform.OS === 'web';
  const l = lib();

  const invites = useRequete(mesInvitations, [], { actif: visible });
  const [occupe, setOccupe] = useState<string | null>(null);
  const [souci, setSouci] = useState<string | null>(null);

  async function repondre(inv: Invitation, accepter: boolean) {
    setSouci(null);
    setOccupe(inv.id);
    try {
      await repondreInvitation({ membreId: inv.id, accepter });
      invites.recharger();
      onRepondu?.();
    } catch {
      setSouci(l.erreur);
    } finally {
      setOccupe(null);
    }
  }

  const liste = invites.donnees ?? [];

  return (
    <Modal
      visible={visible}
      transparent
      animationType={web ? 'fade' : 'slide'}
      onRequestClose={onFermer}
      statusBarTranslucent>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel={l.fermer}
        onPress={onFermer}
        style={[styles.fond, web ? styles.fondWeb : styles.fondMobile]}>
        <Pressable style={web ? styles.volet : styles.feuille} onPress={() => {}}>
          <SafeAreaView edges={web ? ['top', 'bottom'] : ['bottom']} style={styles.zone}>
            {/* En-tête FIXE : la croix reste visible, jamais dans le défilement. */}
            <View style={styles.entete}>
              <Text style={texte.section}>{l.titre}</Text>
              <Pressable
                accessibilityRole="button"
                accessibilityLabel={l.fermer}
                onPress={onFermer}
                style={styles.croix}>
                <Feather name="x" size={22} color={c.encre} />
              </Pressable>
            </View>

            <ScrollView
              contentContainerStyle={styles.corps}
              showsVerticalScrollIndicator={false}>
              <Text style={styles.intro}>{l.intro}</Text>

              {souci ? <Alerte message={souci} /> : null}

              {invites.chargement && !liste.length ? (
                <ActivityIndicator color={c.encreDouce} style={{ marginVertical: espace.lg }} />
              ) : liste.length === 0 ? (
                <Text style={texte.discret}>{l.aucune}</Text>
              ) : (
                liste.map((inv) => (
                  <View key={inv.id} style={styles.carte}>
                    <View style={styles.ligne}>
                      <View style={styles.tuile}>
                        <Feather name="users" size={18} color={c.action[1]} />
                      </View>
                      <View style={styles.corpsLigne}>
                        <Text style={texte.corps}>{inv.classeNom ?? l.classeSansNom}</Text>
                        <Text style={texte.discret}>
                          {inv.parNom ? l.parQui(inv.parNom) : l.parInconnu}
                        </Text>
                        <Text style={styles.acces}>
                          {inv.acces === 'read' ? l.lecture : l.ecriture}
                        </Text>
                      </View>
                    </View>
                    <PaireBoutons
                      principal={{
                        libelle: l.accepter,
                        onPress: () => repondre(inv, true),
                        occupe: occupe === inv.id,
                      }}
                      secondaire={{
                        libelle: l.refuser,
                        onPress: () => repondre(inv, false),
                      }}
                    />
                  </View>
                ))
              )}

              <BoutonDiscret libelle={l.fermer} onPress={onFermer} />
            </ScrollView>
          </SafeAreaView>
        </Pressable>
      </Pressable>
    </Modal>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    fond: { flex: 1, backgroundColor: 'rgba(23,22,34,0.35)' },
    fondMobile: { justifyContent: 'flex-end' },
    fondWeb: { justifyContent: 'flex-start', alignItems: 'flex-end' },
    feuille: {
      backgroundColor: c.surface,
      borderTopLeftRadius: rayon.carte,
      borderTopRightRadius: rayon.carte,
      maxHeight: '90%',
    },
    volet: {
      backgroundColor: c.surface,
      width: 440,
      maxWidth: '100%',
      height: '100%',
    },
    zone: { flexShrink: 1 },
    entete: {
      flexDirection: 'row',
      alignItems: 'center',
      justifyContent: 'space-between',
      paddingHorizontal: espace.lg,
      paddingTop: espace.lg,
      paddingBottom: espace.md,
    },
    croix: {
      width: 40,
      height: 40,
      borderRadius: 20,
      alignItems: 'center',
      justifyContent: 'center',
      backgroundColor: c.fond,
    },
    corps: { paddingHorizontal: espace.lg, paddingBottom: espace.lg, gap: espace.md },
    intro: { fontFamily: police.corps, fontSize: 15, color: c.encreDouce, lineHeight: 22 },
    carte: {
      backgroundColor: c.fond,
      borderRadius: rayon.carte,
      padding: espace.md,
      gap: espace.md,
    },
    ligne: { flexDirection: 'row', alignItems: 'flex-start', gap: espace.md },
    corpsLigne: { flex: 1, gap: espace.xs },
    tuile: {
      width: 40,
      height: 40,
      borderRadius: rayon.tuile,
      alignItems: 'center',
      justifyContent: 'center',
      backgroundColor: c.actionTeinte,
    },
    acces: { fontFamily: police.accent, fontSize: 13, color: c.encreDouce },
  });
