import { Feather } from '@expo/vector-icons';
import { router, useLocalSearchParams } from 'expo-router';
import { useMemo, useState } from 'react';
import { ActivityIndicator, Pressable, Share, StyleSheet, Text, View } from 'react-native';

import { LigneAttendu, RechercheAttendus } from '@/components/attendus';
import { BoutonRond, Carte } from '@/components/ecran';
import { type Moment, Tuile } from '@/components/elements';
import {
  Alerte,
  BoutonDiscret,
  BoutonPrincipal,
  BoutonSecondaire,
  Champ,
  Pastilles,
} from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { VignettesActivite } from '@/components/vignettes-activite';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import { localeDate } from '@/lib/dates';
import {
  ajouterAttendus,
  CANAUX,
  changerCanal,
  changerRole,
  creneauxDe,
  detailActivite,
  elevesDe,
  nomAffiche,
  dupliquerActivite,
  garderSupport,
  genererMateriel,
  poserAdaptation,
  proposerAdaptations,
  retirerAdaptation,
  retirerAttendu,
  retirerSupport,
  SORTES_MATERIEL,
  supportsDe,
  type Attendu,
  type AttenduRattache,
  type Canal,
  type RoleAttendu,
  type SorteMateriel,
} from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * La fiche d'une activité.
 *
 * « Dans le détail c'est hyper important, on doit trouver ce que l'enfant
 * apprend, tous les attendus et les compétences, tout se retrouve ici. » Ce sont
 * les mots d'Anne-Charlotte, et c'est le cahier des charges de cet écran.
 *
 * Un seul geste principal, et il change selon l'état : une séance à faire se
 * clôture, une séance faite se lit. On ne montre jamais les deux.
 */

/** L'icône d'un moment de la journée, pour sa tuile teintée. */
const ICONE_MOMENT: Record<Moment, keyof typeof Feather.glyphMap> = {
  accueil: 'sunrise',
  ateliers: 'grid',
  dirigees: 'edit-2',
  recreation: 'coffee',
  sortie: 'map-pin',
  social: 'users',
};

function libelleDate(dateIso: string | null): string {
  if (!dateIso) return t.activite.sansDate;
  const [a, m, j] = dateIso.split('-').map((n) => parseInt(n, 10));
  const jour = new Date(a, m - 1, j);
  const aujourdhui = new Date();
  aujourdhui.setHours(0, 0, 0, 0);
  const ecart = Math.round((jour.getTime() - aujourdhui.getTime()) / 86_400_000);
  if (ecart === 0) return t.journal.aujourdhui;
  if (ecart === -1) return t.journal.hier;
  if (ecart === 1) return t.activite.demain;
  return jour.toLocaleDateString(localeDate(), { weekday: 'long', day: 'numeric', month: 'long' });
}

export default function FicheActivite() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { id } = useLocalSearchParams<{ id: string }>();
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;

  const [ajoute, setAjoute] = useState(false);
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);

  // Les adaptations : ce qui est proposé mais pas encore retenu, et le
  // formulaire d'ajout à la main.
  const [proposees, setProposees] = useState<{ eleveId: string; texte: string }[] | null>(null);
  const [cherche, setCherche] = useState(false);
  const [ajouteAdaptation, setAjouteAdaptation] = useState(false);
  const [pourQui, setPourQui] = useState<string | null>(null);
  const [texteAdaptation, setTexteAdaptation] = useState('');

  // Le matériel : ce qui vient d'être écrit et pas encore gardé.
  const [sorte, setSorte] = useState<SorteMateriel | null>(null);
  const [brouillon, setBrouillon] = useState<string | null>(null);
  const [ecrit, setEcrit] = useState(false);

  const activite = useRequete(() => detailActivite(id), [id]);
  const supports = useRequete(() => supportsDe(id), [id]);
  const eleves = useRequete(() => elevesDe(classeId!), [classeId], { actif: !!classeId });
  const creneaux = useRequete(() => creneauxDe(classeId!), [classeId], { actif: !!classeId });

  const detail = activite.donnees;
  const creneau = (creneaux.donnees ?? []).find((c) => c.id === detail?.creneauId) ?? null;
  const faite = detail?.statut === 'completed';
  // 🚨 On ne clôture que ce qui a eu lieu. Une activité planifiée pour dans deux
  // semaines n'a pas à proposer « Clôturer » comme geste principal : clôturer,
  // c'est valider APRÈS coup, pas au moment où l'on planifie. Et une activité
  // sans date n'a pas encore eu lieu du tout : son geste, c'est « Planifier »,
  // pas « Clôturer ». On ne clôture donc que ce qui a UNE date, et passée.
  const aujourdhuiIso = (() => {
    const d = new Date();
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  })();
  const cloturable = !!detail && !!detail.date && detail.date <= aujourdhuiIso;

  async function rattacher(attendu: Attendu) {
    if (!detail) return;
    setErreur(null);
    setOccupe(true);
    try {
      // Rattaché à la main : pas de rôle. Il se pose juste en dessous, en un
      // tap, plutôt que d'être deviné.
      await ajouterAttendus(detail.id, [{ id: attendu.id }]);
      activite.recharger();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.activite.erreur);
    } finally {
      setOccupe(false);
    }
  }

  async function poserRole(attenduId: string, role: RoleAttendu | null) {
    if (!detail) return;
    setErreur(null);
    setOccupe(true);
    try {
      await changerRole({ activiteId: detail.id, attenduId, role });
      activite.recharger();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.activite.erreur);
    } finally {
      setOccupe(false);
    }
  }

  async function dupliquer() {
    if (!detail) return;
    setErreur(null);
    setOccupe(true);
    try {
      // Une copie « à faire », sans date : on atterrit dessus pour la placer où
      // l'on veut (un autre créneau). La séance d'origine n'est pas touchée.
      const { id } = await dupliquerActivite(detail.id);
      router.push({ pathname: '/activite/[id]', params: { id } });
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.activite.erreur);
    } finally {
      setOccupe(false);
    }
  }

  async function poserCanal(canal: Canal | null) {
    if (!detail) return;
    setErreur(null);
    setOccupe(true);
    try {
      await changerCanal(detail.id, canal);
      activite.recharger();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.activite.erreur);
    } finally {
      setOccupe(false);
    }
  }

  async function ecrireMateriel() {
    if (!detail || !classe || !sorte) return;
    setErreur(null);
    setEcrit(true);
    try {
      setBrouillon(await genererMateriel({ classe, activiteId: detail.id, sorte }));
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.activite.materielErreur);
    } finally {
      setEcrit(false);
    }
  }

  async function garderMateriel() {
    if (!detail || !sorte || !brouillon) return;
    setErreur(null);
    setOccupe(true);
    try {
      await garderSupport({ activiteId: detail.id, sorte, texte: brouillon });
      setBrouillon(null);
      setSorte(null);
      supports.recharger();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.activite.materielErreur);
    } finally {
      setOccupe(false);
    }
  }

  async function effacerSupport(supportId: string) {
    setErreur(null);
    setOccupe(true);
    try {
      await retirerSupport(supportId);
      supports.recharger();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.activite.erreur);
    } finally {
      setOccupe(false);
    }
  }

  async function chercherAdaptations() {
    if (!detail) return;
    setErreur(null);
    setCherche(true);
    try {
      setProposees(await proposerAdaptations({ activiteId: detail.id, eleves: eleves.donnees ?? [] }));
    } catch {
      setErreur(t.activite.adaptationsErreur);
      setProposees([]);
    } finally {
      setCherche(false);
    }
  }

  async function garderAdaptation(eleveId: string, texte: string, venueDeLIA: boolean) {
    if (!detail) return;
    setErreur(null);
    setOccupe(true);
    try {
      await poserAdaptation({ activiteId: detail.id, eleveId, texte, venueDeLIA });
      setProposees((l) => (l ?? []).filter((p) => !(p.eleveId === eleveId && p.texte === texte)));
      setAjouteAdaptation(false);
      setTexteAdaptation('');
      setPourQui(null);
      activite.recharger();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.activite.erreur);
    } finally {
      setOccupe(false);
    }
  }

  async function effacerAdaptation(id: string) {
    if (!detail) return;
    setErreur(null);
    setOccupe(true);
    try {
      await retirerAdaptation(id);
      activite.recharger();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.activite.erreur);
    } finally {
      setOccupe(false);
    }
  }

  async function detacher(attenduId: string) {
    if (!detail) return;
    setErreur(null);
    setOccupe(true);
    try {
      await retirerAttendu(detail.id, attenduId);
      activite.recharger();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.activite.erreur);
    } finally {
      setOccupe(false);
    }
  }

  const faitesDeLaSerie = detail
    ? detail.serie.filter((s) => s.statut === 'completed').length + (faite ? 1 : 0)
    : 0;

  return (
    // Le titre de l'écran nomme l'activité elle-même plutôt qu'un générique
    // « Une activité » : on sait de quoi on parle avant même de lire la fiche.
    <SousEcran
      titre={detail?.titre ?? t.activite.titreEcran}
      chargement={activite.chargement}
      actions={
        detail ? (
          // Les gestes secondaires en icônes compactes, EN HAUT : ils prennent
          // peu de place et ressemblent enfin à des boutons (retour Valentin sur
          // la pile de liens en bas de fiche). Le geste principal (Clôturer /
          // Planifier) reste seul, en gros, dans le corps.
          <>
            <BoutonRond
              icone="edit-2"
              libelle={t.activite.modifier}
              onPress={() =>
                router.push({ pathname: '/activite/modifier/[id]', params: { id: detail.id } })
              }
            />
            <BoutonRond icone="copy" libelle={t.activite.dupliquer} onPress={dupliquer} />
            <BoutonRond
              icone="share-2"
              libelle={t.partage.bouton}
              onPress={() => router.push({ pathname: '/partager/[id]', params: { id: detail.id } })}
            />
          </>
        ) : undefined
      }>
    {!detail ? (
        <Carte>
          <Text style={texte.discret}>{t.activite.introuvable}</Text>
        </Carte>
      ) : (
        <>
          <Carte>
            <Text style={texte.titre}>{detail.titre}</Text>
            <View style={styles.ligne}>
              {/* La couleur code le moment de la journée, jamais la matière.
                  Tuile grise quand le moment n'est pas connu. */}
              {creneau?.moment ? (
                <Tuile icone={ICONE_MOMENT[creneau.moment]} moment={creneau.moment} taille={32} />
              ) : (
                <Tuile icone="clock" taille={32} />
              )}
              <Text style={[texte.discret, styles.meta]}>
                {[
                  libelleDate(detail.date),
                  creneau ? `${creneau.debut} ${creneau.libelle}` : null,
                  detail.type === 'workshop' ? t.activite.atelier : null,
                  faite ? t.activite.faite : t.activite.aFaire,
                ]
                  .filter(Boolean)
                  .join(' · ')}
              </Text>
            </View>
            {detail.serie.length ? (
              <Text style={texte.discret}>
                {t.activite.serieFaites(faitesDeLaSerie, detail.serie.length + 1)}
              </Text>
            ) : null}
            {detail.modalite ? (
              <Text style={styles.modalite}>
                {t.activite.modalite(
                  t.cloture.modalites[
                    detail.modalite.split(' · ')[0] as keyof typeof t.cloture.modalites
                  ] ?? detail.modalite,
                )}
              </Text>
            ) : null}
          </Carte>

          {detail.description ? (
            <Carte>
              <Text style={texte.corps}>{detail.description}</Text>
            </Carte>
          ) : null}

          {/* Ce que l'enfant apprend. C'est la partie que l'inspection lit. */}
          <Carte>
            <Text style={texte.section}>{t.activite.attendus}</Text>
            {detail.attendus.length === 0 ? (
              <>
                <Text style={styles.aide}>{t.activite.sansAttendu}</Text>
                <Text style={styles.aide}>{t.activite.sansAttenduAide}</Text>
              </>
            ) : (
              // Rangés PAR RÔLE (principaux, croisés, transversaux), toujours —
              // clôturée ou non. La structure de la prépa (ce que l'inspection
              // lit) est ainsi visible d'un coup, pas noyée dans une liste à plat.
              (['principal', 'croise', 'transversal', 'inconnu'] as const)
                .map((r) => ({
                  r,
                  liste: detail.attendus.filter((a) => (a.role ?? 'inconnu') === r),
                }))
                .filter((g) => g.liste.length > 0)
                .map((g) => (
                  <View key={g.r} style={styles.groupeRole}>
                    <Text style={styles.roleGroupeTitre}>{t.activite.rolesGroupe[g.r]}</Text>
                    {g.liste.map((a) => (
                      <View key={a.id} style={styles.rattachement}>
                        <LigneAttendu
                          attendu={a}
                          note={a.justification ?? undefined}
                          onRetirer={faite || occupe ? undefined : () => detacher(a.id)}
                        />
                        {/* Le rôle se pose ici, sur la fiche, et pas seulement au
                            moment où l'IA le propose. C'est ce que l'inspection
                            lit, donc ça doit rester corrigeable. */}
                        {!faite ? <ChoixRole attendu={a} occupe={occupe} onChoisir={poserRole} /> : null}
                      </View>
                    ))}
                  </View>
                ))
            )}

            {/* Aucun croisé ni transversal : on le dit franchement, plutôt que de
                laisser un vide qui donne l'impression que rien n'a été cherché. */}
            {detail.attendus.length > 0 &&
            !detail.attendus.some((a) => a.role === 'croise' || a.role === 'transversal') ? (
              <Text style={styles.aide}>{t.activite.sansCroises}</Text>
            ) : null}

            {!faite && !ajoute && detail.attendus.length > 0 ? (
              <Text style={styles.aide}>{t.activite.ajouterAttenduAide}</Text>
            ) : null}

            {!faite && !ajoute ? (
              <BoutonDiscret
                libelle={t.activite.ajouterAttendu}
                onPress={() => setAjoute(true)}
              />
            ) : null}

            {!faite && ajoute && classe ? (
              <RechercheAttendus
                classe={classe}
                choisis={[]}
                onBasculer={rattacher}
                exclus={new Set(detail.attendus.map((a) => a.id))}
              />
            ) : null}
          </Carte>

          {/* Le canal d'enseignement, corrigeable ici tant que la séance n'est
              pas clôturée (comme les attendus). Ce que le modèle a déduit d'une
              leçon reste une suggestion : un tap sur le canal posé le retire.
              Sur une séance faite, on l'affiche seulement s'il a été précisé. */}
          {!faite || detail.canal ? (
            <Carte>
              <Text style={texte.section}>{t.activite.canalTitre}</Text>
              {faite ? (
                <Text style={texte.corps}>
                  {detail.canal ? t.canaux[detail.canal] : null}
                </Text>
              ) : (
                <>
                  <Pastilles
                    options={CANAUX.map((canal) => ({ id: canal, libelle: t.canaux[canal] }))}
                    choisi={detail.canal}
                    onChoisir={(v) => poserCanal((v as Canal) ?? null)}
                  />
                  <Text style={styles.aide}>{t.activite.canalAide}</Text>
                </>
              )}
            </Carte>
          ) : null}

          {detail.objectif ||
          detail.materiel ||
          detail.organisation ||
          detail.lieu ||
          detail.duree ||
          detail.groupement ? (
            <Carte>
              {detail.objectif ? (
                <Ligne etiquette={t.activite.objectif} valeur={detail.objectif} />
              ) : null}
              {detail.materiel ? (
                <Ligne etiquette={t.activite.materiel} valeur={detail.materiel} />
              ) : null}
              {detail.organisation ? (
                <Ligne etiquette={t.activite.organisation} valeur={detail.organisation} />
              ) : null}
              {detail.lieu ? <Ligne etiquette={t.activite.lieu} valeur={detail.lieu} /> : null}
              {detail.duree ? (
                <Ligne etiquette={t.activite.duree} valeur={`${detail.duree}`} />
              ) : null}
              {detail.groupement ? (
                <Ligne
                  etiquette={t.activite.groupement}
                  valeur={
                    t.activite.groupements[
                      detail.groupement as keyof typeof t.activite.groupements
                    ] ?? detail.groupement
                  }
                />
              ) : null}
            </Carte>
          ) : null}

          {/* Le matériel. Ce qui manque vraiment n'est pas le nombre de leçons
              mais la profondeur : une activité qui décrit ce que les enfants
              font, sans le texte de la saynète, rend la moitié du travail. */}
          <Carte>
            <Text style={texte.section}>{t.activite.materielTitre}</Text>
            <Text style={styles.aide}>{t.activite.materielAide}</Text>

            {(supports.donnees ?? []).map((s) => (
              <View key={s.id} style={styles.ligneAdaptation}>
                <View style={styles.bloc}>
                  {s.sorte ? (
                    <Text style={styles.etiquette}>{t.activite.materielSortes[s.sorte]}</Text>
                  ) : null}
                  <Text style={texte.corps}>{s.texte}</Text>
                  {/* 🔑 La feuille de partage du système EST la sortie papier.
                      On ne construit pas de moteur d'impression : iOS et Android
                      en ont un, et il connaît déjà l'imprimante de l'école, les
                      Notes, le mail. « L'impression viendra plus tard » était
                      vrai tant qu'on croyait devoir la fabriquer nous-mêmes.

                      Ce qui part, c'est le texte qu'elle a sous les yeux, vers
                      une destination qu'elle choisit. Aucun prénom d'enfant :
                      generer-materiel a l'interdiction d'en écrire. */}
                  <BoutonDiscret
                    libelle={t.activite.materielSortir}
                    onPress={() =>
                      void Share.share({
                        message: s.texte,
                        title: detail.titre,
                      }).catch(() => null)
                    }
                  />
                </View>
                <Pressable
                  accessibilityRole="button"
                  accessibilityLabel={`${t.activite.retirer} : ${
                    s.sorte ? t.activite.materielSortes[s.sorte] : ''
                  }`}
                  disabled={occupe}
                  onPress={() => effacerSupport(s.id)}
                  style={styles.retirerAdaptation}>
                  <Feather name="x" size={18} color={c.encreDouce} />
                </Pressable>
              </View>
            ))}

            {(supports.donnees ?? []).length === 0 && !brouillon && !ecrit ? (
              <Text style={styles.aide}>{t.activite.materielAucun}</Text>
            ) : null}

            {ecrit ? (
              <View style={styles.ligneAttente}>
                <ActivityIndicator color={c.encreDouce} />
                <Text style={texte.discret}>{t.activite.materielAttente}</Text>
              </View>
            ) : null}

            {/* Rien n'est enregistré tant qu'elle n'a pas dit oui. */}
            {brouillon ? (
              <View style={styles.proposition}>
                {sorte ? (
                  <Text style={styles.marque}>{t.activite.materielSortes[sorte]}</Text>
                ) : null}
                <Text style={texte.corps}>{brouillon}</Text>
                <BoutonDiscret libelle={t.activite.materielGarder} onPress={garderMateriel} />
                <BoutonDiscret libelle={t.commun.annuler} onPress={() => setBrouillon(null)} />
              </View>
            ) : null}

            {!brouillon && !ecrit ? (
              <>
                <Pastilles
                  options={SORTES_MATERIEL.map((s) => ({
                    id: s,
                    libelle: t.activite.materielSortes[s],
                  }))}
                  choisi={sorte}
                  onChoisir={(v) => setSorte((v as SorteMateriel) ?? null)}
                />
                {sorte ? (
                  <BoutonSecondaire
                    libelle={t.activite.materielEcrire}
                    onPress={ecrireMateriel}
                  />
                ) : null}
                <Text style={styles.aide}>{t.activite.materielPasImprimable}</Text>
              </>
            ) : null}
          </Carte>

          {/* Les adaptations par élève. « Jean qui est HPi, lui proposer un
              défi supplémentaire pour essayer de stimuler l'enfant. »

              🚨 Ce qui sort vers le modèle : le besoin coché, et rien d'autre.
              Ni le prénom, ni le besoin écrit à la main, qui contient en base
              des diagnostics et au moins un prénom d'enfant. L'écran le dit,
              parce que ça concerne des enfants et qu'une enseignante a le droit
              de le savoir sans lire le code. */}
          <Carte>
            <Text style={texte.section}>{t.activite.adaptations}</Text>
            <Text style={styles.aide}>{t.activite.adaptationsAide}</Text>

            {detail.adaptations.length === 0 ? (
              <Text style={styles.aide}>{t.activite.adaptationsAucune}</Text>
            ) : (
              detail.adaptations.map((a) => {
                const eleve = (eleves.donnees ?? []).find((e) => e.id === a.eleveId);
                return (
                  <View key={a.id} style={styles.ligneAdaptation}>
                    <View style={styles.bloc}>
                      <Text style={styles.etiquette}>
                        {eleve ? nomAffiche(eleve) : t.journal.sansEleve}
                      </Text>
                      <Text style={texte.corps}>{a.texte}</Text>
                    </View>
                    {!faite ? (
                      <Pressable
                        accessibilityRole="button"
                        accessibilityLabel={`${t.activite.retirer} : ${a.texte}`}
                        disabled={occupe}
                        onPress={() => effacerAdaptation(a.id)}
                        style={styles.retirerAdaptation}>
                        <Feather name="x" size={18} color={c.encreDouce} />
                      </Pressable>
                    ) : null}
                  </View>
                );
              })
            )}

            {cherche ? (
              <View style={styles.ligneAttente}>
                <ActivityIndicator color={c.encreDouce} />
                <Text style={texte.discret}>{t.activite.adaptationsAttente}</Text>
              </View>
            ) : null}

            {/* Les propositions ne sont pas enregistrées tant qu'elle n'a pas
                dit oui. La machine propose, l'enseignante décide, et ici plus
                qu'ailleurs : ça parle d'un enfant en particulier. */}
            {(proposees ?? []).map((p) => {
              const eleve = (eleves.donnees ?? []).find((e) => e.id === p.eleveId);
              return (
                <View key={`${p.eleveId}-${p.texte}`} style={styles.proposition}>
                  <Text style={styles.marque}>{t.activite.adaptationVenueDeLIA}</Text>
                  <Text style={styles.etiquette}>
                    {eleve ? nomAffiche(eleve) : t.journal.sansEleve}
                  </Text>
                  <Text style={texte.corps}>{p.texte}</Text>
                  <BoutonDiscret
                    libelle={t.activite.adaptationGardee}
                    onPress={() => garderAdaptation(p.eleveId, p.texte, true)}
                  />
                </View>
              );
            })}

            {proposees?.length === 0 && !cherche ? (
              <Text style={styles.aide}>{t.activite.adaptationsRien}</Text>
            ) : null}

            {!faite && !cherche ? (
              <>
                {(eleves.donnees ?? []).some((e) => e.besoins.length > 0) ? (
                  <>
                    <BoutonSecondaire
                      libelle={t.activite.adaptationsProposer}
                      onPress={chercherAdaptations}
                    />
                    <Text style={styles.aide}>{t.activite.adaptationsCeQuiSort}</Text>
                  </>
                ) : (
                  <Text style={styles.aide}>{t.activite.adaptationsSansBesoin}</Text>
                )}

                {!ajouteAdaptation ? (
                  <BoutonDiscret
                    libelle={t.activite.adaptationAjouter}
                    onPress={() => setAjouteAdaptation(true)}
                  />
                ) : (
                  <>
                    <Pastilles
                      etiquette={t.activite.adaptationPour}
                      options={(eleves.donnees ?? []).map((e) => ({
                        id: e.id,
                        libelle: nomAffiche(e),
                      }))}
                      choisi={pourQui}
                      onChoisir={setPourQui}
                    />
                    <Champ
                      etiquette={t.activite.adaptationTexte}
                      value={texteAdaptation}
                      onChangeText={setTexteAdaptation}
                      placeholder={t.activite.adaptationIndice}
                      multiline
                      style={styles.zone}
                      editable={!occupe}
                    />
                    <BoutonSecondaire
                      libelle={t.activite.adaptationGardee}
                      onPress={() =>
                        pourQui ? garderAdaptation(pourQui, texteAdaptation, false) : undefined
                      }
                      occupe={occupe}
                    />
                    <BoutonDiscret
                      libelle={t.commun.annuler}
                      onPress={() => setAjouteAdaptation(false)}
                    />
                  </>
                )}
              </>
            ) : null}
          </Carte>

          {/* Les photos de la séance. Éditable ici (c'est SA leçon) : on peut
              retirer une photo — souvent celle de la prépa qui restait — et en
              ajouter deux-trois de l'activité réalisée, le jeu, la récitation
              (retours Mahé, Sophie). Le composant se charge et se recharge seul. */}
          <VignettesActivite activiteId={detail.id} editable />

          {erreur ? <Alerte message={erreur} /> : null}

          {faite ? (
            <Carte>
              <Text style={texte.discret}>{t.activite.dejaCloturee}</Text>
            </Carte>
          ) : (
            <>
              {/* Le geste principal suit l'état de l'activité. Une séance qui a
                  eu lieu (date passée) se clôture. Une séance sans date n'a pas
                  encore été posée dans le temps : son appel, c'est « Planifier »,
                  et il mène à l'écran où l'on choisit la date. Une séance prévue
                  dans le futur ne propose ni l'un ni l'autre : on la modifie ou
                  on la partage. */}
              {cloturable ? (
                <BoutonPrincipal
                  libelle={t.activite.cloturer}
                  onPress={() =>
                    router.push({ pathname: '/activite/cloturer/[id]', params: { id: detail.id } })
                  }
                  occupe={occupe}
                />
              ) : !detail.date ? (
                <>
                  <BoutonPrincipal
                    libelle={t.activite.planifier}
                    onPress={() =>
                      router.push({ pathname: '/activite/modifier/[id]', params: { id: detail.id } })
                    }
                    occupe={occupe}
                  />
                  <Text style={styles.aide}>{t.activite.planifierIndice}</Text>
                </>
              ) : (
                <Carte>
                  <Text style={texte.discret}>{t.activite.prevueIndice(libelleDate(detail.date))}</Text>
                </Carte>
              )}
              {/* Modifier, dupliquer et partager sont remontés en icônes dans
                  l'en-tête : ici on ne garde que le geste principal. */}
            </>
          )}
        </>
      )}
    </SousEcran>
  );
}

const ROLES: RoleAttendu[] = ['principal', 'croise', 'transversal'];

/**
 * Poser le rôle d'un attendu dans l'activité.
 *
 * 🔑 « C'est hyper important qu'on sache quelle compétence est mise et
 * pourquoi. » Le rôle s'enregistre depuis le 20/08, donc il doit aussi pouvoir
 * se corriger : ce que le modèle a proposé n'est qu'une proposition, et un
 * attendu rattaché à la main n'a aucun rôle tant que personne ne l'a dit.
 *
 * Un tap sur le rôle déjà posé le retire. Ne rien dire est une réponse valable,
 * et « rôle non précisé » vaut mieux qu'un rôle inventé dans un document qui se
 * transmet en juin.
 */
function ChoixRole({
  attendu,
  occupe,
  onChoisir,
}: {
  attendu: AttenduRattache;
  occupe: boolean;
  onChoisir: (attenduId: string, role: RoleAttendu | null) => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <View style={styles.roles}>
      {ROLES.map((r) => {
        const actif = attendu.role === r;
        return (
          <Pressable
            key={r}
            accessibilityRole="button"
            accessibilityState={{ selected: actif, disabled: occupe }}
            accessibilityLabel={`${attendu.libelle}, ${t.activite.roles[r]}`}
            disabled={occupe}
            onPress={() => onChoisir(attendu.id, actif ? null : r)}
            style={[styles.role, actif && styles.roleActif]}>
            <Text style={[styles.texteRole, actif && styles.texteRoleActif]}>
              {t.activite.roles[r]}
            </Text>
          </Pressable>
        );
      })}
    </View>
  );
}

function Ligne({ etiquette, valeur }: { etiquette: string; valeur: string }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <View style={styles.bloc}>
      <Text style={styles.etiquette}>{etiquette}</Text>
      <Text style={texte.corps}>{valeur}</Text>
    </View>
  );
}

