import AsyncStorage from '@react-native-async-storage/async-storage';
import { useEffect, useState, useSyncExternalStore } from 'react';

/**
 * L'aide in-app : de petits « ? » qui, à la demande, ouvrent LE guide de la zone
 * où l'on se trouve. Le contenu ne vit PAS dans l'app : il est mutualisé avec le
 * site (https://educooo.com/guides/), qui porte l'index cherchable et chaque
 * guide en page. L'app ne fait que CONSOMMER cette source (index.json), jamais la
 * dupliquer : un guide corrigé sur le site l'est d'un coup partout.
 *
 * 🔑 DEUX interrupteurs, à ne pas confondre :
 *
 *  1. `AIDE_ACTIVE` (ci-dessous) est le DRAPEAU MAÎTRE, décidé par nous, figé à
 *     `false`. Tant qu'il est faux, la fonctionnalité entière est invisible :
 *     aucun « ? », aucune entrée dans les réglages, aucune bulle. L'app reste
 *     identique au pixel près. Le passer à `true` suffit à tout allumer.
 *
 *  2. Le MODE AIDE (`useModeAide`/`basculerModeAide`) est l'interrupteur de
 *     l'utilisateur·rice, derrière le « ? » global. Éteint par défaut : même
 *     drapeau maître allumé, tant que le mode est éteint, AUCUNE bulle « ? »
 *     n'apparaît à côté des zones. On l'allume pour découvrir, on l'éteint pour
 *     retrouver l'app nue.
 *
 * Cette séparation garantit la contrainte forte : livrer sans rien changer, puis
 * allumer quand le client le décide, puis laisser chacun·e allumer les bulles.
 */

/**
 * Le drapeau maître. `false` = la fonctionnalité entière est éteinte et l'app
 * est identique à avant. Le passer à `true` suffit à tout brancher (le « ? »
 * global, les ancres, l'entrée des réglages). Rien d'autre à toucher.
 */
export const AIDE_ACTIVE: boolean = true;

/** La racine des guides sur le site. Une seule source, jamais recopiée ici. */
export const BASE_GUIDES = 'https://educooo.com/guides';

/** L'URL de la page complète d'un guide, à ouvrir dans le navigateur. */
export function urlGuide(slug: string): string {
  return `${BASE_GUIDES}/${slug}/`;
}

/**
 * Un guide tel que le site l'expose dans `index.json`. On ne stocke pas le corps
 * du guide (il reste en ligne) : juste de quoi le présenter et le chercher.
 */
export type Guide = {
  slug: string;
  titre: string;
  accroche: string;
  /** Le public visé (« Primaire », « Maternelle »…), tel quel depuis le site. */
  public: string;
  /** Mots-clés séparés par des virgules, pour la recherche (comme sur le site). */
  mots: string;
};

/* ────────────────────────────────────────────────────────────────────────────
   LA TABLE ZONE → SLUG

   Le seul endroit qui relie une zone de l'app à un guide du site. Centralisée et
   versionnée ici : ajouter une ancre, c'est ajouter une ligne, pas éparpiller
   des slugs en dur dans les écrans. Le slug est l'identifiant partagé avec le
   site (le dossier `/guides/<slug>/`).

   ⚠️ Certains slugs peuvent ne pas encore exister dans `index.json` (un guide
   pas encore publié). Ce n'est pas une erreur : le panneau se replie proprement
   (voir `PanneauAide`), et le guide apparaîtra dès sa mise en ligne, sans
   toucher l'app.
   ──────────────────────────────────────────────────────────────────────────── */

/** Les zones de l'app qui portent une ancre d'aide. Un id stable par zone. */
export type ZoneAide =
  | 'nouvelle-type-lecon'
  | 'journal-grille-semaine'
  | 'capter-observation';

/** La table centrale zone → slug de guide. */
export const ANCRAGES: Record<ZoneAide, string> = {
  // Le sélecteur séance/séquence de la création : « une leçon en plusieurs cours ».
  'nouvelle-type-lecon': 'lecon-en-plusieurs-cours',
  // L'en-tête de la grille de semaine du journal : planifier sa semaine.
  'journal-grille-semaine': 'planifier-semaine',
  // L'écran Capter : capter une observation.
  'capter-observation': 'capter-observation',
};

/** Le slug de guide attaché à une zone. */
export function slugDeZone(zone: ZoneAide): string {
  return ANCRAGES[zone];
}

/* ────────────────────────────────────────────────────────────────────────────
   L'INDEX DES GUIDES : fetch + cache mémoire + repli gracieux

   On lit `index.json` une fois, on le garde en mémoire pour la session. Hors
   ligne ou en cas d'erreur, on ne montre JAMAIS une erreur brutale : on retombe
   sur ce qu'on a déjà (souvent rien), et on réessaiera au prochain besoin.
   ──────────────────────────────────────────────────────────────────────────── */

let cache: Guide[] | null = null;
let enVol: Promise<Guide[]> | null = null;

/** Vrai si `x` a la forme d'un guide (garde-fou sur une source distante). */
function estGuide(x: unknown): x is Guide {
  if (typeof x !== 'object' || x === null) return false;
  const g = x as Record<string, unknown>;
  return (
    typeof g.slug === 'string' &&
    typeof g.titre === 'string' &&
    typeof g.accroche === 'string'
  );
}

/**
 * Charge l'index des guides, avec cache mémoire et déduplication des appels
 * concurrents. Ne rejette jamais : sur erreur réseau, renvoie ce qu'on a déjà
 * (ou une liste vide) sans mettre le cache en échec, pour réessayer plus tard.
 */
export async function chargerGuides(): Promise<Guide[]> {
  if (cache) return cache;
  if (enVol) return enVol;
  enVol = (async () => {
    try {
      const reponse = await fetch(`${BASE_GUIDES}/index.json`, {
        headers: { accept: 'application/json' },
      });
      if (!reponse.ok) throw new Error(`HTTP ${reponse.status}`);
      const brut: unknown = await reponse.json();
      const liste = Array.isArray(brut) ? brut.filter(estGuide) : [];
      // On ne mémorise que si on a vraiment reçu quelque chose : une liste vide
      // (site momentanément indisponible) ne doit pas se figer pour la session.
      if (liste.length) cache = liste;
      return liste;
    } catch {
      // Repli gracieux : hors-ligne ou erreur, on renvoie l'existant sans crier.
      return cache ?? [];
    } finally {
      enVol = null;
    }
  })();
  return enVol;
}

/**
 * L'index des guides pour un composant. `chargement` reste vrai tant qu'on n'a
 * pas de réponse ET pas de cache : un écran peut afficher un indicateur discret.
 */
export function useGuides(): { guides: Guide[]; chargement: boolean } {
  const [guides, setGuides] = useState<Guide[]>(cache ?? []);
  const [chargement, setChargement] = useState<boolean>(cache === null);

  useEffect(() => {
    let vivant = true;
    // Cache déjà là au premier rendu : l'état initial le porte. Sinon (ou s'il
    // s'est rempli entre-temps), `chargerGuides` le rend sans refaire d'appel.
    chargerGuides().then((liste) => {
      if (!vivant) return;
      setGuides(liste);
      setChargement(false);
    });
    return () => {
      vivant = false;
    };
  }, []);

  return { guides, chargement };
}

/** Un guide par son slug, chargé via l'index (null si absent ou pas encore là). */
export function useGuide(slug: string | null): { guide: Guide | null; chargement: boolean } {
  const { guides, chargement } = useGuides();
  const guide = slug ? (guides.find((g) => g.slug === slug) ?? null) : null;
  return { guide, chargement };
}

/**
 * Filtre les guides sur une recherche libre, comme la recherche du site : on
 * cherche dans le titre, l'accroche et les mots-clés, insensible à la casse et
 * aux accents. Une requête vide renvoie tout.
 */
export function chercherGuides(guides: Guide[], requete: string): Guide[] {
  const q = normaliser(requete).trim();
  if (!q) return guides;
  const termes = q.split(/\s+/);
  return guides.filter((g) => {
    const foin = normaliser(`${g.titre} ${g.accroche} ${g.mots}`);
    return termes.every((terme) => foin.includes(terme));
  });
}

/** Minuscule + sans accents, pour une recherche tolérante. */
function normaliser(s: string): string {
  return s
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

/* ────────────────────────────────────────────────────────────────────────────
   LE MODE AIDE : l'interrupteur de l'utilisateur·rice

   Un état partagé par toute l'app (les bulles « ? » apparaissent d'un coup sur
   tous les écrans), sans monter de fournisseur : un petit magasin externe lu par
   `useSyncExternalStore`. Le choix est persisté par appareil, comme les coach
   marks. Éteint par défaut : l'app reste nue tant qu'on ne le demande pas.
   ──────────────────────────────────────────────────────────────────────────── */

const CLE_MODE = 'educooo:aide:mode';

let modeActif = false;
let luDepuisDisque = false;
const abonnes = new Set<() => void>();

function emettre() {
  abonnes.forEach((f) => f());
}

/** Lit le choix mémorisé une seule fois. Silencieux : au pire, on reste éteint. */
async function lireModeUneFois() {
  // Drapeau maître éteint : on ne touche même pas au stockage. Rien ne change.
  if (!AIDE_ACTIVE) return;
  if (luDepuisDisque) return;
  luDepuisDisque = true;
  try {
    if ((await AsyncStorage.getItem(CLE_MODE)) === '1') {
      modeActif = true;
      emettre();
    }
  } catch {
    // Stockage illisible : on garde le mode éteint, déjà en place.
  }
}

/**
 * Le mode aide est-il allumé ? Réactif : tout composant qui appelle ce hook se
 * remet à jour quand on bascule le mode, où que soit le « ? » global.
 */
export function useModeAide(): boolean {
  useEffect(() => {
    void lireModeUneFois();
  }, []);
  return useSyncExternalStore(
    (cb) => {
      abonnes.add(cb);
      return () => {
        abonnes.delete(cb);
      };
    },
    () => modeActif,
    () => modeActif,
  );
}

/** Allume/éteint le mode aide, et mémorise le choix (sans bloquer). */
export function basculerModeAide(): void {
  modeActif = !modeActif;
  luDepuisDisque = true;
  emettre();
  AsyncStorage.setItem(CLE_MODE, modeActif ? '1' : '0').catch(() => {
    // Écriture ratée sans gravité : le mode est déjà appliqué pour la session.
  });
}
