import { router, useLocalSearchParams } from 'expo-router';
import { useMemo, useState } from 'react';
import { StyleSheet, Text } from 'react-native';

import { Carte } from '@/components/ecran';
import {
  Alerte,
  BoutonDiscret,
  BoutonPrincipal,
  BoutonSecondaire,
  Champ,
  Pastilles,
} from '@/components/formulaire';
import { SelecteurJoursMenu } from '@/components/selecteur-jours-menu';
import { SelecteurMoment } from '@/components/selecteur-moment';
import { SousEcran } from '@/components/sous-ecran';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import {
  cleMoment,
  creneauPourMoment,
  creneauxDe,
  detailActivite,
  modifierActivite,
  planifierActivite,
  projetsDe,
  rangerDansProjet,
  supprimerActivite,
} from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { police, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Modifier, déplacer, supprimer une séance.
 *
 * Cet écran manquait, et c'était le trou le plus bête : l'app savait créer,
 * planifier et clôturer, elle ne savait pas **corriger**. Une enseignante qui
 * se trompait de date n'avait aucun recours, et sur un atelier récurrent la
 * même erreur laisse douze lignes intouchables.
 *
 * 🔑 **Les attendus ne se modifient pas ici.** Ils se rattachent un par un sur
 * la fiche, parce que chacun porte un rôle : remplacer la liste d'un bloc
 * effacerait des rôles sans le dire.
 *
 * ⚠️ Une séance clôturée ne s'ouvre pas ici. Elle a écrit des constats dans le
 * dossier d'enfants, et les défaire est un geste distinct, plus rare, qui
 * mérite son propre écran le jour où il existera.
 */

const GROUPEMENTS = ['classe', 'petit_groupe', 'binome', 'individuel'] as const;

function jourIso(dateIso: string): number {
  const [a, m, j] = dateIso.split('-').map((n) => parseInt(n, 10));
  const jour = new Date(a, m - 1, j).getDay();
  return jour === 0 ? 7 : jour;
}

export default function ModifierActivite() {
  const couleurs = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(couleurs), [couleurs]);
  const { id } = useLocalSearchParams<{ id: string }>();
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;

  const activite = useRequete(() => detailActivite(id), [id]);
  const creneaux = useRequete(() => creneauxDe(classeId!), [classeId], { actif: !!classeId });
  const projets = useRequete(() => projetsDe(classeId!), [classeId], { actif: !!classeId });
  const detail = activite.donnees;

  const [titre, setTitre] = useState('');
  const [description, setDescription] = useState('');
  const [objectif, setObjectif] = useState('');
  const [materiel, setMateriel] = useState('');
  const [organisation, setOrganisation] = useState('');
  const [lieu, setLieu] = useState('');
  const [duree, setDuree] = useState('');
  const [groupement, setGroupement] = useState<string | null>(null);
  // Ranger dans un projet est un geste rare : il vit dans les détails, pas
  // dans la forme courte. « Personne ne le fait deux fois par jour. »
  const [projetId, setProjetId] = useState<string | null>(null);
  const [quand, setQuand] = useState<string | null>(null);
  const [creneauId, setCreneauId] = useState<string | null>(null);
  const [details, setDetails] = useState(false);
  const [aSupprimer, setASupprimer] = useState(false);
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);

  // On remplit les champs quand la fiche arrive, une seule fois : les remplir à
  // chaque rendu écraserait ce qu'elle est en train de taper. On le fait au
  // rendu où la fiche change (schéma React « ajuster l'état quand une prop
  // change ») : la fiche déjà recopiée est gardée en état pour comparer.
  const [ficheRecopiee, setFicheRecopiee] = useState<typeof detail>(null);
  if (detail && detail !== ficheRecopiee) {
    setFicheRecopiee(detail);
    setTitre(detail.titre);
    setDescription(detail.description ?? '');
    setObjectif(detail.objectif ?? '');
    setMateriel(detail.materiel ?? '');
    setOrganisation(detail.organisation ?? '');
    setLieu(detail.lieu ?? '');
    setDuree(detail.duree ? String(detail.duree) : '');
    setGroupement(detail.groupement);
    setQuand(detail.date);
    setCreneauId(detail.creneauId);
    setProjetId(detail.projetId);
    setDetails(
      !!(
        detail.objectif ||
        detail.materiel ||
        detail.organisation ||
        detail.lieu ||
        detail.duree ||
        detail.projetId
      ),
    );
  }

  const creneauxDuJour = (creneaux.donnees ?? []).filter((c) => !quand || c.jour === jourIso(quand));
  const serie = detail ? detail.serie.length + 1 : 1;

  async function enregistrer() {
    if (!detail) return;
    setErreur(null);
    setOccupe(true);
    try {
      await modifierActivite({
        activiteId: detail.id,
        titre,
        description,
        objectif,
        materiel,
        organisation,
        lieu,
        groupement,
        duree: duree.trim() ? parseInt(duree.trim(), 10) : null,
      });
      // La date part par le même chemin que la planification initiale : une
      // seule fonction sait ce qu'une date implique pour le statut.
      if (quand !== detail.date || creneauId !== detail.creneauId) {
        await planifierActivite({ activiteId: detail.id, date: quand, creneauId });
      }
      if (projetId !== detail.projetId) {
        await rangerDansProjet({ activiteId: detail.id, projetId });
      }
      router.replace({ pathname: '/activite/[id]', params: { id: detail.id } });
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.activite.erreurModification);
    } finally {
      setOccupe(false);
    }
  }

  async function supprimer(touteLaSerie: boolean) {
    if (!detail) return;
    setErreur(null);
    setOccupe(true);
    try {
      await supprimerActivite({ activiteId: detail.id, touteLaSerie });
      // On revient au journal : la fiche qu'on vient de supprimer n'a plus rien
      // à montrer, et y retourner afficherait « cette activité n'existe plus ».
      router.dismissAll();
      router.replace('/journal');
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.activite.erreurSuppression);
    } finally {
      setOccupe(false);
    }
  }

  return (
    <SousEcran titre={t.activite.modifierTitre} chargement={activite.chargement}>
      {!detail ? (
        <Carte>
          <Text style={texte.discret}>{t.activite.introuvable}</Text>
        </Carte>
      ) : (
        <>
          {/* Séance clôturée : on PRÉVIENT (elle a écrit des constats) mais on ne
              bloque plus. Corriger un titre ou une date, ou supprimer un doublon
              clôturé par erreur, doit rester possible après clôture (retour Mahé). */}
          {detail.statut === 'completed' ? (
            <Carte>
              <Text style={texte.discret}>{t.activite.dejaCloturee}</Text>
              <Text style={styles.aide}>{t.activite.clotureeCorrigeable}</Text>
            </Carte>
          ) : null}

          <Carte>
            <Champ
              etiquette={t.activite.quoi}
              value={titre}
              onChangeText={setTitre}
              editable={!occupe}
            />
            <Champ
              etiquette={t.activite.description}
              value={description}
              onChangeText={setDescription}
              multiline
              style={styles.zone}
              editable={!occupe}
            />
          </Carte>

          {/* Déplacer. C'est le geste pour lequel cet écran existe. */}
          <Carte>
            <Text style={styles.etiquette}>{t.activite.quand}</Text>
            {/* Un vrai calendrier, passé et futur sans borne (retour Sophie 18/09 :
                les pastilles ne montraient que quelques jours autour d'aujourd'hui). */}
            <SelecteurJoursMenu
              unique
              choisis={quand ? [quand] : []}
              onBasculer={(d) => {
                // On garde le MÊME moment si le nouveau jour l'a : déplacer une
                // leçon de mardi 8:20 à jeudi 8:20 se fait en un geste.
                const actuel = (creneaux.donnees ?? []).find((c) => c.id === creneauId);
                const cle = actuel ? cleMoment(actuel) : null;
                const meme = cle ? creneauPourMoment(creneaux.donnees ?? [], jourIso(d), cle) : null;
                setQuand(d);
                setCreneauId(meme);
              }}
            />
            <BoutonDiscret
              libelle={t.activite.pasEncore}
              onPress={() => {
                setQuand(null);
                setCreneauId(null);
              }}
            />

            {quand && creneauxDuJour.length ? (
              <SelecteurMoment
                etiquette={t.activite.moment}
                options={creneauxDuJour.map((c) => ({
                  cle: c.id,
                  debut: c.debut,
                  fin: c.fin,
                  libelle: c.libelle,
                }))}
                choisi={creneauId}
                onChoisir={setCreneauId}
              />
            ) : null}
            {quand && !creneaux.chargement && creneauxDuJour.length === 0 ? (
              <Text style={styles.aide}>{t.activite.momentAucun}</Text>
            ) : null}
          </Carte>

          {!details ? (
            <BoutonDiscret libelle={t.activite.plusDeDetails} onPress={() => setDetails(true)} />
          ) : (
            <Carte>
              <Champ
                etiquette={t.activite.objectif}
                value={objectif}
                onChangeText={setObjectif}
                multiline
                style={styles.zone}
                editable={!occupe}
              />
              <Champ
                etiquette={t.activite.materiel}
                value={materiel}
                onChangeText={setMateriel}
                multiline
                style={styles.zone}
                editable={!occupe}
              />
              <Champ
                etiquette={t.activite.organisation}
                value={organisation}
                onChangeText={setOrganisation}
                multiline
                style={styles.zone}
                editable={!occupe}
              />
              <Champ
                etiquette={t.activite.lieu}
                value={lieu}
                onChangeText={setLieu}
                editable={!occupe}
              />
              <Champ
                etiquette={t.activite.duree}
                value={duree}
                onChangeText={(v) => setDuree(v.replace(/[^0-9]/g, ''))}
                keyboardType="number-pad"
                editable={!occupe}
              />
              <Pastilles
                etiquette={t.activite.groupement}
                options={GROUPEMENTS.map((g) => ({ id: g, libelle: t.activite.groupements[g] }))}
                choisi={groupement}
                onChoisir={setGroupement}
              />
              {(projets.donnees ?? []).length ? (
                <Pastilles
                  etiquette={t.projet.ranger}
                  options={(projets.donnees ?? []).map((p) => ({ id: p.id, libelle: p.titre }))}
                  choisi={projetId}
                  onChoisir={setProjetId}
                />
              ) : null}
            </Carte>
          )}

          {erreur ? <Alerte message={erreur} /> : null}

          <BoutonPrincipal
            libelle={t.activite.enregistrer}
            onPress={enregistrer}
            occupe={occupe}
            inactif={!titre.trim()}
          />

          {/* La suppression se confirme, et jamais derrière une icône seule :
              une poubelle se tape par erreur, une phrase non. */}
          {!aSupprimer ? (
            <BoutonDiscret libelle={t.activite.supprimer} onPress={() => setASupprimer(true)} />
          ) : (
            <Carte>
              <Text style={styles.aide}>{t.activite.supprimerPourquoi}</Text>
              <BoutonSecondaire
                libelle={t.activite.supprimerSeance}
                onPress={() => supprimer(false)}
                occupe={occupe}
              />
              {serie > 1 ? (
                <>
                  <BoutonSecondaire
                    libelle={t.activite.supprimerSerie(serie)}
                    onPress={() => supprimer(true)}
                    occupe={occupe}
                  />
                  {detail.serie.some((s) => s.statut === 'completed') ? (
                    <Text style={styles.aide}>
                      {t.activite.supprimerGardees(
                        detail.serie.filter((s) => s.statut === 'completed').length,
                      )}
                    </Text>
                  ) : null}
                </>
              ) : null}
              <BoutonDiscret libelle={t.activite.annuler} onPress={() => setASupprimer(false)} />
            </Carte>
          )}
        </>
      )}
    </SousEcran>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  aide: { fontFamily: police.corps, fontSize: 14, color: c.encreDouce },
  etiquette: { fontFamily: police.accent, fontSize: 14, color: c.encreDouce },
  zone: { minHeight: 88, textAlignVertical: 'top' },
});
