import { router } from 'expo-router';
import { useMemo, useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';

import {
  EnteteTableau,
  PanneauDetail,
  SelecteurPeriodes,
  TableauDirection,
  type FiltreDetail,
} from '@/components/direction/tableau';
import { Carte } from '@/components/ecran';
import { BoutonSecondaire, Pastilles } from '@/components/formulaire';
import { t } from '@/i18n';
import { chargerPeriodes, detailDirection, mesEcolesDirection, tableauDirection } from '@/lib/direction';
import { BACKEND_ABSENT } from '@/lib/etablissement';
import { bornesPeriode, indexPeriodeCourante, rythme as rythmeDe, type ModePeriode } from '@/lib/periodes';
import { useRequete } from '@/lib/requete';
import { espace, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Le tableau direction branché sur les vraies données (compte direction ou
 * admin, écoles approuvées). La vraie garde est côté serveur : cet écran ne
 * fait que présenter ce que les fonctions veulent bien renvoyer.
 *
 * 🔑 Une direction peut avoir plusieurs écoles approuvées (le PO de Benjamin en
 * préside onze, hors périmètre v1) : on propose alors un choix, une école à la
 * fois, parce qu'une matrice qui mélange deux écoles ne se lit pas.
 */
export function VueDirectionConnectee() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const V = t.vueDirection;

  const ecoles = useRequete(mesEcolesDirection, []);
  const [choisie, setChoisie] = useState<string | null>(null);
  const ecole = (ecoles.donnees ?? []).find((e) => e.id === choisie) ?? ecoles.donnees?.[0] ?? null;

  // Les périodes de CETTE école : surcharge de la direction, sinon calendrier
  // officiel de sa juridiction, sinon trimestres. Lues en données, jamais codées.
  const periodes = useRequete(() => chargerPeriodes({ ecole: ecole!.id }), [ecole?.id], { actif: !!ecole });
  const liste = useMemo(() => periodes.donnees ?? [], [periodes.donnees]);
  const [choixIndex, setIndex] = useState<number | null>(null);
  const index = choixIndex ?? indexPeriodeCourante(liste);
  const [mode, setMode] = useState<ModePeriode>('cumul');
  const bornes = useMemo(() => bornesPeriode(liste, index, mode), [liste, index, mode]);
  const rythme = rythmeDe(liste, index, mode);

  const synthese = useRequete(
    () => tableauDirection(ecole?.id ?? null, bornes.debut, bornes.fin),
    [ecole?.id, bornes.debut, bornes.fin],
    { actif: !!ecole && liste.length > 0 },
  );

  const [filtre, setFiltre] = useState<FiltreDetail | null>(null);
  // Pas de mémoïsation : le panneau ne relance la lecture que sur un nouveau filtre.
  const charger = (f: FiltreDetail) =>
      detailDirection({
        ecole: ecole?.id ?? null,
        debut: bornes.debut,
        fin: bornes.fin,
        classe: f.classe?.id ?? null,
        discipline: f.discipline ?? null,
      });

  const backendAbsent = ecoles.erreur === BACKEND_ABSENT || synthese.erreur === BACKEND_ABSENT;
  if (backendAbsent) {
    return (
      <Carte>
        <Text style={texte.discret}>{V.bientot}</Text>
        <View style={styles.espaceHaut}>
          <BoutonSecondaire libelle={V.demoVoir} onPress={() => router.push('/direction/demo')} />
        </View>
      </Carte>
    );
  }

  return (
    <View style={styles.pile}>
      <EnteteTableau ecole={ecole ? { nom: ecole.nom, commune: ecole.commune } : null}>
        {liste.length ? (
          <SelecteurPeriodes periodes={liste} index={index} mode={mode} onIndex={setIndex} onMode={setMode} />
        ) : null}
      </EnteteTableau>
      {(ecoles.donnees ?? []).length > 1 ? (
        <Pastilles
          etiquette={V.ecole}
          options={(ecoles.donnees ?? []).map((e) => ({ id: e.id, libelle: e.nom }))}
          choisi={ecole?.id ?? null}
          onChoisir={(id) => id && setChoisie(id)}
        />
      ) : null}

      {synthese.erreur && !backendAbsent ? (
        <Carte>
          <Text style={texte.discret}>{V.erreur}</Text>
          <View style={styles.espaceHaut}>
            <BoutonSecondaire libelle={V.reessayer} onPress={synthese.recharger} />
          </View>
        </Carte>
      ) : null}

      {synthese.donnees && synthese.donnees.classes.length === 0 ? (
        <Carte>
          <Text style={texte.corps}>{V.aucuneClasse}</Text>
        </Carte>
      ) : null}

      {synthese.donnees && synthese.donnees.classes.length > 0 ? (
        <TableauDirection synthese={synthese.donnees} rythme={rythme} onDetail={setFiltre} />
      ) : null}

      {/* Le code d'école : c'est lui qui fait entrer une classe dans ce tableau,
          et c'est la prof qui le saisit. Montré en bas, une fois le tableau lu. */}
      {ecole?.code ? (
        <Carte>
          <Text style={texte.section}>{V.codeTitre}</Text>
          <Text selectable style={styles.code}>
            {ecole.code.slice(0, 4)} {ecole.code.slice(4)}
          </Text>
          <Text style={texte.discret}>{V.codeAide}</Text>
        </Carte>
      ) : null}

      <PanneauDetail filtre={filtre} charger={charger} onFermer={() => setFiltre(null)} />
    </View>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    pile: { gap: espace.md },
    espaceHaut: { marginTop: espace.sm },
    code: {
      fontFamily: police.titre,
      fontSize: 28,
      letterSpacing: 4,
      color: c.encre,
      backgroundColor: c.actionTeinte,
      borderRadius: rayon.bloc,
      paddingVertical: espace.sm,
      paddingHorizontal: espace.md,
      alignSelf: 'flex-start',
      marginVertical: espace.sm,
    },
  });
