import { router, useFocusEffect } from 'expo-router';
import { useCallback, useMemo, useState } from 'react';
import { Linking, Platform, Pressable, StyleSheet, Text, View } from 'react-native';

import {
  BandeauDemo,
  CadreDirection,
  EnteteTableau,
  PanneauDetail,
  SelecteurPeriodes,
  TableauDirection,
  type FiltreDetail,
} from '@/components/direction/tableau';
import { Carte } from '@/components/ecran';
import { BoutonSecondaire } from '@/components/formulaire';
import { t } from '@/i18n';
import { detailDemo, ECOLE_DEMO, periodesDemo, syntheseDemo } from '@/lib/direction-demo';
import { useLargeurWeb } from '@/lib/largeur-web';
import { rythme as rythmeDe, type ModePeriode } from '@/lib/periodes';
import { useSession } from '@/lib/session';
import { espace, police, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * La vue direction en DÉMONSTRATION, pensée comme un LIEN PUBLIC à envoyer à
 * une direction (on ne remplit jamais un vrai compte de fausses données).
 *
 * 🔑 Accessible SANS compte : la route est déclarée hors de toute garde dans
 * `_layout`, et la barre d'onglets web s'efface sur `/direction/…demo`. Rien
 * ici ne touche le serveur : tout vient de `direction-demo.ts` (libellés FWB
 * réels, chiffres inventés à graine fixe), aucune donnée réelle ne peut fuiter.
 *
 * 🔑 Étiquetée partout : bandeau FIXE (hors défilement) sur l'écran, sur le
 * détail et sur le miroir de démonstration.
 *
 * 🔑 L'appel à l'action est un LIEN vers educooo.com/direction (la page qui
 * présente l'offre aux directions), pas un mailto : un directeur qui ouvre le
 * lien sur son téléphone n'a pas forcément de messagerie configurée, et la page
 * porte déjà le formulaire de contact et le discours. Discret, en bas.
 */
export default function DirectionDemo() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { session } = useSession();
  const V = t.vueDirection;

  // « Noël → Carnaval » par défaut : une demi-année de recul se lit mieux que
  // trois semaines de rentrée (c'est aussi le « 2e trimestre » de la maquette).
  const [index, setIndex] = useState(2);
  const [mode, setMode] = useState<ModePeriode>('cumul');
  const periodes = useMemo(() => periodesDemo(index), [index]);
  const synthese = useMemo(() => syntheseDemo(index, mode), [index, mode]);
  const rythme = rythmeDe(periodes, index, mode);
  const [filtre, setFiltre] = useState<FiltreDetail | null>(null);

  const { setPleine } = useLargeurWeb();
  useFocusEffect(
    useCallback(() => {
      setPleine(Platform.OS === 'web');
      return () => setPleine(false);
    }, [setPleine]),
  );

  // Arrivé·e par un lien direct (pas d'historique) : on renvoie vers l'entrée
  // qui a du sens, l'app si on est connecté·e, la page directions sinon.
  const retour = () => {
    if (router.canGoBack()) router.back();
    else if (session) router.replace('/');
    else void Linking.openURL('https://educooo.com/direction');
  };

  return (
    <CadreDirection titre={V.demoTitre} auRetour={retour} bandeau={<BandeauDemo />}>
      <EnteteTableau ecole={ECOLE_DEMO}>
        <SelecteurPeriodes periodes={periodes} index={index} mode={mode} onIndex={setIndex} onMode={setMode} />
      </EnteteTableau>
      <TableauDirection synthese={synthese} rythme={rythme} onDetail={setFiltre} />

      {/* La transparence, montrée et pas seulement promise : le miroir d'une
          classe de la démo, tel que l'enseignant·e le voit dans son app. */}
      <Carte>
        <Text style={texte.section}>{V.demoMiroirTitre}</Text>
        <Text style={[texte.discret, styles.espace]}>{V.demoMiroirCorps}</Text>
        <BoutonSecondaire
          libelle={V.demoMiroirBouton}
          onPress={() => router.push({ pathname: '/direction/demo-miroir', params: { periode: String(index) } })}
        />
      </Carte>

      <View style={styles.cta}>
        <Text style={texte.discret}>{V.demoCta}</Text>
        <Pressable
          accessibilityRole="link"
          accessibilityLabel={V.demoCtaLien}
          onPress={() => void Linking.openURL('https://educooo.com/direction')}>
          <Text style={styles.lien}>{V.demoCtaLien}</Text>
        </Pressable>
      </View>

      <PanneauDetail
        demo
        filtre={filtre}
        charger={async (f) => detailDemo(index, mode, { classe: f.classe?.id ?? null, discipline: f.discipline ?? null })}
        onFermer={() => setFiltre(null)}
      />
    </CadreDirection>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    espace: { marginVertical: espace.sm },
    cta: { alignItems: 'center', gap: espace.xs, paddingVertical: espace.lg },
    lien: { fontFamily: police.accent, fontSize: 15, color: c.actif, textDecorationLine: 'underline' },
  });
