import AsyncStorage from '@react-native-async-storage/async-storage';
import Constants from 'expo-constants';
import * as StoreReview from 'expo-store-review';
import { Linking } from 'react-native';

/**
 * Demander un avis sur les stores, au bon moment.
 *
 * 🔑 Le principe : un avis ne se quémande pas au démarrage ni en rafale. On ne
 * le demande qu'après un vrai « moment wow » (une célébration, un résultat qui
 * a aidé), quand l'enseignant·e ressent quelque chose de positif. C'est là que
 * l'avis est sincère ET généreux.
 *
 * 🔑 Trois garde-fous se cumulent :
 *   1. L'OS d'Apple/Google limite déjà le nombre de pop-ups par an. On ne le
 *      contourne pas, on l'aide : on ne déclenche que sur un moment choisi.
 *   2. On ne redemande jamais pour la même VERSION de l'app. Une fois la
 *      version courante marquée, plus aucune demande jusqu'à la prochaine mise
 *      à jour (Apple recommande exactement ça).
 *   3. Une « maturité » minimale : on attend un petit nombre de moments
 *      positifs avant la première demande, pour ne pas surgir chez quelqu'un
 *      qui découvre à peine l'app.
 *
 * 🔑 Tolérance aux erreurs : demander un avis est un bonus, jamais un risque.
 * Toute erreur (stockage, module natif indisponible) est avalée en silence.
 * Un avis raté ne doit jamais faire planter l'app.
 */

/** La clé du compteur de « moments positifs » vécus, tous cumulés. */
const CLE_COMPTEUR = 'educooo.avis.compteur';

/** La clé de la dernière version d'app pour laquelle on a DÉJÀ demandé un avis. */
const CLE_VERSION_DEMANDEE = 'educooo.avis.version';

/**
 * Combien de moments positifs avant la toute première demande.
 *
 * 🔑 On laisse le temps de sentir la valeur : trois beaux moments, c'est assez
 * pour que l'app ait déjà rendu service, sans faire attendre indéfiniment.
 */
const SEUIL_MATURITE = 3;

/** La version courante de l'app, ou une chaîne neutre si elle manque. */
function versionCourante(): string {
  return Constants.expoConfig?.version ?? 'inconnue';
}

/** Lit un entier stocké, en retombant sur 0 au moindre doute (première fois, valeur abîmée). */
async function lireEntier(cle: string): Promise<number> {
  try {
    const brut = await AsyncStorage.getItem(cle);
    const n = brut ? parseInt(brut, 10) : 0;
    return Number.isFinite(n) ? n : 0;
  } catch {
    return 0;
  }
}

/**
 * Demander un avis SI, et seulement si, toutes les conditions sont réunies.
 *
 * On appelle ceci depuis un « moment wow ». La fonction vérifie elle-même :
 *   - que le module natif est disponible (`isAvailableAsync`),
 *   - qu'on peut vraiment ouvrir un flux d'avis (`hasAction` : les URLs de
 *     store sont bien configurées ou le natif sait faire),
 *   - qu'on n'a pas déjà demandé pour la version courante,
 *   - que la maturité minimale est atteinte.
 *
 * @param moment Un libellé du moment déclencheur (ex. « semaine-bouclee »).
 *   Sert de trace lisible ; il documente le POURQUOI de la demande.
 */
export async function demanderAvisSiOpportun(moment: string): Promise<void> {
  try {
    // Le natif doit être là. Sur le web, ou en TestFlight, ça répond faux.
    const disponible = await StoreReview.isAvailableAsync();
    if (!disponible) return;

    // Y a-t-il vraiment un flux d'avis à ouvrir ? Sans URLs de store et sans
    // capacité native, inutile de tenter : on éviterait un clic dans le vide.
    const peutAgir = await StoreReview.hasAction();
    if (!peutAgir) return;

    // Un seul avis par version : si on a déjà demandé pour celle-ci, on se tait.
    const version = versionCourante();
    const versionDejaDemandee = await AsyncStorage.getItem(CLE_VERSION_DEMANDEE);
    if (versionDejaDemandee === version) return;

    // Maturité : assez de moments positifs derrière soi ?
    const compteur = await lireEntier(CLE_COMPTEUR);
    if (compteur < SEUIL_MATURITE) return;

    // Tout est vert : on marque la version AVANT de demander. Ainsi, même si le
    // pop-up est ensuite ignoré par l'OS, on ne reviendra pas à la charge pour
    // cette version. Le libellé `moment` reste disponible pour d'éventuels logs.
    void moment;
    await AsyncStorage.setItem(CLE_VERSION_DEMANDEE, version);
    await StoreReview.requestReview();
  } catch {
    // Un avis ne vaut jamais un crash. On avale l'erreur en silence.
  }
}

/**
 * Enregistrer un « moment positif » et, si le seuil est franchi, tenter la
 * demande d'avis dans la foulée.
 *
 * 🔑 C'est LE point d'entrée à câbler dans les écrans. Chaque appel incrémente
 * le compteur de maturité ; quand le compteur atteint le seuil, on enchaîne sur
 * `demanderAvisSiOpportun`. On garde la logique volontairement simple : un
 * compteur qui monte, un seuil, une demande au plus par version.
 *
 * @param moment Un libellé du moment vécu (ex. « rattachement-ia »,
 *   « lecon-generee »). Purement descriptif, pour la lisibilité.
 */
export async function noterMomentPositif(moment: string): Promise<void> {
  try {
    const compteur = (await lireEntier(CLE_COMPTEUR)) + 1;
    await AsyncStorage.setItem(CLE_COMPTEUR, String(compteur));
  } catch {
    // Si l'incrément échoue, on tente quand même la demande : au pire elle ne
    // passera pas les garde-fous. Mieux vaut ça qu'avaler un vrai moment wow.
  }
  await demanderAvisSiOpportun(moment);
}

/**
 * Amener explicitement vers l'écriture d'un avis, à la demande de l'utilisateur.
 *
 * 🔑 Ceci n'est PAS la demande discrète : c'est le bouton « Nous noter » des
 * réglages, où tu choisis toi-même d'aller écrire. On ouvre donc directement la
 * fiche du store (`storeUrl`), sans compteur ni garde-fou de version : ici,
 * c'est toi qui décides, autant de fois que tu veux.
 */
export async function ouvrirAvisEcrit(): Promise<void> {
  try {
    const url = StoreReview.storeUrl();
    if (url) {
      await Linking.openURL(url);
    }
  } catch {
    // Ouvrir une fiche de store ne doit jamais planter l'app non plus.
  }
}
