import { router } from 'expo-router';
import { StyleSheet, View } from 'react-native';

import { Cloudy } from '@/components/cloudy';
import { ComposerObservation } from '@/components/composer-observation';
import { SousEcran } from '@/components/sous-ecran';
import { t } from '@/i18n';
import { espace } from '@/theme/tokens';

/**
 * La capture rapide, en modale, ouverte d'un appui long sur l'onglet micro
 * depuis n'importe quel écran d'onglet. Elle tient la promesse « capte en un
 * mot » PARTOUT, sans avoir à revenir sur l'onglet Capter.
 *
 * 🚨 Elle monte EXACTEMENT la même composition que l'onglet Capter
 * (`ComposerObservation`) : même dictée, même champ, même `creerObservation`,
 * donc la même et unique surface de masquage. Aucun chemin dupliqué.
 *
 * Elle range et se ferme au retour : ranger renvoie là d'où l'on vient, et le
 * geste de retour de la barre referme la modale sans rien enregistrer.
 */
export default function CapterVite() {
  return (
    <SousEcran titre={t.capter.titre}>
      {/* Cloudy micro, sobre, en tête : elle rappelle qu'on est dans le geste de
          capture, sans voler la vedette au bouton de dictée. */}
      <View style={styles.tete}>
        <Cloudy pose="micro" taille={64} anime />
      </View>
      <ComposerObservation onEnregistre={() => router.back()} />
    </SousEcran>
  );
}

const styles = StyleSheet.create({
  tete: { alignItems: 'center', paddingTop: espace.xs },
});
