import { router } from 'expo-router';
import { useMemo, useState } from 'react';
import { StyleSheet, Text } from 'react-native';

import { Carte } from '@/components/ecran';
import { Alerte, BoutonPrincipal, Champ } from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { t } from '@/i18n';
import { monProfil, renommerProfil } from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { police, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Le profil, et volontairement pauvre.
 *
 * Un nom, et l'adresse en lecture. Pas d'avatar (il vit dans « Moi »), pas de
 * langue : la langue d'interface se règle à UN seul endroit, dans Réglages
 * (avec rechargement de l'app). Un deuxième sélecteur ici écrivait la même
 * colonne `profiles.langue` sans recharger et proposait des langues non servies
 * (de/en) : les deux se contredisaient. On garde la source unique.
 *
 * L'adresse ne se change pas ici parce qu'elle sert à se connecter : la changer
 * demande de vérifier la nouvelle, donc c'est un parcours, pas un champ.
 */
export default function Profil() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const profil = useRequete(monProfil, []);
  const [nom, setNom] = useState('');
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);
  const [enregistre, setEnregistre] = useState(false);

  // On préremplit le nom quand le profil arrive, au rendu où la réponse change
  // (pas à chaque rendu, ce qui écraserait la frappe).
  const [profilSource, setProfilSource] = useState<typeof profil.donnees>(null);
  if (profil.donnees !== profilSource) {
    setProfilSource(profil.donnees);
    if (profil.donnees) setNom(profil.donnees.nom ?? '');
  }

  async function enregistrer() {
    setErreur(null);
    setOccupe(true);
    try {
      await renommerProfil(nom);
      setEnregistre(true);
      router.back();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.profil.erreur);
    } finally {
      setOccupe(false);
    }
  }

  return (
    <SousEcran titre={t.profil.titre} chargement={profil.chargement}>
      <Carte>
        <Champ
          etiquette={t.profil.nom}
          value={nom}
          onChangeText={(v) => {
            setNom(v);
            setEnregistre(false);
          }}
          placeholder={t.profil.nomIndice}
          editable={!occupe}
        />
        <Text style={styles.aide}>{t.profil.nomPourquoi}</Text>
      </Carte>

      <Carte>
        <Text style={styles.etiquette}>{t.profil.email}</Text>
        <Text style={texte.corps}>{profil.donnees?.email ?? ''}</Text>
        <Text style={styles.aide}>{t.profil.emailFige}</Text>
      </Carte>

      {erreur ? <Alerte message={erreur} /> : null}
      {enregistre ? <Text style={styles.aide}>{t.profil.enregistre}</Text> : null}

      <BoutonPrincipal libelle={t.profil.enregistrer} onPress={enregistrer} occupe={occupe} />
    </SousEcran>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  aide: { fontFamily: police.corps, fontSize: 14, color: c.encreDouce },
  etiquette: { fontFamily: police.accent, fontSize: 14, color: c.encreDouce },
});
