import { router } from 'expo-router';
import { useMemo } from 'react';
import { StyleSheet, Text, View } from 'react-native';

import { Cloudy } from '@/components/cloudy';
import { Carte } from '@/components/ecran';
import { BoutonPrincipal } from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import { elevesDe } from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * La passation de juin : un mini-pitch honnête, pas la fonctionnalité.
 *
 * 🚨 Rien de faux, aucun bouton mort. On dit ce que la passation FERA (réunir
 * le dossier de chaque élève pour la collègue suivante) et on cadre clairement
 * « à venir ». Le seul geste possible mène à quelque chose qui MARCHE déjà : la
 * synthèse d'un élève, qui existe sur sa fiche et qui est exactement la brique
 * de la passation. On ne promet donc pas un bouton qui ne fait rien : on renvoie
 * vers la seule part de la passation qui est réelle aujourd'hui.
 */
export default function PassationEcran() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;
  const eleves = useRequete(() => elevesDe(classeId!), [classeId], { actif: !!classeId });
  const aDesEleves = (eleves.donnees ?? []).length > 0;

  return (
    <SousEcran titre={t.passation.titre}>
      <Carte>
        <View style={styles.hero}>
          <Cloudy pose="joie" taille={64} />
          <View style={styles.heroTexte}>
            <View style={styles.badge}>
              <Text style={styles.badgeTexte}>{t.passation.aVenir}</Text>
            </View>
            <Text style={texte.corps}>{t.passation.intro}</Text>
          </View>
        </View>
        <Text style={texte.discret}>{t.passation.corps}</Text>
      </Carte>

      {/* Le cadre « pas encore là » : on le dit franchement plutôt que de le
          laisser deviner sous un bouton qui n'aboutirait nulle part. */}
      <Carte compacte>
        <Text style={texte.discret}>{t.passation.cadre}</Text>
      </Carte>

      {/* L'aperçu réel : la synthèse, déjà vivante sur la fiche d'un élève. */}
      <Carte>
        <Text style={texte.section}>{t.passation.apercuTitre}</Text>
        <Text style={texte.discret}>
          {aDesEleves ? t.passation.apercu : t.passation.apercuVide}
        </Text>
        <BoutonPrincipal libelle={t.passation.ouvrir} onPress={() => router.push('/classe')} />
      </Carte>
    </SousEcran>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  hero: { flexDirection: 'row', alignItems: 'center', gap: espace.md },
  heroTexte: { flex: 1, gap: espace.sm },
  badge: {
    alignSelf: 'flex-start',
    backgroundColor: c.actionTeinte,
    borderRadius: rayon.pastille,
    paddingHorizontal: espace.sm,
    paddingVertical: 2,
  },
  badgeTexte: {
    fontFamily: police.accent,
    fontSize: 12,
    color: c.actif,
    letterSpacing: 0.2,
  },
});
