import { useLocalSearchParams, useRouter } from 'expo-router';
import { useMemo, useRef, useState } from 'react';
import {
  NativeScrollEvent,
  NativeSyntheticEvent,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  useWindowDimensions,
  View,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { Cloudy, type Pose } from '@/components/cloudy';
import { BoutonPrincipal } from '@/components/formulaire';
import { t } from '@/i18n';
import { marquerIntroVue } from '@/lib/intro';
import { espace, police, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Le tour d'arrivée, façon Strava.
 *
 * 🔑 On MONTRE avant de DEMANDER. L'onboarding pose déjà « une leçon d'abord »,
 * mais il commence quand même par une question (le niveau). Ici, encore avant,
 * quelques planches de contexte : à qui c'est, ce que ça fait, ce que ça prouve.
 * Un arrivant comprend la valeur avant qu'on lui demande quoi que ce soit.
 *
 * ⚠️ Un seul dégradé d'action par écran (la charte v9) : c'est « Commencer ».
 * Tout le reste (les points, « Passer ») reste neutre. Une seule Cloudy par
 * planche. Le bouton mène vraiment à la connexion : rien de mort ici.
 *
 * Le drapeau (`educooo:intro-vu`) est posé par le bouton, puis on remplace la
 * route par la connexion. Le montrer une fois de plus n'a aucune gravité, donc
 * on n'attend pas la fin de l'écriture pour naviguer si elle traîne — mais elle
 * est quasi instantanée, alors on l'attend proprement.
 *
 * 🔁 DEUX MODES. En arrivée (sans paramètre), c'est le premier lancement : le
 * bouton pose le drapeau et mène à la connexion. En « revoir » (ouvert depuis
 * « Toi » avec `revoir=1`), quelqu'un de déjà connecté relit les planches : le
 * bouton ne touche PAS au drapeau et fait simplement demi-tour vers l'app.
 */

// Les poses vivent ici, pas dans l'i18n : c'est un choix visuel, pas du texte.
// Une pose par planche, dans le même ordre que les slides du catalogue :
// accueil (qui c'est), capter/ranger, pilotage, journal, progrès, groupes.
const POSES: Pose[] = ['salut', 'micro', 'loupe', 'serenite', 'joie', 'celebration'];

export default function Intro() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const router = useRouter();
  const { revoir, force } = useLocalSearchParams<{ revoir?: string; force?: string }>();
  const modeRevoir = revoir === '1';
  // Mode « force » : un compte DÉJÀ connecté à qui l'on remontre le tour une
  // fois parce qu'il a changé (nouvelle version). Contrairement à « revoir », il
  // POSE le drapeau à la fin (pour ne pas le remontrer en boucle) mais, comme
  // « revoir », il rend la main à l'app plutôt que d'aller vers la connexion.
  const modeForce = force === '1';
  const { width } = useWindowDimensions();
  const defilement = useRef<ScrollView>(null);
  const [index, setIndex] = useState(0);
  const [occupe, setOccupe] = useState(false);

  const slides = t.intro.slides;
  const dernier = index >= slides.length - 1;

  function surDefilement(e: NativeSyntheticEvent<NativeScrollEvent>) {
    const i = Math.round(e.nativeEvent.contentOffset.x / width);
    if (i !== index) setIndex(i);
  }

  function passer() {
    // « Passer » saute à la dernière planche plutôt que de zapper le récit d'un
    // coup : le bouton « Commencer » y est, sous la même main.
    defilement.current?.scrollTo({ x: (slides.length - 1) * width, animated: true });
  }

  async function commencer() {
    // Mode « revoir » : on ne touche pas au drapeau (il est déjà posé) et on
    // rend simplement la main à l'app d'où l'on vient.
    if (modeRevoir) {
      router.back();
      return;
    }
    setOccupe(true);
    await marquerIntroVue();
    // Mode « force » : on est connecté, le tour a été posé par-dessus l'app, on
    // y revient. Sinon (premier lancement, non connecté), on part se connecter.
    if (modeForce) {
      router.back();
      return;
    }
    router.replace('/connexion');
  }

  return (
    <SafeAreaView style={styles.racine} edges={['top', 'bottom']}>
      {/* « Passer », discret, en haut à droite. Il disparaît sur la dernière
          planche : il n'aurait plus rien à sauter. */}
      {!dernier ? (
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={t.intro.passer}
          onPress={passer}
          style={styles.passer}>
          <Text style={styles.passerTexte}>{t.intro.passer}</Text>
        </Pressable>
      ) : (
        // Un espace réservé de même hauteur : sans lui, le contenu remonterait
        // d'un cran en arrivant sur la dernière planche.
        <View style={styles.passer} pointerEvents="none" />
      )}

      <ScrollView
        ref={defilement}
        horizontal
        pagingEnabled
        showsHorizontalScrollIndicator={false}
        onMomentumScrollEnd={surDefilement}
        style={styles.piste}>
        {slides.map((slide, i) => (
          <View key={i} style={[styles.slide, { width }]}>
            <Cloudy pose={POSES[i]} taille={180} />
            <Text style={[texte.titre, styles.accroche]}>{slide.accroche}</Text>
            <Text style={[texte.corps, styles.corps]}>{slide.corps}</Text>
          </View>
        ))}
      </ScrollView>

      {/* Le pied fixe, hors du défilement horizontal : les points de pagination
          puis l'unique bouton d'action. */}
      <View style={styles.pied}>
        <View style={styles.points}>
          {slides.map((_, i) => (
            <View key={i} style={[styles.point, i === index && styles.pointActif]} />
          ))}
        </View>
        <BoutonPrincipal
          libelle={modeRevoir || modeForce ? t.intro.revoirFin : t.intro.commencer}
          onPress={commencer}
          occupe={occupe}
        />
      </View>
    </SafeAreaView>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  racine: { flex: 1, backgroundColor: c.fond },
  passer: {
    alignSelf: 'flex-end',
    minHeight: 44,
    justifyContent: 'center',
    paddingHorizontal: espace.lg,
  },
  passerTexte: { fontFamily: police.accent, fontSize: 15, color: c.encreDouce },
  piste: { flex: 1 },
  slide: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: espace.xl,
    gap: espace.md,
  },
  accroche: { textAlign: 'center', fontSize: 28 },
  corps: { textAlign: 'center', color: c.encreDouce, lineHeight: 24 },
  pied: { paddingHorizontal: espace.lg, paddingBottom: espace.md, gap: espace.lg },
  points: { flexDirection: 'row', justifyContent: 'center', gap: espace.sm },
  point: {
    width: 8,
    height: 8,
    borderRadius: 4,
    backgroundColor: c.bord,
  },
  pointActif: { backgroundColor: c.actif, width: 22 },
});
