import { Alerte, BoutonDiscret, BoutonPrincipal, Pastilles } from '@/components/formulaire';
import { Presse } from '@/components/presse';
import { langue, type Langue } from '@/i18n';
import {
  inviterCollegue,
  membresDe,
  retirerMembre,
  type NiveauAcces,
} from '@/lib/co-enseignement';
import { mesCollegues } from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Le panneau d'invitation au co-enseignement d'UNE classe (vue propriétaire).
 *
 * 🔑 On ne réinvente pas la découverte : on choisit un·e collègue DÉJÀ accepté·e
 * (via « Collègues », dans Groupes), puis un niveau d'accès, et on invite. Le
 * panneau montre aussi les co-profs actuel·les, avec de quoi les retirer.
 *
 * 🎨 Charte : feuille qui monte du bas (mobile) ou volet à droite (web), croix
 * FIXE hors du défilement, tutoiement, écriture inclusive, pas de tiret cadratin.
 */

/* ── Libellés de chrome, en local (fr + nl), repli fr. Comme l'aide in-app : le
   chrome d'une feature neuve vit ici, on n'alourdit pas le catalogue partagé. ─ */
type Lib = {
  titre: string;
  fermer: string;
  explication: string;
  coProfsTitre: string;
  aucunCoProf: string;
  enAttente: string;
  accepte: string;
  retirer: string;
  choisirCollegue: string;
  aucunCollegue: string;
  niveau: string;
  lecture: string;
  ecriture: string;
  lectureAide: string;
  ecritureAide: string;
  inviter: string;
  dejaInvitee: string;
  erreur: string;
};

const LIB: Record<Langue, Lib> = {
  fr: {
    titre: 'Co-enseignement',
    fermer: 'Fermer',
    explication:
      "Invite un·e collègue à co-enseigner cette classe. En immersion, vous partagez le semainier et sa moitié du programme : ce que tu prépares et ce que l'autre prépare se rejoignent au même endroit.",
    coProfsTitre: 'Co-enseignant·es',
    aucunCoProf: "Personne pour l'instant. Invite un·e collègue ci-dessous.",
    enAttente: 'en attente',
    accepte: 'a accepté',
    retirer: 'Retirer',
    choisirCollegue: 'Quel·le collègue ?',
    aucunCollegue:
      "Tu n'as pas encore de collègue accepté·e. Ajoute-en un·e dans Groupes, onglet Collègues, puis reviens ici.",
    niveau: "Niveau d'accès",
    lecture: 'Lecture',
    ecriture: 'Écriture',
    lectureAide: 'Voit tout, ne modifie rien. Pour un coup de main de quelques jours.',
    ecritureAide:
      'Modifie le journal et le programme. Pour une immersion ou un remplacement long.',
    inviter: 'Envoyer l’invitation',
    dejaInvitee: "Cette personne est déjà invitée sur cette classe.",
    erreur: "L'invitation n'a pas pu partir. Réessaie.",
  },
  nl: {
    titre: 'Co-teaching',
    fermer: 'Sluiten',
    explication:
      'Nodig een collega uit om deze klas samen te geven. Bij immersie deel je de weekplanning en de helft van het programma: wat jij voorbereidt en wat de ander voorbereidt komen op dezelfde plek samen.',
    coProfsTitre: 'Co-leerkrachten',
    aucunCoProf: 'Nog niemand. Nodig hieronder een collega uit.',
    enAttente: 'in afwachting',
    accepte: 'heeft aanvaard',
    retirer: 'Verwijderen',
    choisirCollegue: 'Welke collega?',
    aucunCollegue:
      'Je hebt nog geen aanvaarde collega. Voeg er een toe in Groepen, tabblad Collega’s, en kom dan terug.',
    niveau: 'Toegangsniveau',
    lecture: 'Lezen',
    ecriture: 'Schrijven',
    lectureAide: 'Ziet alles, wijzigt niets. Voor een handje hulp van enkele dagen.',
    ecritureAide: 'Wijzigt het dagboek en het programma. Voor immersie of een lange vervanging.',
    inviter: 'Uitnodiging versturen',
    dejaInvitee: 'Deze persoon is al uitgenodigd voor deze klas.',
    erreur: 'De uitnodiging kon niet vertrekken. Probeer opnieuw.',
  },
};

function lib(): Lib {
  return LIB[langue] ?? LIB.fr;
}

export function PanneauCoEnseignement({
  classeId,
  onFermer,
}: {
  classeId: string;
  onFermer: () => void;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const web = Platform.OS === 'web';
  const l = lib();

  const membres = useRequete(() => membresDe(classeId), [classeId]);
  const collegues = useRequete(mesCollegues, []);

  const [collegueId, setCollegueId] = useState<string | null>(null);
  const [acces, setAcces] = useState<NiveauAcces>('write_full');
  const [occupe, setOccupe] = useState(false);
  const [souci, setSouci] = useState<string | null>(null);

  // Les collègues acceptés qui ne sont pas DÉJÀ membres (invités ou co-profs) de
  // cette classe : on n'invite pas deux fois la même personne.
  const listeMembres = membres.donnees ?? [];
  const dejaMembres = new Set(listeMembres.map((m) => m.personneId));
  const invitables = (collegues.donnees ?? [])
    .filter((x) => x.statut === 'accepted' && !dejaMembres.has(x.personneId))
    .map((x) => ({ id: x.personneId, libelle: x.nom ?? '—' }));

  async function inviter() {
    if (!collegueId) return;
    setSouci(null);
    setOccupe(true);
    try {
      await inviterCollegue({ classeId, collegueId, acces });
      setCollegueId(null);
      membres.recharger();
    } catch (e) {
      const msg = e instanceof Error ? e.message : '';
      setSouci(msg === 'deja_invitee' ? l.dejaInvitee : l.erreur);
    } finally {
      setOccupe(false);
    }
  }

  async function retirer(membreId: string) {
    setSouci(null);
    setOccupe(true);
    try {
      await retirerMembre({ membreId });
      membres.recharger();
    } catch {
      setSouci(l.erreur);
    } finally {
      setOccupe(false);
    }
  }

  return (
    <Modal
      visible
      transparent
      animationType={web ? 'fade' : 'slide'}
      onRequestClose={onFermer}
      statusBarTranslucent>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel={l.fermer}
        onPress={onFermer}
        style={[styles.fond, web ? styles.fondWeb : styles.fondMobile]}>
        <Pressable style={web ? styles.volet : styles.feuille} onPress={() => {}}>
          <SafeAreaView edges={web ? ['top', 'bottom'] : ['bottom']} style={styles.zone}>
            {/* En-tête FIXE : la croix reste visible, jamais dans le défilement. */}
            <View style={styles.entete}>
              <Text style={texte.section}>{l.titre}</Text>
              <Pressable
                accessibilityRole="button"
                accessibilityLabel={l.fermer}
                onPress={onFermer}
                style={styles.croix}>
                <Feather name="x" size={22} color={c.encre} />
              </Pressable>
            </View>

            <ScrollView
              contentContainerStyle={styles.corps}
              keyboardShouldPersistTaps="handled"
              showsVerticalScrollIndicator={false}>
              <Text style={styles.explication}>{l.explication}</Text>

              {souci ? <Alerte message={souci} /> : null}

              {/* Les co-profs actuel·les. */}
              <Text style={styles.rubrique}>{l.coProfsTitre}</Text>
              {membres.chargement && !listeMembres.length ? (
                <ActivityIndicator color={c.encreDouce} style={{ marginVertical: espace.md }} />
              ) : listeMembres.length === 0 ? (
                <Text style={texte.discret}>{l.aucunCoProf}</Text>
              ) : (
                listeMembres.map((m) => (
                  <View key={m.id} style={styles.ligne}>
                    <View style={styles.pastille}>
                      <Text style={styles.initiale}>
                        {(m.nom ?? '?').trim().charAt(0).toUpperCase() || '?'}
                      </Text>
                    </View>
                    <View style={styles.corpsLigne}>
                      <Text style={texte.corps}>{m.nom ?? '—'}</Text>
                      <Text style={texte.discret}>
                        {m.statut === 'pending' ? l.enAttente : l.accepte} ·{' '}
                        {m.acces === 'read' ? l.lecture : l.ecriture}
                      </Text>
                    </View>
                    <Pressable
                      accessibilityRole="button"
                      accessibilityLabel={`${l.retirer} ${m.nom ?? ''}`}
                      disabled={occupe}
                      onPress={() => retirer(m.id)}
                      style={styles.retirer}>
                      <Feather name="x" size={16} color={c.encreDouce} />
                    </Pressable>
                  </View>
                ))
              )}

              {/* Inviter. */}
              <View style={styles.separateur} />

              {collegues.chargement && !invitables.length ? (
                <ActivityIndicator color={c.encreDouce} style={{ marginVertical: espace.md }} />
              ) : invitables.length === 0 ? (
                <Text style={texte.discret}>{l.aucunCollegue}</Text>
              ) : (
                <>
                  <Pastilles
                    etiquette={l.choisirCollegue}
                    options={invitables}
                    choisi={collegueId}
                    onChoisir={setCollegueId}
                  />

                  <Pastilles
                    etiquette={l.niveau}
                    options={[
                      { id: 'read', libelle: l.lecture },
                      { id: 'write_full', libelle: l.ecriture },
                    ]}
                    choisi={acces}
                    onChoisir={(id) => {
                      if (id === 'read' || id === 'write_full') setAcces(id);
                    }}
                  />
                  <Text style={styles.aide}>
                    {acces === 'read' ? l.lectureAide : l.ecritureAide}
                  </Text>

                  <View style={{ marginTop: espace.sm }}>
                    <BoutonPrincipal
                      libelle={l.inviter}
                      onPress={inviter}
                      occupe={occupe}
                      inactif={!collegueId}
                    />
                  </View>
                </>
              )}

              <BoutonDiscret libelle={l.fermer} onPress={onFermer} />
            </ScrollView>
          </SafeAreaView>
        </Pressable>
      </Pressable>
    </Modal>
  );
}

