    rubrique: { fontFamily: police.titre, fontSize: 15, color: c.encre, marginTop: espace.sm },
    aide: { fontFamily: police.corps, fontSize: 14, color: c.encreDouce, lineHeight: 20 },
    separateur: { height: 1, backgroundColor: c.bord, marginVertical: espace.sm },
