/** Le nombre de jours (arrondi au supérieur) d'ici la date, 0 si passée, null si inconnue. */
function joursRestants(iso: string | null): number | null {
  if (!iso) return null;
  const ms = Date.parse(iso) - Date.now();
  if (Number.isNaN(ms)) return null;
  return Math.max(0, Math.ceil(ms / 86_400_000));
}

/**
 * « Réglages » : tout ce qui se règle, sorti de l'onglet « Moi ».
 *
 * 🚨 **Rien d'autre que des réglages, jamais.** La règle vient d'un défaut
 * mesuré : `/plus` dans l'app héritée contenait neuf choses sans rapport, du
 * Copilot à l'aide en passant par la vue Inspection, parce qu'un écran fourre-
 * tout attire tout ce qui n'a pas de maison. Il est devenu inutilisable sans que
 * personne le décide. Le contenu (le profil d'effet maître) vit dans « Moi » ;
 * ici, on ne fait que régler.
 */
export default function Reglages() {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { preference, definir } = useTheme();
  const { deconnecter } = useSession();
  const { classe, enCours } = useClasse();
  const { abonne, offre, essaiAppActif, essaiExpireLe } = useAbonnement();
  // Le prix localisé de l'offre annuelle (« 59,99 € »), lu depuis le store quand
  // il est chargé ; null tant qu'on ne l'a pas (SDK inerte, réseau).
  const prixAbonnement = offre?.product.priceString ?? null;
  const classeId = classe?.id ?? null;

  // Un seul bouton, deux destinations selon l'état : le paywall maison quand ce
  // n'est pas pris, le Customer Center natif quand ça l'est.
  async function gererAbonnement() {
    if (!abonne) {
      router.push('/abonnement');
      return;
    }
    try {
      await ouvrirEspaceClient();
    } catch {
      Alert.alert(t.abonnement.erreurEspaceClient);
    }
  }

  // Le rôle, pour n'ouvrir l'accès direction qu'à celles et ceux qui l'ont. La
  // vraie garde reste serveur (RPC self-scoping) ; ici on évite d'afficher une
  // porte fermée à une enseignante ordinaire.
  const role = useRequete(monRole, []);
  const estEncadrement =
    role.donnees === 'direction' || role.donnees === 'inspection' || role.donnees === 'admin';
  const rituel = useRequete(lireRituel, []);
  const creneaux = useRequete(() => creneauxDe(classeId!), [classeId], { actif: !!classeId });
  const referentiels = useRequete(() => referentielsDeLaClasse(classe!), [classe?.id, classe?.cycle], {
    actif: !!classe,
  });
  // Le compte « à replanifier » : les activités qu'une absence a récupérées et
  // qui attendent une nouvelle date. Sert de badge sur l'entrée dédiée.
  const aReplanifier = useRequete(() => nombreAReplanifier(classeId!), [classeId], {
    actif: !!classeId,
  });
  useFocusEffect(
    useCallback(() => {
      rituel.recharger();
      if (classeId) {
        creneaux.recharger();
        referentiels.recharger();
        aReplanifier.recharger();
      }
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [classeId]),
  );

  const suivis = (referentiels.donnees ?? []).filter((r) => r.actif).length;

  // La page d'ouverture préférée (défaut Capter). Chargée une fois, changeable
  // d'un tap. Les libellés reprennent ceux des onglets.
  const [page, setPage] = useState<PageAccueil>('capter');
  useEffect(() => {
    pageAccueil().then(setPage);
  }, []);

  // La liste cherchable de l'aide, ouverte en plein écran depuis l'entrée « Aide ».
  // Tenue en modale (pas en route) pour ne pas dépendre de la régénération des
  // types de routes. Invisible tant que le drapeau maître AIDE_ACTIVE est éteint.
  const [aideOuverte, setAideOuverte] = useState(false);
  // « Changer mon mot de passe » : tenu en modale (pas en route) pour ne pas
  // dépendre de la régénération des types de routes, comme la liste d'aide.
  const [mdpOuvert, setMdpOuvert] = useState(false);
  const LIBELLE_PAGE: Record<PageAccueil, string> = {
    index: t.onglets.accueil,
    journal: t.onglets.journal,
    capter: t.onglets.capter,
    groupes: t.onglets.groupes,
    vous: t.onglets.vous,
  };

  /**
   * Bascule de langue, pontée. Elle fait DEUX choses : elle change l'UI
   * (`definirLangue`, qui recharge l'app) ET elle range le choix sur le profil
   * (`enregistrerLangue`). On écrit le profil d'abord, avant le rechargement,
   * sinon le reload couperait l'écriture en vol. L'échec de l'écriture profil
   * n'est pas bloquant : l'app doit quand même basculer.
   */
  async function basculerLangue(code: Langue) {
    if (code === langue) return;
    try {
      await enregistrerLangue(code);
    } catch {
      // Le profil n'a pas pu être écrit (réseau) : le choix d'UI, lui, part
      // quand même. Le profil se resynchronisera au prochain passage.
    }
    await definirLangue(code);
  }

  return (
    <SousEcran
      titre={t.moi.reglages}
      actions={<BoutonTheme preference={preference} definir={definir} />}>
      {/* ── Mon compte : qui je suis, comment je me connecte, ce que je paie.
          « Changer mon mot de passe » vit ici, juste sous le profil, pour être
          trouvé d'un coup d'œil (retour Valentin : écran devenu un bordel). ── */}
      <Section titre={SECTIONS[langue].compte} premier />

      <Reglage
        icone="user"
        moment="accueil"
        titre={t.vous.profil}
        indice={t.vous.profilIndice(null)}
        vers="/vous/profil"
      />

      {/* Changer mon mot de passe : ouvre une modale in-app (pas une route). Ne
          dépend d'aucun drapeau — c'est un ajout autonome qui n'altère aucun
          flux existant. */}
      <Reglage
        icone="lock"
        moment="recreation"
        titre={LIB_MDP[langue].entree}
        indice={LIB_MDP[langue].entreeIndice}
        onPress={() => setMdpOuvert(true)}
      />

      {/* Mon abonnement : TOUJOURS visible (retour terrain « tout le monde
          demande le prix »). Le statut (essai en cours, jours restants) vient de
          la grâce du profil, qui ne dépend pas de RevenueCat — il s'affiche même
          quand le SDK est inerte. Le prix vient de l'offre du store quand elle
          est chargée. On voit où l'on en est, et on peut s'abonner avant la fin. */}
      <Reglage
        icone={abonne ? 'award' : essaiAppActif ? 'gift' : 'star'}
        moment="ateliers"
        titre={
          abonne || essaiAppActif
            ? LIBELLES_MOI[langue].abonnementTitre
            : LIBELLES_MOI[langue].sAbonner
        }
        indice={
          abonne
            ? LIBELLES_MOI[langue].abonnementActif
            : essaiAppActif
              ? LIBELLES_MOI[langue].abonnementEssai(
                  joursRestants(essaiExpireLe) ?? 0,
                  prixAbonnement,
                )
              : LIBELLES_MOI[langue].abonnementFin(prixAbonnement)
        }
        onPress={() => void gererAbonnement()}
      />

      {/* ── Ma classe et mon programme : « Mes classes » toujours là (même sans
          classe, pour en créer une) ; le reste apparaît dès qu'une classe est
          choisie. ── */}
      <Section titre={SECTIONS[langue].classe} />

      <Reglage
        icone="users"
        moment="social"
        titre={t.vous.classes}
        indice={classe ? t.vous.classesIndice(enCours.length, classe.nom) : t.vous.sansClasse}
        vers="/vous/classes"
      />

      {classe ? (
        <>
          <Reglage
            icone="clock"
            moment="ateliers"
            titre={t.vous.semaine}
            indice={t.vous.semaineIndice((creneaux.donnees ?? []).length)}
            vers="/vous/semaine"
          />

          <Reglage
            icone="book"
            moment="dirigees"
            titre={t.vous.referentiels}
            indice={t.vous.referentielsIndice(suivis, (referentiels.donnees ?? []).length)}
            vers="/vous/referentiels"
          />

          <Reglage
            icone="copy"
            moment="ateliers"
            titre={t.dupliquer.entree}
            indice={t.dupliquer.entreeIndice}
            onPress={() => router.push('/dupliquer')}
          />

          {/* L'absence de l'enseignant·e : déclarer pour récupérer une journée
              planifiée, puis reposer les activités reportées. On peut aussi
              déclarer depuis le journal ; ici c'est la porte des réglages. */}
          <Reglage
            icone="user-x"
            moment="social"
            titre={LIBELLES_MOI[langue].absence}
            indice={LIBELLES_MOI[langue].absenceIndice}
            onPress={() => router.push('/absence')}
          />

          <Reglage
            icone="rotate-ccw"
            moment="sortie"
            titre={LIBELLES_MOI[langue].replanifier}
            indice={
              (aReplanifier.donnees ?? 0) > 0
                ? LIBELLES_MOI[langue].replanifierCompte(aReplanifier.donnees ?? 0)
                : LIBELLES_MOI[langue].replanifierRien
            }
            onPress={() => router.push('/replanifier')}
          />

          <Reglage
            icone="send"
            moment="recreation"
            titre={LIBELLES_MOI[langue].passation}
            indice={LIBELLES_MOI[langue].passationIndice}
            onPress={() => router.push('/passation')}
          />
        </>
      ) : null}

      {/* ── Rappels : ce qui te fait signe (rituel du soir, notifications). ── */}
      <Section titre={SECTIONS[langue].rappels} />

      <Reglage
        icone="moon"
        moment="dirigees"
        titre={t.vous.rituel}
        indice={
          rituel.donnees?.actif ? t.vous.rituelActif(rituel.donnees.heure) : t.vous.rituelInactif
        }
        vers="/vous/rituel"
      />

      <Reglage
        icone="bell"
        moment="sortie"
        titre={t.vous.notifications}
        indice={t.vous.notificationsIndice}
        vers="/vous/notifications"
      />

      {/* ── Apparence : langue, page d'ouverture. Le thème (Système / Clair /
          Sombre) n'est pas ici : il vit sur l'écrou en haut à droite (retour
          Valentin 24/08). ── */}
      <Section titre={SECTIONS[langue].apparence} />

      {/* La bascule de langue est pontée : elle flippe l'UI ET persiste
          `profiles.langue` (voir basculerLangue). Montrée seulement s'il y a un
          vrai choix. */}
      {LANGUES.length > 1 ? (
        <SelecteurLigne
          titre={t.vous.langue}
          options={LANGUES.map((l) => ({ id: l.code as Langue, libelle: l.nom }))}
          choisi={langue}
          onChoisir={(code) => void basculerLangue(code)}
        />
      ) : null}

      {/* La page sur laquelle l'app s'ouvre (retour Valentin 24/08). Défaut
          Capter, changeable ici, condensée sur une ligne. */}
      <SelecteurLigne
        titre={t.vous.pageAccueil}
        options={PAGES_ACCUEIL.map((p) => ({ id: p as PageAccueil, libelle: LIBELLE_PAGE[p] }))}
        choisi={page}
        onChoisir={(id) => {
          setPage(id);
          void definirPageAccueil(id);
        }}
      />

      {/* ── Mes données : ce qu'on garde et ce qu'on efface. La suppression du
          compte reste à part, sous un filet, au ton sobre (action irréversible). ── */}
      <Section titre={SECTIONS[langue].donnees} />

      <Reglage
        icone="shield"
        moment="recreation"
        titre={t.vous.confiance}
        indice={t.vous.confianceIndice}
        vers="/vous/donnees"
      />

      {/* Suppression du compte, posée à part sous un filet. POURQUOI elle est
          nommée sans détour et facile à trouver : Apple (règle 5.1.1(v)) exige
          que la suppression soit évidente. Au build 9, elle n'était accessible
          que par une tuile « Tout effacer » enfouie dans « Tes données », et le
          contrôle App Store ne l'a pas trouvée. Le lien porte `supprimer=1` :
          l'écran « Tes données » ouvre alors le flux de suppression d'emblée. */}
      <View style={styles.separateur} />
      <Reglage
        icone="trash-2"
        moment="social"
        titre={t.vous.supprimerCompte}
        indice={t.vous.supprimerCompteIndice}
        onPress={() => router.push({ pathname: '/vous/donnees', params: { supprimer: '1' } })}
      />

      {/* ── Aide et contact : relancer le guide, écrire, noter, parrainer, et le
          mot aux directions d'école. ── */}
      <Section titre={SECTIONS[langue].aide} />

      <Reglage
        icone="compass"
        moment="dirigees"
        titre={t.vous.revoirIntro}
        indice={t.vous.revoirIntroIndice}
        onPress={() => router.push('/guide')}
      />

      {/* L'aide : la liste cherchable de tous les guides du site, mutualisés avec
          le web. Invisible tant que le drapeau maître AIDE_ACTIVE est éteint,
          pour ne rien changer en prod avant le feu vert du client. */}
      {AIDE_ACTIVE ? (
        <Reglage
          icone="help-circle"
          moment="accueil"
          titre={libAide().entree}
          indice={libAide().entreeIndice}
          onPress={() => setAideOuverte(true)}
        />
      ) : null}

      {/* Nous contacter : le WhatsApp d'Anne-Charlotte, pour une question directe. */}
      <Reglage
        icone="message-circle"
        moment="social"
        titre={LIBELLES_MOI[langue].contacter}
        indice={LIBELLES_MOI[langue].contacterIndice}
        onPress={() => void Linking.openURL('https://wa.me/32472629195')}
      />

      <Reglage
        icone="star"
        moment="ateliers"
        titre={LIBELLES_MOI[langue].noter}
        indice={LIBELLES_MOI[langue].noterIndice}
        onPress={() => void ouvrirAvisEcrit()}
      />

      <Reglage
        icone="gift"
        moment="social"
        titre={LIBELLES_MOI[langue].parrainage}
        indice={LIBELLES_MOI[langue].parrainageIndice}
        onPress={() => router.push({ pathname: '/groupes', params: { tab: 'parrainage' } })}
      />

      {/* Pour les directions d'école : on n'ouvre plus le site dans le dos du
          prof. On passe d'abord par une fenêtre in-app qui explique, de SON
          point de vue, ce que la direction voit et ne voit pas ; le lien vers
          le site y est un bouton, posé après l'explication. */}
      <Reglage
        icone="home"
        moment="dirigees"
        titre={LIBELLES_MOI[langue].directionContact}
        indice={LIBELLES_MOI[langue].directionContactIndice}
        onPress={() => router.push('/direction-info')}
      />

      {/* ── Direction : le suivi agrégé de l'établissement. N'apparaît, section
          et entrée comprises, que pour un rôle d'encadrement (la vraie garde
          reste serveur). ── */}
      {estEncadrement ? (
        <>
          <Section titre={SECTIONS[langue].direction} />
          <Reglage
            icone="briefcase"
            moment="dirigees"
            titre={LIBELLES_MOI[langue].direction}
            indice={LIBELLES_MOI[langue].directionIndice}
            onPress={() => router.push('/direction')}
          />
        </>
      ) : null}

      <BoutonDiscret libelle={t.vous.deconnexion} onPress={() => void deconnecter()} />

      <Text style={styles.version}>
        {t.vous.version} {Constants.expoConfig?.version}
      </Text>

      <Text style={styles.mentionSource}>{LIBELLES_MOI[langue].sourceFwb}</Text>

      {/* La liste cherchable de l'aide, en plein écran. Rend null si AIDE_ACTIVE
          est éteint : sans ça, aucune surface d'aide n'existe. */}
      <ListeAide visible={aideOuverte} onFermer={() => setAideOuverte(false)} />

      {/* La modale « Changer mon mot de passe ». */}
      <ChangerMotDePasse visible={mdpOuvert} onFermer={() => setMdpOuvert(false)} />
    </SousEcran>
  );
}

/**
 * Changer son mot de passe, en modale in-app. Deux champs (nouveau + confirmer)
 * et `supabase.auth.updateUser({ password })`. La croix de fermeture reste fixe
 * en haut (règle studio), hors de tout défilement — le contenu est court.
 */
function ChangerMotDePasse({ visible, onFermer }: { visible: boolean; onFermer: () => void }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const lib = LIB_MDP[langue];
  const [mdp, setMdp] = useState('');
  const [confirme, setConfirme] = useState('');
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);
  const [succes, setSucces] = useState(false);

  function fermer() {
    setMdp('');
    setConfirme('');
    setErreur(null);
    setSucces(false);
    onFermer();
  }

  async function enregistrer() {
    setErreur(null);
    setSucces(false);
    if (mdp.length < MIN_MOT_DE_PASSE) return setErreur(lib.court);
    if (mdp !== confirme) return setErreur(lib.pasIdentiques);
    setOccupe(true);
    const { error } = await supabase.auth.updateUser({ password: mdp });
    setOccupe(false);
    if (error) {
      // On dit la VRAIE raison plutôt qu'un « échec » générique. Le projet a la
      // vérification « mot de passe compromis » (HIBP) activée : un mot de passe
      // trop courant est refusé, et il faut le dire clairement.
      const m = (error.message ?? '').toLowerCase();
      if (m.includes('weak') || m.includes('pwned') || m.includes('known') || m.includes('leak') || m.includes('compromis') || m.includes('common')) {
        return setErreur(lib.tropCourant);
      }
      if (m.includes('session') || m.includes('jwt') || m.includes('logged') || m.includes('missing')) {
        return setErreur(lib.session);
      }
      return setErreur(lib.echec);
    }
    setMdp('');
    setConfirme('');
    setSucces(true);
  }

  if (!visible) return null;
  return (
    <Modal visible transparent animationType="fade" onRequestClose={fermer} statusBarTranslucent>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel={lib.fermer}
        onPress={fermer}
        style={styles.mdpFond}>
        {/* Un tap DANS la carte ne ferme pas. */}
        <Pressable style={styles.mdpCarte} onPress={() => {}}>
          <SafeAreaView edges={['bottom']}>
            {/* En-tête fixe : la croix reste visible, jamais dans un défilement. */}
            <View style={styles.mdpEntete}>
              <Text style={[texte.titre, styles.mdpTitre]}>{lib.titre}</Text>
              <Pressable
                accessibilityRole="button"
                accessibilityLabel={lib.fermer}
                onPress={fermer}
                style={styles.mdpCroix}>
                <Feather name="x" size={22} color={c.encre} />
              </Pressable>
            </View>

            <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
              <View style={styles.mdpCorps}>
                <Champ
                  etiquette={lib.champNouveau}
                  value={mdp}
                  onChangeText={(v) => {
                    setMdp(v);
                    setErreur(null);
                    setSucces(false);
                  }}
                  placeholder={lib.indice}
                  secureTextEntry
                  autoCapitalize="none"
                  autoCorrect={false}
                  autoComplete="new-password"
                  textContentType="newPassword"
                  editable={!occupe}
                />
                <Champ
                  etiquette={lib.champConfirme}
                  value={confirme}
                  onChangeText={(v) => {
                    setConfirme(v);
                    setErreur(null);
                    setSucces(false);
                  }}
                  placeholder={lib.indice}
                  secureTextEntry
                  autoCapitalize="none"
                  autoCorrect={false}
                  autoComplete="new-password"
                  textContentType="newPassword"
                  returnKeyType="go"
                  onSubmitEditing={enregistrer}
                  editable={!occupe}
                />
                {erreur ? <Alerte message={erreur} /> : null}
                {succes ? <Text style={styles.mdpSucces}>{lib.succes}</Text> : null}
                <BoutonPrincipal
                  libelle={lib.enregistrer}
                  onPress={enregistrer}
                  occupe={occupe}
                  inactif={mdp.length < MIN_MOT_DE_PASSE || confirme.length < MIN_MOT_DE_PASSE}
                />
              </View>
            </KeyboardAvoidingView>
          </SafeAreaView>
        </Pressable>
      </Pressable>
    </Modal>
  );
}

/**
 * L'écrou du thème, fixe en haut à droite de Réglages (retour Valentin 24/08).
 * Un seul bouton qui cycle Système → Clair → Sombre à chaque tap, l'icône disant
 * l'état courant (téléphone = système, soleil = clair, lune = sombre). Il
 * remplace le segment de thème qui vivait dans le corps.
 */
function BoutonTheme({
  preference,
  definir,
}: {
  preference: Preference;
  definir: (p: Preference) => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const idx = ORDRE_THEME.indexOf(preference);
  const suivant = ORDRE_THEME[(idx + 1) % ORDRE_THEME.length];
  const icones: Record<Preference, keyof typeof Feather.glyphMap> = {
    systeme: 'smartphone',
    clair: 'sun',
    sombre: 'moon',
  };
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`${THEME_LIBELLES[langue].titre} : ${THEME_LIBELLES[langue].options[preference]}. Toucher pour changer.`}
      onPress={() => definir(suivant)}
      style={styles.ecrouTheme}>
      <Feather name={icones[preference]} size={18} color={c.encre} />
    </Pressable>
  );
}

/**
 * Un en-tête de section : un petit titre discret (majuscules espacées, encre
 * douce) qui coiffe un groupe d'entrées. Il porte lui-même sa marge haute pour
 * détacher nettement la section de la précédente ; `premier` la retire pour la
 * toute première, collée sous la barre de titre.
 */
function Section({ titre, premier = false }: { titre: string; premier?: boolean }) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <Text
      accessibilityRole="header"
      style={[styles.sectionTitre, premier && styles.sectionTitrePremier]}>
      {titre}
    </Text>
  );
}

/**
 * Un sélecteur sur UNE ligne : titre à gauche, valeur choisie + chevron à droite.
 * Au tap, une petite feuille liste les options ; en choisir une la referme. Sert
 * à condenser langue et page d'ouverture (retour Valentin) plutôt que d'étaler
 * toutes les options en segments/pastilles.
 */
function SelecteurLigne<T extends string>({
  titre,
  options,
  choisi,
  onChoisir,
}: {
  titre: string;
  options: { id: T; libelle: string }[];
  choisi: T;
  onChoisir: (id: T) => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const [ouvert, setOuvert] = useState(false);
  const valeur = options.find((o) => o.id === choisi)?.libelle ?? '';
  return (
    <Carte compacte>
      <Presse
        accessibilityRole="button"
        accessibilityLabel={`${titre} : ${valeur}`}
        onPress={() => setOuvert(true)}
        style={styles.selLigne}>
        <Text style={styles.selTitre}>{titre}</Text>
        <View style={styles.selDroite}>
          <Text style={styles.selValeur}>{valeur}</Text>
          <Feather name="chevron-down" size={18} color={c.nonRattache} />
        </View>
      </Presse>
      <Modal visible={ouvert} transparent animationType="fade" onRequestClose={() => setOuvert(false)}>
        <Pressable style={styles.selFond} onPress={() => setOuvert(false)}>
          <Pressable style={styles.selMenu} onPress={() => {}}>
            {options.map((o) => {
              const actif = o.id === choisi;
              return (
                <Presse
                  key={o.id}
                  accessibilityRole="button"
                  accessibilityLabel={o.libelle}
                  onPress={() => {
                    setOuvert(false);
                    if (!actif) onChoisir(o.id);
                  }}
                  style={styles.selOption}>
                  <Text style={[styles.selOptionTexte, actif && styles.selOptionActive]}>{o.libelle}</Text>
                  {actif ? <Feather name="check" size={18} color={c.action[1]} /> : null}
                </Presse>
              );
            })}
          </Pressable>
        </Pressable>
      </Modal>
    </Carte>
  );
}

/**
 * Une ligne de réglage : carte compacte à tuile teintée, qui porte son état
 * plutôt qu'un simple chevron.
 */
function Reglage({
  icone,
  moment,
  titre,
  indice,
  vers,
  onPress,
}: {
  icone: keyof typeof Feather.glyphMap;
  moment: Moment;
  titre: string;
  indice: string;
  vers?:
    | '/vous/profil'
    | '/vous/classes'
    | '/vous/semaine'
    | '/vous/referentiels'
    | '/vous/donnees'
    | '/vous/notifications'
    | '/vous/rituel';
  onPress?: () => void;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const declencher = onPress ?? (vers ? () => router.push(vers) : () => {});
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`${titre}, ${indice}`}
      onPress={declencher}>
      <Carte compacte>
        <View style={styles.ligne}>
          <Tuile icone={icone} moment={moment} />
          <View style={styles.corps}>
            <Text style={texte.corps}>{titre}</Text>
            <Text style={texte.discret}>{indice}</Text>
          </View>
          <Feather name="chevron-right" size={20} color={c.nonRattache} />
        </View>
      </Carte>
    </Pressable>
  );
}

