import * as Haptics from 'expo-haptics';
import { forwardRef } from 'react';
import { Platform, Pressable, type PressableProps, type StyleProp, type View, type ViewStyle } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withSpring,
} from 'react-native-reanimated';

import { motion } from '@/theme/tokens';

const PressableAnimee = Animated.createAnimatedComponent(Pressable);

// Le web a un état que le tactile n'a pas : le survol. On l'exploite pour un
// retour léger — la cible se soulève d'un cheveu quand la souris passe dessus —
// qui dit « ça se clique » sans bruit. Purement web : sur natif, il n'y a pas de
// pointeur, ces poignées ne se déclenchent jamais et l'échelle reste à 1.
const SURVOL = Platform.OS === 'web' ? 1.02 : 1;

/**
 * Le press qui répond, brique unique de la charte de mouvement.
 *
 * Un élément qui se touche rentre légèrement sous le doigt (ressort vif, court)
 * et rend un petit choc haptique au moment du contact. C'est le retour le plus
 * discret possible : on le sent plus qu'on ne le voit. Toutes les cartes et tous
 * les boutons de l'app passent par ici, pour que le geste se sente pareil
 * partout.
 *
 * ⚠️ Respecte « réduire les animations » : sous ce réglage, l'échelle ne bouge
 * pas (on ne force aucun mouvement). L'haptique, elle, n'est pas du mouvement
 * visuel : elle reste, sauf si on la coupe explicitement par `haptique={false}`.
 *
 * Un `Pressable` désactivé n'émet pas d'évènement de press : un bouton grisé ne
 * rentre pas et ne vibre pas, sans code en plus.
 */
export const Presse = forwardRef<View, PressableProps & {
  /** Échelle atteinte au press. Par défaut le retrait doux de la charte. */
  echelle?: number;
  /** Choc haptique au contact. Vrai par défaut ; à couper pour un geste massif. */
  haptique?: boolean;
  style?: StyleProp<ViewStyle>;
}>(function Presse(
  { echelle = motion.echelle.presse, haptique = true, onPressIn, onPressOut, onHoverIn, onHoverOut, style, ...reste },
  ref,
) {
  const reduire = useReducedMotion();
  // Deux valeurs distinctes qui se multiplient : le press (retrait sous le doigt)
  // et le survol (soulèvement sous la souris, web). Les garder séparées évite
  // qu'un pointeur qui quitte la cible pendant l'appui ne remette l'échelle de
  // travers.
  const facteur = useSharedValue(1);
  const survol = useSharedValue(1);
  const styleAnime = useAnimatedStyle(() => ({ transform: [{ scale: facteur.value * survol.value }] }));

  return (
    <PressableAnimee
      ref={ref}
      {...reste}
      // Le curseur main sur le web dit « ça se clique » avant même le survol.
      style={[Platform.OS === 'web' ? webCurseur : null, style, styleAnime]}
      onPressIn={(e) => {
        if (haptique) {
          Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light).catch(() => {});
        }
        if (!reduire) facteur.value = withSpring(echelle, motion.ressort.vif);
        onPressIn?.(e);
      }}
      onPressOut={(e) => {
        if (!reduire) facteur.value = withSpring(1, motion.ressort.vif);
        onPressOut?.(e);
      }}
      onHoverIn={(e) => {
        if (!reduire) survol.value = withSpring(SURVOL, motion.ressort.doux ?? motion.ressort.vif);
        onHoverIn?.(e);
      }}
      onHoverOut={(e) => {
        if (!reduire) survol.value = withSpring(1, motion.ressort.doux ?? motion.ressort.vif);
        onHoverOut?.(e);
      }}
    />
  );
});

// `cursor` n'existe pas dans les types de style RN, mais RN-web le lit : on le
// pose par un objet à part, typé en `any` juste ici, pour ne pas relâcher le
// typage des styles partout ailleurs.
const webCurseur = { cursor: 'pointer' } as unknown as ViewStyle;
