import { Feather } from '@expo/vector-icons';
import { useMemo, useState } from 'react';
import { Modal, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';

import { t } from '@/i18n';
import { espace, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/** Un moment proposé : sa clé, son horaire, son libellé, et les autres noms qu'il porte selon le jour. */
export type OptionMoment = {
  cle: string;
  debut: string;
  fin: string;
  libelle: string;
  /** Les autres libellés du même horaire selon le jour (« ven : Psychomotricité »). */
  autres?: string[];
};

/**
 * Le choix du moment, en PUCE COMPACTE qui ouvre une feuille avec la liste
 * COMPLÈTE (retour Sophie/Valentin 24/09 : la rangée de pastilles s'étalait sur
 * tout l'écran, montrait des doublons, et coupait des créneaux). Même grammaire
 * que le calendrier (`SelecteurJoursMenu`) : on voit ce qui est choisi, on ouvre
 * pour changer, la feuille se ferme au choix. « Sans moment » est toujours en tête.
 */
export function SelecteurMoment({
  options,
  choisi,
  onChoisir,
  etiquette,
}: {
  options: OptionMoment[];
  /** La clé choisie, `null` = sans moment. */
  choisi: string | null;
  onChoisir: (cle: string | null) => void;
  etiquette?: string;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const [ouvert, setOuvert] = useState(false);

  // Une clé venue d'ailleurs (case du semainier) peut porter un libellé voisin :
  // on la rattache à l'option de même heure.
  const actuel =
    options.find((o) => o.cle === choisi) ??
    (choisi ? options.find((o) => choisi.split('\u0000')[0] === o.debut) : undefined) ??
    null;
  const resume = actuel ? `${actuel.debut} · ${actuel.libelle}` : t.activite.momentSans;

  function choisir(cle: string | null) {
    onChoisir(cle);
    setOuvert(false);
  }

  return (
    <View style={styles.groupe}>
      {etiquette ? <Text style={styles.etiquette}>{etiquette}</Text> : null}
      <Pressable
        accessibilityRole="button"
        accessibilityLabel={`${etiquette ?? t.activite.moment}, ${resume}`}
        onPress={() => setOuvert(true)}
        style={styles.puce}>
        <Feather name="clock" size={16} color={c.encreDouce} />
        <Text style={styles.puceTexte} numberOfLines={1}>
          {resume}
        </Text>
        <Feather name="chevron-down" size={16} color={c.encre} />
      </Pressable>

      <Modal visible={ouvert} transparent animationType="fade" onRequestClose={() => setOuvert(false)}>
        <Pressable style={styles.voile} onPress={() => setOuvert(false)}>
          <Pressable style={styles.feuille} onPress={() => {}}>
            {/* En-tête fixe, hors ScrollView : la croix reste atteignable (charte). */}
            <View style={styles.tete}>
              <Text style={styles.titre}>{t.activite.moment}</Text>
              <Pressable
                accessibilityRole="button"
                accessibilityLabel={t.activite.joursMenuFermer}
                onPress={() => setOuvert(false)}
                hitSlop={8}
                style={styles.fermer}>
                <Feather name="x" size={18} color={c.encreDouce} />
              </Pressable>
            </View>
            <ScrollView style={styles.liste} showsVerticalScrollIndicator={false}>
              <Ligne
                styles={styles}
                c={c}
                heure=""
                libelle={t.activite.momentSans}
                actif={choisi === null}
                onPress={() => choisir(null)}
              />
              {options.map((o) => (
                <Ligne
                  key={o.cle}
                  styles={styles}
                  c={c}
                  heure={o.fin ? `${o.debut}\n${o.fin}` : o.debut}
                  libelle={o.libelle}
                  autres={o.autres}
                  actif={o.cle === actuel?.cle}
                  onPress={() => choisir(o.cle)}
                />
              ))}
            </ScrollView>
          </Pressable>
        </Pressable>
      </Modal>
    </View>
  );
}

function Ligne({
  styles,
  c,
  heure,
  libelle,
  autres,
  actif,
  onPress,
}: {
  styles: ReturnType<typeof creerStyles>;
  c: Couleurs;
  heure: string;
  libelle: string;
  autres?: string[];
  actif: boolean;
  onPress: () => void;
}) {
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityState={{ selected: actif }}
      accessibilityLabel={heure ? `${heure.replace('\n', ' à ')} ${libelle}` : libelle}
      onPress={onPress}
      style={[styles.ligne, actif && styles.ligneActive]}>
      <Text style={styles.heure}>{heure}</Text>
      <View style={styles.corps}>
        <Text style={[styles.libelle, actif && styles.libelleActif]}>{libelle}</Text>
        {autres?.length ? <Text style={styles.autres}>{autres.join(' · ')}</Text> : null}
      </View>
      {actif ? <Feather name="check" size={18} color={c.actif} /> : null}
    </Pressable>
  );
}

