import * as ImagePicker from 'expo-image-picker';
import { useEffect, useSyncExternalStore } from 'react';

import type { Pose } from '@/components/cloudy';
import { langue, type Langue } from '@/i18n';

import { supabase } from './supabase';

/**
 * Les rares messages d'erreur que l'avatar remonte tels quels à l'écran
 * (`AvatarChoisir` affiche `e.message`). Tenus en local, bilingues, pour ne pas
 * servir du français à une prof nl (les seuls libellés du domaine qui étaient
 * restés FR en dur).
 */
const LIB_AVATAR: Record<Langue, { sansSession: string; fichierVide: string; permissionPhotos: string }> = {
  fr: {
    sansSession: "Ta session a expiré. Reconnecte-toi, puis réessaie de changer d'avatar.",
    fichierVide: "Le fichier est vide, rien n'a été joint.",
    permissionPhotos:
      "Educooo n'a pas accès à tes photos. Autorise l'accès dans les réglages pour en choisir une.",
  },
  nl: {
    sansSession: 'Je sessie is verlopen. Meld je opnieuw aan en probeer je avatar nogmaals te wijzigen.',
    fichierVide: 'Het bestand is leeg, er is niets toegevoegd.',
    permissionPhotos:
      "Educooo heeft geen toegang tot je foto's. Geef toegang in de instellingen om er een te kiezen.",
  },
};

/**
 * L'avatar de l'enseignant·e : soit un preset (une pose de la mascotte Cloudy),
 * soit sa propre photo. La valeur choisie est rangée sur `profiles.avatar`.
 *
 * 🔑 Le format stocké est auto-descriptif, pour se lire sans table de plus :
 *   - `preset:<pose>` pour un avatar Cloudy (ex. `preset:salut`) ;
 *   - une URL publique complète (https://…) pour une photo perso ;
 *   - `null` quand rien n'est choisi (l'app retombe sur Cloudy neutre).
 *
 * 🖼️ La photo perso vit dans le seau PUBLIC `avatars` (voir la migration
 * `20260911_avatar.sql`), sous `<uid>/avatar-<timestamp>.<ext>`. On y range
 * l'URL publique, stable et cacheable : l'avatar s'affiche dans l'en-tête de
 * chaque écran, on ne veut pas signer une URL à chaque montage.
 *
 * 🚨 On n'ajoute AUCUNE fonction dans `donnees.ts` : tout l'avatar vit ici, y
 * compris la lecture/écriture sur `profiles`, pour garder une seule maison.
 */

const SEAU = 'avatars';

/** Le préfixe qui distingue une clé de preset d'une URL de photo. */
const PREFIXE_PRESET = 'preset:';

/**
 * Le petit jeu d'avatars proposé, appuyé sur les poses de Cloudy (charte : que
 * des poses positives, jamais une pose négative dirigée vers l'utilisatrice).
 * Chaque `cle` est la valeur stockée (`preset:<pose>`), la `pose` sert au rendu,
 * et `libelleClef` pointe l'étiquette d'accessibilité dans l'i18n.
 */
export type PresetAvatar = { cle: string; pose: Pose };

export const PRESETS_AVATAR: PresetAvatar[] = (
  ['salut', 'joie', 'serenite', 'loupe', 'micro', 'prof', 'randonneur', 'chapeau', 'celebration', 'neutre'] as const
).map((pose) => ({ cle: `${PREFIXE_PRESET}${pose}`, pose }));

/** Les poses connues, pour valider une clé de preset lue en base. */
const POSES_VALIDES = new Set<string>(PRESETS_AVATAR.map((p) => p.pose));

/** Le résultat de la résolution d'une valeur d'avatar, prêt à peindre. */
export type AvatarResolu =
  | { type: 'photo'; url: string }
  | { type: 'preset'; pose: Pose }
  | { type: 'defaut' };

/**
 * Traduit la valeur brute de `profiles.avatar` en descripteur d'affichage.
 * Synchrone à dessein : le rendu de l'en-tête ne doit pas attendre un réseau.
 * Toute valeur inattendue retombe proprement sur le défaut (Cloudy neutre).
 */
export function resoudreAvatar(valeur: string | null | undefined): AvatarResolu {
  if (!valeur) return { type: 'defaut' };
  if (valeur.startsWith(PREFIXE_PRESET)) {
    const pose = valeur.slice(PREFIXE_PRESET.length);
    return POSES_VALIDES.has(pose) ? { type: 'preset', pose: pose as Pose } : { type: 'defaut' };
  }
  if (valeur.startsWith('http')) return { type: 'photo', url: valeur };
  return { type: 'defaut' };
}

/**
 * 🌍 STORE RÉACTIF GLOBAL de l'avatar. Sans lui, chaque en-tête lisait sa propre
 * copie au montage : changer l'avatar dans « Moi » ne se voyait que sur cette
 * page. Ici une seule valeur partagée : tout `useAvatar()` (tous les en-têtes,
 * l'aperçu de « Moi ») se re-rend dès qu'on la change, partout à la fois.
 * `undefined` = pas encore chargé ; on charge une fois à la première lecture.
 */
let avatarActuel: string | null | undefined = undefined;
let chargementLance = false;
const auditeurs = new Set<() => void>();

function notifierAvatar() {
  for (const l of auditeurs) l();
}

/** Met à jour la valeur partagée et prévient tous les abonnés (après écriture base). */
export function poserAvatarLocal(valeur: string | null): void {
  avatarActuel = valeur;
  notifierAvatar();
}

/**
 * L'avatar courant, réactif. Charge la valeur une fois (première lecture), puis
 * suit le store : un changement fait par n'importe quel écran se voit partout.
 */
export function useAvatar(): string | null {
  const valeur = useSyncExternalStore(
    (cb) => {
      auditeurs.add(cb);
      return () => auditeurs.delete(cb);
    },
    () => (avatarActuel === undefined ? null : avatarActuel),
    () => (avatarActuel === undefined ? null : avatarActuel),
  );
  useEffect(() => {
    if (!chargementLance) {
      chargementLance = true;
      lireAvatar()
        .then((v) => poserAvatarLocal(v))
        .catch(() => {
          // Lecture ratée : on ne bloque rien, l'en-tête garde Cloudy neutre.
          chargementLance = false;
        });
    }
  }, []);
  return valeur;
}

/** L'uid de la session, ou une erreur lisible : on n'écrit jamais sans identité. */
async function uidSession(): Promise<string> {
  const { data } = await supabase.auth.getUser();
  const id = data.user?.id;
  if (!id) throw new Error(LIB_AVATAR[langue].sansSession);
  return id;
}

/** L'extension d'un URI/MIME, pour nommer le fichier. Défaut `jpg`. */
function extensionDe(mime: string | null, uri: string, defaut: string): string {
  if (mime?.includes('/')) {
    const ext = mime.split('/')[1]?.toLowerCase();
    if (ext) return ext === 'jpeg' ? 'jpg' : ext;
  }
  const propre = uri.split('?')[0];
  const point = propre.lastIndexOf('.');
  if (point !== -1 && point > propre.lastIndexOf('/')) {
    const ext = propre.slice(point + 1).toLowerCase();
    if (ext && ext.length <= 5) return ext;
  }
  return defaut;
}

/** Lit la valeur brute d'avatar de l'enseignant·e connecté·e (ou null). */
export async function lireAvatar(): Promise<string | null> {
  const { data: session } = await supabase.auth.getUser();
  const id = session.user?.id;
  if (!id) return null;
  const { data, error } = await supabase
    .from('profiles')
    .select('avatar')
    .eq('id', id)
    .maybeSingle();
  if (error) throw error;
  return data?.avatar ?? null;
}

/** Range un preset Cloudy comme avatar (`cle` vaut `preset:<pose>`). */
export async function enregistrerPreset(cle: string): Promise<void> {
  const id = await uidSession();
  const { error } = await supabase.from('profiles').update({ avatar: cle }).eq('id', id);
  if (error) throw error;
  poserAvatarLocal(cle);
}

/** Efface l'avatar : retour au défaut (Cloudy neutre). Best-effort côté fichiers. */
export async function retirerAvatar(): Promise<void> {
  const id = await uidSession();
  const { error } = await supabase.from('profiles').update({ avatar: null }).eq('id', id);
  if (error) throw error;
  poserAvatarLocal(null);
  await viderDossier(id).catch(() => {});
}

/**
 * Lit un fichier local en `ArrayBuffer`.
 *
 * 🚨 On n'envoie PAS un `Blob` : sur React Native il remonte régulièrement à
 * zéro octet et l'upload « réussit » en écrivant un fichier vide. L'`ArrayBuffer`
 * obtenu par `fetch` est la voie recommandée par Supabase pour Expo (même leçon
 * que la dictée et les médias d'observation).
 */
async function lireFichier(uri: string): Promise<ArrayBuffer> {
  const reponse = await fetch(uri);
  const donnees = await reponse.arrayBuffer();
  if (!donnees.byteLength) throw new Error(LIB_AVATAR[langue].fichierVide);
  return donnees;
}

/** Retire tous les fichiers du dossier avatar de l'uid (nettoyage best-effort). */
async function viderDossier(uid: string): Promise<void> {
  const { data } = await supabase.storage.from(SEAU).list(uid);
  const chemins = (data ?? []).map((f) => `${uid}/${f.name}`);
  if (chemins.length) await supabase.storage.from(SEAU).remove(chemins);
}

/**
 * Ouvre la galerie, envoie la photo choisie dans le seau `avatars`, range son
 * URL publique sur le profil, et renvoie cette URL. `null` si on annule.
 *
 * Permission demandée d'abord (message clair si refus). `quality: 0.6` compresse
 * pour un envoi léger sur un réseau d'école. On carre l'image (`allowsEditing`)
 * pour un avatar rond propre. On vide l'ancien dossier avant d'écrire, pour ne
 * pas accumuler d'orphelins.
 */
export async function envoyerPhotoAvatar(): Promise<string | null> {
  const permission = await ImagePicker.requestMediaLibraryPermissionsAsync();
  if (!permission.granted) {
    throw new Error(LIB_AVATAR[langue].permissionPhotos);
  }
  const resultat = await ImagePicker.launchImageLibraryAsync({
    mediaTypes: ['images'],
    quality: 0.6,
    allowsMultipleSelection: false,
    allowsEditing: true,
    aspect: [1, 1],
    exif: false,
  });
  if (resultat.canceled) return null;
  const asset = resultat.assets?.[0];
  if (!asset?.uri) return null;

  const uid = await uidSession();
  const ext = extensionDe(asset.mimeType ?? null, asset.uri, 'jpg');
  const chemin = `${uid}/avatar-${Date.now()}.${ext}`;

  const donnees = await lireFichier(asset.uri);
  const { error: erreurUpload } = await supabase.storage
    .from(SEAU)
    .upload(chemin, donnees, { contentType: asset.mimeType ?? 'image/jpeg', upsert: false });
  if (erreurUpload) throw erreurUpload;

  const { data: pub } = supabase.storage.from(SEAU).getPublicUrl(chemin);
  const url = pub.publicUrl;

  const { error } = await supabase.from('profiles').update({ avatar: url }).eq('id', uid);
  if (error) {
    // La ligne n'a pas pu être écrite : on ne garde pas un fichier fantôme.
    await supabase.storage.from(SEAU).remove([chemin]).catch(() => {});
    throw error;
  }

  // L'écriture a réussi : on retire les avatars précédents (tout sauf le neuf).
  const { data: contenu } = await supabase.storage.from(SEAU).list(uid);
  const vieux = (contenu ?? [])
    .map((f) => `${uid}/${f.name}`)
    .filter((p) => p !== chemin);
  if (vieux.length) await supabase.storage.from(SEAU).remove(vieux).catch(() => {});

  poserAvatarLocal(url);
  return url;
}
