import AsyncStorage from '@react-native-async-storage/async-storage';
import { createClient } from '@supabase/supabase-js';
import { AppState, Platform } from 'react-native';
import 'react-native-url-polyfill/auto';

import { env } from './env';

export const supabase = createClient(env.supabaseUrl, env.supabasePublishableKey, {
  auth: {
    storage: AsyncStorage,
    autoRefreshToken: true,
    persistSession: true,
    // Pas de session dans l'URL : on n'est pas dans un navigateur.
    detectSessionInUrl: false,
  },
});

// 🔴 Sur mobile, les minuteries JS dorment quand l'app passe en arrière-plan :
// le jeton d'accès (1 h) expire sans être rafraîchi, et la PREMIÈRE requête au
// retour part avec un jeton mort. Symptôme vu chez Sophie (22/09) : « La
// création a échoué », puis ça passe au deuxième tap. Supabase demande de
// relancer le rafraîchissement à chaque retour au premier plan. Le web garde
// son propre cycle (onglet visible), on n'y touche pas.
if (Platform.OS !== 'web') {
  AppState.addEventListener('change', (etat) => {
    if (etat === 'active') supabase.auth.startAutoRefresh();
    else supabase.auth.stopAutoRefresh();
  });
}
