import { router, useLocalSearchParams } from 'expo-router';
import { useEffect, useMemo, useState } from 'react';
import { StyleSheet, Text } from 'react-native';

import { Carte } from '@/components/ecran';
import { Alerte, BoutonDiscret, BoutonPrincipal } from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { t } from '@/i18n';
import { collegueParCode, demanderCollegue } from '@/lib/donnees';
import { police, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Ce que le QR d'une collègue ouvre.
 *
 * 🔑 C'est cette route qui permet de se passer d'un scanner embarqué.
 *
 * Le QR porte `educooo://c/<code>`. L'appareil photo d'un iPhone ou d'un
 * Android lit déjà les QR et propose d'ouvrir le lien : on atterrit ici, dans
 * l'app, sans qu'on ait eu à demander l'autorisation caméra ni à maintenir un
 * écran de scan. Le téléphone fait mieux ce travail que nous.
 *
 * 🚨 ON NE LIE PERSONNE AUTOMATIQUEMENT.
 *
 * L'écran montre qui est en face et attend un geste. Un QR se scanne par
 * curiosité, par erreur, ou dans le dos de quelqu'un ; ouvrir un lien n'est pas
 * consentir à un lien. Et de toute façon la demande devra encore être acceptée
 * de l'autre côté : deux gestes, un par personne.
 */
export default function ParCode() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { code } = useLocalSearchParams<{ code: string }>();

  const [personne, setPersonne] = useState<{ id: string; nom: string | null } | null>(null);
  const [cherche, setCherche] = useState(true);
  const [envoyee, setEnvoyee] = useState(false);
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);

  useEffect(() => {
    let vivant = true;
    // Sans code, il n'y a rien à chercher : l'écran le déduit au rendu (plus bas).
    if (!code) return;
    collegueParCode(code)
      .then((r) => {
        if (vivant) {
          setPersonne(r);
          setCherche(false);
        }
      })
      .catch(() => {
        if (vivant) {
          setErreur(t.groupes.erreurAction);
          setCherche(false);
        }
      });
    return () => {
      vivant = false;
    };
  }, [code]);

  async function demander() {
    if (!personne) return;
    setErreur(null);
    setOccupe(true);
    try {
      await demanderCollegue(personne.id);
      setEnvoyee(true);
    } catch (e) {
      setErreur(
        e instanceof Error && e.message === 'deja_demande'
          ? t.groupes.dejaDemande
          : t.groupes.erreurAction,
      );
    } finally {
      setOccupe(false);
    }
  }

  return (
    <SousEcran titre={t.groupes.ajouterTitre} chargement={!!code && cherche}>
      {!personne ? (
        <Carte>
          <Text style={texte.discret}>{t.groupes.codeIntrouvable}</Text>
        </Carte>
      ) : envoyee ? (
        <Carte>
          <Text style={styles.confirme}>{t.groupes.demandee}</Text>
          <BoutonDiscret libelle={t.commun.annuler} onPress={() => router.replace('/groupes')} />
        </Carte>
      ) : (
        <Carte>
          <Text style={texte.section}>{t.groupes.trouvee(personne.nom)}</Text>
          <BoutonPrincipal
            libelle={t.groupes.demander}
            onPress={demander}
            occupe={occupe}
          />
          <BoutonDiscret libelle={t.commun.annuler} onPress={() => router.back()} />
        </Carte>
      )}
      {erreur ? <Alerte message={erreur} /> : null}
    </SousEcran>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  confirme: { fontFamily: police.accent, fontSize: 15, color: c.actif },
});
