/**
 * Choisir des attendus du référentiel.
 *
 * Le même geste revient à quatre endroits : ranger une observation, créer une
 * activité, compléter une activité, et clôturer une séance qui n'a rien de
 * rattaché. Un composant écrit quatre fois dérive quatre fois, et le pire
 * endroit où faire dériver l'interface est celui qui décide de ce qui atterrit
 * dans le dossier d'un enfant.
 *
 * Deux choses tenues ici, et elles ne sont pas cosmétiques.
 *
 * Rien n'est jamais coché d'avance. La machine propose, l'enseignante décide.
 *
 * Le code d'un attendu ne s'affiche que s'il est réel. 2 663 attendus portent un
 * code fabriqué du type `EXP-001`, non unique, et `donnees.ts` les rend déjà à
 * `null` : un code faux est pire qu'un code absent, parce qu'il donne à croire
 * qu'on peut le retrouver dans le document officiel.
 */

export function LigneAttendu({
  attendu,
  choisi,
  onBasculer,
  marque,
  note,
  citation,
  citationVerifiee,
  confiance,
  onRetirer,
}: {
  attendu: Attendu;
  choisi?: boolean;
  onBasculer?: () => void;
  /** Une étiquette courte devant le libellé : le rôle, ou un état. */
  marque?: string;
  /** Une phrase qui explique la proposition. */
  note?: string;
  citation?: string;
  citationVerifiee?: boolean;
  confiance?: 'haute' | 'moyenne';
  /** Quand la ligne n'est pas un choix mais un rattachement déjà fait. */
  onRetirer?: () => void;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const contenu = (
    <>
      {onBasculer ? (
        <View style={[styles.coche, choisi && styles.cocheActive]}>
          {choisi ? <Feather name="check" size={16} color={c.surface} /> : null}
        </View>
      ) : null}
      <View style={styles.corps}>
        {marque ? <Text style={styles.marque}>{marque}</Text> : null}
        <Text style={texte.corps}>{attendu.libelle}</Text>
        <Text style={texte.discret}>
          {[attendu.domaine, attendu.competence, attendu.code].filter(Boolean).join(' · ')}
        </Text>
        {note ? <Text style={styles.note}>{note}</Text> : null}
        {/* La citation est la preuve : si elle ne se retrouve pas dans le texte,
            on le dit au lieu de la présenter comme une justification. */}
        {citation ? (
          <Text style={citationVerifiee ? styles.citation : styles.citationDouteuse}>
            {citationVerifiee ? t.ranger.citation(citation) : t.ranger.citationDouteuse}
          </Text>
        ) : null}
      </View>
      {confiance ? (
        <View style={[styles.confiance, confiance === 'haute' && styles.confianceHaute]} />
      ) : null}
      {onRetirer ? (
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={`${t.activite.retirer} : ${attendu.libelle}`}
          onPress={onRetirer}
          style={styles.retirer}>
          <Feather name="x" size={18} color={c.encreDouce} />
        </Pressable>
      ) : null}
    </>
  );

  if (!onBasculer) {
    return <View style={styles.ligne}>{contenu}</View>;
  }

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityState={{ selected: !!choisi }}
      accessibilityLabel={[marque, attendu.libelle, attendu.domaine].filter(Boolean).join(', ')}
      onPress={onBasculer}
      style={[styles.ligne, choisi && styles.ligneActive]}>
      {contenu}
    </Pressable>
  );
}

/**
 * La recherche à la main.
 *
 * 🚨 C'est une **issue de secours**, jamais le chemin principal. La même
 * recherche du mot « écrire » rend 104 attendus sans les bons filtres et 10
 * avec : la différence tient à des réglages qu'une enseignante ne voit pas et ne
 * peut pas juger. Personne ne doit avoir à affronter 7 226 attendus, c'est le
 * travail de la machine.
 */
export function RechercheAttendus({
  classe,
  choisis,
  onBasculer,
  exclus,
}: {
  classe: Classe;
  choisis: string[];
  onBasculer: (attendu: Attendu) => void;
  /** Les attendus déjà rattachés, qu'on ne propose pas deux fois. */
  exclus?: Set<string>;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { saisie, differee, setSaisie } = useRechercheDifferee();

  const resultats = useRequete(
    () => chercherAttendus({ classe, recherche: differee }),
    [classe.id, differee],
    { actif: differee.trim().length >= 3 },
  );

  const liste = (resultats.donnees ?? []).filter((a) => !exclus?.has(a.id));

  return (
    <View style={styles.bloc}>
      <Champ
        etiquette={t.ranger.recherche}
        value={saisie}
        onChangeText={setSaisie}
        placeholder={t.ranger.rechercheIndice}
        autoCorrect={false}
        autoFocus
      />
      {/* Descendre dans le programme au lieu de deviner le bon mot (retour Sophie 24/09). */}
      <ParcourirProgramme classe={classe} choisis={choisis} onBasculer={onBasculer} exclus={exclus} />
      {saisie.trim().length > 0 && saisie.trim().length < 3 ? (
        <Text style={styles.note}>{t.ranger.rechercheCourte}</Text>
      ) : null}
      {resultats.chargement ? <ActivityIndicator color={c.encreDouce} /> : null}
      {!resultats.chargement && liste.length === 0 && differee.trim().length >= 3 ? (
        <Text style={styles.note}>{t.ranger.aucunResultat}</Text>
      ) : null}
      {liste.map((a) => (
        <LigneAttendu
          key={a.id}
          attendu={a}
          choisi={choisis.includes(a.id)}
          onBasculer={() => onBasculer(a)}
        />
      ))}
    </View>
  );
}

/**
 * Le champ de recherche, sans requête à chaque frappe.
 *
 * `chercherAttendus` fait plusieurs allers-retours (les référentiels visibles,
 * puis les attendus), donc taper « découper » lancerait huit recherches dont
 * sept périmées. Le hook de requête sait déjà ignorer les réponses en retard,
 * mais il ne sait pas ne pas les demander.
 *
 * On rend les deux valeurs : la saisie pour l'affichage, qui doit rester
 * immédiate, et la valeur différée pour la requête.
 */
function useRechercheDifferee() {
  const [saisie, setSaisie] = useState('');
  const [differee, setDifferee] = useState('');
  const minuteur = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (minuteur.current) clearTimeout(minuteur.current);
    minuteur.current = setTimeout(() => setDifferee(saisie), 350);
    return () => {
      if (minuteur.current) clearTimeout(minuteur.current);
    };
  }, [saisie]);

  return { saisie, differee, setSaisie };
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  bloc: { gap: espace.sm },
  ligne: {
    flexDirection: 'row',
    gap: espace.md,
    alignItems: 'flex-start',
    backgroundColor: c.fond,
    borderRadius: rayon.bloc,
    borderWidth: 1,
    borderColor: c.bord,
    padding: espace.md,
  },
  ligneActive: {
    borderColor: c.actif,
    backgroundColor: c.surface,
    ...ombre.carte,
  },
  coche: {
    width: 24,
    height: 24,
    borderRadius: 8,
    borderWidth: 2,
    borderColor: c.bord,
    alignItems: 'center',
    justifyContent: 'center',
    marginTop: 2,
  },
  cocheActive: { backgroundColor: c.actif, borderColor: c.actif },
  corps: { flex: 1, gap: espace.xs },
  marque: {
    fontFamily: police.titre,
    fontSize: 12,
    color: c.encreDouce,
    textTransform: 'uppercase',
    letterSpacing: 0.4,
  },
  note: { fontFamily: police.corps, fontSize: 14, color: c.encreDouce },
  citation: { fontFamily: police.corps, fontSize: 13, color: c.encreDouce, fontStyle: 'italic' },
  citationDouteuse: { fontFamily: police.accent, fontSize: 13, color: c.action[1] },
  confiance: {
    width: 8,
    height: 8,
    borderRadius: 4,
    borderWidth: 2,
    borderColor: c.nonRattache,
    marginTop: 6,
  },
  confianceHaute: { backgroundColor: c.actif, borderColor: c.actif },
  retirer: { width: 32, height: 32, alignItems: 'center', justifyContent: 'center' },
});
