import { Feather } from '@expo/vector-icons';
import { ReactNode, useMemo } from 'react';
import { Pressable, ScrollView, StyleSheet, Text, useWindowDimensions, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { Cloudy, type Pose } from '@/components/cloudy';
import { Presse } from '@/components/presse';
import { SelecteurClasse } from '@/components/selecteur-classe';
import { espace, maxContenu, maxContenuLarge, motion, ombre, pointLarge, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Gabarit d'écran : fond neutre, en-tête fixe, contenu en cartes blanches.
 *
 * 🔑 L'en-tête du témoin v9 tient en trois pièces : l'avatar Cloudy à gauche, le
 * titre, et des boutons ronds d'action à droite. Il était réduit à un titre nu,
 * ce qui aplatissait tous les écrans. La mascotte revient ici, une seule fois
 * par écran, comme le veut la charte.
 *
 * L'en-tête ne défile pas : sur un écran de liste, on garde le titre et les
 * gestes sous la main. Le contenu réserve en bas la place de la nav flottante.
 */
export function Ecran({
  titre,
  avatar,
  avatarMenu,
  actions,
  selecteurClasse = false,
  sousEntete,
  pleineLargeur = false,
  children,
}: {
  titre: string;
  /** Affiche Cloudy à gauche du titre. `true` prend la pose neutre. */
  avatar?: Pose | true;
  /**
   * Un élément tactile posé à l'EXTRÊME gauche de l'en-tête (avant le titre) :
   * l'avatar de navigation quand le drapeau `NAV_AVATAR` est ON, qui ouvre
   * l'espace « Moi ». Il prend la place de l'avatar Cloudy décoratif s'il est
   * fourni. À `undefined` (défaut, drapeau OFF), rien ne s'ajoute : l'en-tête
   * est identique à aujourd'hui.
   */
  avatarMenu?: ReactNode;
  /** Boutons ronds à droite (voir BoutonRond). */
  actions?: ReactNode;
  /**
   * Affiche le sélecteur de classe juste à droite du titre. Réservé aux écrans
   * qui parlent d'UNE classe et où l'on bascule souvent (pilotage, journal,
   * capter) : le geste est alors sous la main partout, pas enfoui dans Réglages.
   */
  selecteurClasse?: boolean;
  /**
   * Une rangée FIXE sous l'en-tête, hors du défilement : elle reste sous la main
   * quand on scrolle (la barre de semaine du journal, par exemple).
   */
  sousEntete?: ReactNode;
  /**
   * L'écran DEMANDE la pleine largeur (grille du semainier) : sur grand écran on
   * l'élargit à `maxContenuLarge` au lieu de la colonne étroite de lecture. Le
   * défaut reste la colonne étroite (bon pour du texte empilé).
   */
  pleineLargeur?: boolean;
  children?: ReactNode;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const pose = avatar === true ? 'neutre' : avatar;
  // Grands écrans : on centre l'en-tête et la colonne de cartes sur une largeur
  // confortable. Sous le seuil (tout téléphone), `large` est faux et rien ne
  // s'ajoute : la mise en page reste identique au pixel près.
  const { width } = useWindowDimensions();
  const large = width > pointLarge;
  const colonne = pleineLargeur ? styles.colonneLarge : styles.colonne;
  return (
    <SafeAreaView style={styles.racine} edges={['top']}>
      <View style={[styles.entete, large && colonne]}>
        {avatarMenu ? avatarMenu : pose ? <Cloudy pose={pose} taille={38} cercle /> : null}
        {/* Titre et sélecteur de classe groupés à gauche ; un ressort les
            sépare des boutons d'action à droite. Le titre rétrécit avant le
            sélecteur pour que la puce de classe reste toujours lisible. */}
        <View style={styles.groupeTitre}>
          <Text style={[texte.titre, styles.titre]} numberOfLines={1}>
            {titre}
          </Text>
          {selecteurClasse ? <SelecteurClasse /> : null}
        </View>
        <View style={styles.espace} />
        {actions ? <View style={styles.actions}>{actions}</View> : null}
      </View>
      {sousEntete ? (
        <View style={[styles.sousEntete, large && colonne]}>{sousEntete}</View>
      ) : null}
      <ScrollView
        contentContainerStyle={[styles.contenu, large && colonne]}
        showsVerticalScrollIndicator={false}>
        {children}
      </ScrollView>
    </SafeAreaView>
  );
}

/**
 * Bouton rond d'en-tête : une icône sur une pastille blanche à ombre douce.
 * Pour les gestes secondaires d'un écran (messages, notifications, fermer).
 */
export function BoutonRond({
  icone,
  onPress,
  libelle,
  pastille = false,
}: {
  icone: keyof typeof Feather.glyphMap;
  onPress: () => void;
  libelle: string;
  /** Point corail en haut à droite, pour signaler du nouveau. */
  pastille?: boolean;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <Presse
      accessibilityRole="button"
      accessibilityLabel={libelle}
      onPress={onPress}
      style={styles.rond}>
      <Feather name={icone} size={18} color={c.encre} />
      {pastille ? <View style={styles.point} /> : null}
    </Presse>
  );
}

/**
 * Carte blanche sur fond neutre.
 *
 * `compacte` sert aux lignes de liste. Une carte de contenu mérite ses 24
 * pixels de marge, une ligne de liste non : six élèves remplissaient tout
 * l'écran et le bouton d'ajout passait sous le pli. Une classe de vingt-cinq
 * devenait un couloir.
 */
export function Carte({
  children,
  compacte = false,
  onPress,
}: {
  children: ReactNode;
  compacte?: boolean;
  /**
   * Rend la carte tactile : elle rentre un peu sous le doigt (scale + haptique).
   * Sans `onPress`, la carte reste un simple contenant immobile — une carte qui
   * n'ouvre rien ne doit ni s'enfoncer ni vibrer.
   */
  onPress?: () => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const style = [styles.carte, compacte && styles.carteCompacte];
  if (!onPress) return <View style={style}>{children}</View>;
  return (
    <Presse
      accessibilityRole="button"
      onPress={onPress}
      echelle={motion.echelle.presse}
      style={style}>
      {children}
    </Presse>
  );
}

/**
 * En-tête de section entre deux cartes : un titre, et un lien d'action à droite
 * (« Tout voir »). Le lien porte le corail de l'action, seul accent autorisé sur
 * du texte.
 */
export function EnteteSection({
  titre,
  action,
  onAction,
}: {
  titre: string;
  action?: string;
  onAction?: () => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <View style={styles.section}>
      <Text style={styles.sectionTitre}>{titre}</Text>
      {action && onAction ? (
        <Pressable accessibilityRole="button" accessibilityLabel={action} onPress={onAction}>
          <Text style={styles.sectionAction}>{action}</Text>
        </Pressable>
      ) : null}
    </View>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  racine: { flex: 1, backgroundColor: c.fond },
  entete: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: espace.sm,
    paddingHorizontal: espace.md,
    paddingTop: espace.sm,
    paddingBottom: espace.sm,
  },
  // Le TITRE reste toujours entier (priorité au titre, retour Valentin : « Pilotage »
  // se faisait couper depuis l'ajout de l'avatar). C'est la puce de classe qui
  // rétrécit/tronque si la place manque, pas le titre.
  titre: { flexShrink: 0 },
  groupeTitre: { flexDirection: 'row', alignItems: 'center', gap: espace.sm, flexShrink: 1, minWidth: 0 },
  espace: { flex: 1 },
  sousEntete: { paddingHorizontal: espace.md, paddingBottom: espace.sm },
  actions: { flexDirection: 'row', gap: espace.sm },
  rond: {
    width: 38,
    height: 38,
    borderRadius: 19,
    backgroundColor: c.surface,
    alignItems: 'center',
    justifyContent: 'center',
    ...ombre.carte,
  },
  point: {
    position: 'absolute',
    top: 8,
    right: 9,
    width: 8,
    height: 8,
    borderRadius: 4,
    backgroundColor: c.actif,
  },
  // Le bas réserve la hauteur de la nav flottante (62 + 14 de marge + jeu).
  contenu: { padding: espace.md, paddingTop: espace.xs, paddingBottom: 110, gap: espace.md },
  // Colonne centrée, plafonnée : appliquée seulement au-delà de `pointLarge`.
  colonne: { width: '100%', maxWidth: maxContenu, alignSelf: 'center' },
  colonneLarge: { width: '100%', maxWidth: maxContenuLarge, alignSelf: 'center' },
  carte: {
    backgroundColor: c.surface,
    borderRadius: rayon.carte,
    padding: espace.lg,
    gap: espace.sm,
    ...ombre.carte,
  },
  carteCompacte: { padding: espace.md, borderRadius: rayon.bloc, gap: espace.xs },
  section: {
    flexDirection: 'row',
    alignItems: 'baseline',
    justifyContent: 'space-between',
    paddingHorizontal: espace.xs,
    marginTop: espace.xs,
  },
  sectionTitre: { fontFamily: police.titre, fontSize: 17, color: c.encre, letterSpacing: -0.3 },
  sectionAction: { fontFamily: police.accent, fontSize: 13, color: c.action[1] },
});
