/**
 * Groupes : les collègues d'abord, les leçons ensuite.
 *
 * 🔑 **L'ordre des onglets est l'ordre du besoin.** Partager une leçon sans
 * collègue à qui l'envoyer n'a aucun sens, donc le lien vient avant le partage.
 * Chez Strava, Clubs et Challenges sont côte à côte parce qu'on peut faire l'un
 * sans l'autre. Ici non.
 *
 * 🚨 **Pas de challenges, et c'est une décision, pas un oubli.** Un classement
 * sur « qui a clôturé le plus de séances » pousserait à clôturer des séances
 * qu'on n'a pas faites, et abîmerait le seul chiffre sur lequel une enseignante
 * s'appuie pour dire où en sont ses élèves.
 *
 * ⚠️ **L'onglet Leçons dit ce qu'il fera.** Un onglet vide sans explication se
 * lit comme une panne. Un onglet qui annonce son contenu se lit comme une
 * promesse, et engage à la tenir.
 */

type Onglet = 'collegues' | 'lecons' | 'defis' | 'parrainage';

export default function Groupes() {
  // On peut ouvrir Groupes directement sur un onglet (ex. `/groupes?tab=parrainage`,
  // depuis l'entrée Parrainage des Réglages). Sinon, Collègues en premier : c'est
  // le seul des quatre qui marche sans les autres.
  const { tab } = useLocalSearchParams<{ tab?: string }>();
  const [onglet, setOnglet] = useState<Onglet>(tab === 'parrainage' ? 'parrainage' : 'collegues');

  // 🔑 L'onglet Groupes est persistant : si on arrive depuis Réglages avec
  // `?tab=parrainage` alors qu'il est DÉJÀ monté, l'initialiseur d'état ne
  // rejoue pas. On suit donc le paramètre, au rendu où il change (schéma React
  // « ajuster l'état quand une prop change »), pour que la redirection tombe
  // toujours sur le bon onglet ; on ne touche à rien quand aucun `tab` n'est passé.
  const [tabPrecedent, setTabPrecedent] = useState(tab);
  if (tab !== tabPrecedent) {
    setTabPrecedent(tab);
    if (tab === 'parrainage') setOnglet('parrainage');
  }

  return (
    // 🌥️ Cloudy salue en tête de Groupes : c'est l'écran social de l'app, la
    // pose « salut » y est à sa place. Une seule Cloudy par écran, portée par
    // le prop `avatar` de l'en-tête (charte v9).
    <Ecran
      titre={t.groupes.titre}
      avatarMenu={NAV_AVATAR ? <AvatarNav /> : undefined}
      actions={<BoutonParrainage variant="pastille" onPress={() => setOnglet('parrainage')} />}>
      <Onglets
        options={[
          { id: 'collegues' as Onglet, libelle: t.groupes.ongletCollegues },
          { id: 'lecons' as Onglet, libelle: t.groupes.ongletLecons },
          { id: 'defis' as Onglet, libelle: t.groupes.ongletDefis },
          { id: 'parrainage' as Onglet, libelle: t.groupes.ongletParrainage },
        ]}
        choisi={onglet}
        onChoisir={setOnglet}
      />
      {onglet === 'collegues' ? (
        <Collegues onOuvrirParrainage={() => setOnglet('parrainage')} />
      ) : onglet === 'lecons' ? (
        <Lecons />
      ) : onglet === 'defis' ? (
        <Defis />
      ) : (
        // L'onglet Parrainage affiche le contenu COMPLET (partage, suivi, manne,
        // filleul·es), le même que la route `/parrainage`, via le panneau
        // partagé : le parrainage est un acte social, sa maison est ici.
        <ParrainagePanneau />
      )}
    </Ecran>
  );
}

/**
 * Les collègues : montrer son code, ou entrer celui d'en face.
 *
 * 🚨 CE BLOC NE DEMANDE PLUS D'ADRESSE, ET C'EST UNE CORRECTION DE FOND.
 *
 * La première version cherchait par adresse email. Ça marchait, et c'était
 * désuet pour une raison simple : il fallait connaître l'adresse EXACTE avec
 * laquelle la collègue s'était inscrite. Personne ne sait ça de personne. Un
 * formulaire qui demande une chose qu'on n'a pas est un formulaire qu'on
 * abandonne.
 *
 * Le code inverse la charge : on le MONTRE. Côte à côte en salle des profs, on
 * scanne. À distance, on l'envoie par le moyen qu'on utilise déjà.
 *
 * 🔑 LE QR PORTE `educooo://c/<code>`, ET C'EST CE QUI ÉVITE UN SCANNER.
 *
 * L'appareil photo d'un iPhone ou d'un Android lit déjà les QR et propose
 * d'ouvrir le lien. Embarquer notre propre scanner voudrait dire une dépendance
 * native de plus, une autorisation caméra de plus à justifier, et un écran de
 * plus à maintenir — pour refaire moins bien ce que le téléphone fait déjà.
 *
 * ⚠️ Un lien `https://` aurait exigé des liens universels, donc un fichier
 * d'association servi par educooo.com et un build pour l'éprouver. Le schéma
 * de l'app marche sans rien de tout ça, dès l'installation.
 */
function Collegues({ onOuvrirParrainage }: { onOuvrirParrainage: () => void }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const liens = useRequete(mesCollegues, []);
  const blocages = useRequete(mesBlocages, []);

  const [saisie, setSaisie] = useState('');
  const [trouvee, setTrouvee] = useState<{ id: string; nom: string | null } | null>(null);
  const [rienTrouve, setRienTrouve] = useState(false);
  const [ouvertCode, setOuvertCode] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [souci, setSouci] = useState<string | null>(null);
  const [occupe, setOccupe] = useState(false);

  const tous = liens.donnees ?? [];
  const recues = tous.filter((c) => c.statut === 'pending' && c.sens === 'recue');
  const envoyees = tous.filter((c) => c.statut === 'pending' && c.sens === 'envoyee');
  const liees = tous.filter((c) => c.statut === 'accepted');

  async function chercher() {
    setSouci(null);
    setMessage(null);
    setTrouvee(null);
    setRienTrouve(false);
    setOccupe(true);
    try {
      const r = await collegueParCode(saisie);
      if (r) setTrouvee(r);
      else setRienTrouve(true);
    } catch {
      setSouci(t.groupes.erreurAction);
    } finally {
      setOccupe(false);
    }
  }

  async function demander(id: string) {
    setSouci(null);
    setOccupe(true);
    try {
      await demanderCollegue(id);
      setMessage(t.groupes.demandee);
      setTrouvee(null);
      setSaisie('');
      setOuvertCode(false);
      liens.recharger();
    } catch (e) {
      setSouci(
        e instanceof Error && e.message === 'deja_demande'
          ? t.groupes.dejaDemande
          : t.groupes.erreurAction,
      );
    } finally {
      setOccupe(false);
    }
  }

  async function repondre(lienId: string, accepter: boolean) {
    setSouci(null);
    setOccupe(true);
    try {
      await repondreCollegue({ lienId, accepter });
      liens.recharger();
    } catch {
      setSouci(t.groupes.erreurAction);
    } finally {
      setOccupe(false);
    }
  }

  async function retirer(lienId: string) {
    setSouci(null);
    setOccupe(true);
    try {
      await retirerCollegue(lienId);
      liens.recharger();
    } catch {
      setSouci(t.groupes.erreurAction);
    } finally {
      setOccupe(false);
    }
  }

  // Bloquer demande confirmation : le geste défait le lien et coupe les deux
  // sens, donc il ne part pas d'un tap distrait.
  function bloquer(collegue: Collegue) {
    Alert.alert(t.groupes.bloquerTitre(collegue.nom), t.groupes.bloquerMessage, [
      { text: t.groupes.bloquerAnnuler, style: 'cancel' },
      {
        text: t.groupes.bloquerConfirmer,
        style: 'destructive',
        onPress: async () => {
          setSouci(null);
          setOccupe(true);
          try {
            await bloquerCollegue(collegue.personneId, collegue.lienId);
            setMessage(t.groupes.bloquerFaite);
            liens.recharger();
            blocages.recharger();
          } catch {
            setSouci(t.groupes.erreurAction);
          } finally {
            setOccupe(false);
          }
        },
      },
    ]);
  }

  async function debloquer(personneId: string) {
    setSouci(null);
    setOccupe(true);
    try {
      await debloquerCollegue(personneId);
      setMessage(t.groupes.debloquerFaite);
      blocages.recharger();
      liens.recharger();
    } catch {
      setSouci(t.groupes.erreurAction);
    } finally {
      setOccupe(false);
    }
  }

  return (
    <>
      {/* L'appât de parrainage remplace le gros bloc QR/invitation pour gagner de
          la place (retour Valentin 24/08) : inviter une collègue passe désormais
          par le parrainage, où le code et le QR vivent déjà. */}
      <BoutonParrainage variant="carte" onPress={onOuvrirParrainage} />

      <Carte>
        {!ouvertCode ? (
          <BoutonDiscret libelle={t.groupes.saisirCode} onPress={() => setOuvertCode(true)} />
        ) : (
          <>
            <Champ
              etiquette={t.groupes.codeChamp}
              value={saisie}
              onChangeText={(v) => {
                setSaisie(v);
                setTrouvee(null);
                setRienTrouve(false);
              }}
              placeholder={t.groupes.codeIndice}
              autoCapitalize="characters"
              autoCorrect={false}
              editable={!occupe}
            />
            <BoutonDiscret libelle={t.groupes.codeChercher} onPress={chercher} />
          </>
        )}

        {trouvee ? (
          <View style={styles.resultat}>
            <Text style={texte.corps}>{t.groupes.trouvee(trouvee.nom)}</Text>
            <BoutonDiscret libelle={t.groupes.demander} onPress={() => void demander(trouvee.id)} />
          </View>
        ) : null}

        {rienTrouve ? <Text style={styles.aide}>{t.groupes.codeIntrouvable}</Text> : null}
        {message ? <Text style={styles.confirme}>{message}</Text> : null}
        {souci ? <Alerte message={souci} /> : null}
      </Carte>

      {liens.erreur ? <Alerte message={t.groupes.erreur} /> : null}

      {recues.length > 0 ? (
        <>
          <EnteteSection titre={t.groupes.recues} />
          {recues.map((c) => (
            <Carte key={c.lienId} compacte>
              <View style={styles.ligne}>
                <Pastille nom={c.nom} />
                <Text style={[texte.corps, styles.nom]}>{c.nom ?? '—'}</Text>
              </View>
              <View style={styles.deux}>
                <Pressable
                  accessibilityRole="button"
                  accessibilityLabel={`${t.groupes.accepter} ${c.nom ?? ''}`}
                  disabled={occupe}
                  onPress={() => void repondre(c.lienId, true)}
                  style={styles.accepter}>
                  <Text style={styles.accepterTexte}>{t.groupes.accepter}</Text>
                </Pressable>
                <Pressable
                  accessibilityRole="button"
                  accessibilityLabel={`${t.groupes.refuser} ${c.nom ?? ''}`}
                  disabled={occupe}
                  onPress={() => void repondre(c.lienId, false)}
                  style={styles.refuser}>
                  <Text style={styles.refuserTexte}>{t.groupes.refuser}</Text>
                </Pressable>
              </View>
            </Carte>
          ))}
        </>
      ) : null}

      <EnteteSection titre={t.groupes.liees} />
      {liees.length === 0 && envoyees.length === 0 ? (
        <Carte>
          <Text style={texte.discret}>{t.groupes.aucune}</Text>
        </Carte>
      ) : null}

      {liees.map((c) => (
        <LigneCollegue
          key={c.lienId}
          collegue={c}
          onRetirer={() => void retirer(c.lienId)}
          onBloquer={() => bloquer(c)}
        />
      ))}

      {envoyees.map((c) => (
        <LigneCollegue
          key={c.lienId}
          collegue={c}
          enAttente
          onRetirer={() => void retirer(c.lienId)}
          onBloquer={() => bloquer(c)}
        />
      ))}

      {/* 🚨 Les comptes bloqués, et le seul geste qui compte ici : débloquer.
          On les montre pour que le blocage ne soit pas un cul-de-sac invisible.
          Rien d'autre n'est proposé : on ne renoue pas un lien depuis ici, on
          lève d'abord le blocage. */}
      {(blocages.donnees ?? []).length > 0 ? (
        <>
          <EnteteSection titre={t.groupes.bloques} />
          {(blocages.donnees ?? []).map((b) => (
            <Carte key={b.personneId} compacte>
              <View style={styles.ligne}>
                <Pastille nom={b.nom} />
                <Text style={[texte.corps, styles.nom]}>{b.nom ?? '—'}</Text>
                <Pressable
                  accessibilityRole="button"
                  accessibilityLabel={`${t.groupes.debloquer} ${b.nom ?? ''}`}
                  disabled={occupe}
                  onPress={() => void debloquer(b.personneId)}
                  style={styles.boutonLigne}>
                  <Text style={styles.refuserTexte}>{t.groupes.debloquer}</Text>
                </Pressable>
              </View>
            </Carte>
          ))}
        </>
      ) : null}
    </>
  );
}

function LigneCollegue({
  collegue,
  enAttente = false,
  onRetirer,
  onBloquer,
}: {
  collegue: Collegue;
  enAttente?: boolean;
  onRetirer: () => void;
  onBloquer?: () => void;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <Carte compacte>
      <View style={styles.ligne}>
        <Pastille nom={collegue.nom} enAttente={enAttente} />
        <View style={styles.corps}>
          <Text style={texte.corps}>{collegue.nom ?? '—'}</Text>
          {enAttente ? <Text style={texte.discret}>{t.groupes.attente}</Text> : null}
        </View>
        {/* Bloquer et retirer se ressemblent, mais ne disent pas la même chose :
            retirer défait un lien, bloquer refuse la personne dans les deux
            sens. Deux gestes distincts, deux icônes. */}
        {onBloquer ? (
          <Pressable
            accessibilityRole="button"
            accessibilityLabel={`${t.groupes.bloquer} ${collegue.nom ?? ''}`}
            onPress={onBloquer}
            hitSlop={8}>
            <Feather name="slash" size={18} color={c.nonRattache} />
          </Pressable>
        ) : null}
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={`${t.groupes.retirer} ${collegue.nom ?? ''}`}
          onPress={onRetirer}
          hitSlop={8}>
          <Feather name="x" size={18} color={c.nonRattache} />
        </Pressable>
      </View>
    </Carte>
  );
}

/** L'initiale, parce qu'un avatar demanderait une photo que personne n'a mise. */
function Pastille({ nom, enAttente = false }: { nom: string | null; enAttente?: boolean }) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <View style={[styles.pastille, enAttente && styles.pastilleAttente]}>
      <Text style={styles.initiale}>{(nom ?? '?').trim().charAt(0).toLocaleUpperCase('fr')}</Text>
    </View>
  );
}

/**
 * Les leçons, reçues et envoyées.
 *
 * 🔑 Les deux moitiés comptent, et pas pour la même raison. Recevoir donne du
 * matériel tout prêt. Envoyer donne quelque chose de plus rare : savoir que son
 * travail a servi ailleurs. C'est la seule mesure sociale de l'app qui ne
 * compare personne — « trois collègues l'ont reprise » ne classe pas, ça dit
 * que ça a porté.
 */
function Lecons() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { classe } = useClasse();
  const recues = useRequete(leconsRecues, []);
  const envoyees = useRequete(leconsEnvoyees, []);
  const [occupe, setOccupe] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [souci, setSouci] = useState<string | null>(null);

  async function reprendre(lecon: LeconPartagee) {
    if (!classe || !lecon.lienId) return;
    setSouci(null);
    setOccupe(true);
    try {
      await reprendreLecon({
        leconId: lecon.id,
        lienId: lecon.lienId,
        classeId: classe.id,
      });
      setMessage(t.groupes.leconRepriseFaite);
      recues.recharger();
    } catch (e) {
      setSouci(e instanceof Error ? e.message : t.groupes.leconRepriseErreur);
    } finally {
      setOccupe(false);
    }
  }

  async function retirer(leconId: string) {
    setSouci(null);
    setOccupe(true);
    try {
      await retirerLecon(leconId);
      setMessage(t.groupes.leconRetiree);
      envoyees.recharger();
    } catch {
      setSouci(t.groupes.erreurAction);
    } finally {
      setOccupe(false);
    }
  }

  async function signaler(lecon: LeconPartagee, motif: string, commentaire: string) {
    setSouci(null);
    setOccupe(true);
    try {
      await signalerLecon({ leconId: lecon.id, lienId: lecon.lienId, motif, commentaire });
      setMessage(t.groupes.signalerFaite);
      // La leçon disparaît de l'écran : `leconsRecues` masque ce qu'on a signalé.
      recues.recharger();
    } catch {
      setSouci(t.groupes.erreurAction);
    } finally {
      setOccupe(false);
    }
  }

  function bloquerAuteur(lecon: LeconPartagee) {
    const personneId = lecon.de?.personneId;
    if (!personneId) return;
    Alert.alert(t.groupes.bloquerTitre(lecon.de?.nom ?? null), t.groupes.bloquerMessage, [
      { text: t.groupes.bloquerAnnuler, style: 'cancel' },
      {
        text: t.groupes.bloquerConfirmer,
        style: 'destructive',
        onPress: async () => {
          setSouci(null);
          setOccupe(true);
          try {
            await bloquerCollegue(personneId);
            setMessage(t.groupes.bloquerFaite);
            // Les leçons de ce compte quittent l'écran (filtre anti-blocage).
            recues.recharger();
          } catch {
            setSouci(t.groupes.erreurAction);
          } finally {
            setOccupe(false);
          }
        },
      },
    ]);
  }

  const listeRecues = recues.donnees ?? [];
  const listeEnvoyees = envoyees.donnees ?? [];

  return (
    <>
      {message ? <Text style={styles.confirme}>{message}</Text> : null}
      {souci ? <Alerte message={souci} /> : null}

      {/* 🚨 Deux sections dans un seul défilement, et pas une deuxième rangée
          d'onglets. Un écran qui empile onglets et sous-onglets ne dit plus
          lequel commande l'autre. « Une progression, pas une juxtaposition. » */}
      <EnteteSection titre={t.groupes.leconsRecues} />
      {listeRecues.length === 0 ? (
        <Carte>
          <Text style={texte.discret}>{t.groupes.leconsAucuneRecue}</Text>
        </Carte>
      ) : (
        listeRecues.map((l) => (
          <LeconRecue
            key={l.id}
            lecon={l}
            occupe={occupe || !classe}
            onReprendre={() => void reprendre(l)}
            onSignaler={(motif, commentaire) => void signaler(l, motif, commentaire)}
            onBloquerAuteur={() => bloquerAuteur(l)}
          />
        ))
      )}

      <EnteteSection titre={t.groupes.leconsEnvoyees} />
      {listeEnvoyees.length === 0 ? (
        <Carte>
          <Text style={texte.discret}>{t.groupes.leconsAucuneEnvoyee}</Text>
        </Carte>
      ) : (
        listeEnvoyees.map((l) => (
          <LeconEnvoyee key={l.id} lecon={l} onRetirer={() => void retirer(l.id)} />
        ))
      )}
    </>
  );
}

/** Les motifs de signalement. L'identifiant part en base, le libellé reste à l'écran. */
const MOTIFS_SIGNAL = [
  { id: 'offensant', libelle: t.groupes.signalerMotifs.offensant },
  { id: 'inapproprie', libelle: t.groupes.signalerMotifs.inapproprie },
  { id: 'spam', libelle: t.groupes.signalerMotifs.spam },
  { id: 'autre', libelle: t.groupes.signalerMotifs.autre },
];

function LeconRecue({
  lecon,
  occupe,
  onReprendre,
  onSignaler,
  onBloquerAuteur,
}: {
  lecon: LeconPartagee;
  occupe: boolean;
  onReprendre: () => void;
  onSignaler: (motif: string, commentaire: string) => void;
  onBloquerAuteur: () => void;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const [ouverte, setOuverte] = useState(false);
  // Le signalement s'écrit là où on lit la leçon, pas dans une feuille qui
  // recouvre l'écran : la personne garde la leçon sous les yeux pendant qu'elle
  // dit ce qui ne va pas.
  const [signalement, setSignalement] = useState(false);
  const [motif, setMotif] = useState<string | null>(null);
  const [commentaire, setCommentaire] = useState('');

  function envoyerSignalement() {
    if (!motif) return;
    onSignaler(motif, commentaire);
    setSignalement(false);
    setMotif(null);
    setCommentaire('');
  }

  return (
    <Carte>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel={lecon.titre}
        onPress={() => {
          // On marque « vue » à l'ouverture, pas à la réception : recevoir
          // n'est pas lire, et la personne qui l'a écrite mérite la vraie information.
          if (!ouverte && lecon.lienId) void marquerLeconVue(lecon.lienId);
          setOuverte(!ouverte);
        }}>
        <Text style={texte.corps}>{lecon.titre}</Text>
        <Text style={texte.discret}>
          {[
            t.groupes.leconDe(lecon.de?.nom ?? null),
            lecon.niveaux,
            lecon.attendus.length ? t.groupes.leconAttendus(lecon.attendus.length) : null,
          ]
            .filter(Boolean)
            .join(' · ')}
        </Text>
        {lecon.repriseLe ? <Text style={styles.confirme}>{t.groupes.leconReprise}</Text> : null}
      </Pressable>

      {ouverte ? (
        <View style={styles.detail}>
          {lecon.objectif ? <Text style={styles.aide}>{lecon.objectif}</Text> : null}
          {lecon.description ? <Text style={styles.aide}>{lecon.description}</Text> : null}
          {lecon.materiel ? <Text style={styles.aide}>{lecon.materiel}</Text> : null}
          {lecon.attendus.map((a, i) => (
            <Text key={i} style={styles.attendu}>
              {a.libelle}
            </Text>
          ))}
          {!lecon.repriseLe ? (
            <BoutonDiscret libelle={t.groupes.leconReprendre} onPress={onReprendre} />
          ) : null}

          {/* La modération, discrète mais toujours atteignable une fois la
              leçon ouverte : signaler le contenu, ou bloquer la personne. */}
          {signalement ? (
            <View style={styles.signal}>
              <Text style={texte.section}>{t.groupes.signalerTitre}</Text>
              <Text style={styles.aide}>{t.groupes.signalerAide}</Text>
              <Pastilles options={MOTIFS_SIGNAL} choisi={motif} onChoisir={setMotif} />
              <Champ
                etiquette={t.groupes.signalerCommentaire}
                value={commentaire}
                onChangeText={setCommentaire}
                placeholder={t.groupes.signalerCommentaireIndice}
                multiline
                editable={!occupe}
              />
              <BoutonPrincipal
                libelle={t.groupes.signalerEnvoyer}
                onPress={envoyerSignalement}
                inactif={!motif}
                occupe={occupe}
              />
              <BoutonDiscret
                libelle={t.groupes.signalerAnnuler}
                onPress={() => {
                  setSignalement(false);
                  setMotif(null);
                  setCommentaire('');
                }}
              />
            </View>
          ) : (
            <View style={styles.moderation}>
              <BoutonDiscret libelle={t.groupes.signaler} onPress={() => setSignalement(true)} />
              {lecon.de?.personneId ? (
                <BoutonDiscret libelle={t.groupes.bloquerAuteur} onPress={onBloquerAuteur} />
              ) : null}
            </View>
          )}
        </View>
      ) : null}
    </Carte>
  );
}

function LeconEnvoyee({ lecon, onRetirer }: { lecon: LeconPartagee; onRetirer: () => void }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const dests = lecon.destinataires ?? [];
  const vues = dests.filter((d) => d.vueLe).length;
  const reprises = dests.filter((d) => d.repriseLe).length;

  // Le chiffre le plus fort en premier : une reprise vaut mieux qu'une lecture.
  const etat =
    reprises > 0
      ? t.groupes.leconRepriseParMulti(reprises)
      : vues > 0
        ? t.groupes.leconVue(vues)
        : t.groupes.leconPersonne;

  return (
    <Carte>
      <Text style={texte.corps}>{lecon.titre}</Text>
      <Text style={texte.discret}>
        {[etat, lecon.attendus.length ? t.groupes.leconAttendus(lecon.attendus.length) : null]
          .filter(Boolean)
          .join(' · ')}
      </Text>
      {reprises > 0 ? (
        <View style={styles.reprises}>
          {dests
            .filter((d) => d.repriseLe)
            .map((d, i) => (
              <View key={i} style={styles.badge}>
                <Text style={styles.badgeTexte}>{d.nom ?? '—'}</Text>
              </View>
            ))}
        </View>
      ) : null}
      <BoutonDiscret libelle={t.groupes.leconRetirer} onPress={onRetirer} />
    </Carte>
  );
}

/**
 * Les défis, pas encore construits — et une question à la place.
 *
 * 🔑 UNE LIGNE, ET DEUX POUCES.
 *
 * Pas une feuille de route : on ne promet rien à quelqu'un qui ne nous connaît
 * pas, et un écran qui raconte ce qui va venir engage à le livrer. Mais un
 * écran vide n'apprend rien non plus.
 *
 * Une phrase tournée vers ce que ça lui apporte, et une question fermée. Trois
 * secondes à répondre, et ça tranche la seule chose qui décide de la suite :
 * est-ce que ça intéresse quelqu'un. Aujourd'hui on n'en sait rien.
 *
 * ⚠️ La réponse se change. Un pouce qu'on ne peut pas défaire est un piège,
 * pas une question — et quelqu'un qui a tapé par erreur fausserait le compte
 * sans pouvoir se corriger.
 */
const SUJET_DEFIS = 'defis';

function Defis() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const reponse = useRequete(() => monInteret(SUJET_DEFIS), []);
  const [occupe, setOccupe] = useState(false);

  async function repondre(interesse: boolean) {
    setOccupe(true);
    try {
      await direMonInteret({ sujet: SUJET_DEFIS, interesse });
      reponse.recharger();
    } catch {
      // Un avis perdu n'est pas une panne : on ne dérange pas pour ça.
    } finally {
      setOccupe(false);
    }
  }

  const donnee = reponse.donnees;

  return (
    <Carte>
      <Text style={styles.aide}>{t.groupes.defisPitch}</Text>

      {donnee === null || donnee === undefined ? (
        <>
          <Text style={texte.corps}>{t.groupes.defisQuestion}</Text>
          <View style={styles.deux}>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={`${t.groupes.defisQuestion} ${t.groupes.defisOui}`}
              disabled={occupe}
              onPress={() => void repondre(true)}
              style={styles.pouce}>
              <Feather name="thumbs-up" size={18} color={c.encre} />
              <Text style={styles.pouceTexte}>{t.groupes.defisOui}</Text>
            </Pressable>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={`${t.groupes.defisQuestion} ${t.groupes.defisNon}`}
              disabled={occupe}
              onPress={() => void repondre(false)}
              style={styles.pouce}>
              <Feather name="thumbs-down" size={18} color={c.encre} />
              <Text style={styles.pouceTexte}>{t.groupes.defisNon}</Text>
            </Pressable>
          </View>
        </>
      ) : (
        <>
          <Text style={styles.confirme}>{t.groupes.defisMerci}</Text>
          <BoutonDiscret
            libelle={t.groupes.defisChanger}
            onPress={() => void repondre(!donnee)}
          />
        </>
      )}
    </Carte>
  );
}

