import { Feather } from '@expo/vector-icons';
import { Image } from 'expo-image';
import { useMemo, useState } from 'react';
import { Modal, Pressable, StyleSheet, Text, View } from 'react-native';

import { Presse } from '@/components/presse';
import { t } from '@/i18n';
import { listerMedias } from '@/lib/media';
import { useRequete } from '@/lib/requete';
import { espace, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * Les vignettes des photos jointes à une observation, en relecture.
 *
 * 🚨 Sans elles, une observation faite d'une seule photo (un cahier, une trace)
 * se range « à l'aveugle » : on ne voit pas ce qu'on rattache. C'est le pendant
 * lecture du bouton photo de la capture.
 *
 * Le composant se charge lui-même : il signe les URLs (seau privé) via
 * `listerMedias`. Il vit dans une liste (`.map`) sur l'écran Capter et sur la
 * fiche élève, donc chaque instance porte sa propre requête — c'est voulu, un
 * composant par ligne garde les hooks propres.
 *
 * Rien ne s'affiche tant qu'il n'y a pas d'image : une observation sans photo,
 * ou en cours de chargement, ne montre aucun trou. On ne garde que les images
 * (`type === 'photo'`) ; l'audio se lit ailleurs.
 */
export function VignettesMedias({
  observationId,
  taille = 68,
  etiquette = false,
}: {
  observationId: string;
  /** Côté de la tuile en points. ~64-72 en relecture, plus petit dans une liste. */
  taille?: number;
  /** Affiche le libellé « Photos » au-dessus de la rangée. */
  etiquette?: boolean;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const [agrandie, setAgrandie] = useState<string | null>(null);

  const medias = useRequete(() => listerMedias(observationId), [observationId]);
  const photos = useMemo(
    () => (medias.donnees ?? []).filter((m) => m.type === 'photo'),
    [medias.donnees],
  );

  if (photos.length === 0) return null;

  return (
    <View style={styles.bloc}>
      {etiquette ? <Text style={styles.etiquette}>{t.medias.photos}</Text> : null}
      <View style={styles.rangee}>
        {photos.map((photo) => (
          <Presse
            key={photo.id}
            accessibilityRole="button"
            accessibilityLabel={t.medias.ouvrir}
            onPress={() => setAgrandie(photo.url)}
            style={[styles.tuile, { width: taille, height: taille }]}>
            <Image source={{ uri: photo.url }} style={styles.image} contentFit="cover" />
          </Presse>
        ))}
      </View>

      {/* Un tap ouvre la photo en grand. La croix reste fixe, hors de tout
          défilement : elle est toujours atteignable. */}
      <Modal
        visible={agrandie !== null}
        transparent
        animationType="fade"
        onRequestClose={() => setAgrandie(null)}>
        <View style={styles.voile}>
          <Pressable
            accessibilityRole="button"
            accessibilityLabel={t.medias.fermer}
            onPress={() => setAgrandie(null)}
            style={styles.croix}>
            <Feather name="x" size={22} color="#FFFFFF" />
          </Pressable>
          <Pressable style={styles.zoomFond} onPress={() => setAgrandie(null)}>
            {agrandie ? (
              <Image source={{ uri: agrandie }} style={styles.imageGrande} contentFit="contain" />
            ) : null}
          </Pressable>
        </View>
      </Modal>
    </View>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    bloc: { gap: espace.sm },
    etiquette: { fontFamily: police.corps, fontSize: 14, color: c.encreDouce },
    rangee: { flexDirection: 'row', flexWrap: 'wrap', gap: espace.sm },
    tuile: {
      borderRadius: rayon.tuile,
      overflow: 'hidden',
      borderWidth: 1,
      borderColor: c.bord,
    },
    image: { width: '100%', height: '100%' },
    // Le plein écran vit sur un voile d'encre sombre, indépendant du thème : une
    // photo se regarde sur du noir, clair ou sombre.
    voile: { flex: 1, backgroundColor: 'rgba(10, 9, 15, 0.94)' },
    zoomFond: { flex: 1, alignItems: 'center', justifyContent: 'center', padding: espace.lg },
    imageGrande: { width: '100%', height: '100%' },
    croix: {
      position: 'absolute',
      top: espace.xl + espace.md,
      right: espace.lg,
      zIndex: 2,
      width: 44,
      height: 44,
      borderRadius: 22,
      backgroundColor: 'rgba(23, 22, 34, 0.72)',
      alignItems: 'center',
      justifyContent: 'center',
    },
  });
