/**
 * La démonstration de la vue direction : une école FICTIVE, à envoyer en lien
 * ouvert à une direction qui n'a pas encore d'équipe inscrite.
 *
 * 🔑 CE QUI EST VRAI ET CE QUI EST INVENTÉ, dit sans détour
 *
 *  - VRAIS : les libellés du programme (compétences et attendus FWB, extraits
 *    en lecture de la base le 24/09/2026 dans `direction-demo-catalogue.json` :
 *    un échantillon de 10 compétences par discipline au plus, 2 attendus
 *    chacune, pour trois profils, maternelle officielle, P1-P2 et P3-P6), et le
 *    calendrier FWB 2026-2027 (congés officiels, `periodes.ts`).
 *  - INVENTÉS : l'école, les noms des enseignant·es (aucun compte réel), et
 *    tous les chiffres, tirés d'un générateur à graine fixe (même démo à chaque
 *    ouverture). Le bandeau « démonstration » le dit sur chaque écran.
 *
 * 🔑 COHÉRENT AVEC LES RÈGLES DE LA v1.1
 *
 * Le jeu est construit compétence par compétence, séance par séance, puis
 * agrégé exactement comme le serveur agrège : un pourcentage de compétences
 * travaillées en principal, des couches croisé et transversal à part, un
 * drill-down attendu par attendu qui explique chaque case. Une classe est
 * « suivie hors EducooO » (3 séances), une autre répète beaucoup la grammaire
 * (le « six fois grammaire » de Benjamin).
 */
import catalogue from './direction-demo-catalogue.json';
import {
  DISCIPLINES,
  type Canaux,
  type Compte,
  type Discipline,
  type LigneClasse,
  type LigneDetail,
  type Synthese,
} from './direction';
import {
  bornesPeriode,
  CALENDRIER_FWB_2026_2027,
  deduirePeriodes,
  type ModePeriode,
  type Periode,
} from './periodes';

type CompetenceCatalogue = { c: string; d: string; a: string[] };
type Profil = 'M' | 'P12' | 'P36';
const CATALOGUE = catalogue as Record<Profil, Partial<Record<Discipline, CompetenceCatalogue[]>>>;

export const ECOLE_DEMO = { nom: 'École du Bois-Joli', commune: 'Namur' } as const;

/**
 * Les neuf classes. `rythme` règle la vitesse de couverture (1 = au rythme de
 * l'année), `seances` le volume d'une année pleine. La 2e primaire est suivie au
 * carnet papier : 3 séances seulement, jamais un pourcentage.
 */
const CLASSES: { nom: string; cycle: string; profil: Profil; enseignant: string; rythme: number; seances: number }[] = [
  { nom: '1re maternelle', cycle: 'M1', profil: 'M', enseignant: 'Claire Dubois', rythme: 0.95, seances: 150 },
  { nom: '2e maternelle', cycle: 'M2', profil: 'M', enseignant: 'Inès Marchal', rythme: 0.9, seances: 160 },
  { nom: '3e maternelle', cycle: 'M3', profil: 'M', enseignant: 'Lucie Hendrickx', rythme: 0.8, seances: 130 },
  { nom: '1re primaire', cycle: 'P1', profil: 'P12', enseignant: 'Nadia Lambert', rythme: 0.92, seances: 170 },
  { nom: '2e primaire', cycle: 'P2', profil: 'P12', enseignant: 'Olivier Gérard', rythme: 0, seances: 3 },
  { nom: '3e primaire', cycle: 'P3', profil: 'P36', enseignant: 'Anne Simon', rythme: 1, seances: 180 },
  { nom: '4e primaire', cycle: 'P4', profil: 'P36', enseignant: 'Karim Dupont', rythme: 0.7, seances: 140 },
  { nom: '5e primaire', cycle: 'P5', profil: 'P36', enseignant: 'Julie Laurent', rythme: 0.85, seances: 150 },
  { nom: '6e primaire', cycle: 'P6', profil: 'P36', enseignant: 'Marc Leroy', rythme: 0.88, seances: 160 },
];

/** Générateur pseudo-aléatoire à graine (mulberry32) : même démo à chaque fois. */
function hasard(graine: number) {
  let a = graine >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Les périodes FWB 2026-2027, lues comme si la période `index` venait de finir. */
export function periodesDemo(index = 2): Periode[] {
  const base = deduirePeriodes(CALENDRIER_FWB_2026_2027, CALENDRIER_FWB_2026_2027.rentree);
  const fin = base[Math.min(index, base.length - 1)]?.fin ?? CALENDRIER_FWB_2026_2027.fin;
  return deduirePeriodes(CALENDRIER_FWB_2026_2027, fin);
}

/**
 * Par classe, par compétence, par attendu : combien de séances, dans quelle
 * couche, et dans quelle période. Tout le reste (tuiles, matrice, détail) se
 * CALCULE depuis ces séances, comme le fait le serveur.
 */
type SeanceAttendu = { principal: number[]; croise: number[]; transversal: number[] };
type CompDemo = { discipline: Discipline; domaine: string; libelle: string; attendus: { libelle: string; parPeriode: SeanceAttendu }[] };
type ClasseDemo = { id: string; def: (typeof CLASSES)[number]; competences: CompDemo[]; delegues: number };

let MEMO: ClasseDemo[] | null = null;
function construire(nbPeriodes: number): ClasseDemo[] {
  if (MEMO) return MEMO;
  MEMO = CLASSES.map((def, i) => {
    const r = hasard(7919 + i * 131);
    const competences: CompDemo[] = [];
    for (const d of DISCIPLINES) {
      for (const cc of CATALOGUE[def.profil][d] ?? []) {
        // La période où la compétence est travaillée pour la première fois : plus
        // la classe va vite (`rythme`), plus elle tombe tôt. Au-delà de la
        // dernière période, elle reste ouverte toute l'année.
        const depart = def.rythme === 0 ? 99 : Math.floor((r() / def.rythme) * nbPeriodes * 1.05);
        const attendus = (cc.a.length ? cc.a : [cc.c]).map((libelle, k) => {
          const p: SeanceAttendu = { principal: [], croise: [], transversal: [] };
          for (let per = 0; per < nbPeriodes; per++) {
            const principal = per >= depart && (k === 0 || r() < 0.55) && (per === depart || r() < 0.45) ? 1 + Math.floor(r() * 2) : 0;
            p.principal.push(principal);
            // Une classe suivie au carnet papier n'a pas non plus de liens croisés.
            const actif = def.rythme > 0;
            p.croise.push(actif && r() < 0.035 ? 1 : 0);
            p.transversal.push(actif && r() < 0.02 ? 1 : 0);
          }
          return { libelle, parPeriode: p };
        });
        competences.push({ discipline: d, domaine: cc.d, libelle: cc.c, attendus });
      }
    }
    // La 4e primaire répète la grammaire : la première compétence de français
    // revient à chaque période, plusieurs fois (« six fois grammaire »).
    if (def.cycle === 'P4') {
      const f = competences.find((c) => c.discipline === 'francais');
      if (f) {
        f.libelle = `${f.libelle} (grammaire)`;
        f.attendus[0].parPeriode.principal = f.attendus[0].parPeriode.principal.map(() => 3);
      }
    }
    return { id: `demo-${i}`, def, competences, delegues: def.cycle === 'P1' ? 2 : 0 };
  });
  return MEMO;
}

/** Les séances d'un attendu dans la fenêtre de périodes [de, a]. */
const somme = (xs: number[], de: number, a: number) => xs.slice(de, a + 1).reduce((s, x) => s + x, 0);

/**
 * La synthèse démo pour une période. En cumul, de la première période à
 * celle-ci ; sinon, la période seule. Mêmes formes que la réponse serveur.
 */
export function syntheseDemo(index: number, mode: ModePeriode): Synthese {
  const periodes = periodesDemo(index);
  const classes = construire(periodes.length);
  const de = mode === 'cumul' ? 0 : index;
  const a = index;
  const lignes: LigneClasse[] = classes.map((cl, i) => {
    const r = hasard(104729 + i * 17 + index * 7 + (mode === 'seule' ? 3 : 0));
    const disciplines: Partial<Record<Discipline, Compte>> = {};
    const seancesComp: { libelle: string; n: number }[] = [];
    for (const c of cl.competences) {
      const p = c.attendus.reduce((s, x) => s + somme(x.parPeriode.principal, de, a), 0);
      const cr = c.attendus.reduce((s, x) => s + somme(x.parPeriode.croise, de, a), 0);
      const tr = c.attendus.reduce((s, x) => s + somme(x.parPeriode.transversal, de, a), 0);
      const v = disciplines[c.discipline] ?? { total: 0, travailles: 0, croisees: 0, transversales: 0 };
      disciplines[c.discipline] = {
        total: v.total + 1,
        travailles: v.travailles + (p > 0 ? 1 : 0),
        croisees: v.croisees + (cr > 0 ? 1 : 0),
        transversales: v.transversales + (tr > 0 ? 1 : 0),
      };
      seancesComp.push({ libelle: c.libelle, n: p });
    }
    const total = Object.values(disciplines).reduce((s, x) => s + (x?.total ?? 0), 0);
    const travailles = Object.values(disciplines).reduce((s, x) => s + (x?.travailles ?? 0), 0);
    const croisees = Object.values(disciplines).reduce((s, x) => s + (x?.croisees ?? 0), 0);
    const transversales = Object.values(disciplines).reduce((s, x) => s + (x?.transversales ?? 0), 0);
    // Le volume de séances suit la part de l'année couverte par la fenêtre.
    const partAnnee =
      (periodes[a].joursClasseCumules - (de > 0 ? periodes[de - 1].joursClasseCumules : 0)) / periodes[a].joursClasseAnnee;
    const seances = cl.def.seances < 5 ? cl.def.seances : Math.round(cl.def.seances * partAnnee);
    const tri = [...seancesComp].sort((x, y) => y.n - x.n);
    const sommeSeances = tri.reduce((s, x) => s + x.n, 0);
    const canaux: Canaux =
      seances < 5
        ? { visuel: 1, auditif: 0, kinesthesique: 1, mixte: 1, non_precise: 0 }
        : (() => {
            const v = 0.18 + r() * 0.15;
            const au = 0.12 + r() * 0.12;
            const k = cl.def.profil === 'M' ? 0.3 + r() * 0.1 : 0.12 + r() * 0.12;
            const mx = 0.2 + r() * 0.1;
            const np = Math.max(0, 1 - v - au - k - mx);
            const x = (f: number) => Math.round(seances * f);
            return { visuel: x(v), auditif: x(au), kinesthesique: x(k), mixte: x(mx), non_precise: x(np) };
          })();
    return {
      id: cl.id,
      nom: cl.def.nom,
      cycle: cl.def.cycle,
      enseignant: cl.def.enseignant,
      seances,
      peuDeDonnees: seances < 5,
      total,
      travailles,
      croisees,
      transversales,
      delegues: cl.delegues,
      disciplines,
      canaux,
      equilibre: {
        competences: total,
        competencesTravaillees: travailles,
        competencesRepetees: tri.filter((x) => x.n >= 6).length,
        partTop3: sommeSeances > 0 ? tri.slice(0, 3).reduce((s, x) => s + x.n, 0) / sommeSeances : null,
        plusTravaillee: tri[0]?.n ? { libelle: tri[0].libelle, seances: tri[0].n } : null,
      },
    };
  });
  return { periode: bornesPeriode(periodes, index, mode), seuilPeuDeDonnees: 5, classes: lignes };
}

/** Le drill-down démo, calculé depuis les mêmes séances que la synthèse. */
export function detailDemo(
  index: number,
  mode: ModePeriode,
  filtre: { classe?: string | null; discipline?: Discipline | null },
): LigneDetail[] {
  const periodes = periodesDemo(index);
  const classes = construire(periodes.length).filter((c) => !filtre.classe || c.id === filtre.classe);
  const de = mode === 'cumul' ? 0 : index;
  // Clé = compétence + attendu : on somme sur les classes (vue école entière).
  const parCle = new Map<string, LigneDetail>();
  const ordre: string[] = [];
  for (const cl of classes) {
    for (const c of cl.competences) {
      if (filtre.discipline && c.discipline !== filtre.discipline) continue;
      for (const at of c.attendus) {
        const cle = `${c.discipline}|${c.libelle}|${at.libelle}`;
        let l = parCle.get(cle);
        if (!l) {
          l = {
            discipline: c.discipline,
            domaine: c.domaine,
            competenceId: `${c.discipline}|${c.libelle}`,
            competence: c.libelle,
            attendu: at.libelle,
            principal: 0,
            croise: 0,
            transversal: 0,
            classesTravaillees: 0,
            classesTotal: 0,
          };
          parCle.set(cle, l);
          ordre.push(cle);
        }
        const p = somme(at.parPeriode.principal, de, index);
        l.principal += p;
        l.croise += somme(at.parPeriode.croise, de, index);
        l.transversal += somme(at.parPeriode.transversal, de, index);
        l.classesTotal += 1;
        if (p > 0) l.classesTravaillees += 1;
      }
    }
  }
  return ordre.map((k) => parCle.get(k)!);
}
