/* ── Ce que l'écran en fait ────────────────────────────────────────────────── */

/** La période en cours (ou la dernière passée, ou la première à venir). */
export function indexPeriodeCourante(periodes: Periode[], aujourdhui = isoDuJour()): number {
  const i = periodes.findIndex((p) => aujourdhui <= p.requeteFin);
  return i === -1 ? Math.max(0, periodes.length - 1) : i;
}

/** Les bornes à interroger : depuis la rentrée (cumul) ou la période seule. */
export function bornesPeriode(periodes: Periode[], index: number, mode: ModePeriode): { debut: string; fin: string } {
  const p = periodes[index];
  if (!p) return { debut: '1970-01-01', fin: '1970-01-01' };
  return { debut: mode === 'cumul' ? periodes[0].requeteDebut : p.requeteDebut, fin: p.requeteFin };
}

export type Rythme = { jours: number; total: number; part: number };

/**
 * Le repère « X semaines de classe sur Y » : jours de classe écoulés à la fin de
 * la période choisie (ou aujourd'hui si elle n'est pas finie). En « période
 * seule », pas de repère : une période ne couvre pas une part fixe du programme.
 */
export function rythme(periodes: Periode[], index: number, mode: ModePeriode): Rythme | null {
  const p = periodes[index];
  if (!p || mode === 'seule' || p.joursClasseAnnee === 0) return null;
  const jours = Math.min(p.joursClasseCumules, p.joursClasseACeJour);
  return { jours, total: p.joursClasseAnnee, part: jours / p.joursClasseAnnee };
}
