import AsyncStorage from '@react-native-async-storage/async-storage';
import { Platform } from 'react-native';

import { rattacherCode, ressembleAUnCode } from './parrainage';

/**
 * Le CODE DE PARRAINAGE EN ATTENTE : la fin de la friction « note ton code ».
 *
 * 🔑 Le problème que ça résout. Une collègue partage `educooo.com/r/SONCODE`.
 * Aujourd'hui la personne qui ouvre le lien voit son code, doit le RETENIR, puis
 * le retaper à la main à l'inscription. Chaque étape perd du monde. Sur le web,
 * on peut supprimer tout ça : le lien de partage porte le code en paramètre
 * (`app.educooo.com/?parrain=SONCODE`), on le capte au chargement, on le range,
 * et on le rattache TOUT SEUL dès qu'un compte existe. Zéro copie, zéro mémoire,
 * zéro saisie.
 *
 * ⚠️ Web d'abord, et c'est une limite honnête. Sur une app installée depuis un
 * store, aucun paramètre d'URL ne survit à l'installation sans « deep link
 * différé » (une brique d'attribution + des liens universels + un build). Tant
 * qu'on ne l'a pas, la capture automatique ne vaut que pour l'app web ; sur
 * mobile, on réduit la friction autrement (collage du code depuis le presse-
 * papiers, voir l'onboarding), sans jamais promettre une magie qu'on ne tient pas.
 *
 * La valeur rangée n'est PAS une donnée de compte : c'est une intention captée
 * avant même qu'un compte existe (marque d'appareil, comme le drapeau d'intro).
 * On la garde jusqu'à ce qu'elle soit soit appliquée, soit jugée définitivement
 * inutilisable par le serveur.
 */
const CLE = 'educooo:parrainage-en-attente';

/** Les clés d'URL qu'on accepte pour le code, par ordre de préférence. */
const PARAMS = ['parrain', 'parrainage', 'r', 'code'];

/**
 * Capte un code de parrainage depuis l'URL courante (WEB uniquement) et le range
 * s'il est plausible. À appeler une fois au démarrage de l'app web.
 *
 * On lit deux formes : le paramètre `?parrain=CODE` (le chemin d'partage propre)
 * et le chemin `/r/CODE` (au cas où le lien du site atterrit tel quel sur l'app).
 * On ne touche à rien si le code est absent ou malformé : pas d'écrasement d'un
 * code déjà capté par une visite sans code.
 */
export async function capterCodeWebDepuisURL(): Promise<void> {
  if (Platform.OS !== 'web' || typeof window === 'undefined') return;
  try {
    const url = new URL(window.location.href);
    let brut: string | null = null;
    for (const p of PARAMS) {
      const v = url.searchParams.get(p);
      if (v) {
        brut = v;
        break;
      }
    }
    // Repli : le chemin `/r/CODE` (le format des liens du site).
    if (!brut) {
      const m = url.pathname.match(/\/r\/([^/?#]+)/i);
      if (m) brut = decodeURIComponent(m[1]);
    }
    if (!ressembleAUnCode(brut)) return;
    const code = (brut as string).trim().toUpperCase();
    await AsyncStorage.setItem(CLE, code);
    // On nettoie l'URL pour ne pas laisser traîner le code dans la barre
    // d'adresse (et éviter de le re-capter à chaque rechargement). L'historique
    // est remplacé, pas empilé : le bouton « précédent » ne ramène pas au lien.
    try {
      for (const p of PARAMS) url.searchParams.delete(p);
      const propre = url.pathname.replace(/\/r\/[^/?#]+/i, '/') + url.search + url.hash;
      window.history.replaceState(null, '', propre || '/');
    } catch {
      // Nettoyage cosmétique : un échec ici n'a aucune conséquence fonctionnelle.
    }
  } catch {
    // Une URL illisible ne doit jamais empêcher l'app de démarrer.
  }
}

/** Le code en attente, ou null. Sûr partout (natif comme web). */
export async function codeEnAttente(): Promise<string | null> {
  try {
    return await AsyncStorage.getItem(CLE);
  } catch {
    return null;
  }
}

/** Oublie le code en attente (appliqué, ou jugé inutilisable). */
export async function oublierCodeEnAttente(): Promise<void> {
  try {
    await AsyncStorage.removeItem(CLE);
  } catch {
    // Sans gravité : au pire on retentera, et le serveur refera son verdict.
  }
}

/**
 * Tente de rattacher le code en attente au compte connecté, une fois.
 *
 * 🔑 À n'appeler que SOUS SESSION : sans compte, la RPC part en anonyme et
 * échouerait pour rien. Le résultat pilote ce qu'on garde :
 *  - appliqué → on oublie le code (c'est fait, first-touch posé).
 *  - verdict DÉFINITIF du serveur (code inconnu, auto-parrainage, déjà rattachée)
 *    → on oublie aussi : le réessayer ne changerait jamais rien.
 *  - échec potentiellement TRANSITOIRE (réseau, socle pas déployé, pas encore de
 *    profil) → on GARDE, on retentera au prochain démarrage.
 *
 * Renvoie ce qui s'est passé, pour qu'un écran puisse fêter l'application
 * discrètement s'il le souhaite.
 */
export type IssueRattachement = 'applique' | 'aucun' | 'definitif' | 'a-retenter';

const RAISONS_DEFINITIVES = new Set(['code_inconnu', 'auto_parrainage', 'deja_rattachee', 'code_vide']);

export async function consommerCodeEnAttente(): Promise<IssueRattachement> {
  const code = await codeEnAttente();
  if (!code) return 'aucun';
  const r = await rattacherCode(code);
  if (r.ok) {
    await oublierCodeEnAttente();
    return 'applique';
  }
  if (r.raison && RAISONS_DEFINITIVES.has(r.raison)) {
    await oublierCodeEnAttente();
    return 'definitif';
  }
  // Transitoire : on garde le code pour une prochaine tentative.
  return 'a-retenter';
}
