import {
  copierLeconPlacee,
  creneauxDe,
  listeActivites,
  type ActiviteListe,
  type Classe,
  type Creneau,
} from '@/lib/donnees';

/**
 * Le multi-classes : deux gestes pour l'enseignant·e qui tient PLUSIEURS classes.
 *
 * 🔑 Cas d'usage fondateur : Mme Mahé est à mi-temps en immersion. Elle donne LA
 * MÊME leçon dans deux de ses classes (lundi la B, mardi la A) et veut, d'un
 * côté, les VOIR côte à côte dans le semainier sans changer de classe active, et
 * de l'autre, RECOPIER une leçon d'une classe vers l'autre sans tout ressaisir.
 *
 * Ce module ne fait que ça, et le fait EN LECTURE de la couche `donnees.ts` : il
 * réutilise `creneauxDe` et `listeActivites` (jamais réécrits ici) pour agréger,
 * et il n'écrit qu'une chose, une copie de leçon dans une classe cible, déléguée à
 * `copierLeconPlacee` (couche donnees) mais visant une AUTRE classe.
 *
 * 🚨 La vue agrégée est une vue de LECTURE : aucune édition multi-classes (pas de
 * glisser-déposer inter-classes). Le mode mono-classe du journal reste le défaut.
 */

/** Info de distinction d'une classe dans la vue agrégée : pastille + libellé. */
export type InfoClasse = {
  id: string;
  nom: string;
  /** Abrégé compact pour la pastille sur chaque bloc (« 2B », « M3 », « PS »…). */
  abrege: string;
  /**
   * Index de couleur STABLE = la position de la classe dans la liste reçue.
   * L'affichage (journal) transforme cet index en une couleur du thème, pour que
   * la lib ne dépende pas de `tokens.ts`.
   */
  couleurIndex: number;
};

/** Le résultat d'une semaine agrégée, prêt à nourrir `GrilleSemaine`. */
export type SemaineMultiClasses = {
  /** Créneaux fusionnés, un représentant par (jour, début), pour la grille. */
  creneaux: Creneau[];
  /**
   * Séances de TOUTES les classes actives, `creneauId` réaligné sur le créneau
   * représentatif de son (jour, début) pour tomber dans la case rendue.
   */
  activites: ActiviteListe[];
  /** `activite.id` → la classe d'origine, pour poser la pastille de distinction. */
  classeParActivite: Map<string, InfoClasse>;
};

/** Ajoute des jours à une date ISO en date pure, sans fuseau (comme `decalerISO`). */
function ajouterJoursISO(iso: string, jours: number): string {
  const [a, m, j] = iso.split('-').map((n) => parseInt(n, 10));
  const d = new Date(Date.UTC(a, m - 1, j));
  d.setUTCDate(d.getUTCDate() + jours);
  return d.toISOString().slice(0, 10);
}

/**
 * Un abrégé lisible pour la pastille. Le nom complet vit dans la légende ; ici on
 * ne veut qu'un repère court. Un token qui porte un chiffre (« 2B », « M3 »,
 * « P1 ») est le meilleur repère quand il existe ; sinon on prend les initiales
 * des premiers mots, et à défaut les premières lettres du nom.
 */
function abregerNom(nom: string): string {
  const net = (nom ?? '').trim();
  if (!net) return '?';
  const mots = net.split(/\s+/);
  const avecChiffre = mots.find((mot) => /\d/.test(mot));
  if (avecChiffre) return avecChiffre.toLocaleUpperCase('fr').slice(0, 4);
  const initiales = mots.map((m) => m[0] ?? '').join('').toLocaleUpperCase('fr');
  return (initiales || net).slice(0, 3).toLocaleUpperCase('fr');
}

/**
 * Agrège la semaine de TOUTES les classes données : leurs créneaux fusionnés et
 * leurs séances réunies, avec de quoi distinguer visuellement chaque classe.
 *
 * 🔑 La grille du semainier construit ses lignes à partir des créneaux (groupés
 * par heure de début) et pose chaque séance sur `${date}|${creneauId}`. Deux
 * classes ont des créneaux d'`id` DIFFÉRENTS au même (jour, début). Pour que les
 * séances des deux tombent dans la même case rendue, on fusionne les créneaux en
 * gardant UN représentant par (jour, début), et on réaligne le `creneauId` de
 * chaque séance sur ce représentant. Une séance sans créneau (ou dont le créneau
 * n'existe pas cette semaine) reste « sans heure », comme en mono-classe.
 */
export async function chargerSemaineMultiClasses(
  classes: Classe[],
  lundiISO: string,
): Promise<SemaineMultiClasses> {
  const debut = lundiISO;
  const fin = ajouterJoursISO(lundiISO, 4);

  const infoParClasse = new Map<string, InfoClasse>();
  classes.forEach((cl, i) => {
    infoParClasse.set(cl.id, {
      id: cl.id,
      nom: cl.nom,
      abrege: abregerNom(cl.nom),
      couleurIndex: i,
    });
  });

  // Créneaux + séances de chaque classe, en parallèle. On lit la couche donnees
  // telle quelle : ces deux fonctions appliquent déjà parité A/B, semaine propre
  // et suppression douce.
  const parClasse = await Promise.all(
    classes.map(async (cl) => ({
      classe: cl,
      creneaux: await creneauxDe(cl.id, debut),
      activites: await listeActivites({ classeId: cl.id, depuis: debut, jusqua: fin, limite: 200 }),
    })),
  );

  // Fusion des créneaux : le premier vu à un (jour, début) gagne la case ; on
  // retient pour chaque créneau l'id du représentant de son (jour, début).
  const representantParCle = new Map<string, Creneau>();
  const idVersRepresentant = new Map<string, string>();
  for (const { creneaux } of parClasse) {
    for (const cr of creneaux) {
      const cle = `${cr.jour}|${cr.debut}`;
      const rep = representantParCle.get(cle);
      if (rep) {
        idVersRepresentant.set(cr.id, rep.id);
      } else {
        representantParCle.set(cle, cr);
        idVersRepresentant.set(cr.id, cr.id);
      }
    }
  }
  const creneaux = [...representantParCle.values()];

  const activites: ActiviteListe[] = [];
  const classeParActivite = new Map<string, InfoClasse>();
  for (const { classe, activites: acts } of parClasse) {
    const info = infoParClasse.get(classe.id);
    if (!info) continue;
    for (const a of acts) {
      // Réalignement sur le représentant ; un créneau inconnu retombe en « sans
      // heure » plutôt que de disparaître.
      const creneauId = a.creneauId ? (idVersRepresentant.get(a.creneauId) ?? null) : null;
      activites.push({ ...a, creneauId });
      classeParActivite.set(a.id, info);
    }
  }

  return { creneaux, activites, classeParActivite };
}

/**
 * Copie UNE leçon vers une AUTRE classe de l'enseignant·e, en statut non-fait.
 *
 * 🔑 Le cas Mme Mahé : la même leçon dans deux de ses classes, sans la ressaisir.
 * On recopie la MATIÈRE (titre, préparation, attendus et leur rôle) mais jamais
 * l'ANCRAGE de la source (ni sa clôture, ni ses adaptations d'élèves nommés). La
 * copie naît « à faire » : `unplanned` sans date/créneau (elle attend d'être
 * placée dans la classe cible), ou `planned` si on lui donne un créneau à poser.
 *
 * Délègue à `copierLeconPlacee` (couche donnees) — donc attendus posés sur le
 * nouvel id, photos de préparation suivies et séquence recréée en unité — mais la
 * cible est une classe DIFFÉRENTE : `classroom_id` = la classe choisie, pas celle
 * de la source. Les attendus suivent : Mme Mahé donne la même leçon au même
 * niveau, ses attendus valent dans les deux classes.
 */
export async function copierLeconVersClasse(params: {
  activiteId: string;
  classeCibleId: string;
  /** Date ISO où poser la copie. Absente = « à planifier » (unplanned). */
  date?: string | null;
  /** Créneau où poser la copie, quand une date est donnée. */
  creneauId?: string | null;
}): Promise<{ id: string }> {
  const date = params.date ?? null;
  // Toute la robustesse (attendus posés sur le nouvel id, photos de préparation,
  // séquence recréée en unité) vit dans `copierLeconPlacee` : ici on ne fait que
  // viser une AUTRE classe et choisir le placement.
  return copierLeconPlacee(params.activiteId, {
    classroomId: params.classeCibleId,
    // Non-fait : datée si un créneau est choisi, sinon « à planifier ».
    status: date ? 'planned' : 'unplanned',
    date,
    slotId: date ? (params.creneauId ?? null) : null,
  });
}
