/**
 * Les trois réseaux, mêmes libellés que l'onboarding (t.bienvenue.reseau*) pour
 * ne pas écrire deux fois la même liste. Le réseau reste facultatif : une classe
 * peut ne pas en porter, comme toutes celles d'avant ce champ.
 */
const RESEAUX: { id: Reseau; libelle: string }[] = [
  { id: 'officiel', libelle: t.bienvenue.reseauOfficiel },
  { id: 'libre_confessionnel', libelle: t.bienvenue.reseauLibreConf },
  { id: 'libre_non_confessionnel', libelle: t.bienvenue.reseauLibreNonConf },
];
import { espace, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Libellés du co-enseignement, en local (fr + nl, repli fr). Comme l'aide
 * in-app : le chrome d'une feature neuve reste ici, on n'alourdit pas le
 * catalogue partagé. Tutoiement, inclusif, pas de tiret cadratin.
 */
const CO: Record<Langue, { invitations: string; invitationsAide: string; ajouter: string }> = {
  fr: {
    invitations: 'Invitations',
    invitationsAide: "Les classes qu'on t'invite à co-enseigner",
    ajouter: 'Ajouter un·e co-enseignant·e',
  },
  nl: {
    invitations: 'Uitnodigingen',
    invitationsAide: 'Klassen die je uitgenodigd wordt samen te geven',
    ajouter: 'Co-leerkracht toevoegen',
  },
};

function libCo() {
  return CO[langue] ?? CO.fr;
}

/**
 * Tes classes : en changer, en créer, en archiver.
 *
 * 🔑 **Une classe se crée sans élève.** Aucun écran ne demande une donnée dont
 * il n'a pas besoin tout de suite : l'onboarding hérité réclamait la classe,
 * l'horaire, les référentiels, les élèves et un avatar avant de rien montrer.
 *
 * 🚨 **On archive, on ne supprime pas — et il faut pouvoir y retourner.**
 *
 * La deuxième moitié de cette phrase manquait, et c'était le défaut. Mesuré le
 * 20/08/2026 : la bêta-testeuse a archivé sa classe `M1B` le 25 juillet, puis
 * créé celle de la rentrée. L'ancienne porte **380 activités, 27 élèves, 40
 * observations et 3 090 constats**, soit 90 % de tout ce que contient la base.
 *
 * `mesClasses` filtrait `archived_at is null` et aucun écran ne montrait les
 * archives. En ouvrant l'app elle voyait une classe vide, et son année entière
 * avait disparu. Rien n'était perdu en base ; tout était perdu pour elle, ce
 * qui revient exactement au même.
 *
 * D'où les deux sections, et le retour en arrière. Un archivage sans
 * désarchivage, c'est une suppression avec un mot plus doux.
 */
/**
 * Les champs d'une classe, partagés par la création et la modification : nom,
 * niveaux, réseau, et juridiction quand il y a un vrai choix. Une seule
 * définition, pour que créer et modifier ne divergent jamais.
 */
function ChampsClasse({
  nom,
  setNom,
  niveaux,
  setNiveaux,
  reseau,
  setReseau,
  juridiction,
  setJuridiction,
  juridictions,
  occupe,
}: {
  nom: string;
  setNom: (v: string) => void;
  niveaux: string[];
  setNiveaux: (maj: (l: string[]) => string[]) => void;
  reseau: Reseau | null;
  setReseau: (r: Reseau | null) => void;
  juridiction: string;
  setJuridiction: (code: string) => void;
  juridictions: Juridiction[];
  occupe: boolean;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <>
      <Champ
        etiquette={t.classes.nom}
        value={nom}
        onChangeText={setNom}
        placeholder={t.classes.nomIndice}
        editable={!occupe}
      />

      {/* Plusieurs niveaux, pas un : une classe verticale de maternelle en
          accueille trois, et c'est le cas le plus courant en Belgique. */}
      <Text style={styles.etiquette}>{t.classes.niveaux}</Text>
      <Text style={styles.aide}>{t.classes.niveauxAide}</Text>
      <View style={styles.rangee}>
        {NIVEAUX_FWB.map((n) => {
          const actif = niveaux.includes(n);
          return (
            <Pressable
              key={n}
              accessibilityRole="button"
              accessibilityState={{ selected: actif }}
              accessibilityLabel={`${t.classes.niveaux} ${n}`}
              onPress={() =>
                setNiveaux((l) =>
                  actif
                    ? l.filter((x) => x !== n)
                    : // On garde l'ordre officiel, pas l'ordre des taps :
                      // « M1-M3 » et « M3-M1 » ne se lisent pas pareil.
                      NIVEAUX_FWB.filter((x) => x === n || l.includes(x)),
                )
              }
              style={[styles.niveau, actif && styles.niveauActif]}>
              <Text style={[styles.texteNiveau, actif && styles.texteNiveauActif]}>{n}</Text>
            </Pressable>
          );
        })}
      </View>

      <Pastilles
        etiquette={t.classes.reseau}
        options={RESEAUX}
        choisi={reseau}
        onChoisir={(id) => setReseau(id as Reseau | null)}
      />
      <Text style={styles.aide}>{t.classes.reseauAide}</Text>

      {/* La juridiction n'apparaît que s'il y a un vrai choix : sinon on garde
          la valeur par défaut sans encombrer l'écran. */}
      {juridictions.length > 1 ? (
        <>
          <Pastilles
            etiquette={t.classes.juridiction}
            options={juridictions.map((j) => ({ id: j.code, libelle: j.libelle }))}
            choisi={juridiction}
            onChoisir={(id) => {
              if (id) setJuridiction(id);
            }}
          />
          <Text style={styles.aide}>{t.classes.juridictionAide}</Text>
        </>
      ) : null}
    </>
  );
}

export default function Classes() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { classes, enCours, classe, choisir, chargement, erreur, recharger } = useClasse();
  const passees = classes.filter((c) => c.archivee);

  const [ouvert, setOuvert] = useState(false);
  const [nom, setNom] = useState('');
  const [niveaux, setNiveaux] = useState<string[]>([]);
  const [annee, setAnnee] = useState(anneeScolaireCourante());
  const [reseau, setReseau] = useState<Reseau | null>(null);
  const [juridiction, setJuridiction] = useState<string>(JURIDICTION_DEFAUT);
  const [aArchiver, setAArchiver] = useState<string | null>(null);
  const [occupe, setOccupe] = useState(false);
  const [souci, setSouci] = useState<string | null>(null);
  const [invitationsOuvert, setInvitationsOuvert] = useState(false);

  const juridictions = useRequete(listeJuridictions, []);
  const listeJur = juridictions.donnees ?? [];

  async function creer() {
    setSouci(null);
    setOccupe(true);
    try {
      const creee = await creerClasse({
        nom,
        niveaux,
        anneeScolaire: annee,
        network: reseau,
        juridiction,
      });
      recharger();
      choisir(creee.id);
      setOuvert(false);
      setNom('');
      setNiveaux([]);
      setReseau(null);
      setJuridiction(JURIDICTION_DEFAUT);
    } catch (e) {
      setSouci(e instanceof Error ? e.message : t.classes.erreurCreation);
    } finally {
      setOccupe(false);
    }
  }

  async function desarchiver(id: string) {
    setSouci(null);
    setOccupe(true);
    try {
      await desarchiverClasse(id);
      recharger();
    } catch (e) {
      setSouci(e instanceof Error ? e.message : t.classes.erreurCreation);
    } finally {
      setOccupe(false);
    }
  }

  async function archiver(id: string) {
    setSouci(null);
    setOccupe(true);
    try {
      await archiverClasse(id);
      setAArchiver(null);
      recharger();
    } catch (e) {
      setSouci(e instanceof Error ? e.message : t.classes.erreurCreation);
    } finally {
      setOccupe(false);
    }
  }

  return (
    <SousEcran titre={t.classes.titre} chargement={chargement}>
      {erreur ? <Alerte message={t.classes.erreur} /> : null}
      {souci ? <Alerte message={souci} /> : null}

      {/* Les invitations reçues : une entrée globale (elles ne dépendent pas
          d'une classe à moi), qui ouvre la feuille Accepter / Refuser. */}
      <Carte onPress={() => setInvitationsOuvert(true)}>
        <View style={[styles.ligne, { alignItems: 'center' }]}>
          <Tuile icone="mail" />
          <View style={styles.corps}>
            <Text style={texte.corps}>{libCo().invitations}</Text>
            <Text style={texte.discret}>{libCo().invitationsAide}</Text>
          </View>
          <Feather name="chevron-right" size={20} color={c.nonRattache} />
        </View>
      </Carte>

      {enCours.length === 0 ? (
        <Carte>
          <Text style={texte.discret}>{t.classes.aucune}</Text>
        </Carte>
      ) : (
        enCours.map((c) => (
          <LigneClasse
            key={c.id}
            classe={c}
            active={c.id === classe?.id}
            // « Seule » se compte sur les classes en cours : une archivée ne
            // rattrape pas une enseignante qui archiverait sa dernière.
            seule={enCours.length === 1}
            occupe={occupe}
            enArchivage={aArchiver === c.id}
            juridictions={listeJur}
            onActiver={() => choisir(c.id)}
            onDemanderArchivage={() => setAArchiver(aArchiver === c.id ? null : c.id)}
            onArchiver={() => archiver(c.id)}
            onModifie={recharger}
            onSouci={setSouci}
          />
        ))
      )}

      {passees.length > 0 ? (
        <>
          <View style={styles.section}>
            <Text style={texte.section}>{t.classes.passees}</Text>
            <Text style={styles.aide}>{t.classes.passeesAide}</Text>
          </View>
          {passees.map((c) => (
            <LignePassee
              key={c.id}
              classe={c}
              active={c.id === classe?.id}
              occupe={occupe}
              onConsulter={() => choisir(c.id)}
              onRemettre={() => desarchiver(c.id)}
            />
          ))}
        </>
      ) : null}

      {!ouvert ? (
        <BoutonSecondaire libelle={t.classes.ajouter} onPress={() => setOuvert(true)} />
      ) : (
        <Carte>
          <ChampsClasse
            nom={nom}
            setNom={setNom}
            niveaux={niveaux}
            setNiveaux={setNiveaux}
            reseau={reseau}
            setReseau={setReseau}
            juridiction={juridiction}
            setJuridiction={setJuridiction}
            juridictions={listeJur}
            occupe={occupe}
          />

          <Champ
            etiquette={t.classes.annee}
            value={annee}
            onChangeText={setAnnee}
            editable={!occupe}
          />

          <PaireBoutons
            principal={{
              libelle: t.classes.creer,
              onPress: creer,
              occupe,
              inactif: !nom.trim() || niveaux.length === 0,
            }}
            secondaire={{ libelle: t.commun.annuler, onPress: () => setOuvert(false) }}
          />
        </Carte>
      )}

      <PanneauInvitations
        visible={invitationsOuvert}
        onFermer={() => setInvitationsOuvert(false)}
        onRepondu={recharger}
      />
    </SousEcran>
  );
}

function LigneClasse({
  classe,
  active,
  seule,
  occupe,
  enArchivage,
  juridictions,
  onActiver,
  onDemanderArchivage,
  onArchiver,
  onModifie,
  onSouci,
}: {
  classe: Classe;
  active: boolean;
  seule: boolean;
  occupe: boolean;
  enArchivage: boolean;
  juridictions: Juridiction[];
  onActiver: () => void;
  onDemanderArchivage: () => void;
  onArchiver: () => void;
  onModifie: () => void;
  onSouci: (message: string) => void;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const eleves = useRequete(() => elevesDe(classe.id), [classe.id]);
  const detail = t.classes.detail(classe.cycle, classe.anneeScolaire, (eleves.donnees ?? []).length);

  // Modifier une classe existante : niveaux, réseau, juridiction. On repart des
  // valeurs de la classe, `lireNiveaux` défaisant le `cycle` en cases à cocher.
  const [enEdition, setEnEdition] = useState(false);
  const [nomE, setNomE] = useState(classe.nom);
  const [niveauxE, setNiveauxE] = useState<string[]>(() => lireNiveaux(classe.cycle));
  const [reseauE, setReseauE] = useState<Reseau | null>(classe.network);
  const [juridictionE, setJuridictionE] = useState<string>(classe.juridiction);
  const [enregistrement, setEnregistrement] = useState(false);
  const [coOuvert, setCoOuvert] = useState(false);

  function ouvrirEdition() {
    // On resynchronise depuis la classe à chaque ouverture : elle a pu changer
    // ailleurs entre deux éditions.
    setNomE(classe.nom);
    setNiveauxE(lireNiveaux(classe.cycle));
    setReseauE(classe.network);
    setJuridictionE(classe.juridiction);
    setEnEdition(true);
  }

  async function enregistrerEdition() {
    onSouci('');
    setEnregistrement(true);
    try {
      await modifierClasse({
        classeId: classe.id,
        nom: nomE,
        niveaux: niveauxE,
        network: reseauE,
        juridiction: juridictionE,
      });
      setEnEdition(false);
      onModifie();
    } catch (e) {
      onSouci(e instanceof Error ? e.message : t.classes.erreurModification);
    } finally {
      setEnregistrement(false);
    }
  }

  if (enEdition) {
    return (
      <Carte>
        <ChampsClasse
          nom={nomE}
          setNom={setNomE}
          niveaux={niveauxE}
          setNiveaux={setNiveauxE}
          reseau={reseauE}
          setReseau={setReseauE}
          juridiction={juridictionE}
          setJuridiction={setJuridictionE}
          juridictions={juridictions}
          occupe={enregistrement}
        />
        <PaireBoutons
          principal={{
            libelle: t.classes.enregistrerModif,
            onPress: enregistrerEdition,
            occupe: enregistrement,
            inactif: !nomE.trim() || niveauxE.length === 0,
          }}
          secondaire={{ libelle: t.commun.annuler, onPress: () => setEnEdition(false) }}
        />
      </Carte>
    );
  }

  return (
    <>
    <Carte>
      <View style={styles.ligne}>
        {/* Corail quand c'est la classe active, gris sinon : l'état vit dans la
            tuile, pas dans un aplat. */}
        {active ? (
          <Tuile icone="users" fond={c.actionTeinte} trait={c.action[0]} />
        ) : (
          <Tuile icone="users" />
        )}
        <View style={styles.corps}>
          <Text style={texte.corps}>{classe.nom}</Text>
          <Text style={texte.discret}>{detail}</Text>
          {active ? <Text style={styles.active}>{t.classes.active}</Text> : null}
        </View>
      </View>

      {!active ? <BoutonDiscret libelle={t.classes.activer} onPress={onActiver} /> : null}

      {!enArchivage ? (
        <BoutonDiscret libelle={t.classes.modifier} onPress={ouvrirEdition} />
      ) : null}

      {/* Co-enseignement : inviter un·e collègue à partager cette classe. Réservé
          aux classes que je possède (toutes celles rendues ici le sont). */}
      {!enArchivage ? (
        <BoutonDiscret libelle={libCo().ajouter} onPress={() => setCoOuvert(true)} />
      ) : null}

      {/* Archiver est irréversible depuis l'app, donc ça se confirme. Le geste
          n'est pas caché derrière une icône poubelle : une icône seule se tape
          par erreur, une phrase non. */}
      {enArchivage ? (
        <>
          <Text style={styles.aide}>
            {seule ? t.classes.derniere : t.classes.archiverPourquoi}
          </Text>
          {!seule ? (
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={`${t.classes.archiverConfirme} ${classe.nom}`}
              disabled={occupe}
              onPress={onArchiver}
              style={styles.confirme}>
              <Feather name="archive" size={16} color={c.encre} />
              <Text style={styles.texteConfirme}>{t.classes.archiverConfirme}</Text>
            </Pressable>
          ) : null}
          <BoutonDiscret libelle={t.classes.archiverAnnule} onPress={onDemanderArchivage} />
        </>
      ) : (
        <BoutonDiscret libelle={t.classes.archiver} onPress={onDemanderArchivage} />
      )}
    </Carte>
    {coOuvert ? (
      <PanneauCoEnseignement classeId={classe.id} onFermer={() => setCoOuvert(false)} />
    ) : null}
    </>
  );
}

/**
 * Une année passée : ce qu'elle contient, et les deux façons d'y revenir.
 *
 * Le chiffre avant le tableau, comme partout : « 27 élèves · 18 séances faites
 * · 40 observations » dit en une ligne pourquoi on ne veut pas la perdre. Une
 * ligne qui ne dirait que le nom et l'année ne mériterait pas sa hauteur.
 */
function LignePassee({
  classe,
  active,
  occupe,
  onConsulter,
  onRemettre,
}: {
  classe: Classe;
  active: boolean;
  occupe: boolean;
  onConsulter: () => void;
  onRemettre: () => void;
}) {
  const couleurs = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(couleurs), [couleurs]);
  const contenu = useRequete(() => contenuDe(classe.id), [classe.id]);
  const c = contenu.donnees;

  return (
    <Carte>
      <View style={styles.ligne}>
        {/* Une classe archivée : tuile grise, elle dort. */}
        <Tuile icone="archive" />
        <View style={styles.corps}>
          <Text style={texte.corps}>{classe.nom}</Text>
          <Text style={texte.discret}>
            {classe.cycle} · {classe.anneeScolaire}
          </Text>
          {c ? (
            <Text style={texte.discret}>
              {t.classes.contenu(c.eleves, c.seances, c.observations)}
            </Text>
          ) : null}
          {active ? <Text style={styles.aide}>{t.classes.consultee}</Text> : null}
        </View>
      </View>

      {!active ? (
        <BoutonDiscret libelle={t.classes.consulter} onPress={onConsulter} />
      ) : (
        <Text style={styles.aide}>{t.classes.consulteeAide}</Text>
      )}
      <BoutonDiscret libelle={t.classes.remettre} onPress={onRemettre} />
    </Carte>
  );
}

