import { useMemo, useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';

import { Carte } from '@/components/ecran';
import { Alerte, BoutonPrincipal, BoutonSecondaire } from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import {
  type FormatExport,
  type PaquetExport,
  partagerExport,
  preparerExport,
  resumerPaquet,
} from '@/lib/export';
import { espace, police, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * L'écran qui rend ses données à une enseignante.
 *
 * 🔑 POURQUOI IL EXISTE. L'écran de suppression promet noir sur blanc « une
 * enseignante qui veut garder ses observations doit les avoir sorties avant » —
 * une promesse de sortie qui n'existait pas. La voici. Deux besoins que le RDV
 * écoles rend urgents : la portabilité RGPD (le fichier de données) et le
 * journal de classe (le même contenu, lisible).
 *
 * 🌗 Couleurs et styles de texte via les hooks `useCouleurs()` / `useTexte()`,
 * jamais la constante `color` : l'écran suit le thème clair comme sombre.
 *
 * Les libellés restent EN LOCAL, pas dans le catalogue i18n, comme le sélecteur
 * de thème de « Vous » : l'écran est autonome et ne dépend pas d'une clé
 * partagée que d'autres sessions éditent en parallèle. À déplacer dans `@/i18n`
 * le jour où la traduction de l'app se stabilise.
 */

// Deux temps dans le parcours : on prépare le paquet (un aller-retour serveur),
// puis on le partage, autant de fois qu'on veut, dans l'un ou l'autre format.
type Etat =
  | { phase: 'repos' }
  | { phase: 'preparation' }
  | { phase: 'pret'; paquet: PaquetExport };

export default function Exporter() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);

  const [etat, setEtat] = useState<Etat>({ phase: 'repos' });
  // Quel format est en cours d'écriture/partage, pour n'occuper que son bouton.
  const [partage, setPartage] = useState<FormatExport | null>(null);
  const [erreur, setErreur] = useState<string | null>(null);

  async function preparer() {
    setErreur(null);
    setEtat({ phase: 'preparation' });
    try {
      const paquet = await preparerExport();
      setEtat({ phase: 'pret', paquet });
    } catch (e) {
      setErreur(e instanceof Error ? e.message : "L'export n'a pas pu être préparé.");
      setEtat({ phase: 'repos' });
    }
  }

  async function partagerDans(format: FormatExport) {
    if (etat.phase !== 'pret') return;
    setErreur(null);
    setPartage(format);
    try {
      // Annuler le partage n'est pas une erreur : `shareAsync` se résout sans
      // rien lever, on ne montre donc aucun message dans ce cas.
      await partagerExport(etat.paquet, format);
    } catch (e) {
      setErreur(e instanceof Error ? e.message : "Le partage n'a pas abouti.");
    } finally {
      setPartage(null);
    }
  }

  const resume = etat.phase === 'pret' ? resumerPaquet(etat.paquet) : null;

  return (
    <SousEcran titre="Exporter mes données">
      <Carte>
        <Text style={texte.corps}>Tout ce que tu as noté, à toi</Text>
        <Text style={styles.detail}>
          Tu peux récupérer une copie de tes données à tout moment : c’est ton droit, et
          c’est aussi ce qu’il faut faire avant de fermer ton compte, parce que la
          suppression, elle, est sans retour.
        </Text>
      </Carte>

      <Carte>
        <Text style={texte.corps}>Deux formats, le même contenu</Text>
        <Text style={styles.detail}>
          Le journal de classe est fait pour se lire et s’imprimer : tes classes, tes
          élèves, tes leçons, tes observations et les constats de maîtrise, mis en page.
          Les données brutes, en JSON, sont pensées pour une machine, si tu veux tout
          garder ou reprendre ailleurs.
        </Text>
      </Carte>

      <Carte>
        <Text style={texte.corps}>Ce que l’export contient, et rien d’autre</Text>
        <Text style={styles.detail}>
          Seulement tes données à toi. Les prénoms de tes élèves y sont, tels que tu les as
          écrits : l’export te revient à toi, il ne part pas vers l’IA. Les photos et sons
          joints à tes observations arrivent sous forme de liens de téléchargement, qui
          restent valables une semaine.
        </Text>
      </Carte>

      {erreur ? <Alerte message={erreur} /> : null}

      {etat.phase !== 'pret' ? (
        <BoutonPrincipal
          libelle="Préparer mon export"
          onPress={() => void preparer()}
          occupe={etat.phase === 'preparation'}
        />
      ) : (
        <>
          {resume ? (
            <View style={styles.resume}>
              <Text style={styles.detail}>
                Prêt : {resume.classes} classe·s, {resume.eleves} élève·s, {resume.activites}{' '}
                leçon·s, {resume.observations} observation·s, {resume.constats} constat·s
                {resume.medias > 0 ? `, ${resume.medias} média·s` : ''}.
              </Text>
            </View>
          ) : null}

          <BoutonPrincipal
            libelle="Partager le journal de classe"
            onPress={() => void partagerDans('journal')}
            occupe={partage === 'journal'}
            inactif={partage !== null && partage !== 'journal'}
          />
          <BoutonSecondaire
            libelle="Partager les données (JSON)"
            onPress={() => void partagerDans('donnees')}
            occupe={partage === 'donnees'}
          />
        </>
      )}
    </SousEcran>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    detail: { fontFamily: police.corps, fontSize: 14, lineHeight: 21, color: c.encreDouce },
    resume: { paddingHorizontal: espace.xs },
  });
