import { useMemo, useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';

import { Cloudy } from '@/components/cloudy';
import {
  MiroirClasse,
  PanneauDetail,
  SelecteurPeriodes,
  type FiltreDetail,
} from '@/components/direction/tableau';
import { Carte } from '@/components/ecran';
import { Alerte, BoutonDiscret, BoutonPrincipal, Champ, Pastilles } from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import { chargerPeriodes, detacherClasse, detailMiroir, miroirDirection, rattacherClasse } from '@/lib/direction';
import { BACKEND_ABSENT } from '@/lib/etablissement';
import { bornesPeriode, indexPeriodeCourante, type ModePeriode } from '@/lib/periodes';
import { useRequete } from '@/lib/requete';
import { espace, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * « Ce que voit ma direction » : le miroir côté enseignant·e.
 *
 * 🔑 TRANSPARENCE TOTALE, PAS DE SURVEILLANCE CACHÉE
 *
 * La prof voit ici, au chiffre près, ce que sa direction voit de sa classe :
 * même fonction serveur (`direction__synthese`), mêmes composants d'affichage
 * que le tableau direction. Si les deux écrans divergeaient un jour, la promesse
 * tomberait ; c'est pourquoi rien n'est recalculé ici.
 *
 * 🔑 LE CONSENTEMENT EST ICI
 *
 * Une classe n'entre dans le tableau de la direction que si SA titulaire la
 * rattache, avec le code d'école donné par la direction. Le détachement est un
 * geste d'un tap, sans justification. Une classe non rattachée affiche quand
 * même ce que la direction VERRAIT, pour que la décision se prenne en
 * connaissance de cause.
 */
export default function DirectionMiroir() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const V = t.vueDirection;
  const { enCours, classe: classeActive } = useClasse();

  const [classeId, setClasseId] = useState<string | null>(null);
  const classe = enCours.find((x) => x.id === classeId) ?? classeActive ?? enCours[0] ?? null;

  // Les périodes de la classe : celles de SON école si elle est rattachée
  // (surcharge comprise), sinon le calendrier de sa juridiction. La prof lit
  // donc les mêmes périodes que sa direction.
  const periodes = useRequete(() => chargerPeriodes({ classe: classe!.id }), [classe?.id], { actif: !!classe });
  const liste = useMemo(() => periodes.donnees ?? [], [periodes.donnees]);
  const [choixIndex, setIndex] = useState<number | null>(null);
  const index = choixIndex ?? indexPeriodeCourante(liste);
  const [mode, setMode] = useState<ModePeriode>('cumul');
  const bornes = useMemo(() => bornesPeriode(liste, index, mode), [liste, index, mode]);

  const miroir = useRequete(
    () => miroirDirection(classe!.id, bornes.debut, bornes.fin),
    [classe?.id, bornes.debut, bornes.fin],
    { actif: !!classe && liste.length > 0 },
  );

  const [code, setCode] = useState('');
  const [occupe, setOccupe] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [erreurCode, setErreurCode] = useState<string | null>(null);

  const rattacher = async () => {
    if (!classe || !code.trim()) return;
    setOccupe(true);
    setErreurCode(null);
    setMessage(null);
    try {
      const r = await rattacherClasse(classe.id, code);
      setMessage(V.rattacherOk(r.nom));
      setCode('');
      miroir.recharger();
    } catch (e) {
      setErreurCode(e instanceof Error && e.message === 'code_inconnu' ? V.codeInconnu : V.erreur);
    } finally {
      setOccupe(false);
    }
  };

  const detacher = async () => {
    if (!classe) return;
    setOccupe(true);
    setMessage(null);
    try {
      await detacherClasse(classe.id);
      setMessage(V.detacherOk);
      miroir.recharger();
    } catch {
      setErreurCode(V.erreur);
    } finally {
      setOccupe(false);
    }
  };

  const [filtre, setFiltre] = useState<FiltreDetail | null>(null);
  // Pas de mémoïsation : le panneau ne relance la lecture que sur un nouveau filtre.
  const charger = (f: FiltreDetail) => detailMiroir(classe!.id, bornes.debut, bornes.fin, f.discipline ?? null);

  const m = miroir.donnees;
  const ligne = m?.classes[0] ?? null;

  return (
    <SousEcran titre={V.miroirTitre}>
      <Carte>
        <View style={styles.entete}>
          <Cloudy pose="serenite" taille={54} />
          <Text style={[texte.corps, styles.flex]}>{V.miroirIntro}</Text>
        </View>
      </Carte>

      {enCours.length > 1 ? (
        <Pastilles
          options={enCours.map((x) => ({ id: x.id, libelle: x.nom }))}
          choisi={classe?.id ?? null}
          onChoisir={(id) => id && setClasseId(id)}
        />
      ) : null}
      {liste.length ? (
        <SelecteurPeriodes periodes={liste} index={index} mode={mode} onIndex={setIndex} onMode={setMode} />
      ) : null}

      {miroir.erreur === BACKEND_ABSENT ? (
        <Carte>
          <Text style={texte.discret}>{V.bientot}</Text>
        </Carte>
      ) : miroir.erreur ? (
        <Carte>
          <Text style={texte.discret}>{V.erreur}</Text>
          <BoutonDiscret libelle={V.reessayer} onPress={miroir.recharger} />
        </Carte>
      ) : null}

      {/* Qui voit quoi : l'état du rattachement, dit en clair. */}
      {m ? (
        <Carte>
          <Text style={texte.corps}>
            {m.ecole
              ? V.miroirRattachee(m.ecole.commune ? `${m.ecole.nom} (${m.ecole.commune})` : m.ecole.nom)
              : V.miroirNonRattachee}
          </Text>
          {m.ecole ? (
            <Text style={[texte.discret, styles.espaceHaut]}>
              {m.directions.length ? V.miroirQui(m.directions.join(', ')) : V.miroirPersonne}
            </Text>
          ) : null}
          {message ? <Text style={[styles.message, styles.espaceHaut]}>{message}</Text> : null}
        </Carte>
      ) : null}

      {m && m.titulaire ? (
        m.ecole ? (
          <BoutonDiscret libelle={V.detacher} onPress={() => void detacher()} />
        ) : (
          <Carte>
            <Text style={texte.section}>{V.rattacherTitre}</Text>
            <Text style={[texte.discret, styles.espaceBas]}>{V.rattacherAide}</Text>
            <Champ
              etiquette={V.rattacherChamp}
              value={code}
              onChangeText={setCode}
              autoCapitalize="characters"
              autoCorrect={false}
              maxLength={12}
              placeholder="ABCD EFGH"
            />
            {erreurCode ? <Alerte message={erreurCode} /> : null}
            <View style={styles.espaceHaut}>
              <BoutonPrincipal
                libelle={V.rattacherBouton}
                onPress={() => void rattacher()}
                occupe={occupe}
                inactif={code.replace(/[\s-]/g, '').length < 8}
              />
            </View>
          </Carte>
        )
      ) : m ? (
        <Text style={texte.discret}>{V.coTitulaire}</Text>
      ) : null}

      {/* Exactement les briques du tableau direction, pour cette seule classe. */}
      {ligne && m ? <MiroirClasse ligne={ligne} seuil={m.seuilPeuDeDonnees} onDetail={setFiltre} /> : null}

      <PanneauDetail filtre={filtre} charger={charger} onFermer={() => setFiltre(null)} />
    </SousEcran>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    entete: { flexDirection: 'row', gap: espace.md, alignItems: 'center' },
    flex: { flex: 1 },
    espaceHaut: { marginTop: espace.sm },
    espaceBas: { marginBottom: espace.sm },
    message: {
      fontFamily: police.accent,
      fontSize: 14,
      color: c.encre,
      backgroundColor: c.teinte.recreation,
      borderRadius: rayon.pastille,
      padding: espace.sm,
    },
  });
