/**
 * Le journal répond à une seule question : qu'est-ce qui se passe cette semaine ?
 *
 * C'est l'axe du calendrier, le pilotage étant celui du programme. Ce sont les
 * deux axes qu'une enseignante navigue vraiment, et le journal de classe belge
 * est par nature les deux à la fois, un plan et un registre.
 *
 * 🔑 **La semaine se lit jour par jour, sur les créneaux.** Chaque séance est
 * posée à son heure, avec la couleur de son moment, et les journées vides le
 * disent au lieu de disparaître.
 *
 * 🚨 On ne déroule plus le fil « ce que tu as capté » (retour Valentin 24/08) :
 * ce qui reste à ranger vit dans la boîte de réception (l'icône d'en-tête), pas
 * en fil infini sous la semaine. Le journal ne garde que les jours.
 */

/** Cinq jours : le fondamental belge ne siège pas le week-end. */
const JOURS = [1, 2, 3, 4, 5];

/** Libellé du mode « toutes mes classes » (semainier agrégé, lecture seule). */
const LIB_MULTI = { fr: 'Afficher toutes mes classes', nl: 'Al mijn klassen tonen' };

/** L'icône d'un moment de la journée, pour sa tuile teintée. */
const ICONE_MOMENT: Record<Moment, keyof typeof Feather.glyphMap> = {
  accueil: 'sunrise',
  ateliers: 'grid',
  dirigees: 'edit-2',
  recreation: 'coffee',
  sortie: 'map-pin',
  social: 'users',
};

function isoDe(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

/** Le jour de la semaine (1 = lundi, 7 = dimanche) d'une date ISO, comme `Creneau.jour`. */
function dowDe(cle: string): number {
  const [a, m, j] = cle.split('-').map((n) => parseInt(n, 10));
  const jour = new Date(a, m - 1, j).getDay();
  return jour === 0 ? 7 : jour;
}

/** Le lundi de la semaine d'une date, décalé de N semaines. */
function lundiDe(decalage: number): Date {
  const d = new Date();
  d.setHours(12, 0, 0, 0);
  const jour = d.getDay() === 0 ? 7 : d.getDay();
  d.setDate(d.getDate() - (jour - 1) + decalage * 7);
  return d;
}

function jourDeLaSemaine(base: Date, index: number): Date {
  const d = new Date(base);
  d.setDate(d.getDate() + index);
  return d;
}

/**
 * « Lundi 17 août ».
 *
 * La capitale ne se met qu'à la première lettre : en français les noms de mois
 * sont en minuscules, et `textTransform: capitalize` écrivait « Lundi 17 Août ».
 */
function capitale(s: string): string {
  return s.charAt(0).toLocaleUpperCase('fr') + s.slice(1);
}

function libelleJourCourt(d: Date): string {
  return capitale(d.toLocaleDateString(localeDate(), { weekday: 'long', day: 'numeric', month: 'long' }));
}

export default function Journal() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { classe, enCours } = useClasse();
  const classeId = classe?.id ?? null;
  const [semaine, setSemaine] = useState(0);
  // Mode « toutes mes classes » : le semainier agrège les séances de TOUTES les
  // classes actives, en lecture seule, pour les lire côte à côte sans changer de
  // classe active. N'a de sens qu'en vue Semaine et avec au moins deux classes.
  const [multiClasses, setMultiClasses] = useState(false);
  // Deux lectures d'une même semaine : le FIL (jour par jour) et la GRILLE (le
  // semainier, jours en colonnes). On bascule sur place, sans pousser d'écran.
  const [vue, setVue] = useState<'fil' | 'semaine'>('fil');

  // La grille respire à la largeur de l'écran : sur le web, on demande la pleine
  // largeur pendant qu'on la regarde, et le cadre téléphone s'élargit. On la rend
  // au fil (et à la sortie de l'écran) pour ne pas élargir les autres vues.
  const { setPleine } = useLargeurWeb();
  useFocusEffect(
    useCallback(() => {
      setPleine(Platform.OS === 'web' && vue === 'semaine');
      return () => setPleine(false);
    }, [vue, setPleine]),
  );

  const lundi = useMemo(() => lundiDe(semaine), [semaine]);
  const debut = isoDe(lundi);
  const finSemaine = isoDe(jourDeLaSemaine(lundi, 4));

  // On charge les créneaux DE LA SEMAINE affichée (pas seulement le fond) : c'est
  // ce qui applique la parité A/B et les créneaux propres à la semaine, pour que
  // la grille montre l'horaire réellement en vigueur cette semaine-là.
  const creneaux = useRequete(() => creneauxDe(classeId!, debut), [classeId, debut], {
    actif: !!classeId,
  });

  const activites = useRequete(
    () => listeActivites({ classeId: classeId!, depuis: debut, jusqua: finSemaine, limite: 200 }),
    [classeId, debut],
    { actif: !!classeId },
  );

  // Les absences déclarées sur la semaine : le jour affiche « 🤒 Malade »
  // (retour Sophie 24/09 : l'absence récupérait les leçons sans rien montrer).
  const absences = useRequete(() => absencesEntre(classeId!, debut, finSemaine), [classeId, debut], {
    actif: !!classeId,
  });

  // La taxonomie des types d'apprentissage, pour l'étiquette des séances de
  // séquence (grille + fil). Une seule lecture, indépendante de la classe et de
  // la semaine ; repli embarqué si la base ne répond pas.
  const typesApp = useRequete(() => lireTypesApprentissage(), []);
  const types = typesApp.donnees ?? undefined;

  // Le mode multi-classes n'a de sens qu'en vue Semaine, quand l'enseignant·e a
  // plus d'une classe active.
  const multiActif = multiClasses && vue === 'semaine' && enCours.length > 1;
  const idsEnCours = enCours.map((cl) => cl.id).join(',');
  // La semaine agrégée de toutes les classes actives, chargée seulement en mode
  // multi-classes. Elle réunit créneaux et séances, et sait dire de quelle classe
  // vient chaque séance.
  const multi = useRequete(
    () => chargerSemaineMultiClasses(enCours, debut),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [debut, idsEnCours],
    { actif: multiActif },
  );

  // Une couleur stable par classe, tirée des couleurs de moment de la charte : la
  // pastille de chaque bloc et la légende partagent l'index (l'ordre d'`enCours`).
  const paletteClasses = useMemo(
    () => [c.moment.accueil, c.moment.social, c.moment.dirigees, c.moment.sortie, c.moment.ateliers, c.moment.recreation],
    [c],
  );
  // `activite.id` → { abrégé, couleur } pour la grille : on résout ici l'index de
  // couleur (la lib multi-classes ne dépend pas du thème).
  const classesAffichees = useMemo(() => {
    const m = new Map<string, { abrege: string; couleur: string }>();
    const src = multi.donnees?.classeParActivite;
    if (src) {
      for (const [actId, info] of src) {
        m.set(actId, { abrege: info.abrege, couleur: paletteClasses[info.couleurIndex % paletteClasses.length] });
      }
    }
    return m;
  }, [multi.donnees, paletteClasses]);
  // La légende : chaque classe active, son nom et sa couleur, dans l'ordre qui
  // fixe l'index de couleur.
  const legendeClasses = useMemo(
    () => enCours.map((cl, i) => ({ nom: cl.nom, couleur: paletteClasses[i % paletteClasses.length] })),
    [enCours, paletteClasses],
  );

  // 🚨 On rafraîchit au retour sur l'écran, comme le rituel du soir. Sans ça, le
  // journal gardait des séances périmées : clôturer ailleurs ne rechargeait pas.
  useFocusEffect(
    useCallback(() => {
      if (!classeId) return;
      activites.recharger();
      absences.recharger();
      if (multiActif) multi.recharger();
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [classeId, debut, multiActif]),
  );

  const parCreneau = useMemo(() => {
    const table = new Map<string, Creneau>();
    for (const c of creneaux.donnees ?? []) table.set(c.id, c);
    return table;
  }, [creneaux.donnees]);

  // Une séance à son heure. Sans créneau elle passe en tête de journée : elle a
  // un jour et pas une heure, et la reléguer en bas la ferait rater.
  const seancesDuJour = useMemo(() => {
    const table = new Map<string, ActiviteListe[]>();
    for (const a of activites.donnees ?? []) {
      if (!a.date) continue;
      const dedans = table.get(a.date) ?? [];
      dedans.push(a);
      table.set(a.date, dedans);
    }
    for (const liste of table.values()) {
      liste.sort((x, y) => {
        const hx = x.creneauId ? (parCreneau.get(x.creneauId)?.debut ?? '') : '';
        const hy = y.creneauId ? (parCreneau.get(y.creneauId)?.debut ?? '') : '';
        return hx.localeCompare(hy);
      });
    }
    return table;
  }, [activites.donnees, parCreneau]);

  const aujourdhui = isoDe(new Date());

  // Export PDF de la semaine, sur le web uniquement : on passe les données déjà
  // chargées (créneaux + séances), la lib récupère le détail de chaque séance et
  // ouvre l'impression du navigateur. Si le navigateur bloque la fenêtre, on le
  // dit plutôt que d'échouer en silence.
  // Glisser-déposer d'une séance vers une autre case : on la repose à la nouvelle
  // date et sur le nouveau créneau, puis on recharge. On garde la vue optimiste
  // simple (recharger après l'écriture) ; une erreur silencieuse laisse la grille
  // en place, la séance ayant déjà rebondi visuellement à son ancienne case.
  const deplacerSeance = useCallback(
    async (activiteId: string, date: string, creneauId: string | null) => {
      try {
        await replanifierActivite({ activiteId, date, creneauId });
      } catch {
        // silencieux : rien n'a bougé côté base, la grille reste cohérente.
      } finally {
        activites.recharger();
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );

  async function exporterPdf() {
    try {
      await exporterSemainePdf({
        classeNom: classe?.nom ?? 'Ma classe',
        lundi,
        activites: activites.donnees ?? [],
        creneaux: creneaux.donnees ?? [],
      });
    } catch {
      if (typeof window !== 'undefined') {
        window.alert('Pour exporter en PDF, autorise les fenêtres pop-up pour ce site, puis réessaie.');
      }
    }
  }

  return (
    <Ecran
      titre={t.journal.titre}
      avatarMenu={NAV_AVATAR ? <AvatarNav /> : undefined}
      selecteurClasse
      pleineLargeur={vue === 'semaine'}
      actions={
        <>
          {/* La boîte de réception réunit « à ranger » et les projets/brouillons
              (les projets vivaient ici en icône dossier ; ils y restent, dans un
              tiroir de la boîte). */}
          <BoiteReception classeId={classeId} />
          {/* Export PDF de la semaine : web seulement (l'impression navigateur
              produit le PDF sans module natif, donc sans build). */}
          {Platform.OS === 'web' ? (
            <BoutonRond icone="download" libelle="Exporter la semaine en PDF" onPress={exporterPdf} />
          ) : null}
          {/* Un « ? » qui redonne le mode d'emploi de la grille, à la demande :
              le coach mark ne passe qu'une fois, or des profs cherchaient « un
              tuto » (retour Mahé). Visible en vue Semaine, là où il aide. */}
          {vue === 'semaine' ? (
            <BoutonRond
              icone="help-circle"
              libelle={langue === 'nl' ? 'Hoe werkt het rooster?' : 'Comment marche la grille ?'}
              onPress={() =>
                Alert.alert(
                  langue === 'nl' ? 'Het weekrooster' : 'Le semainier',
                  t.coach.grille,
                )
              }
            />
          ) : null}
          {/* « Je serai absent·e » : récupérer une journée planifiée quand la prof
              est malade, et replanifier ce qui était prévu. Fonction très
              demandée qu'aucun concurrent n'a. */}
          <BoutonRond
            icone="user-x"
            libelle="Je serai absent·e"
            onPress={() => router.push('/absence')}
          />
          {/* Le « + » hérite de la SEMAINE affichée : sur une semaine passée
              (rattraper des jours loupés) ou à venir, l'activité se pose dans
              cette semaine-là et non « aujourd'hui ». Sinon, elle atterrissait
              dans la semaine courante et « rien ne se mettait » là où on
              regardait (retours Sophie, Mahé). Sur la semaine courante, pas de
              date : la création propose aujourd'hui, comme avant. */}
          <BoutonRond
            icone="plus"
            libelle={t.activite.nouvelle}
            onPress={() =>
              router.push({
                pathname: '/activite/type',
                params: semaine === 0 ? {} : { date: debut },
              })
            }
          />
        </>
      }
      sousEntete={
        // La barre de semaine reste FIXE quand on scrolle (retour Valentin 24/08).
        // La bascule Journée/Semaine vit sur la MÊME ligne que la navigation de
        // semaine : deux réglages d'une même semaine, une seule barre, moins de
        // hauteur perdue. Sur un écran étroit, elle passe dessous (flexWrap).
        <View style={styles.barreOutils}>
          <View style={styles.navigation}>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={t.journal.semainePrecedente}
              onPress={() => setSemaine((s) => s - 1)}
              style={styles.fleche}>
              <Feather name="chevron-left" size={20} color={c.encre} />
            </Pressable>
            <View style={styles.centre}>
              <Text style={styles.entete}>
                {semaine === 0 ? t.journal.cetteSemaine : t.journal.semaine}
              </Text>
              <Text style={texte.discret}>
                {t.journal.duAu(
                  lundi.toLocaleDateString(localeDate(), { day: 'numeric', month: 'short' }),
                  jourDeLaSemaine(lundi, 4).toLocaleDateString(localeDate(), {
                    day: 'numeric',
                    month: 'short',
                  }),
                )}
              </Text>
            </View>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={t.journal.semaineSuivante}
              onPress={() => setSemaine((s) => s + 1)}
              style={styles.fleche}>
              <Feather name="chevron-right" size={20} color={c.encre} />
            </Pressable>
            {semaine !== 0 ? (
              <Pressable
                accessibilityRole="button"
                accessibilityLabel={t.journal.aujourdhui}
                onPress={() => setSemaine(0)}
                style={styles.aujourdhui}>
                <Text style={styles.aujourdhuiTexte}>{t.journal.aujourdhui}</Text>
              </Pressable>
            ) : null}
          </View>
          {/* Le mode « toutes mes classes » : bascule le semainier en vue agrégée
              (lecture seule). Visible seulement en vue Semaine et quand il y a
              plus d'une classe active, là où il aide vraiment. */}
          {vue === 'semaine' && enCours.length > 1 ? (
            <Pressable
              accessibilityRole="button"
              accessibilityState={{ selected: multiClasses }}
              accessibilityLabel={LIB_MULTI[langue]}
              onPress={() => setMultiClasses((v) => !v)}
              style={[styles.iconeCopie, multiClasses && styles.iconeCopieActive]}>
              <Feather name="layers" size={18} color={multiClasses ? c.actif : c.encre} />
            </Pressable>
          ) : null}
          {/* Le flux UNIQUE « Copier vers… », à droite du défilement de semaine :
              en deux temps (que copier, puis où coller). Caché sur une classe
              archivée, où l'on ne recompose pas la semaine, et en vue
              multi-classes agrégée (la copie agit sur une seule classe). */}
          {classeId && !classe?.archivee && !multiActif ? (
            <CopierVers
              classeId={classeId}
              classes={enCours}
              lundiISO={debut}
              activites={activites.donnees ?? []}
              creneaux={creneaux.donnees ?? []}
              onCopie={() => activites.recharger()}
            />
          ) : null}
          {/* Ancre d'aide « ? » (mode aide) de la grille de semaine : le guide
              « planifier ta semaine ». Visible en vue Semaine, et seulement quand
              le mode aide est allumé (sinon null, barre inchangée). */}
          {vue === 'semaine' ? <AncreAide zone="journal-grille-semaine" /> : null}
          <Bascule vue={vue} onChoisir={setVue} />
        </View>
      }>
      {activites.erreur ? <Alerte message={t.journal.erreur} /> : null}

      {/* 🚨 Planche orange en tête : la classe n'a pas encore d'horaire (aucun
          créneau dans la semaine type), donc les journées s'affichent en vrac.
          On pousse à poser la semaine une fois, le journal se range ensuite
          (retour Anne-Charlotte, 25/08). On ne la montre pas sur une année
          passée ni pendant le chargement, pour ne pas clignoter. */}
      {classe && !classe.archivee && !creneaux.chargement && (creneaux.donnees?.length ?? 0) === 0 ? (
        <BanniereHoraire />
      ) : null}

      {vue === 'semaine' ? (
        multiActif ? (
          // Vue agrégée (lecture seule) : la légende des classes, puis la grille
          // qui reçoit les séances de toutes les classes et la carte de pastilles.
          // Pas de `onDeplacer` : on ne déplace pas une séance entre classes ici.
          <>
            <LegendeClasses classes={legendeClasses} />
            <GrilleSemaine
              creneaux={multi.donnees?.creneaux ?? []}
              activites={multi.donnees?.activites ?? []}
              lundiISO={debut}
              classes={classesAffichees}
              types={types}
            />
          </>
        ) : (creneaux.donnees?.length ?? 0) > 0 ? (
          <GrilleSemaine
            creneaux={creneaux.donnees ?? []}
            activites={activites.donnees ?? []}
            lundiISO={debut}
            onDeplacer={deplacerSeance}
            types={types}
            absences={absences.donnees ?? []}
          />
        ) : null
      ) : (
        JOURS.map((_, index) => {
        const jour = jourDeLaSemaine(lundi, index);
        const cle = isoDe(jour);
        const seances = seancesDuJour.get(cle) ?? [];
        const cestAujourdhui = cle === aujourdhui;
        // Les moments de la journée, tirés de la semaine type. Une séance posée
        // sur un créneau s'affiche à son moment ; un créneau libre devient un
        // geste « ajouter ici », pour poser une activité sans repartir de zéro.
        // Les séances sans créneau (une date, pas d'heure) passent en tête.
        const creneauxJour = (creneaux.donnees ?? [])
          .filter((cr) => cr.jour === dowDe(cle))
          .sort((a, b) => a.debut.localeCompare(b.debut));
        // Filet : une séance dont le créneau n'est pas dans l'horaire de ce jour
        // (créneau supprimé, autre semaine) remonte en tête au lieu de disparaître.
        const idsJour = new Set(creneauxJour.map((cr) => cr.id));
        const sansCreneau = seances.filter((a) => !a.creneauId || !idsJour.has(a.creneauId));
        return (
          <View key={cle} style={styles.jour}>
            <Text style={[styles.enteteJour, cestAujourdhui && styles.enteteAujourdhui]}>
              {cestAujourdhui ? t.journal.aujourdhui : libelleJourCourt(jour)}
            </Text>
            <View style={styles.absenceJour}>
              <BadgeAbsence absences={absencesDuJour(absences.donnees ?? [], cle)} />
            </View>

            {sansCreneau.map((a) => (
              <LigneSeance key={a.id} activite={a} creneau={undefined} cloturable={cle <= aujourdhui} types={types} />
            ))}

            {creneauxJour.map((cr) => {
              const surCreneau = seances.filter((a) => a.creneauId === cr.id);
              if (surCreneau.length) {
                return surCreneau.map((a) => (
                  <LigneSeance key={a.id} activite={a} creneau={cr} cloturable={cle <= aujourdhui} types={types} />
                ));
              }
              return <MomentLibre key={cr.id} creneau={cr} date={cle} />;
            })}

            {/* Aucun créneau dans la semaine type ET aucune séance : le jour est
                vraiment vide. On le dit, et on pose un « + Ajouter » orange sur la
                même ligne pour appeler à l'action (retour Valentin 24/08). */}
            {creneauxJour.length === 0 && seances.length === 0 ? (
              <Pressable
                accessibilityRole="button"
                accessibilityLabel={`${t.journal.jourVide}, ${t.journal.ajouterMoment}`}
                onPress={() =>
                  router.push({ pathname: '/activite/type', params: { date: cle } })
                }>
                <Carte compacte>
                  <View style={styles.ligne}>
                    <Text style={[texte.discret, styles.corps]}>{t.journal.jourVide}</Text>
                    <View style={styles.ajouterMoment}>
                      <Feather name="plus" size={16} color={c.action[1]} />
                      <Text style={styles.ajouterTexte}>{t.journal.ajouterMoment}</Text>
                    </View>
                  </View>
                </Carte>
              </Pressable>
            ) : null}
          </View>
        );
      })
      )}
    </Ecran>
  );
}

/**
 * La bascule Fil / Semaine : deux lectures d'une même semaine. Le fil déroule les
 * jours (l'axe du calendrier), la semaine les pose en grille (le semainier). Un
 * segment, pas un écran séparé : on reste dans le journal.
 */
function Bascule({
  vue,
  onChoisir,
}: {
  vue: 'fil' | 'semaine';
  onChoisir: (v: 'fil' | 'semaine') => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const options: { id: 'fil' | 'semaine'; libelle: string; icone: keyof typeof Feather.glyphMap }[] = [
    { id: 'fil', libelle: 'Journée', icone: 'list' },
    { id: 'semaine', libelle: 'Semaine', icone: 'grid' },
  ];
  return (
    <View style={styles.bascule}>
      {options.map((o) => {
        const actif = o.id === vue;
        return (
          <Pressable
            key={o.id}
            accessibilityRole="button"
            accessibilityState={{ selected: actif }}
            accessibilityLabel={o.libelle}
            onPress={() => onChoisir(o.id)}
            style={[styles.basculeBouton, actif && styles.basculeActif]}>
            <Feather name={o.icone} size={15} color={actif ? c.surface : c.encreDouce} />
            <Text style={[styles.basculeTexte, actif && styles.basculeTexteActif]}>{o.libelle}</Text>
          </Pressable>
        );
      })}
    </View>
  );
}

/**
 * La planche « planifie ta semaine » : montrée en tête du journal tant que la
 * classe n'a aucun créneau. Sans horaire, les journées s'affichent en vrac (pas
 * de moments), et un simple « Ajouter » par jour ne dit pas qu'il manque la
 * structure. La planche pousse une fois vers l'éditeur de semaine type, puis
 * disparaît d'elle-même dès qu'un créneau existe.
 */
function BanniereHoraire() {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <View style={styles.planche}>
      <View style={styles.plancheRangee}>
        <Feather name="calendar" size={20} color={c.action[1]} />
        <Text style={styles.plancheTitre}>{t.journal.planifieTitre}</Text>
      </View>
      <Text style={styles.plancheAide}>{t.journal.planifieAide}</Text>
      <BoutonPrincipal
        libelle={t.journal.planifieBouton}
        onPress={() => router.push('/vous/semaine')}
      />
    </View>
  );
}

/**
 * Une séance en ligne de liste.
 *
 * La ligne porte quatre informations dans la place d'une : l'heure, le moment
 * par sa couleur, l'état, et le nombre d'attendus. Une ligne de liste doit
 * mériter sa hauteur, sinon elle rétrécit.
 */
function LigneSeance({
  activite,
  creneau,
  cloturable = false,
  types,
}: {
  activite: ActiviteListe;
  creneau?: Creneau;
  /** Le jour est aujourd'hui ou passé : une séance non faite peut être clôturée. */
  cloturable?: boolean;
  /** La taxonomie des types, pour l'étiquette d'une séance de séquence. */
  types?: TypeApprentissage[];
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const faite = activite.statut === 'completed';
  const montrerCloture = cloturable && !faite;
  // Une séquence multi-étapes : on annonce l'avancement (k/N) sur la ligne, et le
  // type en étiquette sous le titre. Une leçon mono-étape n'affiche rien de plus.
  const estSequence = activite.sequenceTotal > 1;
  const detail = [
    creneau ? `${creneau.debut} ${creneau.libelle}` : t.journal.sansMoment,
    activite.type === 'workshop' ? t.activite.atelier : null,
    estSequence && activite.stepOrder
      ? texteEtape(activite.stepOrder, activite.sequenceTotal)
      : null,
    faite ? t.activite.faite : t.activite.aFaire,
    // Zéro attendu veut dire que sa clôture n'écrira rien et qu'elle ne comptera
    // pas dans le programme. Autant le dire sur la ligne.
    activite.attendus === 0 ? t.activite.sansAttendu : null,
  ]
    .filter(Boolean)
    .join(' · ');

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`${activite.titre}, ${detail}`}
      onPress={() => router.push({ pathname: '/activite/[id]', params: { id: activite.id } })}>
      <Carte compacte>
        <View style={styles.ligne}>
          {faite ? (
            <Tuile icone="check" moment="recreation" />
          ) : creneau?.moment ? (
            <Tuile icone={ICONE_MOMENT[creneau.moment]} moment={creneau.moment} />
          ) : (
            <Tuile icone="clock" />
          )}
          <View style={styles.corps}>
            <Text style={texte.corps}>{activite.titre}</Text>
            <Text style={texte.discret}>{detail}</Text>
            {estSequence ? <EtiquetteType code={activite.learningType} types={types} /> : null}
          </View>
          {montrerCloture ? (
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={`${t.journal.cloturer}, ${activite.titre}`}
              onPress={() =>
                router.push({ pathname: '/activite/cloturer/[id]', params: { id: activite.id } })
              }
              hitSlop={8}
              style={styles.cloturerChip}>
              <Feather name="check" size={15} color={c.moment.recreation} />
              <Text style={styles.cloturerTexte}>{t.journal.cloturer}</Text>
            </Pressable>
          ) : (
            <Feather name="chevron-right" size={20} color={c.nonRattache} />
          )}
        </View>
      </Carte>
    </Pressable>
  );
}

/**
 * Un moment de la journée encore libre : la tuile de son moment, l'heure et le
 * libellé du créneau, et un geste « ajouter » qui ouvre la création d'activité
 * déjà posée sur ce jour et ce créneau. C'est ce qui rend un jour vide utile :
 * on ajoute depuis le moment plutôt que de tout ressaisir.
 */
function MomentLibre({ creneau, date }: { creneau: Creneau; date: string }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`${t.journal.ajouterMoment}, ${creneau.debut} ${creneau.libelle}`}
      onPress={() =>
        router.push({ pathname: '/activite/type', params: { date, creneau: creneau.id } })
      }>
      <Carte compacte>
        <View style={styles.ligne}>
          {creneau.moment ? (
            <Tuile icone={ICONE_MOMENT[creneau.moment]} moment={creneau.moment} />
          ) : (
            <Tuile icone="clock" />
          )}
          <View style={styles.corps}>
            <Text style={texte.discret}>
              {creneau.debut} {creneau.libelle}
            </Text>
          </View>
          <View style={styles.ajouterMoment}>
            <Feather name="plus" size={16} color={c.action[1]} />
            <Text style={styles.ajouterTexte}>{t.journal.ajouterMoment}</Text>
          </View>
        </View>
      </Carte>
    </Pressable>
  );
}

/**
 * La légende du semainier agrégé : chaque classe active, son point de couleur et
 * son nom. Elle donne la clé de lecture des pastilles posées sur les blocs, pour
 * qu'un « 2B » corail se rattache tout de suite à sa classe.
 */
function LegendeClasses({ classes }: { classes: { nom: string; couleur: string }[] }) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  if (!classes.length) return null;
  return (
    <View
      accessibilityRole="summary"
      accessibilityLabel={`${LIB_MULTI[langue]} : ${classes.map((cl) => cl.nom).join(', ')}`}
      style={styles.legende}>
      {classes.map((cl) => (
        <View key={cl.nom} style={styles.legendeItem}>
          <View style={[styles.legendePoint, { backgroundColor: cl.couleur }]} />
          <Text style={styles.legendeTexte} numberOfLines={1}>
            {cl.nom}
          </Text>
        </View>
      ))}
    </View>
  );
}

