import { Feather } from '@expo/vector-icons';
import { useMemo } from 'react';
import { router } from 'expo-router';
import { Linking, StyleSheet, Text, View } from 'react-native';

import { Cloudy } from '@/components/cloudy';
import { Carte } from '@/components/ecran';
import { BoutonPrincipal, BoutonSecondaire } from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { t } from '@/i18n';
import { espace, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * « Et ta direction, elle voit quoi ? »
 *
 * 🔑 Une fenêtre intermédiaire AVANT d'ouvrir la page côté site. Le lien vers
 * educooo.com/direction reste, mais il ne s'ouvre plus dans le dos du prof :
 * d'abord on explique, de SON point de vue, ce que la direction voit et surtout
 * ce qu'elle ne voit pas. Le but n'est pas de vendre un tableau de bord à la
 * direction, c'est de rassurer l'enseignant·e et de l'inviter à en parler pour
 * les bonnes raisons: une école qui se pilote ensemble, pas une classe fliquée.
 *
 * Le parti pris de fond, tenu ici comme dans le produit : le respect et la
 * transparence envers le prof passent avant le confort de contrôle.
 */
export default function DirectionInfo() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const d = t.directionInfo;

  return (
    <SousEcran titre={d.titre}>
      <Carte>
        <View style={styles.entete}>
          <Cloudy pose="serenite" taille={54} />
          <Text style={[texte.corps, styles.accroche]}>{d.accroche}</Text>
        </View>
      </Carte>

      {/* Ce qu'elle voit : des tendances collectives, jamais l'individu. */}
      <Carte>
        <Text style={texte.section}>{d.voitTitre}</Text>
        {d.voit.map((ligne) => (
          <View key={ligne} style={styles.ligne}>
            <Feather name="check" size={18} color={c.actif} style={styles.puce} />
            <Text style={[texte.corps, styles.ligneTexte]}>{ligne}</Text>
          </View>
        ))}
      </Carte>

      {/* Ce qu'elle ne voit jamais : la garantie, dite noir sur blanc. */}
      <Carte>
        <Text style={texte.section}>{d.voitPasTitre}</Text>
        {d.voitPas.map((ligne) => (
          <View key={ligne} style={styles.ligne}>
            <Feather name="x" size={18} color={c.nonRattache} style={styles.puce} />
            <Text style={[texte.corps, styles.ligneTexte]}>{ligne}</Text>
          </View>
        ))}
      </Carte>

      <Carte>
        <Text style={styles.note}>{d.seuil}</Text>
        <Text style={styles.note}>{d.fond}</Text>
      </Carte>

      <Carte>
        <Text style={[texte.corps, styles.inviter]}>{d.inviter}</Text>
      </Carte>

      {/* Le geste principal : vérifier soi-même, sur SA classe, ce que la
          direction voit (le miroir). La promesse « tu peux vérifier » tient
          enfin par un écran, plus seulement par une phrase. */}
      <BoutonPrincipal libelle={d.miroir} onPress={() => router.push('/direction-miroir')} />

      {/* Le lien vers le site n'est plus le geste par défaut : c'est un choix
          délibéré, posé après l'explication. */}
      <BoutonSecondaire
        libelle={d.ouvrir}
        onPress={() => void Linking.openURL('https://educooo.com/direction')}
      />
    </SousEcran>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    entete: { flexDirection: 'row', gap: espace.md, alignItems: 'center' },
    accroche: { flex: 1 },
    ligne: { flexDirection: 'row', gap: espace.sm, alignItems: 'flex-start', marginTop: espace.xs },
    puce: { marginTop: 2 },
    ligneTexte: { flex: 1 },
    note: {
      fontFamily: police.corps,
      fontSize: 14,
      color: c.encreDouce,
      lineHeight: 20,
      marginTop: espace.xs,
    },
    inviter: {
      fontFamily: police.accent,
      fontSize: 15,
      color: c.encre,
      backgroundColor: c.actionTeinte,
      borderRadius: rayon.tuile,
      padding: espace.md,
    },
  });
