/**
 * Le gabarit des écrans direction : barre fixe (retour ou croix, TOUJOURS
 * visible hors du défilement, règle UX du studio), puis une colonne large
 * plafonnée à `maxContenuLarge`. `SousEcran` plafonne à une largeur de lecture
 * (680), trop étroite pour une matrice de dix colonnes.
 */
export function CadreDirection({
  titre,
  sousTitre,
  auRetour,
  bandeau,
  children,
}: {
  titre: string;
  sousTitre?: string;
  auRetour?: () => void;
  /** Un bandeau fixe sous la barre (l'étiquette « démonstration »). */
  bandeau?: ReactNode;
  children: ReactNode;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <SafeAreaView style={styles.racine} edges={['top']}>
      <View style={[styles.barre, styles.colonne]}>
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={t.cloture.retour}
          onPress={() => (auRetour ? auRetour() : router.canGoBack() ? router.back() : router.replace('/'))}
          style={styles.retour}>
          <Feather name="chevron-left" size={24} color={c.encre} />
        </Pressable>
        <View style={styles.barreCentre}>
          <Text style={texte.section} numberOfLines={1}>
            {titre}
          </Text>
          {sousTitre ? (
            <Text style={texte.discret} numberOfLines={1}>
              {sousTitre}
            </Text>
          ) : null}
        </View>
        <View style={styles.retour} />
      </View>
      {bandeau ? <View style={[styles.colonne, styles.bandeauZone]}>{bandeau}</View> : null}
      <ScrollView contentContainerStyle={[styles.contenu, styles.colonne]}>{children}</ScrollView>
    </SafeAreaView>
  );
}

