/* ── En-tête : école + période ─────────────────────────────────────────────── */

/** « 24/08 » : la date courte d'une borne de période. */
const dateCourte = (iso: string) => `${iso.slice(8, 10)}/${iso.slice(5, 7)}`;

/**
 * Le sélecteur de période, lu depuis les DONNÉES (calendrier officiel, surcharge
 * de l'école ou repli) : plus aucun bouton de trimestre codé en dur. En repli,
 * les libellés viennent de l'i18n (le serveur renvoie du français).
 */
export function SelecteurPeriodes({
  periodes,
  index,
  mode,
  onIndex,
  onMode,
}: {
  periodes: Periode[];
  index: number;
  mode: ModePeriode;
  onIndex: (i: number) => void;
  onMode: (m: ModePeriode) => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const libelle = (p: Periode, i: number) => (p.source === 'repli' ? V().trimestres[i] ?? p.libelle : p.libelle);
  const p = periodes[index];
  return (
    <View style={styles.periodes}>
      <Pastilles
        options={periodes.map((x, i) => ({ id: String(i), libelle: libelle(x, i) }))}
        choisi={String(index)}
        // Une pastille de période ne se désélectionne pas : on reste sur le choix.
        onChoisir={(id) => id != null && onIndex(Number(id))}
      />
      <Pastilles
        options={[
          { id: 'cumul', libelle: V().modeCumul },
          { id: 'seule', libelle: V().modeSeul },
        ]}
        choisi={mode}
        onChoisir={(id) => id && onMode(id as ModePeriode)}
      />
      {p ? (
        <Text style={styles.petit}>
          {V().periodeDates(dateCourte(p.debut), dateCourte(p.fin), Math.round(p.joursClasse / 5))} ·{' '}
          {V().sourcePeriodes[p.source]}
        </Text>
      ) : null}
    </View>
  );
}

