/**
 * Le choix de couche, partagé par la répartition et la matrice.
 *
 * 🔑 Pourquoi un sélecteur plutôt que trois colonnes : la matrice a déjà dix
 * colonnes, les tripler la rendrait illisible sur téléphone. Une couche à la
 * fois, principal par défaut ; les tuiles et les cartes de classe restent
 * TOUJOURS en principal (c'est la couverture), avec les deux autres couches en
 * petit sous la barre. Rien n'est jamais additionné.
 */
export function SelecteurCouche({ couche, onCouche }: { couche: Couche; onCouche: (c: Couche) => void }) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <View style={styles.periodes}>
      <Pastilles
        options={COUCHES.map((x) => ({ id: x, libelle: V().couches[x] }))}
        choisi={couche}
        onChoisir={(id) => id && onCouche(id as Couche)}
      />
      <Text style={styles.petit}>{V().coucheAide[couche]}</Text>
    </View>
  );
}

/* ── Le tableau complet ────────────────────────────────────────────────────── */

export type FiltreDetail = { classe?: LigneClasse | null; discipline?: Discipline | null };

/**
 * Les quatre tuiles, la répartition par discipline, les classes, la matrice,
 * les canaux et l'équilibre. Les trois points d'entrée du drill-down (une
 * discipline, une classe, une case) remontent par `onDetail`.
 */
export function TableauDirection({
  synthese,
  rythme,
  onDetail,
}: {
  synthese: Synthese;
  /** Les jours de classe écoulés, ou null en « période seule ». */
  rythme: Rythme | null;
  onDetail: (f: FiltreDetail) => void;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { width } = useWindowDimensions();
  const large = width > LARGE;
  const [couche, setCouche] = useState<Couche>('principal');
  const r = useMemo(() => resumer(synthese), [synthese]);
  const pctGlobal = pourcent(r.global);
  const etendue = etendueNiveaux(r.suivies);

  return (
    <View style={styles.pile}>
      <View style={[styles.tuiles, large && styles.tuilesLarge]}>
        <View style={[styles.tuile, styles.tuileGlobal, large ? styles.tuileQuart : styles.tuileDemi]}>
          <Text style={styles.tuileChiffre}>{V().tuileGlobal(pctGlobal)}</Text>
          <Text style={styles.tuileChiffreLibelle}>{V().tuileGlobalLibelle}</Text>
          <Text style={styles.tuileTexte}>{V().tuileGlobalDetail(r.global.travailles, r.global.total)}</Text>
          <Barre pct={pctGlobal} couleur={c.actif} fond={c.actionTeinte} repere={rythme?.part ?? null} />
          {rythme ? (
            <Text style={styles.tuileRepere}>
              {V().rythme(Math.round(rythme.jours / 5), Math.round(rythme.total / 5), Math.round(rythme.part * 100))}
            </Text>
          ) : null}
        </View>
        <Tuile
          chiffre={r.suivies.length}
          texte={etendue ? V().tuileClasses(nomNiveau(etendue.premier), nomNiveau(etendue.dernier)) : V().tuileClassesSimple}
          extra={r.horsEducooo.length ? V().tuileHorsEducooo(r.horsEducooo.length) : undefined}
          large={large}
        />
        <Tuile chiffre={r.disciplinesCouvertes} texte={V().tuileDisciplines} large={large} />
        <Tuile chiffre={r.croisementsSous30} texte={V().tuileCroisements} large={large} />
      </View>

      <View style={[styles.deuxColonnes, large && styles.deuxColonnesLarge]}>
        <View style={[styles.flexColonne, large && styles.colonneGauche]}>
          <Carte>
            <TitreBloc titre={V().repartitionTitre} aide={V().repartitionAide} />
            <SelecteurCouche couche={couche} onCouche={setCouche} />
            {r.parDiscipline.map(({ discipline, compte }) => (
              <LigneDiscipline
                key={discipline}
                discipline={discipline}
                compte={compte}
                couche={couche}
                onPress={() => onDetail({ discipline })}
              />
            ))}
          </Carte>
        </View>
        <View style={[styles.flexColonne, large && styles.colonneDroite]}>
          <Carte>
            <TitreBloc titre={V().classesTitre} aide={V().classesAide} />
            <View style={styles.grilleClasses}>
              {synthese.classes.map((cl) => (
                <View key={cl.id} style={large ? styles.celluleClasse : styles.celluleClassePleine}>
                  <CarteClasse classe={cl} seuil={synthese.seuilPeuDeDonnees} onPress={() => onDetail({ classe: cl })} />
                </View>
              ))}
            </View>
          </Carte>
        </View>
      </View>

      <Carte>
        <View style={styles.matriceEntete}>
          <Text style={texte.section}>{V().matriceTitre}</Text>
          <Legende />
        </View>
        <SelecteurCouche couche={couche} onCouche={setCouche} />
        <Matrice synthese={synthese} couche={couche} onDetail={onDetail} />
      </Carte>

      <View style={[styles.deuxColonnes, large && styles.deuxColonnesLarge]}>
        <View style={[styles.flexColonne, large && styles.colonneGauche]}>
          <Carte>
            <TitreBloc titre={V().canauxTitre} />
            <Text style={texte.discret}>{V().canauxAide}</Text>
            <BarreCanaux canaux={r.canaux} />
          </Carte>
        </View>
        <View style={[styles.flexColonne, large && styles.colonneDroite]}>
          <Carte>
            <TitreBloc titre={V().equilibreTitre} />
            <Text style={texte.discret}>{V().equilibreAide}</Text>
            {r.suivies.map((cl) => (
              <View key={cl.id} style={styles.equilibreLigne}>
                <Text style={styles.equilibreClasse}>{cl.nom}</Text>
                <BlocEquilibre classe={cl} compact />
              </View>
            ))}
            {r.suivies.length === 0 ? <Text style={texte.discret}>{V().equilibreVide}</Text> : null}
          </Carte>
        </View>
      </View>
    </View>
  );
}

function Tuile({ chiffre, texte: libelle, extra, large }: { chiffre: number; texte: string; extra?: string; large: boolean }) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <View style={[styles.tuile, large ? styles.tuileQuart : styles.tuileDemi]}>
      <Text style={styles.tuileChiffre}>{chiffre}</Text>
      <Text style={styles.tuileTexte}>{libelle}</Text>
      {extra ? <Text style={styles.tuileRepere}>{extra}</Text> : null}
    </View>
  );
}

function TitreBloc({ titre, aide }: { titre: string; aide?: string }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <View style={styles.titreBloc}>
      <Text style={texte.section}>{titre}</Text>
      {aide ? <Text style={texte.discret}>{aide}</Text> : null}
    </View>
  );
}

/** Une piste de progression, avec en option le repère du rythme de l'année. */
function Barre({ pct, couleur, fond, repere }: { pct: number; couleur: string; fond: string; repere?: number | null }) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <View style={[styles.piste, { backgroundColor: fond }]}>
      <View style={[styles.remplissage, { width: `${Math.min(100, pct)}%`, backgroundColor: couleur }]} />
      {repere != null ? <View style={[styles.repere, { left: `${Math.round(repere * 100)}%` }]} /> : null}
    </View>
  );
}

/* ── Les briques exportées (tableau + miroir) ──────────────────────────────── */

/** « Éveil, initiation scientifique · 78 sur 121 · 64 % travaillé · 43 encore ouverts ». */
export function LigneDiscipline({
  discipline,
  compte,
  couche = 'principal',
  onPress,
}: {
  discipline: Discipline;
  compte: Compte;
  couche?: Couche;
  onPress?: () => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const moment = MOMENT_DISCIPLINE[discipline];
  const pct = pourcent(compte, couche);
  const touchees = dansCouche(compte, couche);
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`${nomDiscipline(discipline)}, ${V().ratio(touchees, compte.total)}`}
      onPress={onPress}
      disabled={!onPress}
      style={({ pressed }) => [styles.ligneDiscipline, pressed && styles.presse]}>
      <View style={styles.ligneDisciplineEntete}>
        <Text style={styles.nomDiscipline} numberOfLines={2}>
          {nomDiscipline(discipline)}
        </Text>
        <View style={[styles.pastilleRatio, { backgroundColor: c.teinte[moment] }]}>
          <Text style={styles.pastilleRatioTexte}>{V().ratio(touchees, compte.total)}</Text>
        </View>
      </View>
      <Barre pct={pct} couleur={c.moment[moment]} fond={c.bord} />
      <Text style={styles.petit}>
        {couche === 'principal'
          ? V().ligneDiscipline(pct, compte.total - compte.travailles)
          : `${pct} % · ${V().couches[couche]}`}
      </Text>
    </Pressable>
  );
}

/** La carte d'une classe : pastille abrégée, nom, titulaire, %, barre, ratio. */
export function CarteClasse({
  classe,
  seuil,
  onPress,
}: {
  classe: LigneClasse;
  seuil: number;
  onPress?: () => void;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const pct = pourcent(classe);
  const moment = MOMENT_PALIER[palier(pct)];
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={classe.nom}
      onPress={onPress}
      disabled={!onPress}
      style={({ pressed }) => [styles.carteClasse, pressed && styles.presse]}>
      <View style={styles.carteClasseEntete}>
        <View style={[styles.pastilleClasse, { backgroundColor: c.teinte.dirigees }]}>
          <Text style={[styles.pastilleClasseTexte, { color: c.moment.dirigees }]}>{abregeClasse(classe)}</Text>
        </View>
        <View style={styles.flex}>
          <Text style={styles.nomClasse} numberOfLines={1}>
            {classe.nom}
          </Text>
          <Text style={texte.discret} numberOfLines={1}>
            {classe.enseignant ?? V().enseignantInconnu}
          </Text>
        </View>
        {classe.peuDeDonnees ? (
          <Feather name="book" size={18} color={c.encreDouce} />
        ) : (
          <Text style={[styles.pctClasse, { color: c.encre }]}>{pct} %</Text>
        )}
      </View>
      {classe.peuDeDonnees ? (
        <>
          <Text style={styles.peuDonnees}>{V().peuDonnees}</Text>
          <Text style={styles.petit}>{V().peuDonneesAide(classe.seances, seuil)}</Text>
        </>
      ) : (
        <>
          <Barre pct={pct} couleur={c.moment[moment]} fond={c.bord} />
          <Text style={styles.petit}>{V().ligneClasse(classe.travailles, classe.total)}</Text>
          <Text style={styles.petit}>{V().classeCouches(classe.croisees, classe.transversales)}</Text>
        </>
      )}
      {classe.delegues > 0 ? <Text style={styles.petit}>{V().delegues(classe.delegues)}</Text> : null}
    </Pressable>
  );
}

function Legende() {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const paliers: Palier[] = ['regarder', 'enCours', 'bien', 'large'];
  return (
    <View style={styles.legende}>
      {paliers.map((p, i) => (
        <View key={p} style={styles.legendeItem}>
          <View style={[styles.legendePoint, { backgroundColor: c.moment[MOMENT_PALIER[p]] }]} />
          <Text style={styles.petit}>{V().legende[i]}</Text>
        </View>
      ))}
    </View>
  );
}

/**
 * La matrice classes × disciplines. Défile horizontalement sur téléphone (dix
 * colonnes ne tiennent pas en 375 points), la première colonne reste lisible
 * parce qu'elle est dans la même rangée que ses cases.
 */
export function Matrice({
  synthese,
  couche = 'principal',
  onDetail,
}: {
  synthese: Synthese;
  couche?: Couche;
  onDetail: (f: FiltreDetail) => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const colonnes = colonnesMatrice(synthese);
  // Sur téléphone, la colonne des classes se resserre : deux cases de plus
  // visibles avant de devoir faire défiler la matrice.
  const { width } = useWindowDimensions();
  const colClasse = width < 600 ? styles.matriceColClasseEtroite : null;
  return (
    <ScrollView horizontal showsHorizontalScrollIndicator>
      <View>
        <View style={styles.matriceLigne}>
          <Text style={[styles.matriceTete, styles.matriceColClasse, colClasse]}>{V().matriceClasse}</Text>
          {colonnes.map((d) => (
            <Text key={d} style={[styles.matriceTete, styles.matriceCol]} numberOfLines={1}>
              {nomDisciplineCourt(d)}
            </Text>
          ))}
          <Text style={[styles.matriceTete, styles.matriceCol]}>{V().matriceTotal}</Text>
        </View>
        {synthese.classes.map((cl) => (
          <View key={cl.id} style={styles.matriceLigne}>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={cl.nom}
              onPress={() => onDetail({ classe: cl })}
              style={[styles.matriceColClasse, colClasse]}>
              <Text style={styles.nomClasse} numberOfLines={1}>
                {cl.nom}
              </Text>
              <Text style={styles.petit} numberOfLines={1}>
                {cl.enseignant ?? V().enseignantInconnu}
              </Text>
            </Pressable>
            {colonnes.map((d) => (
              <Case
                key={d}
                compte={cl.disciplines[d]}
                couche={couche}
                grise={cl.peuDeDonnees}
                onPress={() => onDetail({ classe: cl, discipline: d })}
              />
            ))}
            <Case compte={cl} couche={couche} grise={cl.peuDeDonnees} total onPress={() => onDetail({ classe: cl })} />
          </View>
        ))}
      </View>
    </ScrollView>
  );
}

function Case({
  compte,
  couche,
  grise,
  total = false,
  onPress,
}: {
  compte?: Compte;
  couche: Couche;
  grise: boolean;
  total?: boolean;
  onPress: () => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  if (!compte || compte.total === 0) {
    return (
      <View style={[styles.case, styles.matriceCol, { backgroundColor: c.fond }]}>
        <Text style={styles.petit}>·</Text>
      </View>
    );
  }
  const pct = pourcent(compte, couche);
  const touchees = dansCouche(compte, couche);
  // Une classe « peu de données » : on montre le ratio (il existe) mais sans
  // couleur de palier, pour ne pas peindre en rose un carnet papier.
  const moment = MOMENT_PALIER[palier(pct)];
  const fond = grise ? c.fond : total ? c.bord : c.teinte[moment];
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`${pct} %, ${touchees}/${compte.total}`}
      onPress={onPress}
      style={({ pressed }) => [styles.case, styles.matriceCol, { backgroundColor: fond }, pressed && styles.presse]}>
      <Text style={[styles.casePct, !grise && !total && { color: c.encre }]}>{grise ? '·' : `${pct} %`}</Text>
      <Text style={styles.petit}>
        {touchees}/{compte.total}
      </Text>
      {!grise && !total ? <View style={[styles.caseTrait, { backgroundColor: c.moment[moment] }]} /> : null}
    </Pressable>
  );
}

/** La répartition VAK en une barre segmentée + la légende chiffrée. */
export function BarreCanaux({ canaux }: { canaux: Canaux }) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const cles: { cle: keyof Canaux; moment: Moment | null }[] = [
    { cle: 'visuel', moment: 'accueil' },
    { cle: 'auditif', moment: 'dirigees' },
    { cle: 'kinesthesique', moment: 'recreation' },
    { cle: 'mixte', moment: 'ateliers' },
    { cle: 'non_precise', moment: null },
  ];
  const somme = cles.reduce((s, k) => s + canaux[k.cle], 0);
  const coul = (m: Moment | null) => (m ? c.moment[m] : c.nonRattache);
  return (
    <View style={styles.canaux}>
      <View style={[styles.piste, styles.pisteCanaux]}>
        {somme > 0
          ? cles.map((k) =>
              canaux[k.cle] > 0 ? (
                <View key={k.cle} style={{ flex: canaux[k.cle], backgroundColor: coul(k.moment) }} />
              ) : null,
            )
          : null}
      </View>
      <View style={styles.legende}>
        {cles.map((k) => (
          <View key={k.cle} style={styles.legendeItem}>
            <View style={[styles.legendePoint, { backgroundColor: coul(k.moment) }]} />
            <Text style={styles.petit}>
              {V().canaux[k.cle]} · {canaux[k.cle]}
              {somme > 0 ? ` (${Math.round((canaux[k.cle] / somme) * 100)} %)` : ''}
            </Text>
          </View>
        ))}
      </View>
    </View>
  );
}

/** Le signal d'équilibre d'une classe, formulé sans jugement. */
export function BlocEquilibre({ classe, compact = false }: { classe: LigneClasse; compact?: boolean }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const e = classe.equilibre;
  if (classe.peuDeDonnees || e.partTop3 == null) {
    return <Text style={compact ? styles.petit : texte.discret}>{V().equilibreVide}</Text>;
  }
  const zero = Math.max(0, e.competences - e.competencesTravaillees);
  const style = compact ? styles.petit : texte.corps;
  return (
    <View style={styles.equilibre}>
      <Text style={style}>{V().equilibreTop3(Math.round(e.partTop3 * 100))}</Text>
      {e.competencesRepetees > 0 ? <Text style={style}>{V().equilibreRepetees(e.competencesRepetees)}</Text> : null}
      <Text style={style}>{V().equilibreZero(zero)}</Text>
      {e.plusTravaillee ? (
        <Text style={style} numberOfLines={compact ? 2 : undefined}>
          {V().equilibrePlus(e.plusTravaillee.libelle, e.plusTravaillee.seances)}
        </Text>
      ) : null}
    </View>
  );
}

/* ── Le drill-down ─────────────────────────────────────────────────────────── */

/**
 * Le panneau « les attendus derrière le chiffre ». En `Modal` plein écran, avec
 * une croix FIXE en haut (hors défilement, règle du studio). La lecture est
 * déléguée à `charger` : direction, miroir ou démo branchent chacun la leur,
 * le panneau ne sait pas d'où viennent les lignes.
 */
export function PanneauDetail({
  filtre,
  charger,
  onFermer,
  demo = false,
}: {
  filtre: FiltreDetail | null;
  charger: (f: FiltreDetail) => Promise<LigneDetail[]>;
  onFermer: () => void;
  demo?: boolean;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  // La lecture passe par `useRequete` (réponse périmée ignorée, démontage sûr).
  // `charger` change à chaque rendu du parent : seul le filtre relance.
  const requete = useRequete(() => charger(filtre!), [filtre], { actif: !!filtre });
  const lignes = filtre && !requete.chargement ? requete.donnees : null;
  const erreur = requete.erreur;
  const [vue, setVue] = useState<'tout' | 'ouverts' | 'travailles'>('tout');
  // Un nouveau filtre repart sur « Tout » : on mémorise le filtre vu, et on
  // remet la vue à zéro pendant le rendu (motif React « ajuster l'état quand une
  // prop change », sans effet ni rendu en cascade).
  const [filtreVu, setFiltreVu] = useState<FiltreDetail | null>(filtre);
  if (filtreVu !== filtre) {
    setFiltreVu(filtre);
    setVue('tout');
  }

  const titre = [
    filtre?.classe?.nom ?? V().detailToutesClasses,
    filtre?.discipline ? nomDiscipline(filtre.discipline) : V().detailToutes,
  ].join(' · ');

  // Compétence → ses attendus. Le filtre porte sur la COMPÉTENCE (travaillée
  // en principal ou encore ouverte), la même règle que le pourcentage.
  const competences = regrouperDetail(lignes ?? []).filter((co) =>
    vue === 'tout' ? true : vue === 'ouverts' ? co.principal === 0 : co.principal > 0,
  );
  // Des intertitres discipline · domaine, dans l'ordre du programme (déjà trié
  // côté serveur) : on ne réordonne pas.
  const blocs: { cle: string; titre: string; competences: typeof competences }[] = [];
  for (const co of competences) {
    const cle = `${co.discipline}|${co.domaine}`;
    const dernier = blocs[blocs.length - 1];
    if (dernier?.cle === cle) dernier.competences.push(co);
    else blocs.push({ cle, titre: `${nomDisciplineCourt(co.discipline)} · ${co.domaine}`, competences: [co] });
  }
  const plusieursClasses = !filtre?.classe;

  return (
    <Modal visible={!!filtre} animationType="slide" onRequestClose={onFermer} presentationStyle="pageSheet">
      <SafeAreaView style={styles.racine} edges={['top', 'bottom']}>
        <View style={[styles.barre, styles.colonne]}>
          <View style={styles.retour} />
          <View style={styles.barreCentre}>
            <Text style={texte.section} numberOfLines={1}>
              {V().detailTitre}
            </Text>
            <Text style={texte.discret} numberOfLines={1}>
              {titre}
            </Text>
          </View>
          <Pressable accessibilityRole="button" accessibilityLabel={V().fermer} onPress={onFermer} style={styles.retour}>
            <Feather name="x" size={24} color={c.encre} />
          </Pressable>
        </View>
        {demo ? (
          <View style={[styles.colonne, styles.bandeauZone]}>
            <BandeauDemo />
          </View>
        ) : null}
        <ScrollView contentContainerStyle={[styles.contenu, styles.colonne]}>
          <Carte>
            <Text style={texte.discret}>{V().detailGarantie}</Text>
          </Carte>
          <Pastilles
            options={V().detailFiltres.map((libelle, i) => ({ id: ['tout', 'ouverts', 'travailles'][i], libelle }))}
            choisi={vue}
            onChoisir={(id) => setVue((id as typeof vue) ?? 'tout')}
          />
          {erreur ? <Text style={texte.discret}>{V().erreur}</Text> : null}
          {lignes == null && !erreur ? <ActivityIndicator color={c.encreDouce} /> : null}
          {lignes != null && competences.length === 0 ? <Text style={texte.discret}>{V().detailVide}</Text> : null}
          {blocs.map((b) => (
            <Carte key={b.cle}>
              <Text style={styles.detailBloc}>{b.titre}</Text>
              {b.competences.map((co) => (
                <View key={co.id} style={styles.detailCompetence}>
                  <View style={styles.detailLigne}>
                    <View
                      style={[
                        styles.detailPoint,
                        { backgroundColor: co.principal > 0 ? c.moment.recreation : c.nonRattache },
                      ]}
                    />
                    <View style={styles.flex}>
                      <Text style={styles.detailCompetenceTitre}>{co.libelle}</Text>
                      <Text style={styles.petit}>
                        {co.principal > 0 ? V().detailCompetenceTravaillee : V().detailCompetenceOuverte}
                      </Text>
                    </View>
                  </View>
                  {/* Un seul attendu qui répète la compétence (fréquent en maternelle) :
                      on ne le réécrit pas, on donne ses séances sous la compétence. */}
                  {co.attendus.length === 1 && co.attendus[0].attendu === co.libelle ? (
                    <Text style={[styles.petit, styles.detailAttenduSeul]}>
                      {co.attendus[0].principal + co.attendus[0].croise + co.attendus[0].transversal > 0
                        ? V().detailCouches(co.attendus[0].principal, co.attendus[0].croise, co.attendus[0].transversal)
                        : V().detailOuvert}
                      {plusieursClasses ? ` · ${V().detailClasses(co.attendus[0].classesTravaillees, co.attendus[0].classesTotal)}` : ''}
                    </Text>
                  ) : co.attendus.map((l, i) => (
                    <View key={`${co.id}-${i}`} style={styles.detailAttendu}>
                      <Text style={texte.corps}>{l.attendu}</Text>
                      <Text style={styles.petit}>
                        {l.principal + l.croise + l.transversal > 0
                          ? V().detailCouches(l.principal, l.croise, l.transversal)
                          : V().detailOuvert}
                        {plusieursClasses ? ` · ${V().detailClasses(l.classesTravaillees, l.classesTotal)}` : ''}
                      </Text>
                    </View>
                  ))}
                </View>
              ))}
            </Carte>
          ))}
        </ScrollView>
      </SafeAreaView>
    </Modal>
  );
}

