/* ── Le bloc « ma classe, vue par la direction » (miroir réel et démo) ─────── */

/**
 * Exactement les briques du tableau direction, pour UNE classe : sa carte, ses
 * disciplines (avec le même choix de couche), ses canaux, son équilibre. Partagé
 * par le miroir réel et le miroir de démonstration, pour que la démo montre la
 * vraie transparence et pas une maquette à part.
 */
export function MiroirClasse({
  ligne,
  seuil,
  onDetail,
}: {
  ligne: LigneClasse;
  seuil: number;
  onDetail: (f: FiltreDetail) => void;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const [couche, setCouche] = useState<Couche>('principal');
  return (
    <View style={styles.pile}>
      <Text style={texte.section}>{V().miroirMaClasse}</Text>
      <CarteClasse classe={ligne} seuil={seuil} onPress={() => onDetail({ classe: ligne })} />
      <Carte>
        <SelecteurCouche couche={couche} onCouche={setCouche} />
        {DISCIPLINES.filter((d) => (ligne.disciplines[d]?.total ?? 0) > 0).map((d) => (
          <LigneDiscipline
            key={d}
            discipline={d}
            compte={ligne.disciplines[d]!}
            couche={couche}
            onPress={() => onDetail({ classe: ligne, discipline: d })}
          />
        ))}
      </Carte>
      <Carte>
        <Text style={texte.section}>{V().canauxTitre}</Text>
        <Text style={texte.discret}>{V().canauxAide}</Text>
        <BarreCanaux canaux={ligne.canaux} />
      </Carte>
      <Carte>
        <Text style={texte.section}>{V().equilibreTitre}</Text>
        <Text style={[texte.discret, styles.espaceBas]}>{V().equilibreAide}</Text>
        <BlocEquilibre classe={ligne} />
      </Carte>
    </View>
  );
}
