import { LinearGradient } from 'expo-linear-gradient';
import { forwardRef, useMemo, type ReactNode } from 'react';
import {
  ActivityIndicator,
  Platform,
  Pressable,
  StyleSheet,
  Text,
  TextInput,
  View,
  type PressableStateCallbackType,
  type TextInputProps,
} from 'react-native';

import { Presse } from '@/components/presse';
import { espace, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * Les briques de saisie de la charte v9. Elles vivent ici et nulle part ailleurs :
 * un champ redessiné à la main dans un écran finit toujours par dériver.
 */

export const Champ = forwardRef<TextInput, TextInputProps & { etiquette?: string }>(
  function Champ({ etiquette, style, ...reste }, ref) {
    const c = useCouleurs();
    const styles = useMemo(() => creerStyles(c), [c]);
    return (
      <View style={styles.groupe}>
        {etiquette ? <Text style={styles.etiquette}>{etiquette}</Text> : null}
        <TextInput
          ref={ref}
          placeholderTextColor={c.nonRattache}
          style={[styles.champ, style]}
          {...reste}
        />
      </View>
    );
  },
);

/** Bouton principal. Le dégradé d'action n'apparaît que sur celui-là. */
export function BoutonPrincipal({
  libelle,
  onPress,
  occupe = false,
  inactif = false,
}: {
  libelle: string;
  onPress: () => void;
  occupe?: boolean;
  inactif?: boolean;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const desactive = inactif || occupe;
  return (
    <Presse
      accessibilityRole="button"
      // Le libellé est dans le dégradé, donc invisible pour un lecteur
      // d'écran : on le redonne ici. Vaut pour tous les écrans d'un coup.
      accessibilityLabel={libelle}
      accessibilityState={{ disabled: desactive, busy: occupe }}
      disabled={desactive}
      onPress={onPress}
      style={desactive ? styles.grise : undefined}>
      <LinearGradient
        colors={c.action}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.principal}>
        {occupe ? (
          <ActivityIndicator color={c.surface} />
        ) : (
          <Text style={styles.libellePrincipal}>{libelle}</Text>
        )}
      </LinearGradient>
    </Presse>
  );
}

/**
 * Bouton secondaire : un cadre, pas d'aplat.
 *
 * Il existe parce que `BoutonDiscret` ne se voit pas. Deux libellés gris
 * centrés à la suite se lisent comme des étiquettes, pas comme des gestes, et
 * ça s'est vu tout de suite sur l'écran de création d'activité. Un cadre suffit
 * à dire « ça se touche » sans prendre le dégradé, qui reste réservé à l'action
 * principale de l'écran.
 */
export function BoutonSecondaire({
  libelle,
  onPress,
  icone,
  occupe = false,
}: {
  libelle: string;
  onPress: () => void;
  icone?: ReactNode;
  occupe?: boolean;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <Presse
      accessibilityRole="button"
      accessibilityLabel={libelle}
      accessibilityState={{ busy: occupe, disabled: occupe }}
      disabled={occupe}
      onPress={onPress}
      style={[styles.secondaire, occupe && styles.grise]}>
      {occupe ? <ActivityIndicator color={c.encre} /> : null}
      {icone}
      <Text style={styles.libelleSecondaire}>{libelle}</Text>
    </Presse>
  );
}

/**
 * Deux boutons sur UNE ligne (retour Valentin 24/08) : le secondaire (cadre,
 * fond transparent) à gauche, le principal (dégradé miel) à droite. Ça remplace
 * les paires empilées « Ajouter » / « Annuler » qui prenaient deux fois la
 * hauteur pour rien. Chaque bouton prend la moitié de la largeur.
 */
export function PaireBoutons({
  principal,
  secondaire,
}: {
  principal: { libelle: string; onPress: () => void; occupe?: boolean; inactif?: boolean };
  secondaire: { libelle: string; onPress: () => void };
}) {
  return (
    <View style={{ flexDirection: 'row', gap: espace.sm }}>
      <View style={{ flex: 1 }}>
        <BoutonSecondaire libelle={secondaire.libelle} onPress={secondaire.onPress} />
      </View>
      <View style={{ flex: 1 }}>
        <BoutonPrincipal
          libelle={principal.libelle}
          onPress={principal.onPress}
          occupe={principal.occupe}
          inactif={principal.inactif}
        />
      </View>
    </View>
  );
}

/** L'état d'un `Pressable` sur RN-web, qui ajoute `hovered` au type natif. */
type EtatSurvol = PressableStateCallbackType & { hovered?: boolean };

/** Bouton discret, sans cadre. Pour un geste de repli, pas pour un geste attendu. */
export function BoutonDiscret({ libelle, onPress }: { libelle: string; onPress: () => void }) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={libelle}
      onPress={onPress}
      // Pas de retrait sous le doigt ici (geste de repli) : sur le web, le seul
      // retour est le survol — le libellé passe de gris à encre, la souris prend
      // la main. RN-web passe `hovered` au calcul de style ; sur natif il est
      // toujours faux, rien ne change.
      // Le type RN ne connaît pas `hovered` (propre à RN-web) : on l'annonce
      // optionnel plutôt que de faire taire le compilateur en bloc.
      style={({ hovered }: EtatSurvol) => [styles.discret, hovered ? styles.discretSurvol : null]}>
      {({ hovered }: EtatSurvol) => (
        <Text style={[styles.libelleDiscret, hovered ? styles.libelleDiscretSurvol : null]}>
          {libelle}
        </Text>
      )}
    </Pressable>
  );
}

/**
 * Rangée de choix à sélection unique, réversible d'un tap.
 * Pas de menu déroulant : sur téléphone, un menu cache les options et demande
 * deux gestes. Ici tout est visible et un seul tap suffit, y compris pour
 * désélectionner, parce qu'une observation sans élève est un cas normal.
 */
export function Pastilles<T extends { id: string; libelle: string }>({
  options,
  choisi,
  onChoisir,
  etiquette,
}: {
  options: T[];
  choisi: string | null;
  onChoisir: (id: string | null) => void;
  etiquette?: string;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  if (!options.length) return null;
  return (
    <View style={styles.groupe}>
      {etiquette ? <Text style={styles.etiquette}>{etiquette}</Text> : null}
      <View style={styles.rangee}>
        {options.map((o) => {
          const actif = o.id === choisi;
          return (
            <Pressable
              key={o.id}
              accessibilityRole="button"
              // 🚨 Sans ce libellé, un lecteur d'écran annonce « bouton », sans
              // dire lequel. Trouvé le 20/08 en lisant l'arbre de l'écran de
              // création : neuf boutons anonymes d'affilée. Le défaut était dans
              // ce composant depuis le début, donc il valait aussi pour le choix
              // de l'élève et du niveau au rangement, c'est-à-dire pour les deux
              // gestes les plus fréquents de l'app.
              accessibilityLabel={etiquette ? `${etiquette} ${o.libelle}` : o.libelle}
              accessibilityState={{ selected: actif }}
              onPress={() => onChoisir(actif ? null : o.id)}
              style={[styles.pastille, actif && styles.pastilleActive]}>
              <Text style={[styles.textePastille, actif && styles.textePastilleActive]}>
                {o.libelle}
              </Text>
            </Pressable>
          );
        })}
      </View>
    </View>
  );
}

/** Message d'erreur. Jamais un aplat rouge : on informe, on ne punit pas. */
export function Alerte({ message }: { message: string }) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <View style={styles.alerte}>
      <Text style={styles.texteAlerte}>{message}</Text>
    </View>
  );
}

