import * as ImagePicker from 'expo-image-picker';

import { supabase } from './supabase';

/**
 * Les pièces jointes d'une observation : photo d'un cahier, d'une trace, ou
 * capture audio. Tout vit dans un seau privé Supabase, jamais en public.
 *
 * 🔐 Le contrat de sécurité tient à UNE règle : le chemin de stockage commence
 * TOUJOURS par l'uid de la session. La protection par ligne du seau refuse tout
 * fichier dont le premier segment n'est pas `auth.uid()`. On ne fabrique donc
 * jamais un chemin sans passer par `uidSession()` juste avant l'upload, pour ne
 * pas risquer d'écrire sous l'identité d'une autre personne.
 *
 * On reprend la logique de l'app héritée (`useCapture.tsx`), en l'améliorant sur
 * quatre points :
 *  - les permissions sont demandées explicitement, avec un message clair plutôt
 *    qu'un échec muet ;
 *  - le type de média suit le nouveau contrat (`photo` | `audio`), pas l'ancien
 *    `image` ;
 *  - l'upload passe par un `ArrayBuffer` et non un `Blob`, parce que le `Blob`
 *    remonte parfois à zéro octet sur React Native (même piège que la dictée) ;
 *  - le nom de fichier porte un horodatage, donc joindre une deuxième photo à la
 *    même observation n'écrase plus la première.
 */

const SEAU = 'observation-media';

/** Une image choisie localement, pas encore envoyée. */
export type ImageChoisie = {
  /** URI locale du fichier, utilisable directement dans `expo-image`. */
  uri: string;
  largeur: number;
  hauteur: number;
  /** Type MIME si le picker a su le déterminer, ex. `image/jpeg`. */
  mime: string | null;
  /** Taille en octets quand elle est connue, pour d'éventuels garde-fous. */
  tailleOctets: number | null;
};

/** Un enregistrement audio local, prêt à être joint. */
export type AudioChoisi = {
  uri: string;
  mime: string | null;
  /** Durée en secondes, arrondie. Stockée telle quelle dans `duration_seconds`. */
  dureeSecondes: number | null;
};

/** Une ligne de la table `observation_media`, traduite côté app. */
export type ObservationMedia = {
  id: string;
  observationId: string;
  type: 'photo' | 'audio';
  /** Chemin dans le seau, ex. `uid/observation/photo-1234.jpg`. Sert à signer et à supprimer. */
  cheminStockage: string;
  dureeSecondes: number | null;
  creeLe: string;
};

/**
 * L'uid de la session, ou une erreur claire s'il n'y en a pas.
 *
 * On le relit à chaque upload plutôt que de le recevoir en paramètre : c'est la
 * seule source qui ne peut pas mentir, et c'est exactement ce que la protection
 * par ligne vérifiera. Un appelant qui passerait un mauvais uid ne pourrait de
 * toute façon rien écrire.
 */
async function uidSession(): Promise<string> {
  const { data, error } = await supabase.auth.getUser();
  if (error) throw error;
  const uid = data.user?.id;
  if (!uid) {
    throw new Error("Tu n'es plus connecté·e : reconnecte-toi pour joindre un média.");
  }
  return uid;
}

/**
 * Devine l'extension de fichier depuis le MIME ou l'URI.
 *
 * Le chemin de stockage n'a pas besoin d'une extension exacte, mais une
 * extension juste aide les visionneuses et le CDN à choisir le bon type.
 */
function extensionDe(mime: string | null, uri: string, defaut: string): string {
  const parMime: Record<string, string> = {
    'image/jpeg': 'jpg',
    'image/jpg': 'jpg',
    'image/png': 'png',
    'image/webp': 'webp',
    'image/heic': 'heic',
    'audio/m4a': 'm4a',
    'audio/x-m4a': 'm4a',
    'audio/mp4': 'm4a',
    'audio/mpeg': 'mp3',
    'audio/webm': 'webm',
    'audio/wav': 'wav',
  };
  if (mime && parMime[mime]) return parMime[mime];
  // Repli sur l'URI : `.../IMG_0001.HEIC?truc` -> `heic`.
  const propre = uri.split('?')[0];
  const point = propre.lastIndexOf('.');
  if (point !== -1 && point > propre.lastIndexOf('/')) {
    const ext = propre.slice(point + 1).toLowerCase();
    if (ext && ext.length <= 5) return ext;
  }
  return defaut;
}

/** Normalise un asset de picker en `ImageChoisie`, ou null si rien d'exploitable. */
function versImageChoisie(resultat: ImagePicker.ImagePickerResult): ImageChoisie | null {
  if (resultat.canceled) return null;
  const asset = resultat.assets?.[0];
  if (!asset?.uri) return null;
  return {
    uri: asset.uri,
    largeur: asset.width ?? 0,
    hauteur: asset.height ?? 0,
    mime: asset.mimeType ?? null,
    tailleOctets: asset.fileSize ?? null,
  };
}

/**
 * Ouvre la galerie et renvoie l'image choisie, ou null si on annule.
 *
 * On demande la permission d'abord : refusée, on lève une erreur lisible plutôt
 * que d'ouvrir une galerie vide qui laisserait croire à un bug.
 *
 * `quality: 0.6` est notre compression : une photo de cahier n'a pas besoin du
 * plein format, et diviser le poids accélère l'envoi sur un réseau d'école.
 * Faute d'`expo-image-manipulator` dans le projet, on ne redimensionne pas les
 * pixels ; la qualité JPEG suffit à un usage de trace de classe.
 */
export async function choisirPhoto(): Promise<ImageChoisie | null> {
  const permission = await ImagePicker.requestMediaLibraryPermissionsAsync();
  if (!permission.granted) {
    throw new Error(
      "Educooo n'a pas accès à tes photos. Autorise l'accès dans les réglages pour en joindre une.",
    );
  }
  const resultat = await ImagePicker.launchImageLibraryAsync({
    mediaTypes: ['images'],
    quality: 0.6,
    allowsMultipleSelection: false,
    exif: false,
  });
  return versImageChoisie(resultat);
}

/**
 * Ouvre la caméra et renvoie la photo prise, ou null si on annule.
 * Même contrat que `choisirPhoto`, avec la permission caméra.
 */
export async function prendrePhoto(): Promise<ImageChoisie | null> {
  const permission = await ImagePicker.requestCameraPermissionsAsync();
  if (!permission.granted) {
    throw new Error(
      "Educooo n'a pas accès à la caméra. Autorise l'accès dans les réglages pour prendre une photo.",
    );
  }
  const resultat = await ImagePicker.launchCameraAsync({
    mediaTypes: ['images'],
    quality: 0.6,
    exif: false,
  });
  return versImageChoisie(resultat);
}

/**
 * Lit un fichier local en `ArrayBuffer`.
 *
 * 🚨 On n'envoie PAS un `Blob` : sur React Native il remonte régulièrement à
 * zéro octet et l'upload « réussit » en écrivant un fichier vide. L'`ArrayBuffer`
 * obtenu par `fetch` est la voie recommandée par Supabase pour Expo, et c'est la
 * même leçon que la dictée a payée le 20/08.
 */
async function lireFichier(uri: string): Promise<ArrayBuffer> {
  const reponse = await fetch(uri);
  const donnees = await reponse.arrayBuffer();
  if (!donnees.byteLength) {
    throw new Error("Le fichier est vide : rien n'a été joint.");
  }
  return donnees;
}

/** Traduit une ligne brute de `observation_media` vers notre type. */
function versObservationMedia(ligne: {
  id: string;
  observation_id: string;
  media_type: string;
  storage_path: string;
  duration_seconds: number | null;
  created_at: string;
}): ObservationMedia {
  return {
    id: ligne.id,
    observationId: ligne.observation_id,
    type: ligne.media_type === 'audio' ? 'audio' : 'photo',
    cheminStockage: ligne.storage_path,
    dureeSecondes: ligne.duration_seconds,
    creeLe: ligne.created_at,
  };
}

const COLONNES = 'id, observation_id, media_type, storage_path, duration_seconds, created_at';

/**
 * Joint une photo à une observation : upload dans le seau puis ligne en base.
 *
 * L'ordre compte. On uploade le fichier d'abord ; si l'écriture de la ligne
 * échoue ensuite, on retire le fichier orphelin pour ne pas laisser de déchet
 * dans le seau. L'inverse laisserait une ligne qui pointe vers rien.
 */
export async function joindrePhoto(
  observationId: string,
  image: ImageChoisie,
): Promise<ObservationMedia> {
  const uid = await uidSession();
  const ext = extensionDe(image.mime, image.uri, 'jpg');
  const chemin = `${uid}/${observationId}/photo-${Date.now()}.${ext}`;

  const donnees = await lireFichier(image.uri);
  const { error: erreurUpload } = await supabase.storage
    .from(SEAU)
    .upload(chemin, donnees, { contentType: image.mime ?? 'image/jpeg', upsert: false });
  if (erreurUpload) throw erreurUpload;

  const { data, error } = await supabase
    .from('observation_media')
    .insert({ observation_id: observationId, media_type: 'photo', storage_path: chemin })
    .select(COLONNES)
    .single();
  if (error) {
    // La ligne n'a pas pu être écrite : on ne garde pas un fichier fantôme.
    await supabase.storage
      .from(SEAU)
      .remove([chemin])
      .catch(() => {});
    throw error;
  }
  return versObservationMedia(data);
}

/**
 * Joint une capture audio à une observation.
 *
 * Le pendant audio de `joindrePhoto`, présent parce que le contrat backend porte
 * `media_type = 'audio'` et une colonne `duration_seconds` : la file de médias
 * serait bancale si l'app ne savait joindre que des photos.
 */
export async function joindreAudio(
  observationId: string,
  audio: AudioChoisi,
): Promise<ObservationMedia> {
  const uid = await uidSession();
  const ext = extensionDe(audio.mime, audio.uri, 'm4a');
  const chemin = `${uid}/${observationId}/audio-${Date.now()}.${ext}`;

  const donnees = await lireFichier(audio.uri);
  const { error: erreurUpload } = await supabase.storage
    .from(SEAU)
    .upload(chemin, donnees, { contentType: audio.mime ?? 'audio/m4a', upsert: false });
  if (erreurUpload) throw erreurUpload;

  const { data, error } = await supabase
    .from('observation_media')
    .insert({
      observation_id: observationId,
      media_type: 'audio',
      storage_path: chemin,
      duration_seconds: audio.dureeSecondes ?? null,
    })
    .select(COLONNES)
    .single();
  if (error) {
    await supabase.storage
      .from(SEAU)
      .remove([chemin])
      .catch(() => {});
    throw error;
  }
  return versObservationMedia(data);
}

/**
 * Les médias d'une observation, chacun avec une URL signée prête à afficher.
 *
 * Le seau est privé : une URL de stockage seule ne s'affiche pas, il faut une
 * URL signée à durée limitée. On signe à la lecture plutôt que de stocker une
 * URL, parce qu'une URL signée expire et qu'une URL périmée en base serait un
 * lien mort.
 *
 * Un média dont la signature échoue est ignoré plutôt que de faire tomber toute
 * la liste : mieux vaut afficher trois photos sur quatre qu'un écran d'erreur.
 */
export async function listerMedias(
  observationId: string,
  dureeSignatureSecondes = 3600,
): Promise<(ObservationMedia & { url: string })[]> {
  const { data, error } = await supabase
    .from('observation_media')
    .select(COLONNES)
    .eq('observation_id', observationId)
    .order('created_at', { ascending: true });
  if (error) throw error;

  const medias = (data ?? []).map(versObservationMedia);
  const signes = await Promise.all(
    medias.map(async (media) => {
      const { data: signe } = await supabase.storage
        .from(SEAU)
        .createSignedUrl(media.cheminStockage, dureeSignatureSecondes);
      const url = signe?.signedUrl;
      return url ? { ...media, url } : null;
    }),
  );
  return signes.filter((m): m is ObservationMedia & { url: string } => m !== null);
}

/**
 * Retire un média : le fichier du seau ET la ligne en base.
 *
 * On supprime le fichier d'abord. Si la suppression du fichier échoue, on
 * n'efface pas la ligne : une ligne sans fichier est réparable (on saura quel
 * fichier retirer), un fichier sans ligne est un déchet invisible qu'on ne
 * retrouvera jamais.
 */
export async function retirerMedia(media: ObservationMedia): Promise<void> {
  const { error: erreurFichier } = await supabase.storage.from(SEAU).remove([media.cheminStockage]);
  if (erreurFichier) throw erreurFichier;

  const { error } = await supabase.from('observation_media').delete().eq('id', media.id);
  if (error) throw error;
}
