import Constants from 'expo-constants';
import { Platform } from 'react-native';

type Extra = {
  supabaseUrl?: string;
  supabasePublishableKey?: string;
  revenueCatIosKey?: string;
  revenueCatAndroidKey?: string;
  revenueCatTestKey?: string;
};
const extra = (Constants.expoConfig?.extra ?? {}) as Extra;

/**
 * On échoue bruyamment plutôt que de démarrer sur une base vide ou, pire,
 * sur la mauvaise base. Le lancement passe par Doppler :
 *   doppler run --project gsv06-educooo --config dev -- npx expo start
 */
function requis(valeur: string | undefined, nom: string): string {
  if (!valeur) {
    throw new Error(
      `${nom} est absent. Lance l'app via Doppler : doppler run --project gsv06-educooo --config dev -- npx expo start`,
    );
  }
  return valeur;
}

/**
 * La clé RevenueCat à utiliser au lancement.
 *
 * En développement on préfère le Test Store (`test_`) : c'est là que vit le
 * produit `yearly` aujourd'hui, donc c'est la seule clé avec laquelle un achat
 * est réellement testable sans passer par l'App Store ou le Play Store. En
 * build de release (`__DEV__` faux) on prend la clé publique de la plateforme
 * (appl_ pour iOS, goog_ pour Android) et le Test Store sert de dernier repli.
 *
 * Contrairement à Supabase, on n'échoue PAS si elle manque : l'abonnement est
 * optionnel au fonctionnement de l'app, donc le fournisseur reste simplement
 * inerte et l'app tourne sans lui.
 */
const cleePlateforme = Platform.OS === 'ios' ? extra.revenueCatIosKey : extra.revenueCatAndroidKey;
// Sur le web, le SDK RevenueCat tourne en « Browser Mode » et REFUSE les clés
// natives (appl_/goog_) : `Purchases.configure` y lève « Invalid API key » de
// façon non rattrapée, ce qui fait planter tout l'écran (page blanche). Comme on
// ne vend pas via le web (pas de Web Billing), on laisse RevenueCat totalement
// inerte hors natif : sans clé, le fournisseur se déclare « prêt » sans se
// configurer, et l'accès premium repose sur la seule grâce « mois offert ».
const cleRevenueCat =
  Platform.OS === 'web'
    ? undefined
    : __DEV__
      ? (extra.revenueCatTestKey ?? cleePlateforme)
      : (cleePlateforme ?? extra.revenueCatTestKey);

export const env = {
  supabaseUrl: requis(extra.supabaseUrl, 'EXPO_PUBLIC_SUPABASE_URL'),
  supabasePublishableKey: requis(extra.supabasePublishableKey, 'EXPO_PUBLIC_SUPABASE_PUBLISHABLE_KEY'),
  /** Peut être absente : dans ce cas l'abonnement est simplement désactivé. */
  revenueCatKey: cleRevenueCat,
};
