import { Feather } from '@expo/vector-icons';
import { useMemo, useState } from 'react';
import { Modal, Pressable, StyleSheet, Text, View } from 'react-native';

import { t } from '@/i18n';
import { localeDate } from '@/lib/dates';
import { decalerISO, jourDeISO, lundiDeISO } from '@/lib/donnees';
import { espace, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * Le choix des jours, en MENU DÉROULANT plutôt qu'en bande de boutons (retour
 * Valentin 30/08 : la bande accumulait les boutons et devenait illisible). Une
 * puce compacte montre ce qui est choisi (« 3 jours », ou le jour, ou une
 * invite) et ouvre une feuille où chaque jour se coche. On peut en cocher
 * plusieurs : la leçon se pose sur chacun, au même moment.
 *
 * La feuille est un VRAI CALENDRIER mensuel (retour Sophie 18/09 : la liste des
 * 21 prochains jours empêchait de planifier le passé et le lointain). Mois par
 * mois, sans borne, passé comme futur ; seules les colonnes lundi→vendredi, la
 * semaine type n'ayant que cinq jours. `unique` : un seul jour (écran Modifier),
 * la feuille se ferme au choix.
 */
export function SelecteurJoursMenu({
  choisis,
  onBasculer,
  unique = false,
}: {
  /** Les dates cochées (ISO). */
  choisis: string[];
  /** Coche ou décoche une date (en `unique`, la choisit). */
  onBasculer: (dateISO: string) => void;
  unique?: boolean;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const [ouvert, setOuvert] = useState(false);
  // Le mois affiché, par son 1er jour ISO. S'ouvre sur le premier jour choisi,
  // sinon sur le mois courant.
  const [mois, setMois] = useState(() => premierDuMois(choisis[0] ?? aujourdhui()));
  const semaines = useMemo(() => semainesDuMois(mois), [mois]);
  const ajd = aujourdhui();

  function ouvrir() {
    setMois(premierDuMois(choisis[0] ?? aujourdhui()));
    setOuvert(true);
  }
  function toucher(d: string) {
    onBasculer(d);
    if (unique) setOuvert(false);
  }

  const resume =
    choisis.length === 0
      ? t.activite.joursMenuVide
      : choisis.length === 1
        ? dateLongue(choisis[0])
        : t.activite.joursMenuCompte(choisis.length);

  return (
    <>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel={`${t.activite.joursMenuTitre}, ${resume}`}
        onPress={ouvrir}
        style={styles.puce}>
        <Feather name="calendar" size={16} color={c.encreDouce} />
        <Text style={styles.puceTexte} numberOfLines={1}>
          {resume}
        </Text>
        <Feather name="chevron-down" size={16} color={c.encre} />
      </Pressable>

      <Modal visible={ouvert} transparent animationType="fade" onRequestClose={() => setOuvert(false)}>
        <Pressable style={styles.voile} onPress={() => setOuvert(false)}>
          <Pressable style={styles.feuille} onPress={() => {}}>
            <View style={styles.tete}>
              <Text style={styles.titre}>{unique ? t.activite.jourMenuTitre : t.activite.joursMenuTitre}</Text>
              <Pressable
                accessibilityRole="button"
                accessibilityLabel={t.activite.joursMenuFermer}
                onPress={() => setOuvert(false)}
                style={styles.fermer}>
                <Feather name="check" size={18} color={c.action[1]} />
              </Pressable>
            </View>
            {/* Navigation de mois, sans borne. */}
            <View style={styles.navMois}>
              <Pressable
                accessibilityRole="button"
                accessibilityLabel={t.activite.moisPrecedent}
                hitSlop={8}
                onPress={() => setMois(decalerMois(mois, -1))}
                style={styles.fleche}>
                <Feather name="chevron-left" size={20} color={c.encre} />
              </Pressable>
              <Text style={styles.moisTitre}>{titreMois(mois)}</Text>
              <Pressable
                accessibilityRole="button"
                accessibilityLabel={t.activite.moisSuivant}
                hitSlop={8}
                onPress={() => setMois(decalerMois(mois, 1))}
                style={styles.fleche}>
                <Feather name="chevron-right" size={20} color={c.encre} />
              </Pressable>
            </View>
            {mois !== premierDuMois(ajd) ? (
              <Pressable onPress={() => setMois(premierDuMois(ajd))} style={styles.retourAjd}>
                <Text style={styles.retourAjdTexte}>{t.activite.aujourdhui}</Text>
              </Pressable>
            ) : null}

            <View style={styles.rangee}>
              {t.semaine.jours.slice(0, 5).map((j) => (
                <Text key={j} style={styles.entetJour}>
                  {j.slice(0, 3)}
                </Text>
              ))}
            </View>
            {semaines.map((semaine) => (
              <View key={semaine[0]} style={styles.rangee}>
                {semaine.map((d) => {
                  const actif = choisis.includes(d);
                  const horsMois = d.slice(0, 7) !== mois.slice(0, 7);
                  const estAjd = d === ajd;
                  return (
                    <Pressable
                      key={d}
                      accessibilityRole={unique ? 'button' : 'checkbox'}
                      accessibilityState={unique ? { selected: actif } : { checked: actif }}
                      accessibilityLabel={dateLongue(d)}
                      onPress={() => toucher(d)}
                      style={[styles.cellule, estAjd && styles.celluleAjd, actif && styles.celluleActive]}>
                      <Text
                        style={[
                          styles.celluleTexte,
                          horsMois && styles.celluleHorsMois,
                          actif && styles.celluleTexteActif,
                        ]}>
                        {parseInt(d.slice(8, 10), 10)}
                      </Text>
                    </Pressable>
                  );
                })}
              </View>
            ))}
            {!unique && choisis.length ? (
              <Text style={styles.compte}>{t.activite.joursMenuCompte(choisis.length)}</Text>
            ) : null}
          </Pressable>
        </Pressable>
      </Modal>
    </>
  );
}

/** Aujourd'hui en ISO local. */
function aujourdhui(): string {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

/** Le 1er du mois d'une date ISO. */
function premierDuMois(iso: string): string {
  return `${iso.slice(0, 7)}-01`;
}

/** Le 1er du mois décalé de `n` mois. */
function decalerMois(premier: string, n: number): string {
  const [a, m] = premier.split('-').map((x) => parseInt(x, 10));
  const d = new Date(a, m - 1 + n, 1);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-01`;
}

/** « Septembre 2026 ». */
function titreMois(premier: string): string {
  const [a, m] = premier.split('-').map((x) => parseInt(x, 10));
  const txt = new Date(a, m - 1, 1).toLocaleDateString(localeDate(), { month: 'long', year: 'numeric' });
  return txt.charAt(0).toUpperCase() + txt.slice(1);
}

/** Les semaines (lundi→vendredi, en ISO) qui touchent un mois ouvrable. */
function semainesDuMois(premier: string): string[][] {
  const moisCle = premier.slice(0, 7);
  const out: string[][] = [];
  let lundi = lundiDeISO(premier);
  for (let i = 0; i < 6; i++) {
    const semaine = [0, 1, 2, 3, 4].map((k) => decalerISO(lundi, k));
    if (semaine.some((d) => d.slice(0, 7) === moisCle)) out.push(semaine);
    else if (out.length) break;
    lundi = decalerISO(lundi, 7);
  }
  return out;
}

/** « Jeudi 4 septembre ». Nom du jour via i18n (fiable partout), jour+mois via la locale. */
function dateLongue(iso: string): string {
  const jour = t.semaine.jours[jourDeISO(iso) - 1] ?? '';
  const [a, m, j] = iso.split('-').map((n) => parseInt(n, 10));
  const dm = new Date(a, m - 1, j).toLocaleDateString(localeDate(), {
    day: 'numeric',
    month: 'long',
  });
  return `${jour} ${dm}`.trim();
}

