/**
 * Le choix d'un type d'apprentissage : des PASTILLES DE TEXTE À POINT COLORÉ,
 * volontairement de forme DISTINCTE d'une tuile de moment (la couleur code
 * ailleurs le moment de la journée). Le point porte la couleur du type, le
 * libellé vient de la table (`ref_learning_types`), et le type suggéré porte une
 * mention discrète tant qu'il n'est pas choisi.
 */
function ChoixType({
  types,
  choisi,
  onChoisir,
  suggere,
}: {
  types: TypeApprentissage[];
  choisi: string | null;
  onChoisir: (code: string | null) => void;
  suggere?: string | null;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  if (!types.length) return null;
  return (
    <View style={styles.typesRangee}>
      {types.map((type) => {
        const actif = type.code === choisi;
        const libelle = langue === 'nl' ? type.labelNl ?? type.labelFr : type.labelFr;
        const estSuggere = !actif && suggere === type.code;
        return (
          <Pressable
            key={type.code}
            accessibilityRole="button"
            accessibilityState={{ selected: actif }}
            accessibilityLabel={`${SEQ.typeEtape} ${libelle}${estSuggere ? ` (${SEQ.suggere})` : ''}`}
            onPress={() => onChoisir(actif ? null : type.code)}
            style={[styles.typePastille, actif && styles.typePastilleActive]}>
            <View style={[styles.typePoint, { backgroundColor: couleurDeToken(c, type.colorToken) }]} />
            <Text style={[styles.typeTexte, actif && styles.typeTexteActif]} numberOfLines={1}>
              {libelle}
            </Text>
            {estSuggere ? <Text style={styles.typeSuggere}>{SEQ.suggere}</Text> : null}
          </Pressable>
        );
      })}
    </View>
  );
}

function isoDuJour(decalage = 0): string {
  const d = new Date();
  d.setHours(12, 0, 0, 0);
  d.setDate(d.getDate() + decalage);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

/**
 * Le moment à présélectionner à l'arrivée des créneaux, ou null s'il n'y a rien
 * à proposer. Hors du composant parce que « le moment courant » lit l'horloge.
 */
function momentAProposer(
  creneaux: Creneau[],
  creneauParam: string | undefined,
  choixDate: string,
  quand: string | null,
): string | null {
  // Arrivée depuis une case précise du semainier : on présélectionne SON moment.
  if (creneauParam) {
    const c = creneaux.find((k) => k.id === creneauParam);
    if (c) return cleMoment(c);
  }
  // Sinon, sur « aujourd'hui », on propose le moment courant de la journée.
  if (choixDate !== 'aujourdhui' || !quand) return null;
  const c = creneauCourant(creneaux);
  return c ? cleMoment(c) : null;
}

/** 1 = lundi, comme `week_template_slots.day_of_week`. */
function jourIso(dateIso: string): number {
  const [a, m, j] = dateIso.split('-').map((n) => parseInt(n, 10));
  const jour = new Date(a, m - 1, j).getDay();
  return jour === 0 ? 7 : jour;
}

export default function NouvelleActivite() {
  // Arrivée depuis une compétence de l'accueil : ses attendus sont préchargés.
  // C'est le sens que l'inspection demande, partir de la compétence.
  const couleurs = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(couleurs), [couleurs]);
  // On peut aussi arriver depuis le journal, sur un moment précis d'un jour :
  // la date et le créneau sont alors préremplis, pour que « ajouter ici » pose
  // vraiment l'activité à cet endroit-là de la semaine.
  const {
    competence,
    nom,
    date: dateParam,
    creneau: creneauParam,
    titre: titreParam,
    sansCompetences: sansCompetencesParam,
    reprise: repriseParam,
  } = useLocalSearchParams<{
    competence?: string;
    nom?: string;
    date?: string;
    creneau?: string;
    /** Titre prérempli, quand on arrive depuis le catalogue de types. */
    titre?: string;
    /** '1' quand on arrive du catalogue « Reprendre une leçon existante » : on
     *  ouvre directement la bibliothèque de leçons déjà produites. */
    reprise?: string;
    /**
     * '1' quand le type choisi est logistique (piscine, sortie, visite médicale…) :
     * l'activité se crée sans compétences, donc on n'affiche ni ne force la
     * détection d'attendus. Absent = comportement d'origine, inchangé.
     */
    sansCompetences?: string;
  }>();
  // Une activité logistique : la détection d'attendus est coupée, comme pour une
  // sortie. Rétro-compatible : sans le param, tout se comporte comme avant.
  const sansCompetences = sansCompetencesParam === '1';
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;

  // Deux temps avant de créer : on demande d'abord « du neuf ou une reprise ? ».
  // EXCEPTION : arriver avec une compétence (depuis l'accueil) ou une date/un
  // créneau (depuis le journal « ajouter ici ») dit déjà « nouvelle », on saute
  // le choix. Ces parcours ne doivent pas gagner une étape de plus.
  // Arriver depuis le catalogue de types (titre prérempli ou drapeau logistique)
  // dit déjà « nouvelle » : on saute le choix « du neuf ou une reprise », comme
  // pour une compétence ou une date.
  const sauteLeChoix = !!(
    competence ||
    dateParam ||
    creneauParam ||
    titreParam ||
    sansCompetences
  );
  // Arriver avec `reprise=1` (catalogue « Reprendre une leçon existante ») ouvre
  // directement la bibliothèque : on reste donc en mode « choix » (la bibliothèque
  // s'y superpose), même si une date/un créneau sont préremplis.
  const veutReprise = repriseParam === '1';
  const [mode, setMode] = useState<'choix' | 'formulaire'>(
    sauteLeChoix && !veutReprise ? 'formulaire' : 'choix',
  );
  // Le sélecteur « reprendre » s'ouvre par-dessus le choix (mode reste 'choix').
  const [bibliotheque, setBibliotheque] = useState(veutReprise);
  // L'id de l'activité qu'on est en train de charger pour préremplir, pour un
  // court voile d'attente le temps de lire son détail.
  const [chargeBiblio, setChargeBiblio] = useState<string | null>(null);

  const [titre, setTitre] = useState(titreParam ?? '');
  const [description, setDescription] = useState('');
  // On garde le rôle et la justification avec l'attendu, pas seulement son
  // identifiant : depuis le 20/08 ils s'enregistrent, et ce sont eux que
  // l'inspection lit. Un attendu ajouté à la main n'a pas de rôle, et c'est
  // `null`, pas « transversal » : on n'invente pas une donnée non saisie.
  const [choisis, setChoisis] = useState<Retenu[]>([]);
  const [detecte, setDetecte] = useState(false);
  const [chercheManuellement, setChercheManuellement] = useState(false);
  // « Aujourd'hui » est le défaut doux : le cas le plus fréquent est une séance
  // du jour, et la date reste changeable d'un tap (demain, plus tard, pas
  // encore). On présélectionne, on ne verrouille pas.
  const [quand, setQuand] = useState<string | null>(dateParam ?? isoDuJour());
  const [choixDate, setChoixDate] = useState<'aujourdhui' | 'demain' | 'autre' | 'aucune'>(
    !dateParam
      ? 'aujourdhui'
      : dateParam === isoDuJour(0)
        ? 'aujourdhui'
        : dateParam === isoDuJour(1)
          ? 'demain'
          : 'autre',
  );
  // Sélection multi-jours, active uniquement en mode « Une autre date ». Les
  // autres modes (aujourd'hui/demain/pas encore) restent mono via `quand`, et
  // ce tableau reste vide : rien ne change pour eux.
  //
  // 🔴 CORRECTIF : quand on arrive sur une DATE précise qui n'est ni aujourd'hui
  // ni demain (le cas de « ajouter ici » depuis le semainier, sur n'importe quel
  // jour de la semaine), `choixDate` vaut « autre ». Or `jourCourant` se lit dans
  // `joursChoisis[0]` en mode « autre ». S'il reste vide, `jourCourant` est null,
  // le sélecteur de créneau ne s'affiche pas du tout, et le créneau prérempli
  // (celui de la case cliquée) reste figé : impossible d'en choisir un autre.
  // On amorce donc `joursChoisis` avec la date reçue.
  const [joursChoisis, setJoursChoisis] = useState<string[]>(
    dateParam && dateParam !== isoDuJour(0) && dateParam !== isoDuJour(1) ? [dateParam] : [],
  );
  // Le moment choisi n'est PAS un id de créneau (il diffère d'un jour à l'autre)
  // mais la CLÉ d'un couple (début, libellé), résolue par jour à la création.
  // `null` = « sans moment » (leçon datée sans créneau). Voir `cleMoment` /
  // `creneauPourMoment`. En mono-jour, on peut choisir N'IMPORTE quel moment de
  // la semaine : s'il n'existe pas ce jour-là, on crée le créneau à la création.
  const [momentChoisi, setMomentChoisi] = useState<string | null>(null);
  // Une leçon peut S'ÉTENDRE sur les créneaux consécutifs du même jour (une
  // présentation d'accueil qui dure toute la matinée — retour Mahé). On garde ici
  // les clés des moments qui SUIVENT le moment choisi et que la leçon couvre
  // aussi. À la création, on pose une copie sur chacun (mono-jour uniquement).
  const [creneauxEtendus, setCreneauxEtendus] = useState<string[]>([]);
  const [semaines, setSemaines] = useState(1);
  const [details, setDetails] = useState(false);
  const [objectif, setObjectif] = useState('');
  const [materiel, setMateriel] = useState('');
  // La photo de la prépa scannée : on la garde pour la joindre à la leçon créée
  // comme témoin (retour Sophie : « garder la photo quand on scanne la prépa »).
  // Le PDF ne s'y range pas : les traces d'une leçon sont des images.
  const [photosPrepa, setPhotosPrepa] = useState<ImageChoisie[]>([]);
  // La recherche du sélecteur « Reprendre » : tenue ici pour la garder dans un
  // en-tête FIXE (retour Valentin : la barre de recherche doit rester sous la
  // main quand on parcourt la liste), pendant que BibliothequeListe défile.
  const [rechercheBiblio, setRechercheBiblio] = useState('');
  const [organisation, setOrganisation] = useState('');
  const [lieu, setLieu] = useState('');
  const [duree, setDuree] = useState('');
  const [groupement, setGroupement] = useState<string | null>(null);
  // Le canal d'enseignement. Rien de coché d'avance : c'est une question douce,
  // pas une case obligatoire. On ne l'impose jamais depuis la création.
  const [canal, setCanal] = useState<Canal | null>(null);
  // Mode SÉQUENCE (leçon primaire en plusieurs étapes) vs séance unique (défaut,
  // et le seul comportement proposé à la maternelle). Additif : hors séquence,
  // tout se comporte exactement comme avant.
  const [sequenceMode, setSequenceMode] = useState(false);
  // Le type (niveau Bloom) de l'étape 1 = la tête. Pré-suggéré depuis le titre,
  // toujours défaisable. `type1Manuel` gèle la suggestion dès un choix manuel.
  const [typeEtape1, setTypeEtape1] = useState<string | null>(null);
  const type1Manuel = useRef(false);
  // Les étapes 2..N de la séquence (l'étape 1, c'est le titre de la leçon).
  const [etapesSuite, setEtapesSuite] = useState<EtapeEdition[]>([]);
  const [occupe, setOccupe] = useState(false);
  // Le temps que le modèle lit une préparation importée. On verrouille les
  // champs pendant ce temps : ils vont être réécrits, et laisser taper par-dessus
  // donnerait l'impression que la saisie a été perdue.
  const [analyse, setAnalyse] = useState(false);
  // Vrai dès qu'une préparation a prérempli le formulaire : l'activité créée
  // portera alors l'origine « importée » plutôt que « créée à la main ». Le
  // drapeau ne retombe pas si l'enseignante retouche ensuite les champs : elle
  // corrige un import, elle ne repart pas de zéro.
  const [importee, setImportee] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);

  // Le filet de frappe : la leçon en cours s'écrit sur l'appareil, et une leçon
  // commencée puis perdue (app fermée, retour arrière) se reprend à la
  // réouverture (retour Sophie 24/09). Proposé seulement sur un formulaire vierge.
  const [brouillon, setBrouillon] = useState<BrouillonLecon | null>(null);
  const brouillonLu = useRef(false);
  useEffect(() => {
    if (!classeId || brouillonLu.current) return;
    brouillonLu.current = true;
    if (titreParam || veutReprise) return;
    void lireBrouillonLecon(classeId).then((b) => setBrouillon(b));
  }, [classeId, titreParam, veutReprise]);
  useEffect(() => {
    if (!classeId || brouillon) return;
    if (!titre.trim() && !description.trim()) return;
    const minuteur = setTimeout(() => {
      void ecrireBrouillonLecon(classeId, {
        titre,
        description,
        objectif,
        materiel,
        organisation,
        lieu,
        duree,
        groupement,
        canal,
        modifie: new Date().toISOString(),
      });
    }, 800);
    return () => clearTimeout(minuteur);
  }, [classeId, brouillon, titre, description, objectif, materiel, organisation, lieu, duree, groupement, canal]);
  function reprendreBrouillon() {
    if (!brouillon) return;
    setTitre(brouillon.titre);
    setDescription(brouillon.description);
    setObjectif(brouillon.objectif);
    setMateriel(brouillon.materiel);
    setOrganisation(brouillon.organisation);
    setLieu(brouillon.lieu);
    setDuree(brouillon.duree);
    setGroupement(brouillon.groupement);
    setCanal(brouillon.canal as Canal | null);
    if (brouillon.objectif || brouillon.materiel || brouillon.organisation || brouillon.lieu || brouillon.duree) {
      setDetails(true);
    }
    setBrouillon(null);
  }
  function jeterBrouillon() {
    if (classeId) void effacerBrouillonLecon(classeId);
    setBrouillon(null);
  }

  const eleves = useRequete(() => elevesDe(classeId!), [classeId], { actif: !!classeId });
  const creneaux = useRequete(() => creneauxDe(classeId!), [classeId], { actif: !!classeId });
  // Mémoire de contexte : le dernier groupement et le dernier lieu utilisés
  // dans la classe. Proposés à l'ouverture des détails, jamais imposés.
  const contexte = useRequete(() => dernierContexteActivite(classeId!), [classeId], {
    actif: !!classeId,
  });
  // La taxonomie des types d'apprentissage (Bloom + évaluations), lue une fois.
  // Repli embarqué si la table n'est pas là : le sélecteur marche toujours.
  const typesApp = useRequete(() => lireTypesApprentissage(), []);
  const listeTypes = typesApp.donnees ?? [];

  // Présélection douce du moment courant. Une seule fois, au chargement des
  // créneaux : si l'heure tombe dans un créneau de la semaine type et que la
  // date est restée sur « aujourd'hui », on propose ce créneau. Le geste reste
  // défaisable d'un tap, et changer de date le remet à zéro (plus bas).
  // Appliquée au rendu où les créneaux arrivent ; le drapeau en état garantit
  // qu'on ne la rejoue jamais.
  const [momentPropose, setMomentPropose] = useState(false);
  if (!momentPropose && creneaux.donnees) {
    setMomentPropose(true);
    const propose = momentAProposer(creneaux.donnees, creneauParam, choixDate, quand);
    if (propose) setMomentChoisi(propose);
  }

  // Mémoire du groupement et du lieu, appliquée une seule fois quand elle
  // arrive et seulement si l'enseignante n'a encore rien saisi. Ce sont des
  // données logistiques, pas un jugement : les reproposer d'une séance à l'autre
  // fait gagner du temps sans rien décider à sa place, et tout reste modifiable.
  // Même schéma que le moment : au rendu où elle arrive, une seule fois.
  const [contextePropose, setContextePropose] = useState(false);
  if (!contextePropose && contexte.donnees) {
    setContextePropose(true);
    const { groupement: dernierGroupement, lieu: dernierLieu } = contexte.donnees;
    if (dernierGroupement && (GROUPEMENTS as readonly string[]).includes(dernierGroupement)) {
      setGroupement((g) => g ?? dernierGroupement);
    }
    if (dernierLieu) setLieu((l) => l || dernierLieu);
  }

  // Pré-suggestion du niveau Bloom de l'étape 1 depuis le titre, en mode
  // séquence, tant que la prof n'a pas choisi elle-même. Défaisable : dès un
  // choix manuel, `type1Manuel` gèle la suggestion.
  useEffect(() => {
    if (!sequenceMode || type1Manuel.current) return;
    setTypeEtape1(niveauDepuisTexte(titre));
  }, [titre, sequenceMode]);

  /** Ajoute une étape vide à la suite de la séquence. */
  function ajouterEtape() {
    setEtapesSuite((liste) => [...liste, { titre: '', type: null, manuel: false }]);
  }
  /** Retire une étape de la suite. */
  function retirerEtape(index: number) {
    setEtapesSuite((liste) => liste.filter((_, i) => i !== index));
  }
  /** Change le titre d'une étape, et re-suggère son type tant qu'il est auto. */
  function changerTitreEtape(index: number, titreEtape: string) {
    setEtapesSuite((liste) =>
      liste.map((e, i) =>
        i === index
          ? { ...e, titre: titreEtape, type: e.manuel ? e.type : niveauDepuisTexte(titreEtape) }
          : e,
      ),
    );
  }
  /** Fixe le type d'une étape à la main : on ne re-suggère plus pour elle. */
  function changerTypeEtape(index: number, code: string | null) {
    setEtapesSuite((liste) =>
      liste.map((e, i) => (i === index ? { ...e, type: code, manuel: true } : e)),
    );
  }

  // Les attendus de la compétence d'où l'on vient, cochés d'office : ici
  // l'intention est explicite, et le texte d'aide le dit.
  const depuisCompetence = useRequete(
    () => attendusDeCompetence(competence!),
    [competence],
    { actif: !!competence },
  );
  const prechoisis = depuisCompetence.donnees ?? [];

  // La détection ne part pas toute seule : elle coûte un appel au modèle, et
  // une enseignante qui tape son titre lettre par lettre en déclencherait dix.
  const propositions = useRequete(
    () =>
      detecterAttendus({
        classe: classe!,
        texte: [titre, description].filter(Boolean).join('. '),
        eleves: eleves.donnees ?? [],
      }),
    [classe?.id, detecte],
    { actif: !!classe && detecte && !eleves.chargement },
  );
  // La détection rend deux choses : les attendus, et le matériel déduit du même
  // texte. On isole la liste d'attendus (le reste de l'écran la lit comme avant)
  // et on garde le matériel de côté pour le proposer plus bas.
  const propList = propositions.donnees?.propositions ?? [];
  const materielDetecte = useMemo(
    () => propositions.donnees?.materiel ?? [],
    [propositions.donnees],
  );

  // On préremplit le matériel une seule fois, et seulement s'il est encore vide :
  // la déduction est une aide de départ, jamais un écrasement de ce qu'on a tapé.
  const materielPrerempli = useRef(false);
  useEffect(() => {
    if (materielPrerempli.current || !materielDetecte.length) return;
    materielPrerempli.current = true;
    // Préremplissage unique et gardé : la seule écriture d'état de cet effet.
    setMateriel((m) => (m.trim() ? m : materielDetecte.join('\n')));
  }, [materielDetecte]);

  const retenus = useMemo(() => {
    const table = new Map<string, Retenu>();
    // Les attendus venus d'une compétence n'ont pas de rôle : l'enseignante a
    // désigné la compétence, elle n'a rien dit du rôle qu'elle joue.
    for (const a of prechoisis) {
      table.set(a.id, { attendu: a, role: null, justification: null });
    }
    for (const r of choisis) table.set(r.attendu.id, r);
    return table;
  }, [prechoisis, choisis]);

  // Ce qui partira vraiment : les préchoisis, moins ceux qu'on a décochés.
  const [decoches, setDecoches] = useState<string[]>([]);
  const aRattacher = [...retenus.values()].filter((r) => !decoches.includes(r.attendu.id));
  const attendusIds = aRattacher.map((r) => r.attendu.id);

  function basculer(attendu: Attendu, role: RoleAttendu | null = null, justification = '') {
    if (decoches.includes(attendu.id)) {
      setDecoches((liste) => liste.filter((x) => x !== attendu.id));
      return;
    }
    if (retenus.has(attendu.id)) {
      // Un attendu préchargé se décoche sans disparaître de la liste : le faire
      // disparaître donnerait l'impression d'une suppression définitive.
      if (prechoisis.some((a) => a.id === attendu.id)) {
        setDecoches((liste) => [...liste, attendu.id]);
      } else {
        setChoisis((liste) => liste.filter((r) => r.attendu.id !== attendu.id));
      }
      return;
    }
    setChoisis((liste) => [...liste, { attendu, role, justification: justification || null }]);
  }

  // La bibliothèque de l'enseignant·e : la MÊME que l'onglet « Bibliothèque » du
  // profil (dédupliquée, rangée par domaine), chargée seulement quand le
  // sélecteur de reprise s'ouvre. Réutiliser une leçon de l'an dernier est
  // justement l'usage : `bibliotheque()` inclut les classes archivées.
  const bibli = useRequete(() => chargerBibliotheque(), [], { actif: bibliotheque });

  // Le mode multi-jours n'est actif qu'en « Une autre date » ET dès qu'au moins
  // deux jours sont cochés. Un seul jour se comporte exactement comme avant
  // (récurrence possible, moment choisi par id de créneau).
  const multiJours = choixDate === 'autre' && joursChoisis.length > 1;
  // Le jour de référence pour le mode mono (et pour « autre » à un seul jour) :
  // c'est lui qui pilote les créneaux du jour et la récurrence.
  const jourCourant = choixDate === 'autre' ? joursChoisis[0] ?? null : quand;

  // Tous les moments DISTINCTS de la semaine type (union par clé début+libellé),
  // avec leur horaire, libellé et moment de référence. C'est le vivier du choix
  // LIBRE en mono-jour : on peut poser une leçon sur n'importe quel moment de la
  // semaine, même absent du jour visé (il sera créé pour ce jour à la création).
  // Un moment par HEURE de début (`momentsParHeure`) : plus de doublons quasi
  // identiques d'un jour à l'autre (« 08:50 …Absents/présents » et « 08:50
  // …présences/absences »), chaque jour se résout ensuite par clé puis par heure.
  const momentsSemaine = useMemo(() => momentsParHeure(creneaux.donnees ?? []), [creneaux.donnees]);

  // Mono ET multi-jours : choix LIBRE parmi tous les moments de la semaine (UNION).
  // Un jour coché qui n'a pas ce moment le reçoit, créé pour sa semaine à la
  // création. L'ancienne intersection réduisait le choix à 2 moments sur 12 jours
  // et bloquait la création (retour Sophie 22/09 : « on ne peut choisir son moment »).
  // Un seul jour visé : chaque heure porte le nom qu'elle a CE jour-là (« 10:30
  // Regroupement » le mercredi, pas le nom le plus fréquent de la semaine) ; les
  // autres noms passent en discret. Plusieurs jours : le nom le plus fréquent.
  const momentsDispo = useMemo(() => {
    if (multiJours || !jourCourant) return momentsSemaine;
    const jour = jourIso(jourCourant);
    return momentsSemaine.map((m) => {
      const ceJour = (creneaux.donnees ?? []).find((c) => c.jour === jour && c.debut === m.debut);
      if (!ceJour || ceJour.libelle === m.libelle) return m;
      const autres = [m.libelle, ...m.autres].filter((l) => l !== ceJour.libelle);
      return { ...m, cle: cleMoment(ceJour), libelle: ceJour.libelle, fin: ceJour.fin, autres };
    });
  }, [momentsSemaine, multiJours, jourCourant, creneaux.donnees]);

  // Les moments qui SUIVENT le moment choisi le même jour (mono-jour) : ceux
  // qu'une leçon longue peut couvrir en plus. Vide en multi-jours ou sans moment.
  const debutChoisi = momentsSemaine.find((m) => m.cle === momentChoisi)?.debut ?? '';
  const momentsApres =
    !multiJours && momentChoisi ? momentsSemaine.filter((m) => m.debut > debutChoisi) : [];
  const etendusValides = creneauxEtendus.filter((cle) => momentsApres.some((m) => m.cle === cle));

  // La récurrence n'a de sens qu'en mono-jour : en multi, chaque jour compte une
  // fois et le sélecteur disparaît (semaines forcé à 1, voir `toggleJour`).
  // 🔴 Récurrence × séquence hors périmètre v1 : le sélecteur de récurrence
  // disparaît en mode séquence (la suite se planifie étape par étape).
  const recurrenceVisible =
    sequenceMode
      ? false
      : choixDate === 'aucune'
        ? false
        : choixDate === 'autre'
          ? joursChoisis.length === 1
          : !!quand;

  /** Coche ou décoche un jour dans la bande multi. Passer à deux jours force la récurrence à 1. */
  function toggleJour(jour: string) {
    setJoursChoisis((liste) => {
      const prochain = liste.includes(jour)
        ? liste.filter((x) => x !== jour)
        : [...liste, jour];
      if (prochain.length > 1) setSemaines(1);
      return prochain;
    });
  }

  /**
   * Reprend une activité de la bibliothèque : on charge son détail et on
   * préremplit le formulaire d'une NOUVELLE activité (l'ancienne n'est pas
   * touchée). Titre, description, détails, canal et attendus repris tels quels.
   * L'origine reste « manuel » : c'est une création à la main, inspirée d'une
   * autre, pas un import.
   */
  async function reprendre(id: string) {
    setChargeBiblio(id);
    setErreur(null);
    try {
      const detail = await detailActivite(id);
      if (!detail) {
        setErreur(t.activite.bibliothequeRien);
        return;
      }
      setTitre(detail.titre);
      setDescription(detail.description ?? '');
      setObjectif(detail.objectif ?? '');
      setMateriel(detail.materiel ?? '');
      setOrganisation(detail.organisation ?? '');
      setLieu(detail.lieu ?? '');
      setDuree(detail.duree != null ? String(detail.duree) : '');
      setGroupement(detail.groupement ?? null);
      setCanal(detail.canal ?? null);
      setChoisis(
        detail.attendus.map((a) => ({
          attendu: {
            id: a.id,
            code: a.code,
            libelle: a.libelle,
            competence: a.competence,
            domaine: a.domaine,
          },
          role: a.role,
          justification: a.justification,
        })),
      );
      // Si un détail est repris, on ouvre le pli des détails, sinon le
      // préremplissage resterait caché derrière « Plus de détails ».
      if (
        detail.objectif ||
        detail.materiel ||
        detail.organisation ||
        detail.lieu ||
        detail.duree != null ||
        detail.groupement
      ) {
        setDetails(true);
      }
      setBibliotheque(false);
      setMode('formulaire');
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.activite.bibliothequeRien);
    } finally {
      setChargeBiblio(null);
    }
  }

  /**
   * Repart d'un formulaire vierge. Utile quand on choisit « Créer une nouvelle
   * activité » APRÈS avoir repris une activité (revenu au choix entre-temps) :
   * les champs préremplis par la reprise ne doivent pas rester. On ne touche
   * pas à l'ancrage temporel (date/moment), qui garde ses défauts doux.
   */
  function repartirVierge() {
    setTitre('');
    setDescription('');
    setChoisis([]);
    setDecoches([]);
    setDetecte(false);
    setChercheManuellement(false);
    setObjectif('');
    setMateriel('');
    setOrganisation('');
    setLieu('');
    setDuree('');
    setGroupement(null);
    setCanal(null);
    setDetails(false);
    setImportee(false);
    setSequenceMode(false);
    setTypeEtape1(null);
    type1Manuel.current = false;
    setEtapesSuite([]);
    setErreur(null);
  }

  /**
   * Intègre une préparation : on récupère un fichier (photo ou PDF), on le
   * donne au modèle, et on préremplit le formulaire avec ce qu'il en tire.
   *
   * On ne remplit QUE les champs qui reviennent non vides : jamais on n'efface
   * ce que l'enseignante a déjà tapé, et un champ absent de la préparation
   * reste vide. Rien n'est enregistré ici, elle relit et crée elle-même.
   */
  async function integrerDepuis(
    source: () => Promise<{ images?: string[]; pdf?: string } | null>,
  ) {
    setErreur(null);
    let entree: { images?: string[]; pdf?: string } | null;
    try {
      entree = await source();
    } catch (e) {
      // Une permission refusée ou un picker qui casse : message lisible.
      setErreur(e instanceof Error ? e.message : t.activite.prepaErreur);
      return;
    }
    if (!entree) return; // Annulé : rien à faire, pas d'erreur.
    setAnalyse(true);
    try {
      const champs = await analyserPreparation(entree);
      // Une préparation a été lue : l'activité, à la création, sera « importée ».
      setImportee(true);
      if (champs.titre) setTitre(champs.titre);
      if (champs.description) setDescription(champs.description);
      // Dès qu'un champ de détail revient rempli, on ouvre le pli des détails :
      // sinon le préremplissage serait invisible, caché derrière « Plus de
      // détails », et donnerait l'impression que rien ne s'est passé.
      if (
        champs.objectif ||
        champs.materiel ||
        champs.organisation ||
        champs.lieu ||
        champs.duree
      ) {
        setDetails(true);
      }
      if (champs.objectif) setObjectif(champs.objectif);
      if (champs.materiel) setMateriel(champs.materiel);
      if (champs.organisation) setOrganisation(champs.organisation);
      if (champs.lieu) setLieu(champs.lieu);
      if (champs.duree) setDuree(champs.duree.replace(/[^0-9]/g, ''));
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.activite.prepaErreur);
    } finally {
      setAnalyse(false);
    }
  }

  /** Convertit une image choisie en data URI pour le chemin vision. */
  async function imageEnEntree(image: ImageChoisie | null): Promise<{ images: string[] } | null> {
    if (!image) return null;
    const dataUri = await fichierEnDataUri(image.uri, image.mime ?? 'image/jpeg');
    return { images: [dataUri] };
  }

  /**
   * « Une photo » = l'APPAREIL PHOTO, direct (retour Sophie : prendre sa prépa en
   * photo sans détour, le geste rapide). Sur le web, pas d'appareil fiable : on
   * retombe sur le choix de fichier.
   */
  async function photoAppareilEnEntree(): Promise<{ images: string[] } | null> {
    const image = Platform.OS === 'web' ? await choisirPhoto() : await prendrePhoto();
    // On garde l'image d'origine : elle deviendra un témoin de la leçon, pas
    // seulement une source d'extraction. On remplace (un scan à la fois).
    if (image) setPhotosPrepa([image]);
    return imageEnEntree(image);
  }

  /** « Album » = la galerie / les fichiers, pour une photo déjà prise. */
  async function photoAlbumEnEntree(): Promise<{ images: string[] } | null> {
    const image = await choisirPhoto();
    if (image) setPhotosPrepa([image]);
    return imageEnEntree(image);
  }

  /** Un PDF choisi dans les fichiers, converti en data URI. */
  async function pdfEnEntree(): Promise<{ pdf: string } | null> {
    // Chargé À LA DEMANDE, pas en tête de module : `expo-document-picker` a été
    // ajouté après certains builds (Android 1.0.0). Un import statique en tête
    // faisait échouer `requireNativeModule('ExpoDocumentPicker')` au CHARGEMENT
    // de l'écran sur ces vieux builds → écran blanc puis fermeture (crash Samsung
    // vu en prod). En import DYNAMIQUE, l'écran s'ouvre toujours ; si le module
    // natif manque, seul CE bouton lève une erreur, rattrapée par `integrerDepuis`.
    const DocumentPicker = await import('expo-document-picker');
    const resultat = await DocumentPicker.getDocumentAsync({
      // Sur le web, `type` est recopié tel quel dans l'attribut `accept` du
      // <input> de fichiers. Le MIME seul (`application/pdf`) fait griser les PDF
      // dans le sélecteur de certains navigateurs (le Finder se fie à
      // l'extension) : on ajoute donc `.pdf` SUR LE WEB pour les rendre
      // sélectionnables. Sur natif, on garde exactement l'ancien filtre MIME, qui
      // fonctionne : ajouter une pseudo-extension y fausserait la conversion en UTI.
      type: Platform.OS === 'web' ? ['application/pdf', '.pdf'] : 'application/pdf',
      copyToCacheDirectory: true,
      multiple: false,
    });
    if (resultat.canceled) return null;
    const fichier = resultat.assets?.[0];
    if (!fichier?.uri) return null;
    const dataUri = await fichierEnDataUri(fichier.uri, fichier.mimeType ?? 'application/pdf');
    return { pdf: dataUri };
  }

  async function creer(reessai = false) {
    if (!classe) return;
    setErreur(null);
    setOccupe(true);
    // Les champs communs à toute création, hors ancrage temporel (date, créneau,
    // récurrence), qui diffère selon le mode.
    const base = {
      classeId: classe.id,
      titre,
      attendus: aRattacher.map((r) => ({
        id: r.attendu.id,
        role: r.role,
        justification: r.justification,
      })),
      description,
      objectif,
      materiel,
      organisation,
      lieu,
      groupement,
      canal,
      // Importée si une préparation a prérempli le formulaire, sinon tapée à la
      // main. Le chemin « générée » vient d'ailleurs (activiteDepuisLecon). Une
      // reprise de bibliothèque reste « manuel » : c'est une création à la main.
      origine: importee ? ('importe' as const) : ('manuel' as const),
      duree: duree.trim() ? parseInt(duree.trim(), 10) : null,
      // Logistique : le type a été choisi « sans compétences » dans le catalogue.
      // L'activité s'affiche dans la grille mais ne pèse pas dans le bilan.
      sansCompetences,
    };
    // Le créneau d'un jour pour le moment choisi. S'il existe déjà, on le prend.
    // Sinon, en mono-jour (`creerSiAbsent`), on le crée POUR CETTE SEMAINE : la
    // prof a choisi librement un moment que ce jour n'avait pas dans sa semaine
    // type, on l'y pose sans toucher au modèle de fond. `null` = « sans moment ».
    const monClasseId = classe.id;
    // Résout l'id du créneau d'un jour pour une CLÉ de moment donnée. S'il n'existe
    // pas ce jour-là et qu'on l'autorise, on le crée POUR CETTE SEMAINE (sans
    // toucher le fond). Sert au moment principal ET aux créneaux d'extension.
    const creneauPourCle = async (
      dateISO: string,
      cle: string,
      creerSiAbsent: boolean,
    ): Promise<string | null> => {
      const existant = creneauPourMoment(creneaux.donnees ?? [], jourIso(dateISO), cle);
      if (existant) return existant;
      if (!creerSiAbsent) return null;
      const m = momentsSemaine.find((x) => x.cle === cle);
      if (!m) return null;
      return await ajouterCreneau({
        classeId: monClasseId,
        jour: jourIso(dateISO),
        debut: m.debut,
        fin: m.fin,
        libelle: m.libelle,
        moment: m.moment,
        semaine: lundiDeISO(dateISO),
      });
    };
    const creneauDuJour = (dateISO: string, creerSiAbsent: boolean): Promise<string | null> =>
      momentChoisi ? creneauPourCle(dateISO, momentChoisi, creerSiAbsent) : Promise.resolve(null);

    let creeId: string | null = null;
    let relance = false;
    try {
      if (sequenceMode) {
        // UNE séquence : la tête (étape 1) porte le titre de la leçon et son
        // type ; les étapes suivantes sont recopiées telles quelles. `creerActivite`
        // ne fabrique la chaîne que s'il y a au moins une étape suivante non vide
        // (sinon c'est une leçon mono-étape typée, ce qui reste correct).
        const etapesPayload = [
          { titre, type: typeEtape1 },
          ...etapesSuite.map((e) => ({ titre: e.titre, type: e.type })),
        ];
        // Une seule date, pour la tête : la suite se planifiera au fil des cours
        // (le « quand fais-tu la suite ? » de la clôture, à venir au Lot 2). En
        // « autre date », on ne date que le premier jour coché.
        const dateTete =
          choixDate === 'aucune'
            ? null
            : choixDate === 'autre'
              ? joursChoisis[0] ?? null
              : quand;
        const creneauTete = dateTete ? await creneauDuJour(dateTete, true) : null;
        const { id } = await creerActivite({
          ...base,
          date: dateTete,
          creneauId: creneauTete,
          semaines: 1,
          etapes: etapesPayload,
        });
        creeId = id;
      } else if (choixDate === 'autre') {
        // Une activité PAR jour coché, chacune sur le créneau de ce jour-là qui
        // porte le moment choisi, créé pour sa semaine s'il manque (les créneaux
        // propres à une semaine S'AJOUTENT au fond, voir `creneauxDe`). En multi,
        // pas de récurrence (une fois par jour).
        const jours = [...joursChoisis].sort();
        for (const jour of jours) {
          const creneauIdJour = await creneauDuJour(jour, true);
          const { id } = await creerActivite({
            ...base,
            date: jour,
            creneauId: creneauIdJour,
            semaines: multiJours ? 1 : semaines,
          });
          if (!creeId) creeId = id;
        }
      } else {
        const creneauIdJour = quand ? await creneauDuJour(quand, true) : null;
        const { id } = await creerActivite({ ...base, date: quand, creneauId: creneauIdJour, semaines });
        creeId = id;
        // Extension : la même leçon posée sur les créneaux consécutifs cochés, le
        // même jour (une copie par créneau, sans récurrence). Répond au « ça a duré
        // toute la matinée, sur deux plages » sans refaire la saisie (retour Mahé).
        if (quand && !multiJours) {
          for (const cle of etendusValides) {
            const cid = await creneauPourCle(quand, cle, true);
            await creerActivite({ ...base, date: quand, creneauId: cid, semaines: 1 });
          }
        }
      }

      // La photo de la prépa scannée devient un témoin de la leçon (la première
      // séance, en multi-jours). Non bloquant : une leçon créée vaut mieux qu'une
      // leçon perdue parce que l'envoi de sa photo a échoué.
      if (creeId && photosPrepa.length) {
        try {
          for (const img of photosPrepa) await joindrePhotoActivite(creeId, img, 'preparation');
        } catch (e) {
          console.warn('photo de prépa non jointe (ignorée) :', e);
        }
      }

      // On remplace au lieu d'empiler, et on ouvre la séance créée.
      if (creeId) {
        void effacerBrouillonLecon(classe.id);
        router.replace({ pathname: '/activite/[id]', params: { id: creeId } });
      }
    } catch (e) {
      // Rien n'a encore été écrit : on retente UNE fois après avoir rafraîchi la
      // session. C'est le « il faut cliquer deux fois » de Sophie (22/09) : au
      // retour d'arrière-plan, la première requête part avec un jeton périmé.
      if (!creeId && !reessai) {
        relance = true;
        await supabase.auth.refreshSession().catch(() => {});
        await creer(true);
        return;
      }
      console.warn('création de leçon échouée :', e);
      setErreur(creeId ? t.activite.erreurCreationPartielle : t.activite.erreurCreation);
    } finally {
      // La relance gère son propre état « occupé ».
      if (!relance) setOccupe(false);
    }
  }

  // Les cinq temps de l'assistant hérité, ramenés sur une page qui défile. Ils
  // ne découpent plus la saisie : ils en montrent la forme, en tête, pour se
  // repérer et pour un écran projeté. Un temps est « fait » quand sa section
  // porte quelque chose ; le premier temps pas encore fait est le temps courant.
  // C'est une lecture de l'état, pas une pagination : rien n'est verrouillé.
  const verrou = occupe || analyse;
  const jalons: boolean[] = [
    // Objectifs : le quoi. Un titre ou une description, c'est parti.
    titre.trim().length > 0 || description.trim().length > 0,
    // Matériel et détails : le pli des détails ouvert et au moins un champ posé.
    details &&
      (materiel.trim().length > 0 ||
        objectif.trim().length > 0 ||
        organisation.trim().length > 0 ||
        lieu.trim().length > 0 ||
        duree.trim().length > 0),
    // Compétences : la détection a tourné, ou un attendu est retenu. Une activité
    // logistique (sans compétences) n'a pas cette étape : elle est « faite » d'office.
    sansCompetences || detecte || attendusIds.length > 0,
    // Vérification : de quoi créer. Un titre suffit pour une activité logistique ;
    // sinon un titre ET au moins un attendu rattaché.
    titre.trim().length > 0 && (sansCompetences || attendusIds.length > 0),
    // Planification : une date posée (ou volontairement aucune, qui reste un
    // choix). En multi-jours, au moins un jour coché.
    choixDate === 'aucune' ||
      (choixDate === 'autre' ? joursChoisis.length > 0 : !!quand),
  ];
  const premierNonFait = jalons.indexOf(false);
  const etapeCourante = premierNonFait === -1 ? jalons.length - 1 : premierNonFait;

  // Le retour remonte d'un cran avant de sortir : depuis la bibliothèque vers le
  // choix, depuis le formulaire vers le choix (sauf quand on a sauté le choix,
  // où revenir en arrière doit bien quitter l'écran).
  const auRetour = bibliotheque
    ? () => setBibliotheque(false)
    : mode === 'formulaire' && !sauteLeChoix
      ? () => setMode('choix')
      : undefined;

  // Premier temps : du neuf, ou une reprise. On demande avant d'ouvrir le
  // formulaire, plutôt que de plonger direct dedans.
  if (mode === 'choix' && !bibliotheque) {
    return (
      <SousEcran titre={t.activite.titreEcran} auRetour={auRetour}>
        {/* Les deux actions « leçon » portent l'identité leçon (tuile violette
            « dirigées » + icône), la même que le « + » Leçons de la boîte : une
            couleur par action pour créer l'automatisme (retour Valentin 24/08). */}
        <Carte
          onPress={() => {
            repartirVierge();
            setMode('formulaire');
          }}>
          <View style={styles.choixLigne}>
            <Tuile icone="book" moment="dirigees" />
            <View style={styles.choixCorps}>
              <Text style={texte.section}>{t.activite.choixNouvelle}</Text>
              <Text style={styles.aide}>{t.activite.choixNouvelleAide}</Text>
            </View>
          </View>
        </Carte>
        <Carte onPress={() => setBibliotheque(true)}>
          <View style={styles.choixLigne}>
            <Tuile icone="copy" moment="dirigees" />
            <View style={styles.choixCorps}>
              <Text style={texte.section}>{t.activite.choixReprendre}</Text>
              <Text style={styles.aide}>{t.activite.choixReprendreAide}</Text>
            </View>
          </View>
        </Carte>
      </SousEcran>
    );
  }

  // Le sélecteur de bibliothèque : la liste des activités déjà créées, avec un
  // filtre par titre puisque la liste peut être longue.
  if (mode === 'choix' && bibliotheque) {
    return (
      <SousEcran
        titre={t.activite.bibliothequeTitre}
        auRetour={auRetour}
        enteteFixe={
          <Champ
            value={rechercheBiblio}
            onChangeText={setRechercheBiblio}
            placeholder={t.moi.bibli.recherche}
            autoCorrect={false}
          />
        }>
        {bibli.erreur ? <Alerte message={bibli.erreur} /> : null}
        {/* La MÊME bibliothèque que le profil : filtres, rangement par domaine,
            doublons fondus. La recherche vit dans l'en-tête fixe ci-dessus. */}
        <BibliothequeListe
          lecons={bibli.donnees ?? []}
          chargement={bibli.chargement}
          vide={t.activite.bibliothequeVide}
          enCoursId={chargeBiblio}
          recherche={rechercheBiblio}
          onRecherche={setRechercheBiblio}
          masquerRecherche
          onChoisir={(l) => reprendre(l.id)}
        />
        {erreur ? <Alerte message={erreur} /> : null}
      </SousEcran>
    );
  }

  return (
    <SousEcran titre={t.activite.titreEcran} auRetour={auRetour}>
      <Carte>
        <View
          accessibilityLabel={`${t.activite.etapesTitre} : ${t.activite.etapes[etapeCourante]}`}
          style={styles.etapes}>
          {t.activite.etapes.map((libelle, i) => {
            const etat = jalons[i] ? 'faite' : i === etapeCourante ? 'courante' : 'muette';
            return (
              <View key={libelle} style={styles.etapeColonne}>
                <View style={styles.etapeRail}>
                  <View
                    style={[
                      styles.demiBarre,
                      i === 0 && styles.barreInvisible,
                      jalons[i - 1] && styles.barreFaite,
                    ]}
                  />
                  <View
                    style={[
                      styles.rond,
                      etat === 'faite' && styles.rondFait,
                      etat === 'courante' && styles.rondCourant,
                    ]}>
                    <Text
                      style={[
                        styles.rondNumero,
                        etat === 'courante' && styles.rondNumeroActif,
                        etat === 'faite' && styles.rondNumeroFait,
                      ]}>
                      {i + 1}
                    </Text>
                  </View>
                  <View
                    style={[
                      styles.demiBarre,
                      i === t.activite.etapes.length - 1 && styles.barreInvisible,
                      jalons[i] && styles.barreFaite,
                    ]}
                  />
                </View>
                <Text
                  numberOfLines={2}
                  style={[
                    styles.etapeLibelle,
                    etat === 'courante' && styles.etapeLibelleCourant,
                    etat === 'faite' && styles.etapeLibelleFait,
                  ]}>
                  {libelle}
                </Text>
              </View>
            );
          })}
        </View>
      </Carte>

      {brouillon ? (
        <Carte>
          <Text style={styles.brouillonTexte}>{t.activite.brouillonTrouve(brouillon.titre || brouillon.description.slice(0, 40))}</Text>
          <View style={styles.brouillonActions}>
            <View style={styles.brouillonBouton}>
              <BoutonSecondaire libelle={t.activite.brouillonJeter} onPress={jeterBrouillon} />
            </View>
            <View style={styles.brouillonBouton}>
              <BoutonPrincipal libelle={t.activite.brouillonReprendre} onPress={reprendreBrouillon} />
            </View>
          </View>
        </Carte>
      ) : null}

      <Carte>
        <Champ
          etiquette={t.activite.quoi}
          value={titre}
          onChangeText={setTitre}
          placeholder={t.activite.quoiIndice}
          editable={!verrou}
        />
        <Text style={styles.aide}>{t.activite.quoiAide}</Text>
        <Champ
          etiquette={t.activite.description}
          value={description}
          onChangeText={setDescription}
          placeholder={t.activite.descriptionIndice}
          multiline
          style={styles.zone}
          editable={!verrou}
        />

        {/* Intégrer une préparation. Elle a déjà écrit sa leçon quelque part :
            plutôt que de la retaper, elle la donne et le formulaire se remplit.
            Elle relit et corrige, rien n'est créé sans son geste. */}
        <View style={styles.prepa}>
          <Text style={texte.section}>{t.activite.prepaTitre}</Text>
          <Text style={styles.aide}>{t.activite.prepaAide}</Text>
          {analyse ? (
            <View style={styles.ligneAttente}>
              <ActivityIndicator color={couleurs.encreDouce} />
              <Text style={texte.discret}>{t.activite.prepaAnalyse}</Text>
            </View>
          ) : (
            <View style={styles.prepaBoutons}>
              <View style={styles.prepaBouton}>
                <BoutonSecondaire
                  libelle={t.activite.prepaPhoto}
                  icone={<Feather name="camera" size={16} color={couleurs.encre} />}
                  onPress={() => integrerDepuis(photoAppareilEnEntree)}
                />
              </View>
              <View style={styles.prepaBouton}>
                <BoutonSecondaire
                  libelle={t.activite.prepaAlbum}
                  icone={<Feather name="image" size={16} color={couleurs.encre} />}
                  onPress={() => integrerDepuis(photoAlbumEnEntree)}
                />
              </View>
              <View style={styles.prepaBouton}>
                <BoutonSecondaire
                  libelle={t.activite.prepaPdf}
                  icone={<Feather name="file-text" size={16} color={couleurs.encre} />}
                  onPress={() => integrerDepuis(pdfEnEntree)}
                />
              </View>
            </View>
          )}

          {/* La photo scannée sera gardée comme trace de la leçon : on le montre,
              une vignette et un mot, plutôt que de le faire en douce. */}
          {photosPrepa.length ? (
            <View style={styles.prepaGardee}>
              <Image
                source={{ uri: photosPrepa[0].uri }}
                style={styles.prepaVignette}
                contentFit="cover"
              />
              <Text style={styles.aide}>{t.activite.prepaPhotoGardee}</Text>
            </View>
          ) : null}
        </View>
      </Carte>

      {/* Une séance ou une séquence ? Maternelle mono-étape par défaut ; primaire
          étale une leçon sur plusieurs cours typés. Masqué par SEQUENCES_ACTIVES
          jusqu'à ce que Lot 2 + Lot 3 soient livrés. */}
      {SEQUENCES_ACTIVES ? (
      <Carte>
        <Pastilles
          etiquette={SEQ.modeTitre}
          options={[
            { id: 'une', libelle: SEQ.modeUne },
            { id: 'sequence', libelle: SEQ.modeSequence },
          ]}
          choisi={sequenceMode ? 'sequence' : 'une'}
          onChoisir={(v) => setSequenceMode(v === 'sequence')}
        />
        <Text style={styles.aide}>{SEQ.modeAide}</Text>

        {/* Ancre d'aide « ? » (mode aide) : le guide « une leçon en plusieurs
            cours ». Rend null hors mode aide, donc rien ne bouge sans lui. */}
        <AncreAide zone="nouvelle-type-lecon" />

        {sequenceMode ? (
          <>
            {/* Le type de l'étape 1 (= la tête, qui porte le titre de la leçon). */}
            <View style={styles.etapeBloc}>
              <Text style={styles.etapeEtiquette}>{SEQ.etape1Type}</Text>
              <ChoixType
                types={listeTypes}
                choisi={typeEtape1}
                // Le niveau suggéré depuis le titre ; la pastille « suggéré » ne
                // s'affiche que sur un type non choisi (donc jamais quand la
                // suggestion est déjà celle retenue).
                suggere={niveauDepuisTexte(titre)}
                onChoisir={(code) => {
                  type1Manuel.current = true;
                  setTypeEtape1(code);
                }}
              />
            </View>

            {/* Les étapes suivantes (2..N). */}
            <Text style={texte.section}>{SEQ.etapesTitre}</Text>
            <Text style={styles.aide}>{SEQ.etapesAide}</Text>
            {etapesSuite.map((etape, i) => (
              <View key={i} style={styles.etapeBloc}>
                <View style={styles.etapeEntete}>
                  <Text style={styles.etapeEtiquette}>{SEQ.etapeRang(i + 2)}</Text>
                  <Pressable
                    accessibilityRole="button"
                    accessibilityLabel={SEQ.retirerEtape}
                    onPress={() => retirerEtape(i)}
                    style={styles.etapeRetirer}>
                    <Feather name="x" size={16} color={couleurs.encreDouce} />
                  </Pressable>
                </View>
                <Champ
                  value={etape.titre}
                  onChangeText={(v) => changerTitreEtape(i, v)}
                  placeholder={SEQ.etapeTitreIndice}
                  editable={!verrou}
                />
                <ChoixType
                  types={listeTypes}
                  choisi={etape.type}
                  suggere={etape.manuel ? null : niveauDepuisTexte(etape.titre)}
                  onChoisir={(code) => changerTypeEtape(i, code)}
                />
              </View>
            ))}
            <BoutonSecondaire
              libelle={SEQ.ajouterEtape}
              icone={<Feather name="plus" size={16} color={couleurs.encre} />}
              onPress={ajouterEtape}
            />
          </>
        ) : null}
      </Carte>
      ) : null}

      {competence && prechoisis.length ? (
        <Carte>
          <Text style={texte.discret}>{t.activite.depuisCompetenceAide(nom ?? '')}</Text>
        </Carte>
      ) : null}

      {/* Ce que ça travaille. C'est le geste qui fait comprendre l'app. Masqué
          pour une activité logistique (sans compétences) : on ne demande pas de
          rattacher un attendu à une piscine ou une visite médicale. */}
      {sansCompetences ? null : (
      <Carte>
        <Text style={texte.section}>{t.activite.detecte}</Text>

        {[...retenus.values()].map((r) => (
          <LigneAttendu
            key={r.attendu.id}
            attendu={r.attendu}
            choisi={!decoches.includes(r.attendu.id)}
            onBasculer={() => basculer(r.attendu)}
            marque={r.role ? t.activite.roles[r.role] : undefined}
            note={r.justification ?? undefined}
          />
        ))}

        {/* Le geste qui fait comprendre l'app en dix secondes. Il mérite un
            cadre : deux libellés gris à la suite se lisent comme des
            étiquettes, pas comme des gestes. */}
        {!detecte ? (
          <BoutonSecondaire
            libelle={t.activite.detecter}
            onPress={() => {
              if (titre.trim().length < 10 && description.trim().length < 10) {
                setErreur(t.activite.quoiAide);
                return;
              }
              setErreur(null);
              setDetecte(true);
            }}
          />
        ) : null}

        {propositions.chargement ? (
          <View style={styles.ligneAttente}>
            <ActivityIndicator color={couleurs.encreDouce} />
            <Text style={texte.discret}>{t.activite.detection}</Text>
          </View>
        ) : null}

        {propositions.erreur ? <Alerte message={t.activite.detectionErreur} /> : null}

        {propList.length === 0 && !propositions.chargement && detecte ? (
          <Text style={styles.aide}>{t.activite.detecteRien}</Text>
        ) : null}

        {propList
          .filter((p) => !retenus.has(p.attendu.id))
          .map((p) => (
            <LigneAttendu
              key={p.attendu.id}
              attendu={p.attendu}
              choisi={false}
              onBasculer={() => basculer(p.attendu, p.role, p.pourquoi)}
              marque={t.activite.roles[p.role]}
              note={p.pourquoi}
              citation={p.citation}
              citationVerifiee={p.citationVerifiee}
              confiance={p.confiance}
            />
          ))}

        {propList.length ? (
          <Text style={styles.aide}>{t.activite.detecteAide}</Text>
        ) : null}

        {!chercheManuellement && (detecte || retenus.size > 0) && !propositions.chargement ? (
          <BoutonDiscret
            libelle={t.activite.chercher}
            onPress={() => setChercheManuellement(true)}
          />
        ) : chercheManuellement && classe ? (
          <RechercheAttendus
            classe={classe}
            choisis={attendusIds}
            onBasculer={basculer}
            exclus={new Set([...retenus.keys()])}
          />
        ) : null}
        {/* Toujours à portée, même avant la détection : descendre dans le
            programme pour choisir un attendu (retour Sophie 24/09). La recherche
            manuelle, elle, porte déjà ce lien. */}
        {!chercheManuellement && classe && !sansCompetences ? (
          <ParcourirProgramme
            classe={classe}
            choisis={attendusIds}
            onBasculer={basculer}
            exclus={new Set([...retenus.keys()])}
          />
        ) : null}

        {/* L'avertissement ne se lit qu'une fois : quand des propositions sont
            à l'écran, « coche ce qui te va » dit déjà quoi faire, et empiler
            deux textes d'aide donne l'impression d'un écran qui insiste. */}
        {attendusIds.length === 0 &&
        (detecte || chercheManuellement) &&
        !propositions.chargement &&
        !propList.length ? (
          <Text style={styles.aide}>{t.activite.sansAttenduAide}</Text>
        ) : null}
      </Carte>
      )}

      {/* Par quel canal. Une question douce pour aider à varier l'enseignement,
          jamais une étiquette sur un enfant. Rien n'est coché d'avance. */}
      <Carte>
        <Pastilles
          etiquette={t.activite.canalTitre}
          options={CANAUX.map((c) => ({ id: c, libelle: t.canaux[c] }))}
          choisi={canal}
          onChoisir={(v) => setCanal((v as Canal) ?? null)}
        />
        <Text style={styles.aide}>{t.activite.canalAide}</Text>
      </Carte>

      {/* Quand. Une activité sans date existe : elle attend son tour. */}
      <Carte>
        <Pastilles
          etiquette={t.activite.quand}
          options={[
            { id: 'aujourdhui', libelle: t.activite.aujourdhui },
            { id: 'demain', libelle: t.activite.demain },
            { id: 'autre', libelle: t.activite.plusTard },
            { id: 'aucune', libelle: t.activite.pasEncore },
          ]}
          choisi={choixDate}
          onChoisir={(v) => {
            const choix = (v ?? 'aujourdhui') as typeof choixDate;
            setChoixDate(choix);
            setMomentChoisi(null);
            if (choix === 'autre') {
              // « Une autre date » ouvre la bande multi, avec un premier jour
              // présélectionné : un seul jour se comporte comme avant.
              setQuand(null);
              setJoursChoisis([isoDuJour(2)]);
              setSemaines(1);
            } else {
              setJoursChoisis([]);
              if (choix === 'aujourdhui') setQuand(isoDuJour());
              else if (choix === 'demain') setQuand(isoDuJour(1));
              else {
                setQuand(null);
                setSemaines(1);
              }
            }
          }}
        />

        {/* Le choix des jours en MENU DÉROULANT + cases à cocher (retour Valentin
            30/08 : la bande de boutons devenait illisible). On peut cocher
            plusieurs jours : la leçon se pose sur chacun, au même moment. */}
        {choixDate === 'autre' ? (
          <>
            <SelecteurJoursMenu
              choisis={joursChoisis}
              onBasculer={toggleJour}
            />
            <Text style={styles.aide}>{t.activite.plusieursJoursAide}</Text>
          </>
        ) : null}

        {/* Le moment. Mono-jour : choix LIBRE parmi tous les moments de la
            semaine, plus « Sans moment » ; s'il n'existe pas ce jour-là, il est
            créé à la création. Multi : pareil, sur chaque jour coché. */}
        {(jourCourant || multiJours) && momentsDispo.length ? (
          <>
            <SelecteurMoment
              etiquette={t.activite.moment}
              options={momentsDispo}
              choisi={momentChoisi}
              onChoisir={setMomentChoisi}
            />

            {/* Extension : cette leçon dure-t-elle aussi sur les créneaux suivants
                du même jour ? (une présentation d'accueil qui court toute la
                matinée). On coche, une copie se pose sur chacun. Mono-jour seulement. */}
            {!sequenceMode && momentsApres.length ? (
              <View style={styles.etendre}>
                <Text style={styles.etendreTitre}>
                  {langue === 'nl'
                    ? 'Duurt deze les ook op de volgende tijdvakken?'
                    : 'Cette leçon dure aussi sur les créneaux suivants ?'}
                </Text>
                {momentsApres.map((m) => {
                  const coche = creneauxEtendus.includes(m.cle);
                  return (
                    <Pressable
                      key={m.cle}
                      accessibilityRole="checkbox"
                      accessibilityState={{ checked: coche }}
                      accessibilityLabel={`${m.debut} ${m.libelle}`}
                      onPress={() =>
                        setCreneauxEtendus((liste) =>
                          liste.includes(m.cle)
                            ? liste.filter((x) => x !== m.cle)
                            : [...liste, m.cle],
                        )
                      }
                      style={styles.etendreLigne}>
                      <View style={[styles.etendreCase, coche && styles.etendreCaseActive]}>
                        {coche ? <Feather name="check" size={13} color={couleurs.surface} /> : null}
                      </View>
                      <Text style={styles.etendreLibelle} numberOfLines={1}>
                        {m.debut} {m.libelle}
                      </Text>
                    </Pressable>
                  );
                })}
              </View>
            ) : null}
          </>
        ) : jourCourant && !creneaux.chargement && momentsDispo.length === 0 ? (
          <Text style={styles.aide}>{t.activite.momentAucun}</Text>
        ) : null}

        {recurrenceVisible ? (
          <>
            <Pastilles
              etiquette={t.activite.revient}
              options={SEMAINES.map((n) => ({
                id: String(n),
                libelle: n === 1 ? t.activite.revientNon : t.activite.revientSemaines(n),
              }))}
              choisi={String(semaines)}
              onChoisir={(v) => setSemaines(v ? parseInt(v, 10) : 1)}
            />
            {semaines > 1 ? <Text style={styles.aide}>{t.activite.revientAide}</Text> : null}
          </>
        ) : null}

        {sequenceMode ? <Text style={styles.aide}>{SEQ.dateSuiteAide}</Text> : null}
      </Carte>

      {/* Le détail derrière un seul geste, jamais derrière un choix préalable. */}
      {!details ? (
        <BoutonDiscret libelle={t.activite.plusDeDetails} onPress={() => setDetails(true)} />
      ) : (
        <Carte>
          <Champ
            etiquette={t.activite.objectif}
            value={objectif}
            onChangeText={setObjectif}
            multiline
            style={styles.zone}
            editable={!verrou}
          />
          <Champ
            etiquette={t.activite.materiel}
            value={materiel}
            onChangeText={setMateriel}
            multiline
            style={styles.zone}
            editable={!verrou}
          />
          <Champ
            etiquette={t.activite.organisation}
            value={organisation}
            onChangeText={setOrganisation}
            multiline
            style={styles.zone}
            editable={!verrou}
          />
          <Champ
            etiquette={t.activite.lieu}
            value={lieu}
            onChangeText={setLieu}
            editable={!verrou}
          />
          <Champ
            etiquette={t.activite.duree}
            value={duree}
            onChangeText={(v) => setDuree(v.replace(/[^0-9]/g, ''))}
            keyboardType="number-pad"
            editable={!verrou}
          />
          <Pastilles
            etiquette={t.activite.groupement}
            options={GROUPEMENTS.map((g) => ({ id: g, libelle: t.activite.groupements[g] }))}
            choisi={groupement}
            onChoisir={setGroupement}
          />
          <BoutonDiscret libelle={t.activite.moinsDeDetails} onPress={() => setDetails(false)} />
        </Carte>
      )}

      {erreur ? <Alerte message={erreur} /> : null}

      <BoutonPrincipal
        libelle={t.activite.creer}
        onPress={creer}
        occupe={occupe}
        inactif={
          !titre.trim() ||
          !classe ||
          analyse ||
          // Multi-jours : au moins un jour, et le moment choisi présent partout.
          (choixDate === 'autre' && joursChoisis.length === 0)
        }
      />
    </SousEcran>
  );
}

