import { router, Tabs } from 'expo-router';
import { useEffect, useRef } from 'react';

import { NavVerre } from '@/components/nav-verre';
import { t } from '@/i18n';
import { NAV_AVATAR } from '@/lib/flags';
import { aVuGuide, marquerGuideVu } from '@/lib/guide';
import { aVuIntro, marquerIntroVue } from '@/lib/intro';
import { pageAccueil } from '@/lib/preferences';
import { useMoi } from '@/lib/session';
import { useCouleurs } from '@/theme/tokens';

// La classe active vient du layout racine, au-dessus de la pile entière :
// « Ranger » et « Ma classe » sont empilés par-dessus les onglets et en ont
// besoin aussi.
export default function Onglets() {
  const c = useCouleurs();
  const moi = useMoi();

  // 🔑 Le tour d'arrivée pour TOUT LE MONDE, y compris les comptes déjà créés.
  // Le gate racine (déclaratif) ne montre l'intro qu'aux NON connectés ; un
  // compte déjà connecté ne la reverrait jamais, même après une refonte du tour.
  // On la remontre donc ici, une seule fois, quand la version stockée est en
  // retard (aVuIntro devient faux à chaque montée de VERSION_INTRO). Ce montage
  // n'existe que sous session (sous-arbre `connecte && !sansClasse` du layout
  // racine), donc pas besoin de re-tester la session : on est forcément connecté.
  //
  // ⚠️ On reste hors du garde déclaratif du layout racine : celui-ci gouverne le
  // sous-arbre non connecté et se battrait avec un push ici. Un seul déclencheur
  // impératif, une seule fois (le ref), en modal par-dessus l'app.
  //
  // 🔒 On POSE le drapeau AVANT d'ouvrir, pas à la fin. Le tour est un bonus,
  // jamais une porte : même si on referme la modale d'un glissement sans toucher
  // au bouton, on ne la reverra pas au prochain lancement. Le mode « force » la
  // repose (idempotent) puis rend la main à l'app. Jamais de boucle, jamais un
  // tour qui revient à chaque ouverture.
  // 🎯 Le tour « Prends l'app en main » se lance seul à la session, une fois. On
  // le fait passer APRÈS l'intro : si les planches d'accueil sont dues ce
  // lancement-ci, on les montre et le tour attendra la prochaine ouverture (pas
  // deux fenêtres empilées). Comme l'intro, on pose le drapeau AVANT d'ouvrir :
  // un balayage qui referme le tour sans bouton ne le fait pas revenir.
  const declenche = useRef(false);
  useEffect(() => {
    // On attend de connaître le compte (les onglets montent sous session, donc
    // `moi` est normalement déjà là) : le drapeau du tour est par compte.
    if (declenche.current || !moi) return;
    declenche.current = true;
    aVuIntro().then((vuIntro) => {
      if (!vuIntro) {
        marquerIntroVue();
        router.push({ pathname: '/intro', params: { force: '1' } });
        return;
      }
      aVuGuide(moi).then((vuGuide) => {
        if (!vuGuide) {
          // Première fois : on laisse sur le Pilotage (les premiers pas y vivent)
          // et on ouvre le tour. Pas de redirection vers la page préférée.
          marquerGuideVu(moi);
          router.push('/guide');
          return;
        }
        // Les fois suivantes : l'app s'ouvre sur la page préférée (défaut Capter).
        // Les onglets démarrent sur le Pilotage ; on bascule si un autre choix
        // est mémorisé. Un léger passage par le Pilotage est sans gravité.
        pageAccueil().then((page) => {
          if (page === 'journal') router.replace('/journal');
          else if (page === 'capter') router.replace('/capter');
          else if (page === 'groupes') router.replace('/groupes');
          else if (page === 'vous') router.replace('/vous');
          // 'index' (Pilotage) : rien à faire, c'est déjà la page de départ.
        });
      });
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [moi]);

  return (
    <Tabs
      // La barre est rendue à la main : elle flotte en verre dépoli au-dessus du
      // contenu, ce que le style d'onglets standard ne sait pas faire.
      tabBar={(props) => <NavVerre {...props} />}
      screenOptions={{
        headerShown: false,
        sceneStyle: { backgroundColor: c.fond },
      }}>
      <Tabs.Screen name="index" options={{ title: t.onglets.accueil }} />
      <Tabs.Screen name="journal" options={{ title: t.onglets.journal }} />
      <Tabs.Screen
        name="capter"
        options={{ title: t.onglets.capter, tabBarAccessibilityLabel: t.capter.bouton }}
      />
      <Tabs.Screen name="groupes" options={{ title: t.onglets.groupes }} />
      {/* 🧭 Drapeau NAV_AVATAR ON : « Moi » sort de la barre (href:null la retire
          du menu du bas) mais la route reste montée et navigable — l'avatar des
          en-têtes fait `router.push('/vous')`. NavVerre filtre aussi cette route
          en dur (le tabBar sur-mesure ignore href:null). OFF : onglet normal,
          barre à 5 comme aujourd'hui. */}
      <Tabs.Screen
        name="vous"
        options={NAV_AVATAR ? { href: null } : { title: t.onglets.vous }}
      />
    </Tabs>
  );
}
