import { Image } from 'expo-image';
import { useEffect, useMemo } from 'react';
import { StyleSheet, View } from 'react-native';
import Animated, {
  cancelAnimation,
  Easing,
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withRepeat,
  withSpring,
  withTiming,
} from 'react-native-reanimated';

import { motion, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * Cloudy, la mascotte de l'app. C'est le principe n°3 de la charte : « la
 * mascotte porte l'émotion ». Elle a longtemps manqué au code, alors qu'elle
 * est ce qui rend l'interface vivante là où le fond reste neutre.
 *
 * Rendus 3D pâte à modeler, couleur miel unique (les déclinaisons de couleur du
 * kit n'ont jamais été produites, et teinter un rendu 3D à plat le détruirait ;
 * le miel s'accorde d'ailleurs au dégradé d'action). Les PNG sont détourés sur
 * fond transparent par `outils/detourer-mascotte.py`.
 *
 * 🎞️ Elle respire. Une inspiration lente et minuscule (scale + montée d'un
 * cheveu, en boucle) suffit à la faire vivre sans jamais s'agiter. Et sur les
 * moments forts, `anime` la fait entrer d'un pop discret. Les deux se coupent
 * sous « réduire les animations » : on ne bouge pas la mascotte de qui ne veut
 * pas de mouvement.
 *
 * ⚠️ Deux règles d'usage de la charte, tenues ici par convention d'appel :
 * une seule Cloudy par écran, et jamais une pose négative (colère, puni)
 * dirigée vers l'utilisatrice. Ces deux poses ne sont donc pas embarquées.
 */
const POSES = {
  neutre: require('../../assets/mascotte/cloudy-neutre.png'),
  micro: require('../../assets/mascotte/cloudy-micro.png'),
  celebration: require('../../assets/mascotte/cloudy-celebration.png'),
  endormi: require('../../assets/mascotte/cloudy-endormi.png'),
  loupe: require('../../assets/mascotte/cloudy-loupe.png'),
  salut: require('../../assets/mascotte/cloudy-salut.png'),
  joie: require('../../assets/mascotte/cloudy-joie.png'),
  serenite: require('../../assets/mascotte/cloudy-serenite.png'),
  // Cloudy coiffée du mortier multicolore du logo : c'est devenu la marque
  // (icône d'app + logo). Sert d'ancre de marque sur la connexion.
  chapeau: require('../../assets/mascotte/cloudy-chapeau.png'),
  // Une pose par grand menu (retour Valentin 24/08) : Cloudy prof pour le
  // journal, Cloudy randonneuse à la carte pour le pilotage (on s'oriente), le
  // trio de collègues pour Groupes.
  prof: require('../../assets/mascotte/cloudy-prof.png'),
  randonneur: require('../../assets/mascotte/cloudy-randonneur.png'),
  collegues: require('../../assets/mascotte/cloudy-collegues.png'),
} as const;

export type Pose = keyof typeof POSES;

export function Cloudy({
  pose = 'neutre',
  taille = 40,
  /** Dans une pastille ronde teintée : l'avatar par défaut de l'en-tête. */
  cercle = false,
  /**
   * Respiration idle. Vrai par défaut : la mascotte est vivante partout. À
   * couper pour une Cloudy purement décorative qu'on veut parfaitement fixe.
   */
  respire = true,
  /**
   * Entrée « pop-in » au montage : la mascotte surgit (petite → taille pleine,
   * fondu). Pour les moments où elle arrive à l'écran, la célébration en tête.
   * Faux par défaut : ailleurs elle est déjà là.
   */
  anime = false,
}: {
  pose?: Pose;
  taille?: number;
  cercle?: boolean;
  respire?: boolean;
  anime?: boolean;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const reduire = useReducedMotion();
  // 0 = pas encore entrée, 1 = en place. Sans pop-in, on démarre déjà à 1.
  const entree = useSharedValue(anime ? 0 : 1);
  // Phase de respiration, 0 → 1 → 0 en boucle.
  const souffle = useSharedValue(0);

  useEffect(() => {
    if (!anime || reduire) {
      entree.value = 1;
      return;
    }
    entree.value = 0;
    entree.value = withSpring(1, { duration: motion.duree.lent, dampingRatio: 0.62 });
  }, [anime, reduire, entree]);

  useEffect(() => {
    if (respire && !reduire) {
      souffle.value = withRepeat(
        withTiming(1, { duration: 2800, easing: Easing.inOut(Easing.quad) }),
        -1,
        true,
      );
    } else {
      cancelAnimation(souffle);
      souffle.value = withTiming(0, { duration: motion.duree.rapide });
    }
  }, [respire, reduire, souffle]);

  const styleAnime = useAnimatedStyle(() => {
    // Pop-in : l'échelle monte de 0.6 à 1, l'opacité de 0 à 1.
    const echelleEntree = 0.6 + entree.value * 0.4;
    // Respiration : à peine 2 % d'échelle et un cheveu de montée.
    const echelleSouffle = 1 + souffle.value * 0.02;
    return {
      opacity: entree.value,
      transform: [
        { scale: echelleEntree * echelleSouffle },
        { translateY: souffle.value * -1.5 },
      ],
    };
  });

  const dimension = cercle ? taille * 0.78 : taille;
  const image = (
    <Animated.View style={styleAnime}>
      <Image
        source={POSES[pose]}
        style={{ width: dimension, height: dimension }}
        contentFit="contain"
        // La mascotte n'a pas de sens à énoncer : elle décore, l'écran a déjà son
        // titre. On ne double pas la voix du lecteur d'écran avec « nuage ».
        accessibilityElementsHidden
        importantForAccessibility="no-hide-descendants"
      />
    </Animated.View>
  );
  if (!cercle) return image;
  return <View style={[styles.cercle, { width: taille, height: taille }]}>{image}</View>;
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  cercle: {
    borderRadius: 999,
    backgroundColor: c.actionTeinte,
    alignItems: 'center',
    justifyContent: 'center',
  },
});
