import { ActivityIndicator, Pressable, StyleSheet, Text, View } from 'react-native';
import { useMemo, useState } from 'react';

import { Carte } from '@/components/ecran';
import { Champ, Pastilles } from '@/components/formulaire';
import { langue, t } from '@/i18n';
import { localeDate } from '@/lib/dates';
import { type LeconBibliotheque, type StatutActivite } from '@/lib/donnees';
import { espace, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Le libellé d'avancement d'une SÉQUENCE (« séquence 2/6 »), en local : la
 * feature est neuve, on ne touche pas aux catalogues `src/i18n/*`. Une leçon
 * mono-étape (`etapesTotal <= 1`) n'en affiche aucun.
 */
const LIB_SEQ = {
  fr: (k: number, n: number) => `séquence ${k}/${n}`,
  nl: (k: number, n: number) => `reeks ${k}/${n}`,
}[langue];

/** « 21 septembre » depuis une date ISO. Repli sur '' si la date manque. */
function jourMois(iso: string | null): string {
  if (!iso) return '';
  try {
    return new Intl.DateTimeFormat(localeDate(), { day: 'numeric', month: 'long' }).format(
      new Date(iso),
    );
  } catch {
    return '';
  }
}

/** L'ordre des états dans le filtre : du plus « vivant » au plus « rangé ». */
const ETATS: StatutActivite[] = ['completed', 'planned', 'unplanned', 'draft'];

/**
 * La liste de la BIBLIOTHÈQUE : les leçons du prof, dédupliquées, rangées par
 * domaine (l'intercalaire du classeur), avec recherche et filtres. Partagée
 * entre l'onglet « Bibliothèque » du profil (on ouvre la fiche) et « Reprendre
 * une leçon » à la création (on la reprend). Le geste sur une carte est passé
 * par `onChoisir` : le composant ne sait pas ce qu'on fait de la leçon.
 */
export function BibliothequeListe({
  lecons,
  chargement,
  onChoisir,
  enCoursId,
  vide,
  recherche: rechercheProp,
  onRecherche,
  masquerRecherche = false,
}: {
  lecons: LeconBibliotheque[];
  chargement: boolean;
  onChoisir: (lecon: LeconBibliotheque) => void;
  /** L'id d'une leçon en cours de traitement : un indicateur tourne sur sa carte. */
  enCoursId?: string | null;
  /** Le texte quand il n'y a aucune leçon du tout (pas juste aucun résultat). */
  vide: string;
  /** Recherche CONTRÔLÉE par le parent (pour la garder dans un en-tête fixe). */
  recherche?: string;
  onRecherche?: (v: string) => void;
  /** Le parent rend la barre de recherche ailleurs (en-tête fixe) : on la cache ici. */
  masquerRecherche?: boolean;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);

  // Recherche interne par défaut ; contrôlée si le parent la fournit (cas de
  // l'en-tête fixe, où c'est lui qui rend le champ et tient l'état).
  const [rechercheLocale, setRechercheLocale] = useState('');
  const recherche = rechercheProp ?? rechercheLocale;
  const setRecherche = onRecherche ?? setRechercheLocale;
  const [etat, setEtat] = useState<StatutActivite | null>(null);
  const [croisesSeuls, setCroisesSeuls] = useState(false);

  // Les leçons filtrées, puis regroupées par domaine (l'intercalaire). Les
  // domaines sont triés par ordre alpha, « Sans domaine » toujours en dernier.
  const groupes = useMemo(() => {
    const terme = recherche.trim().toLowerCase();
    const filtrees = lecons.filter((l) => {
      if (etat && l.statut !== etat) return false;
      if (croisesSeuls && !l.aCroises) return false;
      if (terme && !l.titre.toLowerCase().includes(terme)) return false;
      return true;
    });
    const parDomaine = new Map<string, LeconBibliotheque[]>();
    for (const l of filtrees) {
      const cle = l.domaine ?? '';
      const arr = parDomaine.get(cle) ?? [];
      arr.push(l);
      parDomaine.set(cle, arr);
    }
    return [...parDomaine.entries()].sort(([a], [b]) => {
      if (a === '') return 1;
      if (b === '') return -1;
      return a.localeCompare(b, localeDate());
    });
  }, [lecons, recherche, etat, croisesSeuls]);

  if (!chargement && lecons.length === 0) {
    return (
      <Carte>
        <Text style={texte.discret}>{vide}</Text>
      </Carte>
    );
  }

  return (
    <>
      {masquerRecherche ? null : (
        <Champ
          value={recherche}
          onChangeText={setRecherche}
          placeholder={t.moi.bibli.recherche}
          autoCorrect={false}
        />
      )}

      <Pastilles
        options={[
          { id: '', libelle: t.moi.bibli.etatTous },
          ...ETATS.map((e) => ({ id: e, libelle: t.moi.bibli.etat[e] })),
        ]}
        choisi={etat ?? ''}
        onChoisir={(id) => setEtat(id ? (id as StatutActivite) : null)}
      />

      {/* Un interrupteur simple : « seulement ce qui croise des compétences ». */}
      <Pressable
        accessibilityRole="button"
        accessibilityState={{ selected: croisesSeuls }}
        onPress={() => setCroisesSeuls((v) => !v)}
        style={[styles.filtreCroises, croisesSeuls && styles.filtreCroisesActif]}>
        <Text style={[styles.filtreCroisesTexte, croisesSeuls && styles.filtreCroisesTexteActif]}>
          {croisesSeuls ? '✓ ' : ''}
          {t.moi.bibli.croises}
        </Text>
      </Pressable>

      {chargement ? (
        <View style={styles.attente}>
          <ActivityIndicator color={c.encreDouce} />
        </View>
      ) : null}

      {!chargement && groupes.length === 0 ? (
        <Carte>
          <Text style={texte.discret}>{t.moi.bibli.aucunResultat}</Text>
        </Carte>
      ) : null}

      {groupes.map(([domaine, items]) => (
        <View key={domaine || '∅'} style={styles.classeur}>
          {/* L'intercalaire du classeur : le domaine, et le nombre de leçons. */}
          <View style={styles.intercalaire}>
            <Text style={styles.intercalaireTitre} numberOfLines={2}>
              {domaine || t.moi.bibli.sansDomaine}
            </Text>
            <Text style={styles.intercalaireNombre}>{items.length}</Text>
          </View>

          {items.map((l) => {
            const date = jourMois(l.date);
            return (
              <Carte key={l.id} compacte onPress={() => onChoisir(l)}>
                <View style={styles.ligne}>
                  <View style={styles.corps}>
                    <Text style={texte.corps} numberOfLines={1}>
                      {l.titre}
                    </Text>
                    <Text style={texte.discret} numberOfLines={1}>
                      {[
                        t.moi.bibli.etat[l.statut],
                        date,
                        // Une séquence : on montre sa progression (k/N) plutôt que
                        // le compte d'occurrences (qui, lui, vaut pour les copies).
                        l.etapesTotal > 1 ? LIB_SEQ(l.etapesFaites, l.etapesTotal) : null,
                        l.occurrences > 1 ? t.moi.bibli.occurrences(l.occurrences) : null,
                        t.moi.bibli.attendus(l.attendus),
                      ]
                        .filter(Boolean)
                        .join(' · ')}
                    </Text>
                  </View>
                  {enCoursId === l.id ? (
                    <ActivityIndicator color={c.encreDouce} />
                  ) : l.aCroises ? (
                    <View style={styles.badgeCroises}>
                      <Text style={styles.badgeCroisesTexte}>{t.moi.bibli.badgeCroises}</Text>
                    </View>
                  ) : null}
                </View>
              </Carte>
            );
          })}
        </View>
      ))}
    </>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    attente: { paddingVertical: espace.lg, alignItems: 'center' },
    filtreCroises: {
      alignSelf: 'flex-start',
      paddingVertical: 6,
      paddingHorizontal: espace.md,
      borderRadius: rayon.pastille,
      borderWidth: 1,
      borderColor: c.bord,
      backgroundColor: c.fond,
    },
    filtreCroisesActif: {
      borderColor: c.actif,
      backgroundColor: c.actionTeinte,
    },
    filtreCroisesTexte: { fontFamily: police.accent, fontSize: 13, color: c.encreDouce },
    filtreCroisesTexteActif: { color: c.actif },
    classeur: { gap: espace.sm },
    intercalaire: {
      flexDirection: 'row',
      alignItems: 'center',
      gap: espace.sm,
      marginTop: espace.sm,
    },
    intercalaireTitre: {
      flex: 1,
      fontFamily: police.titre,
      fontSize: 15,
      color: c.encre,
    },
    intercalaireNombre: {
      fontFamily: police.accent,
      fontSize: 13,
      color: c.nonRattache,
    },
    ligne: { flexDirection: 'row', gap: espace.sm, alignItems: 'center' },
    corps: { flex: 1, gap: 2 },
    badgeCroises: {
      paddingVertical: 4,
      paddingHorizontal: espace.sm,
      borderRadius: rayon.pastille,
      backgroundColor: c.actionTeinte,
    },
    badgeCroisesTexte: { fontFamily: police.accent, fontSize: 11, color: c.actif },
  });
