import { router, useLocalSearchParams } from 'expo-router';
import { useMemo, useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';

import { Cloudy } from '@/components/cloudy';
import {
  BandeauDemo,
  CadreDirection,
  MiroirClasse,
  PanneauDetail,
  SelecteurPeriodes,
  type FiltreDetail,
} from '@/components/direction/tableau';
import { Carte } from '@/components/ecran';
import { Pastilles } from '@/components/formulaire';
import { t } from '@/i18n';
import { detailDemo, ECOLE_DEMO, periodesDemo, syntheseDemo } from '@/lib/direction-demo';
import { type ModePeriode } from '@/lib/periodes';
import { espace, useTexte } from '@/theme/tokens';

/**
 * Le miroir enseignant·e, en DÉMONSTRATION : ce que la prof d'une classe de
 * l'école fictive voit dans son app, « Ce que voit ma direction ».
 *
 * 🔑 Mêmes briques que le vrai miroir (`MiroirClasse`) et mêmes chiffres que le
 * tableau démo (même générateur), pour montrer à la direction que la
 * transparence n'est pas un argument mais un écran. Sans compte, étiqueté.
 */
export default function DirectionDemoMiroir() {
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(), []);
  const V = t.vueDirection;
  const params = useLocalSearchParams<{ periode?: string }>();

  const [index, setIndex] = useState(() => {
    const i = Number(params.periode);
    return Number.isInteger(i) && i >= 0 && i < 5 ? i : 2;
  });
  const [mode, setMode] = useState<ModePeriode>('cumul');
  const periodes = useMemo(() => periodesDemo(index), [index]);
  const synthese = useMemo(() => syntheseDemo(index, mode), [index, mode]);
  const [classeId, setClasseId] = useState('demo-0');
  const ligne = synthese.classes.find((c) => c.id === classeId) ?? synthese.classes[0];
  const [filtre, setFiltre] = useState<FiltreDetail | null>(null);

  return (
    <CadreDirection
      titre={V.demoMiroirTitreEcran}
      auRetour={() => (router.canGoBack() ? router.back() : router.replace('/direction/demo'))}
      bandeau={<BandeauDemo />}>
      <Carte>
        <View style={styles.entete}>
          <Cloudy pose="serenite" taille={54} />
          <Text style={[texte.corps, styles.flex]}>{V.miroirIntro}</Text>
        </View>
      </Carte>
      <Pastilles
        options={synthese.classes.map((c) => ({ id: c.id, libelle: c.nom }))}
        choisi={ligne.id}
        onChoisir={(id) => id && setClasseId(id)}
      />
      <SelecteurPeriodes periodes={periodes} index={index} mode={mode} onIndex={setIndex} onMode={setMode} />
      <Carte>
        <Text style={texte.corps}>{V.miroirRattachee(`${ECOLE_DEMO.nom} (${ECOLE_DEMO.commune})`)}</Text>
        <Text style={[texte.discret, styles.espaceHaut]}>{V.miroirQui(V.demoMiroirDirection)}</Text>
      </Carte>
      <MiroirClasse ligne={ligne} seuil={synthese.seuilPeuDeDonnees} onDetail={setFiltre} />
      <PanneauDetail
        demo
        filtre={filtre}
        charger={async (f) => detailDemo(index, mode, { classe: ligne.id, discipline: f.discipline ?? null })}
        onFermer={() => setFiltre(null)}
      />
    </CadreDirection>
  );
}

const creerStyles = () =>
  StyleSheet.create({
    entete: { flexDirection: 'row', gap: espace.md, alignItems: 'center' },
    flex: { flex: 1 },
    espaceHaut: { marginTop: espace.sm },
  });
