import AsyncStorage from '@react-native-async-storage/async-storage';
import { router } from 'expo-router';

import { chiffresSemaine, nombreActivitesCompletees } from './donnees';

// Le manifeste, source unique des paliers de trophées. Import relatif (comme
// `moi-progres.tsx`) : le projet n'a pas d'alias Metro pour `assets/`.
import manifest from '../../assets/trophees/manifest.json';

/**
 * Le déclencheur de la célébration « Semaine bouclée ».
 *
 * L'écran (`app/celebration.tsx`) ne décide de rien : il fête des chiffres.
 * Décider s'il y a matière à fêter, et poser le garde-fou anti-répétition, c'est
 * le travail de ce module. Les CHIFFRES eux-mêmes (bouclée ou non, combien
 * d'observations, de moments, de compétences neuves) viennent de `chiffresSemaine`
 * dans `donnees.ts` ; ici on ne fait que l'arithmétique de calendrier, la
 * persistance du marqueur, et la série de semaines consécutives.
 *
 * 🚨 UNE SEULE FOIS PAR SEMAINE. Chaque clôture pourrait rendre la semaine
 * bouclée, mais on ne rouvre l'écran qu'à la PREMIÈRE. Un marqueur par
 * utilisateur·rice et par semaine ISO, dans AsyncStorage, sous la clé
 * `educooo:celebration:<userId>:<lundiISO>`. Il se pose AVANT que l'appelant
 * navigue : ainsi un second appel dans la même semaine retombe sur le marqueur
 * et ne redéclenche rien. Pas de boucle possible.
 */

const PREFIXE = 'educooo:celebration';

function iso(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(
    d.getDate(),
  ).padStart(2, '0')}`;
}

/** Le lundi de la semaine d'une date. Même convention que le journal (ISO, lundi = 1). */
function lundiDe(base: Date): Date {
  const d = new Date(base);
  d.setHours(12, 0, 0, 0);
  const jour = d.getDay() === 0 ? 7 : d.getDay();
  d.setDate(d.getDate() - (jour - 1));
  return d;
}

function ajouterJours(base: Date, n: number): Date {
  const d = new Date(base);
  d.setDate(d.getDate() + n);
  return d;
}

function cleMarqueur(userId: string, lundiISO: string): string {
  return `${PREFIXE}:${userId}:${lundiISO}`;
}

export type ChiffresCelebration = {
  observations: number;
  points: number;
  semaines: number;
  collegues: number;
  moments: number;
};

/**
 * Combien de semaines bouclées d'affilée, la semaine courante comprise.
 *
 * Dérivée des marqueurs déjà posés : on remonte de lundi en lundi tant qu'un
 * marqueur existe. C'est honnête par construction, parce qu'un marqueur n'est
 * posé que sur une semaine réellement bouclée. Comme le tout premier marqueur ne
 * peut donner qu'une série de 1, la série grandit avec l'usage sans jamais
 * annoncer un passé qui n'a pas eu lieu.
 */
async function serieDeSemaines(userId: string, lundiCourant: Date): Promise<number> {
  const toutes = await AsyncStorage.getAllKeys();
  const prefixe = `${PREFIXE}:${userId}:`;
  const marquees = new Set(
    toutes.filter((k) => k.startsWith(prefixe)).map((k) => k.slice(prefixe.length)),
  );
  let serie = 0;
  let curseur = new Date(lundiCourant);
  while (marquees.has(iso(curseur))) {
    serie++;
    curseur = ajouterJours(curseur, -7);
  }
  return serie;
}

/**
 * À appeler après une clôture réussie. Rend les chiffres à passer à l'écran de
 * célébration si la semaine vient d'être bouclée pour la première fois, ou `null`
 * s'il n'y a rien à fêter (semaine non bouclée, ou déjà fêtée).
 *
 * ⚠️ C'est un BONUS : l'appelant enveloppe cet appel dans un try/catch et n'y
 * risque jamais la donnée de la clôture, qui est déjà écrite quand on arrive ici.
 *
 * `dateSeance` est la date de la séance clôturée : c'est elle qui fixe la semaine
 * à examiner. Une séance sans date n'appartient à aucune semaine du calendrier,
 * on retombe alors sur la semaine courante, qui ne la contiendra pas et ne sera
 * donc pas déclarée bouclée par elle seule.
 */
export async function celebrerSiSemaineBouclee(params: {
  classeId: string;
  userId: string;
  dateSeance: string | null;
}): Promise<ChiffresCelebration | null> {
  const reference = params.dateSeance ? new Date(`${params.dateSeance}T12:00:00`) : new Date();
  const lundi = lundiDe(reference);
  const lundiISO = iso(lundi);

  // Le garde anti-répétition d'abord : inutile d'interroger la base si la semaine
  // a déjà été fêtée.
  const cle = cleMarqueur(params.userId, lundiISO);
  if (await AsyncStorage.getItem(cle)) return null;

  const chiffres = await chiffresSemaine({
    classeId: params.classeId,
    lundiISO,
    vendrediISO: iso(ajouterJours(lundi, 4)),
    dimancheISO: iso(ajouterJours(lundi, 6)),
    aujourdISO: iso(new Date()),
  });
  if (!chiffres.bouclee) return null;

  // 🚨 On pose le marqueur AVANT de rendre la main, donc avant toute navigation.
  // La série se calcule ensuite, sur un état déjà écrit : elle compte la semaine
  // courante d'office.
  await AsyncStorage.setItem(cle, iso(new Date()));
  const semaines = await serieDeSemaines(params.userId, lundi);

  return {
    observations: chiffres.observations,
    points: chiffres.points,
    // Filet : la série vaut au moins 1, on vient de poser le marqueur.
    semaines: Math.max(1, semaines),
    // Pas de source fiable de « collègues ayant repris une leçon cette semaine » :
    // on préfère 0 à un chiffre inventé. L'écran masque déjà la bande à 0.
    collegues: 0,
    moments: chiffres.moments,
  };
}

/**
 * L'autre déclencheur : la célébration d'un PALIER DE TROPHÉE. Un palier, c'est
 * un nombre d'activités clôturées (1, 3, 5, 10… — voir `manifest.json`). Quand la
 * clôture qu'on vient d'écrire fait franchir un nouveau palier, on ouvre l'écran
 * `app/trophee-celebration.tsx`, Cloudy en fête et confettis.
 *
 * 🚨 UNE SEULE FOIS PAR PALIER. Comme pour la semaine bouclée, un marqueur garde
 * l'anti-répétition : on mémorise le dernier palier déjà fêté, et on ne rouvre la
 * fête que pour un palier STRICTEMENT plus grand. Pas de userId simple ici (la
 * fonction n'en reçoit pas), donc une clé globale suffit : le nombre d'activités
 * clôturées est déjà celui du compte connecté.
 *
 * ⚠️ BONUS, jamais un risque : tout est enveloppé dans un try/catch et ne relève
 * jamais. Un throw ici casserait la clôture, qui est déjà écrite. On rend `true`
 * si un palier a été fêté (et donc si la navigation a eu lieu), `false` sinon.
 *
 * Le marqueur se pose AVANT de naviguer : un second appel pour le même palier
 * retombe dessus et ne redéclenche rien.
 */
const CLE_TROPHEE = 'educooo:trophee-dernier-palier';

export async function celebrerSiPalierTrophee(): Promise<boolean> {
  try {
    const faites = await nombreActivitesCompletees();
    const paliers: number[] = manifest.paliers;

    // Le plus grand palier atteint : le plus grand seuil <= au nombre d'activités
    // clôturées. 0 si aucun palier n'est encore franchi.
    const atteint = paliers.reduce((max, p) => (p <= faites && p > max ? p : max), 0);
    if (atteint <= 0) return false;

    const brut = await AsyncStorage.getItem(CLE_TROPHEE);
    const dernier = brut ? parseInt(brut, 10) : 0;
    const dernierSain = Number.isFinite(dernier) ? dernier : 0;

    // On ne fête que du neuf, strictement au-dessus du dernier palier célébré.
    if (atteint <= dernierSain) return false;

    // 🚨 Marqueur posé AVANT toute navigation : anti-répétition à l'épreuve d'un
    // second appel dans la même clôture.
    await AsyncStorage.setItem(CLE_TROPHEE, String(atteint));
    router.push({ pathname: '/trophee-celebration', params: { palier: String(atteint) } });
    return true;
  } catch {
    // Fail-open : la clôture a réussi, seule la fête a manqué. Rien à remonter.
    return false;
  }
}
