import { useMemo } from 'react';
import { StyleSheet, Text, View } from 'react-native';

import { AncreAide } from '@/components/aide';
import { AvatarNav } from '@/components/avatar';
import { BoiteReception } from '@/components/boite-reception';
import { CoachMark } from '@/components/coachmark';
import { ComposerObservation } from '@/components/composer-observation';
import { Carte, Ecran, EnteteSection } from '@/components/ecran';
import { Tuile } from '@/components/elements';
import { VignettesMedias } from '@/components/vignettes-medias';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import { NAV_AVATAR } from '@/lib/flags';
import { observationsDe } from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, useTexte } from '@/theme/tokens';

/**
 * Capter, la voix d'abord.
 *
 * 🎨 Le témoin v9 mène cet écran par un gros bouton micro à halo. C'est le bon
 * ordre : en classe, une enseignante dicte, elle ne tape pas accroupie près du
 * bac à sable. La saisie clavier reste là, mais en second, derrière « écrire à
 * la main ».
 *
 * 🚨 La composition (dicter, relire, ranger) vit désormais dans
 * `ComposerObservation`, partagée avec la capture rapide (`capter-vite`). Un
 * seul composant, un seul appel à `creerObservation`, donc une seule surface de
 * masquage. Cet écran n'ajoute que la liste du jour autour de la composition.
 */
export default function Capter() {
  const texte = useTexte();
  const { classe, chargement: classeEnCours } = useClasse();
  const classeId = classe?.id ?? null;

  const dujour = useRequete(() => observationsDe(classeId!, 20), [classeId], { actif: !!classeId });

  const aujourdhui = useMemo(() => {
    const debut = new Date();
    debut.setHours(0, 0, 0, 0);
    return (dujour.donnees ?? []).filter((o) => new Date(o.creeLe) >= debut);
  }, [dujour.donnees]);

  if (!classeEnCours && !classe) {
    return (
      <Ecran titre={t.capter.titre} avatarMenu={NAV_AVATAR ? <AvatarNav /> : undefined}>
        <Carte>
          <Text style={texte.discret}>{t.capter.sansClasse}</Text>
        </Carte>
      </Ecran>
    );
  }

  return (
    <Ecran
      titre={t.capter.titre}
      avatarMenu={NAV_AVATAR ? <AvatarNav /> : undefined}
      selecteurClasse
      actions={<BoiteReception classeId={classeId} />}>
      {/* Le mot d'aide, une seule fois : capter tient à un mot ou une photo. */}
      <CoachMark id="capter" message={t.coach.capter} pose="micro" />

      {/* Ancre d'aide « ? » (mode aide) : le guide « capter une observation ».
          Rend null hors mode aide, donc aucun changement de mise en page. */}
      <AncreAide zone="capter-observation" />

      {/* La composition partagée : dicter ou écrire, relire, préciser, ranger.
          Ranger recharge la liste du jour ci-dessous. */}
      <ComposerObservation onEnregistre={() => dujour.recharger()} />

      <EnteteSection titre={t.capter.aujourdhui} action={String(aujourdhui.length)} />

      {aujourdhui.length === 0 ? (
        <Carte compacte>
          <Text style={texte.discret}>{t.capter.rienAujourdhui}</Text>
        </Carte>
      ) : (
        aujourdhui.map((o) => {
          const range = o.statut !== 'pending';
          return (
            <Carte key={o.id} compacte>
              <View style={styles.ligne}>
                <Tuile icone={range ? 'check' : 'edit-3'} moment={range ? 'recreation' : 'social'} />
                <View style={styles.corps}>
                  {o.texte ? (
                    <Text style={texte.corps} numberOfLines={2}>
                      {o.texte}
                    </Text>
                  ) : null}
                  {/* Une petite vignette sur les lignes qui portent une photo :
                      une observation photo-seule ne se lit plus à l'aveugle. */}
                  <VignettesMedias observationId={o.id} taille={48} />
                  <Text style={texte.discret}>
                    {range ? t.etat.rattache : t.etat.nonRattache}
                  </Text>
                </View>
              </View>
            </Carte>
          );
        })
      )}
    </Ecran>
  );
}

const styles = StyleSheet.create({
  ligne: { flexDirection: 'row', gap: espace.md, alignItems: 'center' },
  corps: { flex: 1, gap: espace.xs },
});
