import { Feather } from '@expo/vector-icons';
import { router, useLocalSearchParams } from 'expo-router';
import { useMemo, useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, Text, View } from 'react-native';

import { CoachMark } from '@/components/coachmark';
import { Carte } from '@/components/ecran';
import { Alerte, BoutonDiscret, BoutonPrincipal, BoutonSecondaire, Champ, Pastilles } from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { VignettesMedias } from '@/components/vignettes-medias';
import { niveauxMaitrise, t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import {
  attendusDejaVus,
  chercherAttendus,
  classerSansRattacher,
  elevesDe,
  observationsDe,
  proposerAttendus,
  rangerObservation,
  type Attendu,
} from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, ombre, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

type Niveau = 'not_started' | 'in_progress' | 'acquired';

/**
 * Ranger une observation : la rattacher à un ou plusieurs attendus du
 * référentiel, sur un élève, avec un niveau de maîtrise.
 *
 * L'IA relit l'observation dès l'ouverture et propose. La recherche à la main
 * reste disponible mais devient une **issue de secours** : personne ne doit
 * avoir à affronter 7 226 attendus, c'est le travail de la machine.
 *
 * Trois choses tenues ici, et elles comptent plus que le confort.
 *
 * Les propositions montrent la **citation** des mots de l'observation qui les
 * justifient. C'est ce qui permet de vérifier d'un coup d'œil au lieu de croire.
 *
 * « Pas rattachable » est une réponse **normale**, pas un échec : la moitié de
 * ce qu'une enseignante note n'est pas une observation d'apprentissage. On le
 * dit, on ne pousse pas à rattacher quand même.
 *
 * Et rien n'est jamais coché d'avance. La machine propose, l'enseignante décide.
 */
export default function Ranger() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { id } = useLocalSearchParams<{ id: string }>();
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;

  const [eleveId, setEleveId] = useState<string | null>(null);
  const [recherche, setRecherche] = useState('');
  const [chercheManuellement, setChercheManuellement] = useState(false);
  const [choisis, setChoisis] = useState<string[]>([]);
  const [niveau, setNiveau] = useState<Niveau>('in_progress');
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);

  const observations = useRequete(() => observationsDe(classeId!, 100), [classeId], {
    actif: !!classeId,
  });
  const eleves = useRequete(() => elevesDe(classeId!), [classeId], { actif: !!classeId });

  const observation = (observations.donnees ?? []).find((o) => o.id === id) ?? null;
  const eleveRetenu = eleveId ?? observation?.eleveId ?? null;

  // L'IA relit l'observation dès l'ouverture. C'est le geste le plus répété de
  // l'app : s'il coûte quatre gestes il ne se fera pas, s'il coûte un tap il se
  // fera. La recherche à la main reste là, en issue de secours.
  const suggestion = useRequete(
    () =>
      proposerAttendus({
        classe: classe!,
        texte: observation!.texte,
        eleves: eleves.donnees ?? [],
      }),
    [classe?.id, observation?.id, (eleves.donnees ?? []).length],
    { actif: !!classe && !!observation?.texte && !eleves.chargement },
  );

  const resultats = useRequete(
    () => chercherAttendus({ classe: classe!, recherche }),
    [classe?.id, recherche],
    { actif: !!classe && recherche.trim().length >= 3 },
  );

  // Les attendus proposés d'un côté, ceux trouvés à la main de l'autre : les
  // deux alimentent la même sélection, donc on garde un index commun.
  const attendusConnus = useMemo(() => {
    const table = new Map<string, Attendu>();
    for (const p of suggestion.donnees?.propositions ?? []) table.set(p.attendu.id, p.attendu);
    for (const a of resultats.donnees ?? []) table.set(a.id, a);
    return table;
  }, [suggestion.donnees, resultats.donnees]);

  const dejaVus = useRequete(() => attendusDejaVus(eleveRetenu!), [eleveRetenu], {
    actif: !!eleveRetenu,
  });

  const optionsEleves = useMemo(
    () =>
      (eleves.donnees ?? []).map((e) => ({
        id: e.id,
        libelle: e.initialeNom ? `${e.prenom} ${e.initialeNom}.` : e.prenom,
      })),
    [eleves.donnees],
  );

  async function valider() {
    if (!observation || !eleveRetenu || !classe) return;
    setErreur(null);
    setOccupe(true);
    try {
      await rangerObservation({
        observationId: observation.id,
        eleveId: eleveRetenu,
        attendusIds: choisis,
        niveau,
        anneeScolaire: classe.anneeScolaire,
        activiteId: observation.activiteId,
      });
      router.back();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.ranger.erreur);
    } finally {
      setOccupe(false);
    }
  }

  // Sortir la note de la file sans la rattacher : ni élève ni attendu requis.
  // C'est la sortie pour tout ce qui n'est pas une observation d'apprentissage.
  // `suivi` distingue une note qu'on garde en vue (« à suivre ») d'une note
  // d'organisation qu'on classe et oublie (retour Valentin 24/08).
  async function classer(suivi: boolean) {
    if (!observation) return;
    setErreur(null);
    setOccupe(true);
    try {
      await classerSansRattacher(observation.id, suivi);
      router.back();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.ranger.erreur);
    } finally {
      setOccupe(false);
    }
  }

  return (
    <SousEcran titre={t.ranger.titre} chargement={observations.chargement}>
      {/* Le mot d'aide, une seule fois : cocher l'attendu, ou classer sans lier. */}
      <CoachMark id="ranger" message={t.coach.ranger} pose="loupe" />

      {!observation ? (
        <Carte>
          <Text style={texte.discret}>{t.ranger.introuvable}</Text>
        </Carte>
      ) : (
        <>
          <Carte>
            <Text style={texte.discret}>{t.ranger.observation}</Text>
            {observation.texte ? <Text style={texte.corps}>{observation.texte}</Text> : null}
            {/* Les photos jointes : sans elles, une observation photo-seule se
                rangerait à l'aveugle. */}
            <VignettesMedias observationId={observation.id} etiquette={!observation.texte} />
          </Carte>

          <Carte>
            <Pastilles
              etiquette={t.ranger.eleve}
              options={optionsEleves}
              choisi={eleveRetenu}
              onChoisir={setEleveId}
            />
            {!eleveRetenu ? <Text style={styles.note}>{t.ranger.eleveObligatoire}</Text> : null}
          </Carte>

          {/* Les propositions de la machine, avant la recherche à la main. */}
          {suggestion.chargement ? (
            <Carte>
              <View style={styles.ligneAttente}>
                <ActivityIndicator color={c.encreDouce} />
                <Text style={texte.discret}>{t.ranger.enRecherche}</Text>
              </View>
            </Carte>
          ) : null}

          {suggestion.erreur ? <Alerte message={t.ranger.proposerErreur} /> : null}

          {suggestion.donnees && !suggestion.donnees.rattachable ? (
            <Carte>
              <Text style={texte.section}>{t.ranger.pasRattachable}</Text>
              <Text style={texte.discret}>
                {suggestion.donnees.raison ??
                  t.ranger.natures[suggestion.donnees.nature] ??
                  t.ranger.natures.autre}
              </Text>
              {/* Il n'y a rien à cocher ici : la sortie, c'est classer. Deux
                  façons de le faire (retour Valentin 24/08) : « à suivre » garde
                  la note en vue, « juste classer » la range et l'oublie. */}
              <Text style={styles.note}>{t.ranger.suiviAide}</Text>
              <BoutonPrincipal
                libelle={t.ranger.marquerSuivi}
                onPress={() => classer(true)}
                occupe={occupe}
              />
              <BoutonSecondaire
                libelle={t.ranger.classerSimple}
                onPress={() => classer(false)}
                occupe={occupe}
              />
            </Carte>
          ) : null}

          {suggestion.donnees?.propositions.length ? (
            <Carte>
              <Text style={texte.discret}>{t.ranger.propositions}</Text>
              {suggestion.donnees.propositions.map((p) => {
                const actif = choisis.includes(p.attendu.id);
                const vu = dejaVus.donnees?.has(p.attendu.id) ?? false;
                return (
                  <Pressable
                    key={p.attendu.id}
                    accessibilityRole="button"
                    accessibilityState={{ selected: actif }}
                    accessibilityLabel={`${p.attendu.libelle}, ${p.attendu.domaine}`}
                    onPress={() =>
                      setChoisis((liste) =>
                        actif ? liste.filter((x) => x !== p.attendu.id) : [...liste, p.attendu.id],
                      )
                    }
                    style={[styles.attendu, actif && styles.attenduActif]}>
                    <View style={[styles.coche, actif && styles.cocheActive]}>
                      {actif ? <Feather name="check" size={16} color={c.surface} /> : null}
                    </View>
                    <View style={styles.corpsAttendu}>
                      <Text style={texte.corps}>{p.attendu.libelle}</Text>
                      <Text style={texte.discret}>
                        {[p.attendu.domaine, p.attendu.code].filter(Boolean).join(' · ')}
                      </Text>
                      {/* La citation est la preuve. Si elle ne se retrouve pas
                          dans le texte, on le dit au lieu de la présenter
                          comme une justification. */}
                      {p.citation ? (
                        <Text style={p.citationVerifiee ? styles.citation : styles.citationDouteuse}>
                          {p.citationVerifiee
                            ? t.ranger.citation(p.citation)
                            : t.ranger.citationDouteuse}
                        </Text>
                      ) : null}
                      {vu ? <Text style={styles.dejaVu}>{t.ranger.dejaVu}</Text> : null}
                    </View>
                    {/* Confiance moyenne : un point creux plutôt qu'un mot,
                        la nuance se lit sans se justifier. */}
                    <View
                      style={[
                        styles.confiance,
                        p.confiance === 'haute' && styles.confianceHaute,
                      ]}
                    />
                  </Pressable>
                );
              })}
            </Carte>
          ) : null}

          {!chercheManuellement && !suggestion.chargement ? (
            <BoutonDiscret
              libelle={t.ranger.chercherQuandMeme}
              onPress={() => setChercheManuellement(true)}
            />
          ) : null}

          {chercheManuellement ? (
          <Carte>
            <Champ
              etiquette={t.ranger.recherche}
              value={recherche}
              onChangeText={setRecherche}
              placeholder={t.ranger.rechercheIndice}
              autoCorrect={false}
              autoFocus
              editable={!occupe}
            />
            {recherche.trim().length > 0 && recherche.trim().length < 3 ? (
              <Text style={styles.note}>{t.ranger.rechercheCourte}</Text>
            ) : null}
            {resultats.chargement ? <ActivityIndicator color={c.encreDouce} /> : null}
            {resultats.donnees?.length === 0 && recherche.trim().length >= 3 ? (
              <Text style={styles.note}>{t.ranger.aucunResultat}</Text>
            ) : null}

            {(resultats.donnees ?? []).map((a) => {
              const actif = choisis.includes(a.id);
              const vu = dejaVus.donnees?.has(a.id) ?? false;
              return (
                <Pressable
                  key={a.id}
                  accessibilityRole="button"
                  accessibilityState={{ selected: actif }}
                  onPress={() =>
                    setChoisis((liste) =>
                      actif ? liste.filter((x) => x !== a.id) : [...liste, a.id],
                    )
                  }
                  style={[styles.attendu, actif && styles.attenduActif]}>
                  <View style={[styles.coche, actif && styles.cocheActive]}>
                    {actif ? <Feather name="check" size={16} color={c.surface} /> : null}
                  </View>
                  <View style={styles.corpsAttendu}>
                    <Text style={texte.corps}>{a.libelle}</Text>
                    <Text style={texte.discret}>
                      {a.domaine}
                      {a.competence ? ` · ${a.competence}` : ''}
                    </Text>
                    {vu ? <Text style={styles.dejaVu}>{t.ranger.dejaVu}</Text> : null}
                  </View>
                </Pressable>
              );
            })}
          </Carte>
          ) : null}

          <Carte>
            <Pastilles
              etiquette={t.ranger.niveau}
              options={(['not_started', 'in_progress', 'acquired'] as Niveau[]).map((n) => ({
                id: n,
                libelle: niveauxMaitrise[n],
              }))}
              choisi={niveau}
              onChoisir={(v) => setNiveau((v as Niveau) ?? 'in_progress')}
            />
          </Carte>

          {erreur ? <Alerte message={erreur} /> : null}
          {choisis.length ? (
            <Text style={styles.compte}>{t.ranger.choisis(choisis.length)}</Text>
          ) : null}

          <BoutonPrincipal
            libelle={t.ranger.valider}
            onPress={valider}
            occupe={occupe}
            inactif={!eleveRetenu || choisis.length === 0}
          />

          {/* Filet de sécurité : tant que rien n'est coché, on peut toujours
              sortir la note de la file sans la rattacher. « À suivre » pour la
              garder en vue, « juste classer » pour la ranger. Personne ne reste
              coincé, même quand l'IA n'a rien proposé. */}
          {choisis.length === 0 && !suggestion.chargement ? (
            <>
              <BoutonSecondaire
                libelle={t.ranger.marquerSuivi}
                onPress={() => classer(true)}
                occupe={occupe}
              />
              <BoutonDiscret libelle={t.ranger.classerSimple} onPress={() => classer(false)} />
            </>
          ) : null}
        </>
      )}
    </SousEcran>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  note: { fontFamily: police.corps, fontSize: 14, color: c.encreDouce },
  attendu: {
    flexDirection: 'row',
    gap: espace.md,
    alignItems: 'flex-start',
    backgroundColor: c.fond,
    borderRadius: rayon.bloc,
    borderWidth: 1,
    borderColor: c.bord,
    padding: espace.md,
  },
  attenduActif: { borderColor: c.actif, backgroundColor: c.surface, ...ombre.carte },
  coche: {
    width: 24,
    height: 24,
    borderRadius: 8,
    borderWidth: 2,
    borderColor: c.bord,
    alignItems: 'center',
    justifyContent: 'center',
    marginTop: 2,
  },
  cocheActive: { backgroundColor: c.actif, borderColor: c.actif },
  corpsAttendu: { flex: 1, gap: espace.xs },
  dejaVu: { fontFamily: police.accent, fontSize: 13, color: c.moment.recreation },
  citation: { fontFamily: police.corps, fontSize: 13, color: c.encreDouce, fontStyle: 'italic' },
  citationDouteuse: { fontFamily: police.accent, fontSize: 13, color: c.action[1] },
  ligneAttente: { flexDirection: 'row', gap: espace.md, alignItems: 'center' },
  confiance: {
    width: 8,
    height: 8,
    borderRadius: 4,
    borderWidth: 2,
    borderColor: c.nonRattache,
    marginTop: 6,
  },
  confianceHaute: { backgroundColor: c.actif, borderColor: c.actif },
  compte: { fontFamily: police.accent, fontSize: 15, color: c.encreDouce, textAlign: 'center' },
});
