import { Feather } from '@expo/vector-icons';
import { BlurView } from 'expo-blur';
import * as Haptics from 'expo-haptics';
import { router, usePathname, type Href } from 'expo-router';
import { useEffect, useMemo } from 'react';
import { Platform, Pressable, StyleSheet, Text, useWindowDimensions, View } from 'react-native';
import Animated, {
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withSpring,
} from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { t } from '@/i18n';
import { NAV_AVATAR } from '@/lib/flags';
import { maxContenu, motion, pointLarge, police, useCouleurs, useTheme, type Couleurs } from '@/theme/tokens';

/**
 * Le sous-ensemble des props de barre d'onglets qu'on utilise réellement.
 * Typé à la main plutôt qu'importé d'un chemin interne d'expo-router : ça
 * découple la barre de la version exacte du routeur.
 */
type Route = { key: string; name: string };
export type NavProps = {
  state: { index: number; routes: Route[] };
  descriptors: Record<string, { options: { title?: string; tabBarAccessibilityLabel?: string } }>;
  navigation: {
    emit(e: { type: 'tabPress'; target: string; canPreventDefault: true }): {
      defaultPrevented: boolean;
    };
    navigate(name: string): void;
  };
};

/**
 * La barre d'onglets flottante en verre dépoli du témoin v9.
 *
 * 🔑 Deux écarts au code précédent, corrigés en revenant au témoin :
 * 1. La barre FLOTTE. Elle ne colle pas au bord, elle a des coins arrondis et
 *    laisse voir le fond à travers un verre dépoli translucide. Une barre
 *    opaque pleine largeur écrasait le bas de chaque écran.
 * 2. Capter est un onglet PLAT comme les autres, avec une icône de micro. Le
 *    gros bouton dégradé surélevé n'existe pas dans la barre du témoin : le
 *    dégradé vit sur l'écran Capter (le bouton de dictée), une seule fois par
 *    écran comme le veut la charte.
 */
const ICONES: Record<string, keyof typeof Feather.glyphMap> = {
  index: 'home',
  journal: 'book-open',
  capter: 'mic',
  groupes: 'users',
  vous: 'smile',
};

/** Un onglet prêt à peindre, indépendant de la source (Tabs ou routeur web). */
type ItemNav = {
  cle: string;
  libelle: string;
  icone: keyof typeof Feather.glyphMap;
  accessibilityLabel: string;
  actif: boolean;
  onPress: () => void;
  onLongPress?: () => void;
};

/**
 * Le rendu pur de la barre flottante, sans savoir d'où viennent les onglets.
 *
 * On l'a extrait pour que deux sources la peignent à l'identique : la barre des
 * onglets (props de navigation) et la barre web posée sur les écrans poussés
 * (routeur). `transparent` allège le verre : sur un écran empilé, la barre se
 * fait plus discrète pour laisser lire le contenu sous elle.
 */
function BarreFlottante({
  items,
  transparent = false,
}: {
  items: ItemNav[];
  transparent?: boolean;
}) {
  const insets = useSafeAreaInsets();
  const c = useCouleurs();
  const { schema } = useTheme();
  const styles = useMemo(() => creerStyles(c, schema), [c, schema]);
  // Grands écrans : au lieu d'un long ruban pleine largeur, une pastille centrée
  // et plafonnée. Sous le seuil (tout téléphone), rien ne change : la barre garde
  // son étirement d'un bord à l'autre.
  const { width } = useWindowDimensions();
  const large = width > pointLarge;
  return (
    <View
      style={[styles.socle, large && styles.socleLarge, { bottom: Math.max(insets.bottom, 14) }]}
      pointerEvents="box-none">
      <BlurView
        intensity={transparent ? 24 : 40}
        tint={schema === 'sombre' ? 'dark' : 'light'}
        style={[styles.barre, transparent && styles.barreTransparente, large && styles.barreLarge]}>
        {items.map((item) => (
          <NavItem
            key={item.cle}
            actif={item.actif}
            libelle={item.libelle}
            icone={item.icone}
            accessibilityLabel={item.accessibilityLabel}
            onPress={item.onPress}
            onLongPress={item.onLongPress}
          />
        ))}
      </BlurView>
    </View>
  );
}

export function NavVerre({ state, descriptors, navigation }: NavProps) {
  // 🧭 Drapeau NAV_AVATAR ON : « Moi » quitte la barre du bas (elle passe de 5 à
  // 4, la place libérée reste vide). La route `vous` est masquée par `href:null`
  // dans le layout, mais un tabBar sur-mesure lit tout `state.routes` : on la
  // retire donc explicitement ici. OFF : aucun filtre, barre identique à
  // aujourd'hui. On garde l'index d'origine pour que `state.index` (actif) reste
  // juste après le filtrage.
  const items: ItemNav[] = state.routes
    .map((route, index) => ({ route, index }))
    .filter(({ route }) => !(NAV_AVATAR && route.name === 'vous'))
    .map(({ route, index }) => {
    const { options } = descriptors[route.key];
    const actif = state.index === index;
    const libelle = typeof options.title === 'string' ? options.title : route.name;

    const onPress = () => {
      const evenement = navigation.emit({
        type: 'tabPress',
        target: route.key,
        canPreventDefault: true,
      });
      if (!actif && !evenement.defaultPrevented) {
        // Un petit accusé de sélection au doigt, le même que celui des
        // sélecteurs natifs : on sent qu'on a changé d'onglet.
        Haptics.selectionAsync().catch(() => {});
        navigation.navigate(route.name);
      }
    };

    // Appui LONG sur l'onglet micro : la capture rapide, ouverte de partout. La
    // barre étant sur tous les écrans d'onglets, le geste rend la capture
    // accessible de n'importe où. L'appui court garde son comportement (aller
    // sur l'onglet Capter). Une haptique légère accuse le geste long, distincte
    // de la sélection d'onglet.
    const onLongPress =
      route.name === 'capter'
        ? () => {
            Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light).catch(() => {});
            router.push('/capter-vite');
          }
        : undefined;

    return {
      cle: route.key,
      libelle,
      icone: ICONES[route.name] ?? 'circle',
      accessibilityLabel: options.tabBarAccessibilityLabel ?? libelle,
      actif,
      onPress,
      onLongPress,
    };
  });
  return <BarreFlottante items={items} />;
}

// Les onglets, dans l'ordre de `(tabs)/_layout.tsx`, avec leur chemin de route.
// C'est la source de la barre web posée sur les écrans poussés.
const ONGLETS_WEB: { nom: keyof typeof ICONES; chemin: Href }[] = [
  { nom: 'index', chemin: '/' },
  { nom: 'journal', chemin: '/journal' },
  { nom: 'capter', chemin: '/capter' },
  { nom: 'groupes', chemin: '/groupes' },
  { nom: 'vous', chemin: '/vous' },
];

// Les chemins des onglets eux-mêmes : sur ces écrans, la barre des onglets est
// déjà rendue par le `Tabs`, on ne la double pas.
const CHEMINS_ONGLETS = new Set(ONGLETS_WEB.map((o) => String(o.chemin)));

// Les écrans hors coquille d'app : connexion, onboarding, paywall, tours plein
// cadre et modales de fête. Une barre de navigation vers les onglets n'y a pas
// de sens (on n'y « navigue » pas, on en sort), on ne la pose donc pas.
// Comparés en « exact OU enfant » : `/abonnement` couvre aussi `/abonnement/x`.
const PREFIXES_SANS_BARRE = [
  '/connexion',
  '/bienvenue',
  '/intro',
  '/guide',
  '/abonnement',
  '/capter-vite',
  '/celebration',
  '/trophee-celebration',
  // La démonstration direction s'ouvre SANS compte : une barre vers des onglets
  // qu'on ne peut pas ouvrir n'y aurait aucun sens.
  '/direction/demo',
  '/direction/demo-miroir',
  // La création d'observation est une MODALE : un écran qu'on remplit et dont on
  // sort, pas un lieu où l'on navigue. Chemin exact, sans enfant.
  '/activite/nouvelle',
];

// 🌐 LE DOUBLON DE BARRE, ET SA CAUSE. Les écrans présentés en `modal` (créer /
// modifier / clôturer une activité, ranger une note) ne couvrent PAS la colonne
// sur le web : ils s'ouvrent en carte, l'écran d'onglet reste visible derrière
// AVEC sa propre barre (le `Tabs` la peint). Si on posait AUSSI la barre
// flottante par-dessus la modale, on en voyait deux. Et de toute façon, sauter
// vers un onglet depuis une modale à remplir n'a pas de sens : on la termine ou
// on la ferme. On efface donc la barre sur ces modales.
//
// ⚠️ Ces routes ont un segment dynamique (`/activite/modifier/<id>`), donc on
// matche l'ENFANT seulement (`startsWith(p + '/')`), jamais l'exact : `/ranger`
// est l'index « À ranger » (un vrai écran poussé, plein cadre, qui GARDE la
// barre), tandis que `/ranger/<id>` est la modale de rangement.
const MODALES_ENFANTS = ['/activite/modifier', '/activite/cloturer', '/ranger'];

/**
 * La barre flottante, mais posée PARTOUT sur le web, y compris sur les écrans
 * poussés (leçon, activité, etc.).
 *
 * 🌐 Web seulement, et pour une raison d'usage : sur le web, chaque écran qui
 * monte du bas s'empile, et l'on devait cliquer plusieurs fois la flèche retour
 * pour revenir naviguer. En gardant la barre visible et translucide sur ces
 * écrans, on rend la navigation directe : un clic sur un onglet y mène, au lieu
 * d'empiler les retours. Sur natif, rien de tout ça : la barre reste strictement
 * celle des onglets, ce composant ne s'y monte jamais (le layout le garde par
 * `Platform.OS`).
 *
 * Elle ne s'affiche pas sur les écrans d'onglets (le `Tabs` y peint déjà sa
 * barre) ni sur les écrans hors coquille (connexion, paywall, tours plein
 * cadre) : y router vers un onglet n'aurait pas de sens. Aucun onglet n'est
 * marqué « actif » : sur un écran poussé, on n'est dans aucun onglet, la barre
 * est un raccourci de sortie, pas un indicateur d'onglet courant.
 */
export function NavFlottanteWeb() {
  const chemin = usePathname();

  // On ne double pas la barre des onglets, et on s'efface des écrans hors
  // coquille. On calcule ces gardes après les Hooks pour ne pas en sauter.
  const surOnglet = CHEMINS_ONGLETS.has(chemin);
  const horsCoquille = PREFIXES_SANS_BARRE.some(
    (p) => chemin === p || chemin.startsWith(`${p}/`),
  );
  // Les modales à segment dynamique : enfant seulement, pour épargner l'index.
  const surModale = MODALES_ENFANTS.some((p) => chemin.startsWith(`${p}/`));
  if (surOnglet || horsCoquille || surModale) return null;

  const libelles: Record<string, string> = {
    index: t.onglets.accueil,
    journal: t.onglets.journal,
    capter: t.onglets.capter,
    groupes: t.onglets.groupes,
    vous: t.onglets.vous,
  };

  const items: ItemNav[] = ONGLETS_WEB.filter(
    // 🧭 Même règle que la barre native : drapeau ON, « Moi » n'est plus un
    // onglet, on ne le peint pas dans la barre posée sur les écrans web. (On
    // garde `vous` dans `CHEMINS_ONGLETS` : sur l'écran /vous lui-même, le Tabs
    // peint déjà sa barre, on ne la double pas.)
    (o) => !(NAV_AVATAR && o.nom === 'vous'),
  ).map((o) => ({
    cle: o.nom,
    libelle: libelles[o.nom],
    icone: ICONES[o.nom],
    // Sur l'onglet micro, on garde le libellé d'accessibilité dédié, comme la
    // barre des onglets (`tabBarAccessibilityLabel`).
    accessibilityLabel: o.nom === 'capter' ? t.capter.bouton : libelles[o.nom],
    // Sur un écran poussé, aucun onglet n'est courant : la barre est un raccourci.
    actif: false,
    // `navigate` rejoint l'onglet en dépilant l'écran poussé, sans l'empiler.
    onPress: () => router.navigate(o.chemin),
    onLongPress: o.nom === 'capter' ? () => router.push('/capter-vite') : undefined,
  }));

  return <BarreFlottante items={items} transparent />;
}

/**
 * Un onglet. L'onglet actif prend un micro-agrandissement (scale 1.06) : rien de
 * criard, juste assez pour que l'œil sente lequel est ouvert, en plus de la
 * couleur. Sous « réduire les animations », il ne grossit pas.
 */
function NavItem({
  actif,
  libelle,
  icone,
  accessibilityLabel,
  onPress,
  onLongPress,
}: {
  actif: boolean;
  libelle: string;
  icone: keyof typeof Feather.glyphMap;
  accessibilityLabel: string;
  onPress: () => void;
  /** Appui long facultatif, pour la capture rapide sur l'onglet micro. */
  onLongPress?: () => void;
}) {
  const c = useCouleurs();
  const { schema } = useTheme();
  const styles = useMemo(() => creerStyles(c, schema), [c, schema]);
  const reduire = useReducedMotion();
  const echelle = useSharedValue(actif ? motion.echelle.actif : 1);
  useEffect(() => {
    const cible = actif ? motion.echelle.actif : 1;
    echelle.value = reduire ? cible : withSpring(cible, motion.ressort.vif);
  }, [actif, reduire, echelle]);
  const styleAnime = useAnimatedStyle(() => ({ transform: [{ scale: echelle.value }] }));

  return (
    <Pressable
      accessibilityRole="tab"
      accessibilityState={{ selected: actif }}
      accessibilityLabel={accessibilityLabel}
      onPress={onPress}
      onLongPress={onLongPress}
      style={[styles.item, actif && styles.itemActif]}>
      <Animated.View style={[styles.itemContenu, styleAnime]}>
        <Feather name={icone} size={20} color={actif ? c.encre : c.nonRattache} />
        <Text style={[styles.libelle, actif && styles.libelleActif]}>{libelle}</Text>
      </Animated.View>
    </Pressable>
  );
}

const creerStyles = (c: Couleurs, schema: 'clair' | 'sombre') => {
  const sombre = schema === 'sombre';
  return StyleSheet.create({
    socle: { position: 'absolute', left: 14, right: 14, alignItems: 'stretch' },
    // Grands écrans : on centre la barre et on la plafonne (pastille centrée).
    socleLarge: { alignItems: 'center' },
    barreLarge: { width: '100%', maxWidth: maxContenu },
    barre: {
      flexDirection: 'row',
      alignItems: 'center',
      height: 64,
      borderRadius: 24,
      paddingHorizontal: 6,
      overflow: 'hidden',
      borderWidth: 1,
      // Un liseré clair fait le reflet du verre au clair ; sur nuit, un liseré
      // clair très discret dessine encore l'arête sans éblouir.
      borderColor: sombre ? 'rgba(255,255,255,0.12)' : 'rgba(255,255,255,0.9)',
      // Sur Android le flou d'expo-blur est limité : un fond translucide plus
      // opaque garde la barre lisible sans compter uniquement sur le verre. Sur
      // nuit, le verre est teinté de la surface sombre plutôt que du blanc.
      backgroundColor: sombre
        ? Platform.OS === 'android'
          ? 'rgba(34,31,48,0.94)'
          : 'rgba(34,31,48,0.6)'
        : Platform.OS === 'android'
          ? 'rgba(255,255,255,0.94)'
          : 'rgba(255,255,255,0.55)',
      shadowColor: '#171622',
      shadowOpacity: sombre ? 0.4 : 0.14,
      shadowRadius: 30,
      shadowOffset: { width: 0, height: 12 },
      elevation: 12,
    },
    // La variante posée sur les écrans poussés (web) : un verre plus translucide,
    // pour se faire discrète au-dessus du contenu tout en restant lisible grâce
    // au liseré et au flou. On ne descend pas plus bas en opacité : sous un
    // certain seuil, les libellés deviendraient illisibles sur un fond clair.
    barreTransparente: {
      backgroundColor: sombre ? 'rgba(34,31,48,0.42)' : 'rgba(255,255,255,0.38)',
    },
    item: {
      flex: 1,
      alignItems: 'center',
      justifyContent: 'center',
      paddingVertical: 8,
      borderRadius: 18,
    },
    itemContenu: { alignItems: 'center', justifyContent: 'center', gap: 4 },
    // La pastille de l'onglet ouvert : une encre discrète au clair, une lumière
    // discrète sur nuit (l'inverse, pour rester visible sur chaque fond).
    itemActif: { backgroundColor: sombre ? 'rgba(255,255,255,0.08)' : 'rgba(23,22,34,0.06)' },
    libelle: { fontFamily: police.accent, fontSize: 9.5, color: c.nonRattache },
    libelleActif: { color: c.encre },
  });
};
