import { Platform, Share } from 'react-native';

import { t } from '@/i18n';

import { supabase } from './supabase';

/**
 * La couche données du PARRAINAGE.
 *
 * Terme unique côté user : « parrainage », jamais « affiliation » (mal compris
 * en BE/FR). Le modèle, tranché par Valentin le 21/08 :
 *  - marraine/parrain : 10 € par filleul·e ABONNÉ·E PAYANT·E, sans plafond. Ce
 *    n'est pas un pourcentage de remise (mal compris), c'est un montant en euros
 *    tangible. Le crédit tombe au paiement réel, jamais à l'inscription.
 *  - « la manne » : la cagnotte que le·la user accumule (10 € par filleule qui
 *    paie). On CONSTRUIT le suivi maintenant ; le VERSEMENT réel est « en cours
 *    de construction pour plus tard », assumé et affiché honnêtement. Plus tard,
 *    la manne sera dépensable chez des offres partenaires.
 *  - filleul·e : -5 € s'il/elle s'abonne avant la fin de l'essai (géré ailleurs,
 *    via un offering RevenueCat et un bandeau à compteur — hors de ce fichier).
 *
 * 🚨 Les tables backend (`referral_codes` / `referrals` / `referral_rewards` /
 * `referral_events`) NE SONT PAS ENCORE DÉPLOYÉES. On ne peut donc pas planter :
 * on détecte l'absence de table (sentinelle PostgREST) et on dégrade proprement
 * vers un écran « bientôt » plutôt que vers un crash. Le jour où le socle de la
 * session build/stores est en place, ce fichier se met à renvoyer de vraies
 * données sans une ligne à changer.
 */

/** La base des liens de partage. Le CODE se colle derrière. */
export const LIEN_BASE = 'https://educooo.com/r/';

/**
 * Le cycle de vie d'une filleule, tel qu'on peut l'AFFICHER honnêtement.
 *
 * `invite` et `clic` sont ANONYMES (un clic n'a pas d'identité tant que la
 * personne ne s'est pas inscrite avec le code), donc ils ne donnent jamais une
 * ligne nominative : ils vivent dans un compteur agrégé (voir `Parrainage.clics`).
 * Les lignes nommées commencent à `inscrit`. On ne promet pas plus que ce que
 * la donnée permet de tenir.
 */
export type EtatFilleul = 'inscrit' | 'essai' | 'abonne' | 'expire';

export type Filleul = {
  id: string;
  /**
   * Le nom affiché de la filleule, ou null. Ne sort de la base que parce que la
   * relation de parrainage est explicite et mutuelle (elle a saisi ton code) ;
   * aucune donnée d'élève n'est jamais touchée par le parrainage.
   */
  nom: string | null;
  etat: EtatFilleul;
  /** Date de bascule la plus parlante (conversion si payée, sinon inscription). */
  depuis: string | null;
  /** Vrai dès que les 10 € sont ACQUIS (elle a payé). */
  recompenseAcquise: boolean;
};

/**
 * La manne : la cagnotte du·de la user.
 *
 * Trois montants distincts, parce que l'honnêteté du produit tient à ne pas
 * confondre « gagné » et « versé » : le versement n'existe pas encore.
 */
export type Manne = {
  /** Total ACQUIS en euros (tout ce qui t'appartient, versé ou non). */
  acquis: number;
  /** En euros, ce qui attend d'être versé (« en construction pour plus tard »). */
  aRecevoir: number;
  /** En euros, ce qui a RÉELLEMENT été versé. Zéro tant que le versement n'existe pas. */
  recu: number;
  /** Nombre de filleul·es payantes qui ont crédité la manne. */
  nbFilleulesPayantes: number;
};

/** Ce que l'écran de parrainage lit d'un coup. */
export type Parrainage = {
  /** Le code du·de la user, ou null s'il n'en a pas encore (généré à l'abonnement). */
  code: string | null;
  /** Le lien prêt à partager, ou null sans code. */
  lien: string | null;
  /** Compteur agrégé de clics sur le lien (anonyme, avant toute inscription). */
  clics: number;
  filleuls: Filleul[];
  manne: Manne;
  /**
   * Vrai si le·la user a DÉJÀ saisi un code de parrainage (first-touch posé).
   * Sert à cacher l'entrée « j'ai un code » : proposer de re-saisir un code à
   * qui en a déjà un serait une fausse promesse, la RPC le refuserait.
   */
  dejaParrainee: boolean;
};

/**
 * Vrai si l'erreur PostgREST dit « cette table n'existe pas / pas dans le cache
 * de schéma ». C'est notre SENTINELLE : le socle backend n'est pas encore
 * déployé, on bascule sur l'écran « bientôt » au lieu de crasher.
 *
 * On couvre les deux mondes : le code SQL brut (`42P01`, undefined_table) et les
 * codes PostgREST (`PGRST205` table introuvable, `PGRST202` fonction introuvable),
 * plus un repli par message pour ne rien laisser passer.
 */
export function tableAbsente(erreur: unknown): boolean {
  const e = erreur as { code?: string; message?: string } | null;
  if (!e) return false;
  const code = e.code ?? '';
  if (code === '42P01' || code === 'PGRST205' || code === 'PGRST202') return true;
  const msg = (e.message ?? '').toLowerCase();
  return (
    msg.includes('does not exist') ||
    msg.includes('could not find the table') ||
    msg.includes('schema cache')
  );
}

/** L'identifiant du·de la user connecté·e. C'est aussi l'`app_user_id` RevenueCat. */
async function moiId(): Promise<string> {
  const { data } = await supabase.auth.getUser();
  const id = data.user?.id;
  if (!id) throw new Error('Pas de session : le parrainage est indisponible.');
  return id;
}

/**
 * Le code de parrainage du·de la user, ou null.
 *
 * Un code est généré côté serveur à l'abonnement (voir contrat backend) : un·e
 * user sans code (pas encore abonné·e, ou code pas encore posé) reçoit null, ce
 * n'est pas une erreur.
 */
export async function monCode(): Promise<string | null> {
  const id = await moiId();
  const { data, error } = await supabase
    .from('referral_codes')
    .select('code')
    .eq('owner_id', id)
    .eq('active', true)
    .maybeSingle();
  if (error) throw error;
  return data?.code ?? null;
}

/** `signup → inscrit`, `trial → essai`, `paid/rewarded → abonne`, `churn → expire`. */
function etatDeStatut(statut: string | null): EtatFilleul {
  switch (statut) {
    case 'trial':
      return 'essai';
    case 'paid':
    case 'rewarded':
      return 'abonne';
    case 'churn':
      return 'expire';
    // 'signup' et tout inattendu retombent sur « inscrit » : une ligne existe,
    // donc la personne s'est au moins inscrite avec le code.
    default:
      return 'inscrit';
  }
}

/**
 * Mes filleul·es, les plus récentes d'abord.
 *
 * Le filtre `referrer_id` est explicite ici, à la différence du reste de l'app
 * qui s'en remet à la protection par ligne : ces tables sont neuves et leur RLS
 * fait partie du contrat que cette session pose pour la session build. Filtrer
 * en clair rend la lecture évidente et ne coûte rien.
 *
 * La jointure vers `profiles` est désambiguïsée par la COLONNE (`referee_id`) et
 * non par le nom de contrainte : il y a deux liens vers `profiles` (parrain·e et
 * filleule), et pointer la colonne est plus stable qu'un nom de contrainte deviné.
 */
export async function mesFilleuls(): Promise<Filleul[]> {
  const id = await moiId();
  const { data, error } = await supabase
    .from('referrals')
    .select('id, status, signed_up_at, converted_at, referee:profiles!referee_id(display_name)')
    .eq('referrer_id', id)
    .order('signed_up_at', { ascending: false });
  if (error) throw error;
  return (data ?? []).map((r) => {
    // PostgREST rend l'embed en objet (un seul parent) ou en tableau selon la
    // cardinalité inférée : on tolère les deux pour ne pas dépendre de ce détail.
    const referee = r.referee as { display_name?: string | null } | { display_name?: string | null }[] | null;
    const nom = Array.isArray(referee) ? (referee[0]?.display_name ?? null) : (referee?.display_name ?? null);
    return {
      id: r.id as string,
      nom,
      etat: etatDeStatut(r.status as string | null),
      depuis: (r.converted_at as string | null) ?? (r.signed_up_at as string | null) ?? null,
      recompenseAcquise: r.status === 'paid' || r.status === 'rewarded',
    };
  });
}

/**
 * La manne du·de la user.
 *
 * On ne lit que les récompenses `referrer_cash` (les 10 €) dont le·la user est
 * bénéficiaire. `due` = à recevoir (pas encore versé), `paid` = réellement versé,
 * `granted` = crédit accordé (option future). L'acquis est la somme des trois :
 * tout ce qui appartient au·à la user, versé ou non.
 */
export async function maManne(): Promise<Manne> {
  const id = await moiId();
  const { data, error } = await supabase
    .from('referral_rewards')
    .select('amount_eur, status')
    .eq('beneficiary_id', id)
    .eq('kind', 'referrer_cash');
  if (error) throw error;
  const lignes = (data ?? []) as { amount_eur: number | string | null; status: string | null }[];
  const somme = (predicat: (l: (typeof lignes)[number]) => boolean) =>
    lignes.filter(predicat).reduce((total, l) => total + Number(l.amount_eur ?? 0), 0);
  const aRecevoir = somme((l) => l.status === 'due');
  const recu = somme((l) => l.status === 'paid');
  const acquis = aRecevoir + recu + somme((l) => l.status === 'granted');
  return { acquis, aRecevoir, recu, nbFilleulesPayantes: lignes.length };
}

/**
 * Vrai si un code de parrainage est déjà posé sur le profil (first-touch).
 *
 * Lecture d'une seule colonne sur `profiles`, protégée par RLS comme le reste :
 * on ne lit que sa propre ligne. Sert à masquer l'entrée « j'ai un code » quand
 * elle n'aurait plus de sens.
 */
export async function estDejaParrainee(): Promise<boolean> {
  const id = await moiId();
  const { data, error } = await supabase
    .from('profiles')
    .select('referred_by_code')
    .eq('id', id)
    .maybeSingle();
  if (error) throw error;
  return Boolean((data as { referred_by_code?: string | null } | null)?.referred_by_code);
}

/** Compte agrégé des clics sur le lien (anonyme). `head` : on ne rapatrie aucune ligne. */
async function compterClics(code: string): Promise<number> {
  const { count, error } = await supabase
    .from('referral_events')
    .select('id', { count: 'exact', head: true })
    .eq('code', code)
    .eq('type', 'click');
  if (error) throw error;
  return count ?? 0;
}

/**
 * Charge tout ce dont l'écran a besoin, en une fois, en absorbant la sentinelle.
 *
 * Renvoie `{ deploye: false }` quand le socle backend manque encore : l'écran
 * montre alors « bientôt » au lieu de planter. Toute AUTRE erreur (réseau, RLS)
 * remonte normalement, pour que `useRequete` l'affiche.
 */
export async function chargerParrainage(): Promise<
  { deploye: true; data: Parrainage } | { deploye: false }
> {
  try {
    const code = await monCode();
    const [filleuls, manne, clics, dejaParrainee] = await Promise.all([
      mesFilleuls(),
      maManne(),
      code ? compterClics(code) : Promise.resolve(0),
      estDejaParrainee(),
    ]);
    return {
      deploye: true,
      data: { code, lien: code ? LIEN_BASE + code : null, clics, filleuls, manne, dejaParrainee },
    };
  } catch (e) {
    if (tableAbsente(e)) return { deploye: false };
    throw e;
  }
}

/**
 * Ouvre la feuille de partage NATIVE (WhatsApp, iMessage, Mail…) avec un message
 * de charte et le lien.
 *
 * `Share` de react-native suffit et n'ajoute aucune dépendance : c'est le bon
 * défaut pour un simple message texte + URL. `expo-sharing` sert à partager des
 * FICHIERS et ne prend pas de message, donc ce n'est pas lui qu'il nous faut.
 *
 * Sur iOS on passe `message` ET `url` séparément (meilleur aperçu de lien) ; sur
 * Android on concatène, la clé `url` y étant ignorée. Renvoie vrai si le partage
 * a bien été effectué (utile plus tard pour journaliser l'état « invitée »).
 */
export async function partagerMonLien(code: string): Promise<boolean> {
  const lien = LIEN_BASE + code;
  const phrase =
    "J'utilise EducooO pour gagner un temps fou sur mes obs et mes bulletins 🌥️ " +
    "Avec mon lien, tu as 5 € de remise si tu t'abonnes pendant ton essai.";
  const resultat = await Share.share(
    Platform.OS === 'ios' ? { message: phrase, url: lien } : { message: `${phrase}\n${lien}` },
    { subject: 'EducooO, mon lien de parrainage' },
  );
  return resultat.action === Share.sharedAction;
}

/**
 * Rattache le·la user connecté·e à un code de parrainage (le geste de la FILLEULE).
 *
 * 🔑 C'est le seul chemin qui déclenche la récompense : sans cet appel, la RPC
 * `rattacher_code_parrainage` n'est jamais sollicitée, la relation ne se crée
 * pas, et la manne de la marraine ne se remplit jamais. Toute la validation vit
 * côté serveur (first-touch immuable, pas d'auto-parrainage, code inconnu
 * refusé) ; ici on ne fait que traduire la `raison` renvoyée en une phrase douce.
 *
 * Idempotent-safe et sans crash : un deuxième essai, son propre code, ou un code
 * inconnu reviennent en `{ ok: false, erreur }`, jamais en exception. L'appel·euse
 * n'a donc qu'à afficher un mot discret. La RPC nettoie déjà le code (trim +
 * majuscules) ; on le fait aussi côté client pour ne rien envoyer d'inutile.
 */
export async function rattacherCode(
  code: string,
): Promise<{ ok: boolean; erreur?: string; raison?: string }> {
  const propre = code.trim().toUpperCase();
  if (!propre) return { ok: false, erreur: t.parrainage.codeErreurGenerique, raison: 'code_vide' };
  try {
    const { data, error } = await supabase.rpc('rattacher_code_parrainage', { p_code: propre });
    // Socle pas encore déployé (sentinelle), réseau, RLS : un mot générique,
    // jamais un crash. On ne distingue pas ces cas pour la filleule. La `raison`
    // reste absente ici : c'est un échec POTENTIELLEMENT transitoire (à réessayer),
    // pas un verdict définitif du serveur.
    if (error) return { ok: false, erreur: t.parrainage.codeErreurGenerique };
    const reponse = data as { ok?: boolean; raison?: string } | null;
    if (reponse?.ok) return { ok: true };
    // On remonte la `raison` du serveur telle quelle en plus du message : le
    // rattachement automatique (code capté sur le web) s'en sert pour savoir s'il
    // doit oublier le code (verdict définitif) ou le regarder plus tard (transitoire).
    switch (reponse?.raison) {
      case 'code_inconnu':
        return { ok: false, erreur: t.parrainage.codeErreurInconnu, raison: 'code_inconnu' };
      case 'auto_parrainage':
        return { ok: false, erreur: t.parrainage.codeErreurAuto, raison: 'auto_parrainage' };
      case 'deja_rattachee':
        return { ok: false, erreur: t.parrainage.codeErreurDeja, raison: 'deja_rattachee' };
      // 'code_vide' (déjà gardé au-dessus) et tout inattendu : mot générique.
      default:
        return { ok: false, erreur: t.parrainage.codeErreurGenerique, raison: reponse?.raison };
    }
  } catch {
    return { ok: false, erreur: t.parrainage.codeErreurGenerique };
  }
}

/**
 * L'alphabet des codes de parrainage (sans les caractères ambigus O/0, I/1, L).
 * Partagé par tout ce qui valide un code avant de le montrer ou de l'envoyer :
 * la capture web (URL), le collage depuis le presse-papiers, le funnel du site.
 */
export const CODE_PARRAINAGE_REGEX = /^[ABCDEFGHJKMNPQRSTUVWXYZ23456789]{4,12}$/;

/** Vrai si la chaîne, une fois nettoyée, a la forme d'un code de parrainage. */
export function ressembleAUnCode(brut: string | null | undefined): boolean {
  return !!brut && CODE_PARRAINAGE_REGEX.test(brut.trim().toUpperCase());
}
