import { router, useLocalSearchParams } from 'expo-router';
import { useMemo, useState } from 'react';
import { ActivityIndicator, StyleSheet, Text, View } from 'react-native';

import { Carte } from '@/components/ecran';
import {
  Alerte,
  BoutonDiscret,
  BoutonPrincipal,
  BoutonSecondaire,
  Champ,
  Pastilles,
} from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import { activiteDepuisLecon, genererLecon, type LeconProposee } from '@/lib/donnees';
import { espace, police, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Écrire une leçon pour une compétence.
 *
 * 🔑 C'est le geste qui fait basculer le produit, et Anne-Charlotte le décrit
 * mieux que n'importe quelle spécification : « Puis boum, t'as l'objectif, t'as
 * le matériel dont t'as besoin. Ça me plaît, et là j'ai ma nouvelle idée. »
 *
 * Jusqu'ici, partir d'une compétence permettait de **saisir** une activité.
 * Maintenant elle en **reçoit** une. C'est la différence entre une app utile et
 * une app qu'on raconte à une collègue en salle des profs.
 *
 * 🔑 **Et c'est aussi « et si tu la travaillais autrement ».** Quand on arrive
 * depuis une compétence qui résiste, l'écran le dit et la consigne serveur
 * interdit de reproposer la même entrée. La fonction qu'elle appelle « dingue »
 * n'est pas un écran de plus : c'est celui-ci, à qui on donne deux chiffres
 * qu'on avait déjà et qui ne débouchaient sur rien.
 *
 * « Soit tu sais ce que tu veux, soit tu dis guide-moi » : le cadrage est
 * entièrement facultatif, et replié tant qu'elle ne le demande pas.
 *
 * ⚠️ Rien n'est enregistré tant qu'elle n'a pas dit « je la garde ». Une leçon
 * qui s'enregistrerait toute seule remplirait sa bibliothèque de brouillons
 * qu'elle n'a pas choisis.
 */

const LIEUX = ['classe', 'dehors', 'motricite'] as const;
const GROUPEMENTS = ['classe', 'petit_groupe', 'binome', 'individuel'] as const;

export default function Lecon() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { competence, nom, seances, acquis, evalues } = useLocalSearchParams<{
    competence: string;
    nom?: string;
    seances?: string;
    acquis?: string;
    evalues?: string;
  }>();
  const { classe } = useClasse();

  const [cadre, setCadre] = useState(false);
  // Le mode : 'complet' = « guide-moi, je n'ai pas d'idée » (l'app propose) ;
  // 'neutre' = « j'ai mon idée » (l'app met en forme sans rien inventer).
  const [mode, setMode] = useState<'complet' | 'neutre'>('complet');
  const [idee, setIdee] = useState('');
  const [pedagogie, setPedagogie] = useState('');
  const [theme, setTheme] = useState('');
  const [lieu, setLieu] = useState<string | null>(null);
  const [groupement, setGroupement] = useState<string | null>(null);
  const [lecon, setLecon] = useState<LeconProposee | null>(null);
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);

  // La compétence résiste : on est en mode « autrement », et on le dit.
  const resiste =
    seances && evalues
      ? {
          seances: parseInt(seances, 10),
          acquis: parseInt(acquis ?? '0', 10),
          evalues: parseInt(evalues, 10),
        }
      : undefined;

  async function ecrire(autrement: boolean) {
    if (!classe || !competence) return;
    setErreur(null);
    setOccupe(true);
    try {
      setLecon(
        await genererLecon({
          classe,
          competenceId: competence,
          competence: nom ?? '',
          theme,
          lieu: lieu ? t.lecon.lieux[lieu as keyof typeof t.lecon.lieux] : undefined,
          groupement: groupement
            ? t.activite.groupements[groupement as keyof typeof t.activite.groupements]
            : undefined,
          resiste,
          mode,
          idee,
          pedagogie,
          // Une deuxième demande sur la même compétence doit changer d'entrée,
          // sinon « une autre idée » rend la même chose autrement tournée. En
          // mode neutre, on ne cherche pas une entrée alternative.
          autrement: mode === 'complet' && (autrement || !!resiste),
        }),
      );
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.lecon.erreur);
    } finally {
      setOccupe(false);
    }
  }

  async function garder() {
    if (!classe || !competence || !lecon) return;
    setErreur(null);
    setOccupe(true);
    try {
      const { id } = await activiteDepuisLecon({
        classe,
        competenceId: competence,
        lecon,
      });
      // On atterrit sur la fiche : c'est là qu'elle la placera dans sa semaine.
      // Chaque étape finit en montrant la suivante.
      router.replace({ pathname: '/activite/[id]', params: { id } });
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.lecon.erreurGarder);
    } finally {
      setOccupe(false);
    }
  }

  return (
    <SousEcran titre={nom || t.lecon.titre} sousTitre={nom ? t.lecon.titre : undefined}>
      {!competence ? (
        <Carte>
          <Text style={texte.discret}>{t.lecon.sansCompetence}</Text>
        </Carte>
      ) : (
        <>
          {resiste ? (
            <Carte>
              <Text style={styles.resiste}>
                {t.lecon.resiste(resiste.seances, resiste.acquis, resiste.evalues)}
              </Text>
            </Carte>
          ) : null}

          {/* « Soit tu sais ce que tu veux, soit tu dis guide-moi. » Le mode dit
              lequel : guide-moi (l'app propose) ou j'ai mon idée (l'app met en
              forme sans rien inventer). Le cadrage reste replié en dessous. */}
          {!lecon ? (
            <>
              <Carte>
                <Pastilles
                  etiquette={t.lecon.modeEtiquette}
                  options={[
                    { id: 'complet', libelle: t.lecon.modeComplet },
                    { id: 'neutre', libelle: t.lecon.modeNeutre },
                  ]}
                  choisi={mode}
                  onChoisir={(v) => setMode(v === 'neutre' ? 'neutre' : 'complet')}
                />
                <Text style={styles.aide}>
                  {mode === 'neutre' ? t.lecon.modeNeutreAide : t.lecon.modeCompletAide}
                </Text>
                {mode === 'neutre' ? (
                  <Champ
                    etiquette={t.lecon.idee}
                    value={idee}
                    onChangeText={setIdee}
                    placeholder={t.lecon.ideeIndice}
                    multiline
                    editable={!occupe}
                  />
                ) : null}
              </Carte>

              {!cadre ? (
                <BoutonDiscret libelle={t.lecon.cadre} onPress={() => setCadre(true)} />
              ) : (
                <Carte>
                  <Text style={styles.aide}>{t.lecon.cadreAide}</Text>
                  <Champ
                    etiquette={t.lecon.theme}
                    value={theme}
                    onChangeText={setTheme}
                    placeholder={t.lecon.themeIndice}
                    editable={!occupe}
                  />
                  <Champ
                    etiquette={t.lecon.pedagogie}
                    value={pedagogie}
                    onChangeText={setPedagogie}
                    placeholder={t.lecon.pedagogieIndice}
                    editable={!occupe}
                  />
                  <Pastilles
                    etiquette={t.lecon.lieu}
                    options={LIEUX.map((l) => ({ id: l, libelle: t.lecon.lieux[l] }))}
                    choisi={lieu}
                    onChoisir={setLieu}
                  />
                  <Pastilles
                    etiquette={t.lecon.groupement}
                    options={GROUPEMENTS.map((g) => ({
                      id: g,
                      libelle: t.activite.groupements[g],
                    }))}
                    choisi={groupement}
                    onChoisir={setGroupement}
                  />
                </Carte>
              )}
            </>
          ) : null}

          {occupe && !lecon ? (
            <Carte>
              <View style={styles.ligneAttente}>
                <ActivityIndicator color={c.encreDouce} />
                <Text style={texte.discret}>{t.lecon.attente}</Text>
              </View>
            </Carte>
          ) : null}

          {erreur ? <Alerte message={erreur} /> : null}

          {/* La leçon, dans l'ordre où une enseignante la lit : ce qu'on fait,
              puis ce que ça vise, puis ce qu'il faut sortir de l'armoire. */}
          {lecon ? (
            <>
              <Carte>
                <Text style={texte.titre}>{lecon.titre}</Text>
                <Text style={texte.discret}>
                  {[
                    lecon.lieu,
                    lecon.duree ? t.lecon.duree(lecon.duree) : null,
                    lecon.approche ? t.lecon.approche(lecon.approche) : null,
                  ]
                    .filter(Boolean)
                    .join(' · ')}
                </Text>
              </Carte>

              <Carte>
                <Text style={texte.corps}>{lecon.description}</Text>
              </Carte>

              {lecon.objectif ? (
                <Bloc etiquette={t.lecon.objectif} valeur={lecon.objectif} />
              ) : null}
              {lecon.materiel ? <Bloc etiquette={t.lecon.materiel} valeur={lecon.materiel} /> : null}
              {lecon.organisation ? (
                <Bloc etiquette={t.lecon.organisation} valeur={lecon.organisation} />
              ) : null}

              <Carte>
                <Text style={styles.aide}>{t.lecon.gardeeAide}</Text>
              </Carte>

              <BoutonPrincipal libelle={t.lecon.garder} onPress={garder} occupe={occupe} />
              <BoutonDiscret libelle={t.lecon.regenerer} onPress={() => ecrire(true)} />
            </>
          ) : (
            <BoutonSecondaire
              libelle={t.lecon.generer}
              onPress={() => ecrire(false)}
              occupe={occupe}
            />
          )}
        </>
      )}
    </SousEcran>
  );
}

function Bloc({ etiquette, valeur }: { etiquette: string; valeur: string }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <Carte>
      <Text style={styles.etiquette}>{etiquette}</Text>
      <Text style={texte.corps}>{valeur}</Text>
    </Carte>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  aide: { fontFamily: police.corps, fontSize: 14, color: c.encreDouce },
  etiquette: { fontFamily: police.accent, fontSize: 14, color: c.encreDouce },
  resiste: { fontFamily: police.accent, fontSize: 15, color: c.action[1] },
  ligneAttente: { flexDirection: 'row', gap: espace.md, alignItems: 'center' },
});
