import { Feather } from '@expo/vector-icons';
import { router } from 'expo-router';
import { useMemo, useState } from 'react';
import { ActivityIndicator, Modal, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';

import { BoutonPrincipal, BoutonSecondaire } from '@/components/formulaire';
import { langue, t } from '@/i18n';
import { localeDate } from '@/lib/dates';
import {
  annulerCopie,
  creneauxDe,
  decalerISO,
  dupliquerJour,
  dupliquerSemaine,
  jourDeISO,
  type ActiviteListe,
  type Classe,
  type Creneau,
} from '@/lib/donnees';
import { copierLeconVersClasse } from '@/lib/multi-classes';
import { useRequete } from '@/lib/requete';
import { espace, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/** Jours courts pour étiqueter un créneau cible, selon la langue. */
const JOURS_COURTS = { fr: ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven'], nl: ['Ma', 'Di', 'Wo', 'Do', 'Vr'] };

type Quoi = 'lecon' | 'jour' | 'semaine';
type Phase = 'quoi' | 'ou' | 'fait';

/** « Lundi 8 septembre ». Le nom du jour vient de l'i18n (fiable partout), le
 *  jour et le mois de la locale. */
function jourLong(iso: string): string {
  const jour = t.semaine.jours[jourDeISO(iso) - 1] ?? '';
  const [a, m, j] = iso.split('-').map((n) => parseInt(n, 10));
  const dm = new Date(a, m - 1, j).toLocaleDateString(localeDate(), { day: 'numeric', month: 'long' });
  return `${jour} ${dm}`.trim();
}

/** « Semaine du 8 septembre ». */
function semaineLong(iso: string): string {
  const [a, m, j] = iso.split('-').map((n) => parseInt(n, 10));
  const d = new Date(a, m - 1, j).toLocaleDateString(localeDate(), { day: 'numeric', month: 'long' });
  return t.journal.reprendreLe(d);
}

/**
 * « Copier vers… » — LE flux unique de copie du Journal. Un seul point d'entrée,
 * en deux temps :
 *   1. Que copier ? — cette leçon (de la semaine), un jour entier, ou toute la
 *      semaine affichée.
 *   2. Où coller ? — dans ma classe (ou une autre de mes classes), et quand
 *      (semaine·s, jour·s, ou créneau·x cible·s selon le « quoi »).
 *
 * Il remplace les quatre anciens gestes (copier une semaine, dupliquer un jour,
 * copier une leçon, copier vers une autre classe) par une seule grammaire. Toute
 * la robustesse (photos de préparation, séquences copiées en unité, attendus
 * posés sur le nouvel id) vit dans la couche `donnees`/`multi-classes`.
 */
export function CopierVers({
  classeId,
  classes,
  lundiISO,
  activites,
  creneaux,
  onCopie,
}: {
  /** La classe active : la source de la copie. */
  classeId: string;
  /** Les classes actives : la source plus les cibles possibles (autre classe). */
  classes: Classe[];
  /** Le lundi de la semaine affichée : la source de « toute la semaine ». */
  lundiISO: string;
  /** Les séances de la semaine affichée : le vivier des leçons et des jours. */
  activites: ActiviteListe[];
  /** Les créneaux de la semaine affichée (classe active). */
  creneaux: Creneau[];
  onCopie: () => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const lib = t.journal.copieVers;

  const [ouvert, setOuvert] = useState(false);
  const [phase, setPhase] = useState<Phase>('quoi');
  const [quoi, setQuoi] = useState<Quoi | null>(null);
  const [leconId, setLeconId] = useState<string | null>(null);
  const [jourSource, setJourSource] = useState<string | null>(null);
  const [classeCible, setClasseCible] = useState<string>(classeId);
  const [ciblesSemaine, setCiblesSemaine] = useState<string[]>([]);
  const [ciblesJour, setCiblesJour] = useState<string[]>([]);
  // Clés de créneau cible : l'id d'un créneau, ou 'sans' (à planifier).
  const [ciblesCreneau, setCiblesCreneau] = useState<string[]>([]);
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState(false);
  // Id de la copie quand une seule leçon a été posée : de quoi offrir « Voir ».
  const [dernierId, setDernierId] = useState<string | null>(null);
  // Tout ce que la copie vient de créer, pour offrir « Annuler » (retour Sophie
  // 14/09 : un tap sur l'icône, une copie non voulue, aucun retour arrière).
  const [crees, setCrees] = useState<string[]>([]);
  const [sansHeure, setSansHeure] = useState(0);
  const [annulee, setAnnulee] = useState(false);

  // Les autres classes actives, pour le choix « une autre de mes classes ».
  const autresClasses = useMemo(
    () => classes.filter((cl) => !cl.archivee && cl.id !== classeId),
    [classes, classeId],
  );

  // Les leçons de la semaine, dédupliquées par titre : on copie une leçon, pas
  // chacune de ses séances.
  const lecons = useMemo(() => {
    const vues = new Set<string>();
    const liste: ActiviteListe[] = [];
    for (const a of activites) {
      const cle = a.titre.trim().toLocaleLowerCase('fr');
      if (vues.has(cle)) continue;
      vues.add(cle);
      liste.push(a);
    }
    return liste;
  }, [activites]);

  // Les jours de la semaine affichée qui portent un plan (sources possibles).
  const joursAvecPlan = useMemo(() => {
    const compte = new Map<string, number>();
    for (const a of activites) if (a.date) compte.set(a.date, (compte.get(a.date) ?? 0) + 1);
    return [0, 1, 2, 3, 4]
      .map((i) => {
        const d = decalerISO(lundiISO, i);
        return { date: d, compte: compte.get(d) ?? 0 };
      })
      .filter((j) => j.compte > 0);
  }, [activites, lundiISO]);

  // Les semaines cibles : deux en arrière, huit en avant, jamais la semaine
  // affichée (qui est la source), sauf si on vise une autre classe.
  const semainesCibles = useMemo(() => {
    const memeClasse = classeCible === classeId;
    return [-2, -1, 0, 1, 2, 3, 4, 5, 6, 7, 8]
      .map((k) => decalerISO(lundiISO, 7 * k))
      .filter((s) => !(memeClasse && s === lundiISO));
  }, [lundiISO, classeCible, classeId]);

  // Les jours cibles : la semaine affichée puis la suivante, jamais le jour
  // source dans la même classe.
  const joursCibles = useMemo(() => {
    const memeClasse = classeCible === classeId;
    const jours: string[] = [];
    for (let k = 0; k < 5; k++) jours.push(decalerISO(lundiISO, k));
    for (let k = 0; k < 5; k++) jours.push(decalerISO(lundiISO, 7 + k));
    return jours.filter((d) => !(memeClasse && d === jourSource));
  }, [lundiISO, classeCible, classeId, jourSource]);

  // Les créneaux de la classe cible pour la semaine affichée : soit ceux déjà en
  // main (classe active), soit chargés pour une autre classe.
  const creneauxAutre = useRequete(
    () => creneauxDe(classeCible, lundiISO),
    [classeCible, lundiISO],
    { actif: quoi === 'lecon' && classeCible !== classeId },
  );
  const creneauxCible = useMemo(
    () => (classeCible === classeId ? creneaux : (creneauxAutre.donnees ?? [])),
    [classeCible, classeId, creneaux, creneauxAutre.donnees],
  );
  const creneauxCibleListe = useMemo(() => {
    return [...creneauxCible]
      .filter((cr) => cr.jour >= 1 && cr.jour <= 5)
      .sort((a, b) => a.jour - b.jour || a.debut.localeCompare(b.debut))
      .map((cr) => ({
        key: `${cr.jour}|${cr.id}`,
        date: decalerISO(lundiISO, cr.jour - 1),
        creneauId: cr.id,
        libelle: t.journal.copie.creneauLigne(
          JOURS_COURTS[langue][cr.jour - 1] ?? '',
          cr.libelle || '—',
          cr.debut,
        ),
      }));
  }, [creneauxCible, lundiISO]);

  function ouvrir() {
    setOuvert(true);
    setPhase('quoi');
    setQuoi(null);
    setLeconId(null);
    setJourSource(null);
    setClasseCible(classeId);
    setCiblesSemaine([]);
    setCiblesJour([]);
    setCiblesCreneau([]);
    setErreur(false);
    setDernierId(null);
    setCrees([]);
    setSansHeure(0);
    setAnnulee(false);
  }

  async function annuler() {
    if (!crees.length) return;
    setOccupe(true);
    setErreur(false);
    try {
      await annulerCopie(crees);
      setCrees([]);
      setAnnulee(true);
      onCopie();
    } catch {
      setErreur(true);
    } finally {
      setOccupe(false);
    }
  }
  function fermer() {
    setOuvert(false);
  }

  function basculer(liste: string[], set: (v: string[]) => void, cle: string) {
    set(liste.includes(cle) ? liste.filter((x) => x !== cle) : [...liste, cle]);
  }

  // Changer de classe cible : les cibles « quand » déjà cochées peuvent ne plus
  // avoir de sens (créneaux d'une autre classe, semaine source réouverte), on les
  // repart à zéro.
  function choisirClasse(id: string) {
    setClasseCible(id);
    setCiblesSemaine([]);
    setCiblesJour([]);
    setCiblesCreneau([]);
  }

  // Le bouton « Coller » n'est actif que si une cible est choisie.
  const peutColler =
    (quoi === 'semaine' && ciblesSemaine.length > 0) ||
    (quoi === 'jour' && ciblesJour.length > 0) ||
    (quoi === 'lecon' && ciblesCreneau.length > 0);

  async function coller() {
    if (!peutColler) return;
    setOccupe(true);
    setErreur(false);
    try {
      let id: string | null = null;
      let combien = 0;
      const ids: string[] = [];
      let sans = 0;
      if (quoi === 'semaine') {
        for (const cible of ciblesSemaine) {
          const r = await dupliquerSemaine({
            classeSourceId: classeId,
            classeCibleId: classeCible,
            semaineSource: lundiISO,
            semaineCible: cible,
          });
          ids.push(...r.ids);
          sans += r.sansCreneau;
          combien += 1;
        }
      } else if (quoi === 'jour' && jourSource) {
        const r = await dupliquerJour({
          classeSourceId: classeId,
          classeCibleId: classeCible,
          dateSource: jourSource,
          datesCibles: ciblesJour,
        });
        ids.push(...r.ids);
        sans += r.sansCreneau;
        combien = ciblesJour.length;
      } else if (quoi === 'lecon' && leconId) {
        const choisis = creneauxCibleListe.filter((cr) => ciblesCreneau.includes(cr.key));
        if (ciblesCreneau.includes('sans')) {
          const res = await copierLeconVersClasse({
            activiteId: leconId,
            classeCibleId: classeCible,
            date: null,
          });
          id = res.id;
          ids.push(res.id);
          combien += 1;
        }
        for (const cr of choisis) {
          const res = await copierLeconVersClasse({
            activiteId: leconId,
            classeCibleId: classeCible,
            date: cr.date,
            creneauId: cr.creneauId,
          });
          id = res.id;
          ids.push(res.id);
          combien += 1;
        }
      }
      // « Voir » n'a de sens que pour une seule copie posée (une leçon, une cible).
      setDernierId(combien === 1 ? id : null);
      setCrees(ids);
      setSansHeure(sans);
      setAnnulee(false);
      setPhase('fait');
      onCopie();
    } catch {
      setErreur(true);
    } finally {
      setOccupe(false);
    }
  }

  // Le titre de la feuille suit le temps courant.
  const titre =
    phase === 'fait'
      ? lib.fait
      : phase === 'ou'
        ? lib.titreOu
        : quoi === 'lecon'
          ? lib.choisirLecon
          : quoi === 'jour'
            ? lib.choisirJour
            : lib.titreQuoi;

  return (
    <>
      {/* Le point d'entrée : l'icône de copie de la barre du Journal. */}
      <Pressable
        accessibilityRole="button"
        accessibilityState={{ expanded: ouvert }}
        accessibilityLabel={lib.bouton}
        onPress={ouvrir}
        style={[styles.iconeCopie, ouvert && styles.iconeCopieActive]}>
        <Feather name="copy" size={18} color={ouvert ? c.actif : c.encre} />
        {/* Un mot à côté de l'icône : les « deux carrés » seuls ne disaient pas
            ce qu'ils faisaient (retour Sophie 14/09). */}
        <Text style={[styles.iconeCopieTexte, ouvert && { color: c.actif }]}>{lib.boutonCourt}</Text>
      </Pressable>

      <Modal visible={ouvert} transparent animationType="fade" onRequestClose={fermer}>
        <Pressable style={styles.voile} onPress={fermer}>
          <Pressable style={styles.feuille} onPress={() => {}}>
            {/* En-tête FIXE, hors ScrollView : la croix de fermeture reste
                atteignable même quand la liste défile (charte). */}
            <View style={styles.entete}>
              <Text style={styles.titre} numberOfLines={1}>
                {titre}
              </Text>
              <Pressable
                accessibilityRole="button"
                accessibilityLabel={lib.fermer}
                onPress={fermer}
                hitSlop={8}
                style={styles.croix}>
                <Feather name="x" size={20} color={c.encreDouce} />
              </Pressable>
            </View>

            {phase === 'fait' ? (
              <View style={styles.faitBloc}>
                <View style={styles.faitPastille}>
                  <Feather name="check" size={22} color={c.moment.recreation} />
                </View>
                <Text style={styles.faitTexte}>
                  {annulee ? lib.annulee : lib.faitCompte(crees.length)}
                </Text>
                {!annulee && sansHeure > 0 ? (
                  <Text style={styles.vide}>{lib.faitSansHeure(sansHeure)}</Text>
                ) : null}
                {erreur ? <Text style={styles.vide}>{lib.erreurAnnuler}</Text> : null}
                {!annulee && crees.length > 0 ? (
                  <BoutonSecondaire
                    libelle={occupe ? lib.annulation : lib.annuler}
                    onPress={annuler}
                  />
                ) : null}
                <View style={styles.pied}>
                  {dernierId && !annulee ? (
                    <View style={styles.moitie}>
                      <BoutonSecondaire
                        libelle={lib.voir}
                        onPress={() => {
                          fermer();
                          router.push({ pathname: '/activite/[id]', params: { id: dernierId } });
                        }}
                      />
                    </View>
                  ) : null}
                  <View style={styles.moitie}>
                    <BoutonPrincipal libelle={lib.fermer} onPress={fermer} />
                  </View>
                </View>
              </View>
            ) : (
              <>
                <ScrollView style={styles.liste}>
                  {erreur ? <Text style={styles.vide}>{lib.erreur}</Text> : null}

                  {/* Temps 1 : que copier ? */}
                  {phase === 'quoi' && quoi === null ? (
                    <>
                      <OptionQuoi
                        c={c}
                        styles={styles}
                        icone="file-text"
                        titre={lib.quoiLecon}
                        aide={lib.quoiLeconAide}
                        onPress={() => setQuoi('lecon')}
                      />
                      <OptionQuoi
                        c={c}
                        styles={styles}
                        icone="sun"
                        titre={lib.quoiJour}
                        aide={lib.quoiJourAide}
                        onPress={() => setQuoi('jour')}
                      />
                      <OptionQuoi
                        c={c}
                        styles={styles}
                        icone="calendar"
                        titre={lib.quoiSemaine}
                        aide={lib.quoiSemaineAide}
                        onPress={() => {
                          setQuoi('semaine');
                          setPhase('ou');
                        }}
                      />
                    </>
                  ) : null}

                  {/* Temps 1b : choisir la leçon source. */}
                  {phase === 'quoi' && quoi === 'lecon' ? (
                    lecons.length === 0 ? (
                      <Text style={styles.vide}>{lib.sansLecon}</Text>
                    ) : (
                      lecons.map((a) => (
                        <Pressable
                          key={a.id}
                          accessibilityRole="button"
                          accessibilityLabel={a.titre}
                          onPress={() => {
                            setLeconId(a.id);
                            setPhase('ou');
                          }}
                          style={styles.ligne}>
                          <Text style={styles.ligneNom} numberOfLines={1}>
                            {a.titre}
                          </Text>
                          <Feather name="chevron-right" size={18} color={c.encreDouce} />
                        </Pressable>
                      ))
                    )
                  ) : null}

                  {/* Temps 1b : choisir le jour source. */}
                  {phase === 'quoi' && quoi === 'jour' ? (
                    joursAvecPlan.length === 0 ? (
                      <Text style={styles.vide}>{lib.sansJour}</Text>
                    ) : (
                      joursAvecPlan.map((j) => (
                        <Pressable
                          key={j.date}
                          accessibilityRole="button"
                          accessibilityLabel={jourLong(j.date)}
                          onPress={() => {
                            setJourSource(j.date);
                            setPhase('ou');
                          }}
                          style={styles.ligne}>
                          <View style={styles.ligneCorps}>
                            <Text style={styles.ligneNom} numberOfLines={1}>
                              {jourLong(j.date)}
                            </Text>
                            <Text style={styles.ligneCompte}>{t.journal.dupJourCompte(j.compte)}</Text>
                          </View>
                          <Feather name="chevron-right" size={18} color={c.encreDouce} />
                        </Pressable>
                      ))
                    )
                  ) : null}

                  {/* Temps 2 : où coller ? */}
                  {phase === 'ou' ? (
                    <>
                      {/* La classe cible, seulement s'il y a une autre classe active. */}
                      {autresClasses.length > 0 ? (
                        <>
                          <Text style={styles.sousTitre}>{lib.classe}</Text>
                          <ChoixRadio
                            styles={styles}
                            c={c}
                            choisi={classeCible === classeId}
                            libelle={lib.maClasse}
                            onPress={() => choisirClasse(classeId)}
                          />
                          {autresClasses.map((cl) => (
                            <ChoixRadio
                              key={cl.id}
                              styles={styles}
                              c={c}
                              choisi={classeCible === cl.id}
                              libelle={cl.nom}
                              onPress={() => choisirClasse(cl.id)}
                            />
                          ))}
                        </>
                      ) : null}

                      {/* Le « quand », selon le quoi. */}
                      {quoi === 'semaine' ? (
                        <>
                          <Text style={styles.sousTitre}>{lib.quandSemaine}</Text>
                          {semainesCibles.map((s) => (
                            <ChoixCase
                              key={s}
                              styles={styles}
                              c={c}
                              coche={ciblesSemaine.includes(s)}
                              libelle={semaineLong(s)}
                              onPress={() => basculer(ciblesSemaine, setCiblesSemaine, s)}
                            />
                          ))}
                        </>
                      ) : null}

                      {quoi === 'jour' ? (
                        <>
                          <Text style={styles.sousTitre}>{lib.quandJour}</Text>
                          {joursCibles.map((d) => (
                            <ChoixCase
                              key={d}
                              styles={styles}
                              c={c}
                              coche={ciblesJour.includes(d)}
                              libelle={jourLong(d)}
                              onPress={() => basculer(ciblesJour, setCiblesJour, d)}
                            />
                          ))}
                        </>
                      ) : null}

                      {quoi === 'lecon' ? (
                        <>
                          <Text style={styles.sousTitre}>{lib.quandCreneau}</Text>
                          <ChoixCase
                            styles={styles}
                            c={c}
                            coche={ciblesCreneau.includes('sans')}
                            libelle={lib.sansCreneau}
                            onPress={() => basculer(ciblesCreneau, setCiblesCreneau, 'sans')}
                          />
                          {creneauxAutre.chargement ? (
                            <View style={styles.centre}>
                              <ActivityIndicator color={c.actif} />
                            </View>
                          ) : (
                            creneauxCibleListe.map((cr) => (
                              <ChoixCase
                                key={cr.key}
                                styles={styles}
                                c={c}
                                coche={ciblesCreneau.includes(cr.key)}
                                libelle={cr.libelle}
                                onPress={() => basculer(ciblesCreneau, setCiblesCreneau, cr.key)}
                              />
                            ))
                          )}
                        </>
                      ) : null}
                    </>
                  ) : null}
                </ScrollView>

                {/* Pied FIXE (hors ScrollView) en temps 2 : revenir, ou coller. */}
                {phase === 'ou' ? (
                  <View style={styles.pied}>
                    <View style={styles.moitie}>
                      <BoutonSecondaire
                        libelle={lib.retour}
                        onPress={() => {
                          // On revient au temps 1 : à la liste source si on l'avait,
                          // sinon aux trois options.
                          if (quoi === 'semaine') setQuoi(null);
                          setPhase('quoi');
                        }}
                      />
                    </View>
                    <View style={styles.moitie}>
                      <BoutonPrincipal
                        libelle={lib.coller}
                        onPress={coller}
                        occupe={occupe}
                        inactif={!peutColler}
                      />
                    </View>
                  </View>
                ) : null}
              </>
            )}
          </Pressable>
        </Pressable>
      </Modal>
    </>
  );
}

/** Une des trois grandes options « que copier ». */
function OptionQuoi({
  c,
  styles,
  icone,
  titre,
  aide,
  onPress,
}: {
  c: Couleurs;
  styles: ReturnType<typeof creerStyles>;
  icone: keyof typeof Feather.glyphMap;
  titre: string;
  aide: string;
  onPress: () => void;
}) {
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`${titre}. ${aide}`}
      onPress={onPress}
      style={styles.option}>
      <View style={styles.optionTuile}>
        <Feather name={icone} size={18} color={c.action[1]} />
      </View>
      <View style={styles.ligneCorps}>
        <Text style={styles.ligneNom} numberOfLines={1}>
          {titre}
        </Text>
        <Text style={styles.ligneCompte}>{aide}</Text>
      </View>
      <Feather name="chevron-right" size={18} color={c.encreDouce} />
    </Pressable>
  );
}

/** Un choix unique (radio) : la classe cible. */
function ChoixRadio({
  styles,
  c,
  choisi,
  libelle,
  onPress,
}: {
  styles: ReturnType<typeof creerStyles>;
  c: Couleurs;
  choisi: boolean;
  libelle: string;
  onPress: () => void;
}) {
  return (
    <Pressable
      accessibilityRole="radio"
      accessibilityState={{ selected: choisi }}
      accessibilityLabel={libelle}
      onPress={onPress}
      style={[styles.ligne, choisi && styles.ligneCochee]}>
      <View style={[styles.radio, choisi && styles.radioCoche]}>
        {choisi ? <View style={styles.radioPoint} /> : null}
      </View>
      <Text style={styles.ligneNom} numberOfLines={1}>
        {libelle}
      </Text>
    </Pressable>
  );
}

/** Un choix multiple (case à cocher) : une semaine, un jour ou un créneau cible. */
function ChoixCase({
  styles,
  c,
  coche,
  libelle,
  onPress,
}: {
  styles: ReturnType<typeof creerStyles>;
  c: Couleurs;
  coche: boolean;
  libelle: string;
  onPress: () => void;
}) {
  return (
    <Pressable
      accessibilityRole="checkbox"
      accessibilityState={{ checked: coche }}
      accessibilityLabel={libelle}
      onPress={onPress}
      style={[styles.ligne, coche && styles.ligneCochee]}>
      <View style={[styles.case, coche && styles.caseCochee]}>
        {coche ? <Feather name="check" size={13} color={c.surface} /> : null}
      </View>
      <Text style={styles.ligneNom} numberOfLines={1}>
        {libelle}
      </Text>
    </Pressable>
  );
}

